  function home_region_key (p_tenancy_id number) return varchar2;
--   function test_search return SYS_REFCURSOR ;
  procedure test_search(p_search_str IN varchar, c1 OUT SYS_REFCURSOR);
  
-- Retrieve from LL_REGIONS table
  function region_key (p_region_id number) return varchar2;
  function region_name (p_region_id number default null, p_region_key varchar2 default null) return varchar2;
  function region_identifier (p_region_id number) return varchar2;
  function ad_name( p_tenancy_id number, p_region_id number, p_ad number) return varchar2;  
  function region_identifier_with_key (p_region_key varchar2) return varchar2;
  
-- Retrieve from OCI
  function ad_per_region (p_tenancy_id number, p_region_id number) return clob;
  function available_per_ad (p_tenancy_id number, p_region_id number, p_service_name varchar2, p_limit_name varchar2, p_compartment_ocid varchar2, p_ad varchar2 default NULL ) return number;
  function get_marketplace_ocid (p_tenancy_id number, p_region_id number, p_listingid varchar2, p_resourceversion varchar2, p_compartment_id varchar2) return varchar2;
  function get_compartment_ocid(p_tenancy_id number, p_name varchar2, p_region_id varchar2, p_compartment_id varchar2 default null) return varchar2;
  function get_parent_compartment(p_tenancy_id number, p_region_id varchar2, p_compartment_id varchar2) return varchar2;
-- Generic functions
   
  function date_to_datetime (p_date in date) return varchar2; 
  function datetime_to_date (p_datetime in varchar2) return date; 
  function hours_readable (p_hours number, p_size varchar2 default 'LONG', p_add_and varchar2 default 'N', p_seconds varchar2 default 'N') return varchar2;
  function hours_to_days (p_hours number) return number;
  function minutes_to_days (p_minutes number) return number;
  function is_number (p_value varchar2) return number;
  function clob_to_blob (p_data  IN  CLOB) return blob;
  function base64encode(p_blob IN BLOB) RETURN CLOB;  
  procedure delete_reservation_steps;
  procedure pause (p_seconds number);
  function distance_country_dc (p_country_code varchar2, p_region_id number) return number;
  
  function cut_off_at_space (p_string varchar2, p_max_characters number) return varchar2;  
  function get_id (p_clob clob) return varchar2;  
  function oci_endpoint (p_type varchar2, p_region_key varchar2) return varchar2; 
  function compare_category_tags (p_workshop_id number, p_filter varchar2) return varchar2;
  function green_button_enabled return varchar2;
-- Retrieve information
  function get_flow_step_source_code (p_step_code varchar2) return varchar2;
  function get_flow_step_object_name (p_step_code varchar2) return varchar2;
  procedure move_compartment (p_tenancy_id number, p_compartment varchar2, p_dest varchar2);
  procedure update_compartment (p_tenancy_id number, p_compartment varchar2, p_name varchar2, p_description varchar2, p_permissions varchar2 default null, p_owner varchar2 default null, p_workshop_id varchar2 default null, p_region varchar2 default null, p_event_id varchar2 default null); 
  
  procedure send_warning_almost_expired;
  procedure truncate_ll_logging (p_hours number);
  
  function system_parameter (p_name varchar2) return varchar2;
-- Generic APEX and PL/SQL calls
  procedure setup_default_jobs (p_code varchar2);
  procedure create_job (p_type IN varchar2, p_parameters IN varchar2, p_jobname IN varchar2 default null, p_repeat IN varchar2 default null, p_start_date date default sysdate);
  procedure send_email (p_to IN varchar2, p_subject IN varchar2, p_body_html IN clob, p_status OUT varchar2, p_result OUT varchar2);
  procedure clean_compartments_recyclebin (p_tenancy_id number default null, p_recyclebin_ocid varchar2 default null, p_available_ocid varchar2 default null);
  function email_default_header (p_type varchar2) return clob;
--
-- Event code emails
  procedure send_eventcode_overviews;
  procedure send_eventcode_overview (p_ec_id number);
-- Retrieve country code from LDAP
  function get_country (p_app_user varchar2) return varchar2;
-- Stress test entries 
  procedure stress_test_build (p_workshop_id number, p_prefix varchar2, p_num_environments number, p_delay number default 0, p_start_number number default 1, p_ssh_key varchar2 default null);
  procedure stress_test_destroy (p_prefix varchar2);
-- Resources and Tenancies
  function limit_definitions_query (p_tenancy_id number, p_servicename varchar2 default null) return varchar2;
-- stubs 
--
 -- ============================================
 --
  function requires_pub_key (p_workshop_id number, p_event_id number default null) return varchar2;
  procedure yum_repo_endpoints;
  function github_cidrs return clob;
  function google_cidrs return clob;
  procedure generate_sitemap;
function subscribed_regions(p_tenancy_id number) return clob;

 
  
END LL_PKG_ADMIN;
