    p_desc_short  IN VARCHAR2,
    p_desc_long   IN VARCHAR2,
    p_model       IN VARCHAR2 DEFAULT NULL,
    p_max_words   IN NUMBER   DEFAULT -1,
    p_overlap     IN NUMBER   DEFAULT -1
);

end "LL_PKG_AI";
