  function tenancy_ocid (p_tenancy_id number) return varchar2 AS 
    cursor c_tenancy is select tenancy_ocid from ll_tenancies where id = p_tenancy_id; 
    v_return_value varchar2(100); 
  BEGIN 
      open c_tenancy; 
      fetch c_tenancy into v_return_value; 
      if c_tenancy%notfound then 
        v_return_value := 'Error: Tenancy ID not found'; 
      end if; 
      close c_tenancy; 
      return(v_return_value); 
  END; 
