--     ##    ######## ##    ## ##     ## ##    ##  ######     ##       ##    ## ##     ## ##     ## ########
--
  function tenancy_name (p_tenancy_id number) return varchar2 is
      cursor c_tenancy is select lower(tenancy_name) as name from ll_tenancies where id = p_tenancy_id; 
    v_return_value varchar2(100); 
  BEGIN 
      open c_tenancy; 
      fetch c_tenancy into v_return_value; 
      if c_tenancy%notfound then 
        v_return_value := 'Error: Tenancy ID not found'; 
      end if; 
      close c_tenancy; 
      return(v_return_value); 
  END; 
 -- get tenancy ID if you pass in the tenancy OCID
 function tenancy_id (p_tenancy_ocid varchar2) return number is 
    cursor c_tenancy is select id from ll_tenancies where tenancy_ocid = p_tenancy_ocid;
    v_return_id number;
 begin
    open c_tenancy;
    fetch c_tenancy into v_return_id;
    if c_tenancy%notfound then
        v_return_id := null;
    end if;
    close c_tenancy;
    return v_return_id;
 end;
    
