  function date_to_datetime (p_date in date) return varchar2 is 
    v_datetime   varchar2(200); 
  begin 
    v_datetime := to_char(p_date,'YYYY-MM-DD')||'T'||to_char(p_date,'HH24:MI:SS')||'.000Z'; 
    return(v_datetime); 
  end; 
