  function datetime_to_date (p_datetime in varchar2) return date is 
    v_text_date varchar2(100); 
    v_text_time varchar2(100); 
    v_date      date; 
  begin 
    v_text_date := substr(p_datetime,1,10); 
    v_text_time := substr(p_datetime,12,8); 
     
    v_date := to_date(v_text_date||' '||v_text_time,'YYYY-MM-DD HH24:MI:SS'); 
 
    return(v_date); 
  end; 
