  function hours_readable (p_hours number, p_size varchar2 default 'LONG', p_add_and varchar2 default 'N', p_seconds varchar2 default 'N') return varchar2 is
  
    v_weeks      number;
    v_days       number;
    v_hours      number;
    v_ref_date   date          := to_date('01-01-2000','DD-MM-YYYY');
    
    v_return_value varchar2(200);
    
    procedure lp_add_value (p_number IN number, p_value IN OUT varchar2, p_long IN varchar2, p_short IN varchar2) is
      v_desc         varchar2(200);
    begin
      if p_number > 0 then
        if p_value is not null then
          p_value := p_value ||', ';
        end if;
        
        p_value := p_value || p_number ||' '|| case p_size when 'LONG' then p_long else p_short end;
        if p_number > 1 then
          p_value := p_value || 's';
        end if;
        
      end if;
    end;
 
  begin
    v_days := p_hours / 24;
    
    -- weeks
    v_weeks := floor(v_days/7);
    lp_add_value(v_weeks, v_return_value,'week','wk');
    
    -- days
    v_days := v_days - (v_weeks*7);
    lp_add_value(floor(v_days),v_return_value,'day','d');
    
    -- hours
    
    v_days := v_days - floor(v_days);
    lp_add_value(to_number(to_char(v_ref_date+v_days,'HH24')),v_return_value,'hour','hr');
    lp_add_value(to_number(to_char(v_ref_date+v_days,'MI'))  ,v_return_value,'minute','min');
    if p_seconds = 'Y' then
      lp_add_value(to_number(to_char(v_ref_date+v_days,'SS'))  ,v_return_value,'second','sec');
    end if;
    
    if p_add_and = 'Y' and instr(v_return_value,',') > 0 then
      v_return_value := substr(v_return_value,1,instr(v_return_value,',',-1)-1) || ' and' || substr(v_return_value,instr(v_return_value,',',-1)+1);
    end if;
    
    return(v_return_value);
                         
  end;                         
