  function compare_category_tags (p_workshop_id number, p_filter varchar2) return varchar2 is 
 
    cursor c_check_tag (p_check_tag number) is  
                          select 'Y' 
                          from ll_workshop_tags llwt, ll_workshops llw 
                          where llw.id = llwt.workshop_id
                          and llw.active_flg='Y'
                          and workshop_id = p_workshop_id 
                          and llwt.tag_id = p_check_tag; 
  
    v_filter_items_arr   apex_t_varchar2; 
    v_result             varchar2(1); 
   
  begin 
    if replace(p_filter,':','') is null then 
      v_result := 'Y'; 
    else 
      v_result := nvl(v_result,'N'); 
      v_filter_items_arr := apex_string.split(p_str => p_filter, p_sep => ':'); 
       
      for x in 1..v_filter_items_arr.count loop 
        if nvl(v_result,'N') = 'N' and v_filter_items_arr(x) is not null then 
          open c_check_tag (p_check_tag => to_number(v_filter_items_arr(x))); 
          fetch c_check_tag into v_result; 
          close c_check_tag; 
        end if;        
      end loop;      
 
    end if; 
     
    return(v_result); 
     
  end; 
