  procedure create_job (p_type IN varchar2, p_parameters IN varchar2, p_jobname IN varchar2 default null, p_repeat IN varchar2 default null, p_start_date date default sysdate) is
    PRAGMA AUTONOMOUS_TRANSACTION;
    
    cursor c_state is select value
                      from ll_system_parameters
                      where name='ENABLE_JOBS';
    v_jobname     varchar2(255);
    v_statement   varchar2(4000);
    v_P1          varchar2(2000);
    v_P2          varchar2(2000);
    v_P3          varchar2(2000);
    v_enable      boolean;
    v_state       varchar2(100);
    
  begin
  
    ll_pkg_log.log(20,'Initial call');
    ll_pkg_log.log(40,'Type is '||p_type);
    case p_type
      when 'RESERVATION_REGISTERED'   then v_statement := 'LL_PKG_RESERVATION.PROCESS_RESERVATION_INITIAL(p_reservation_id => to_number({P1}), '||
                                                                                                         'p_start_gmt      => to_date({P2},'||dbms_assert.enquote_literal('DD-MM-YYYY HH24:MI:SS') ||'));';
      when 'CREATE_AND_PROCESS_RES'   then v_statement := 'LL_PKG_RESERVATION.CREATE_RESERVATION_STEPS (p_reservation_id => to_number({P1})); '||
                                                          'LL_PKG_RESERVATION.SETUP_RESERVATION (p_reservation_id => to_number({P1}));';
      when 'RESTART_RESERVATION'      then v_statement :=  'LL_PKG_RESERVATION.SETUP_RESERVATION (p_reservation_id => to_number({P1}));';
      when 'DELETE_RES_OBJECTS'       then v_statement := 'LL_PKG_DELETE.delete_reservation_objects (p_reservation_id => to_number({P1}));';
      when 'EVERY10MIN'               then v_statement := 'LL_PKG_SCHEDULED.run_every_10_min;';
      when 'EVERY1HOUR'               then v_statement := 'LL_PKG_SCHEDULED.run_every_hour;';
      when 'EVERY1DAY'                then v_statement := 'LL_PKG_SCHEDULED.run_every_day;';
      when 'BACKUP'                   then v_statement := 'LL_PKG_BACKUP.BACKUP_ALL(to_number({P1}));';
      when 'CLEAN_RES_OBJECTS'        then v_statement := 'LL_PKG_DELETE.delete_reservation_objects (p_reservation_id => to_number({P1}));';
      when 'CLEAN_COMPARTMENT'        then v_statement := 'LL_PKG_DELETE.clean_compartment (p_tenancy_id => to_number({P1}), '||
                                                                                           'p_comp_ocid  => {P2}, '||
                                                                                           'p_available_ocid => {P3} );';
    end case;
    
    if v_statement is not null then
    
      ll_pkg_security.set_security_group;
      ll_pkg_log.log(30,'Statement is not null');
      v_P1 := JSON_VALUE(p_parameters,'$.P1');
      v_P2 := JSON_VALUE(p_parameters,'$.P2');
      v_P3 := JSON_VALUE(p_parameters,'$.P3');
      v_statement := replace(v_statement,'{P1}',dbms_assert.enquote_literal(v_P1));
      v_statement := replace(v_statement,'{P2}',dbms_assert.enquote_literal(v_P2));
      v_statement := replace(v_statement,'{P3}',dbms_assert.enquote_literal(v_P3));
      ll_pkg_log.log(40,'Statement: '||v_statement);
      
      open c_state;
      fetch c_state into v_state;
      if c_state%NOTFOUND or v_state = 'TRUE' then
        v_enable := TRUE;
      else
        v_enable := FALSE;
      end if;
      close c_state;
      v_jobname := dbms_scheduler.generate_job_name(nvl(p_jobname,'NONAME')||'_');
      DBMS_SCHEDULER.create_job (
        job_name        => v_jobname,
        job_type        => 'PLSQL_BLOCK',
        job_action      => 'BEGIN '||v_statement||' END;',
        start_date      => CAST(p_start_date AS TIMESTAMP),
        repeat_interval => p_repeat,
        enabled         => v_enable );
        
    end if;
    
    ll_pkg_log.log(20,'End of call');
    
  end;
