  function region_name (p_region_id number default null, p_region_key varchar2 default null) return varchar2 is
    cursor c_regions is select region_name
                        from ll_oci_regions
                        where ( nvl(p_region_key,region_key) = region_key and p_region_key is not null )
                        or    ( nvl(p_region_id ,id        ) = id         and p_region_id is not null );
    v_return_val   varchar2(100);
    
  begin
    open c_regions;
    fetch c_regions into v_return_val;
    close c_regions;
    
    return v_return_val;
    
  end;
