  procedure send_email (p_to IN varchar2, p_subject IN varchar2, p_body_html IN clob, p_status OUT varchar2, p_result OUT varchar2) is
    cursor c_before (p_days number) is 
                       select 'Y'
                       from apex_mail_log
                       where mail_to = p_to
                       and mail_subj = p_subject
                       and mail_message_created > (sysdate - p_days)
                       union
                       select 'Y'
                       from apex_mail_queue
                       where mail_to = p_to
                       and mail_subj = p_subject;
                       
    cursor c_workspace is
                       select workspace_id
                       from apex_applications
                       where alias like 'LIVELABS%';
                       
    v_minute        number := (1/24)/60;
    v_prevent       number := 10;
    v_mailid        number;
    v_dummy         varchar2(1);
    v_clob_txt      clob;
    v_secgrp_id     number;
    
    v_sender        varchar2(100);
    --v_bcc           varchar2(100);
  
  begin
  
    ll_pkg_log.log(20,'Initial call');
    if p_to like '%@LIVELABS.COM' then return; end if;
  
    ll_pkg_security.set_security_group;
    
    v_sender := ll_pkg_admin.system_parameter(p_name => 'EMAIL_SENDER');
    --v_bcc    := ll_pkg_admin.system_parameter(p_name => 'EMAIL_BCC');
     
    open c_before (v_minute * v_prevent);
    fetch c_before into v_dummy;
    if c_before%NOTFOUND then
      ll_pkg_log.log(30,'Preparing message');
      if instr(p_body_html,'<body>') > 0 then
        v_clob_txt := substr(p_body_html,instr(p_body_html,'<body>'));
      else
        v_clob_txt := p_body_html;
      end if;
    
      v_clob_txt := regexp_replace(v_clob_txt, '<[^>]+>', '');
      ll_pkg_log.log(30,'Sending message');
      v_mailid := APEX_MAIL.SEND(
           p_to          => p_to,
           p_from      => v_sender,
           p_subj      => p_subject,
           p_body      => v_clob_txt,
           p_body_html => p_body_html);
           --p_bcc       => v_bcc);
      ll_pkg_log.log(30,'Status is succesful');
      p_status := 'Y';
    else
      p_status := 'N';
      p_result := 'Same sender and subject in last '||v_prevent||' minutes';
      ll_pkg_log.log(30,'Same email again to same sender and subject');
    end if;
    close c_before;
    
    apex_mail.push_queue;
    
    ll_pkg_log.log(20,'End if call');
    
    EXCEPTION
    WHEN others then begin
                       p_status:='N';
                       p_result := 'Issue during send: '||SQLERRM;
                       ll_pkg_log.log(20,p_result);
                     end;
  end;
