  function ad_per_region (p_tenancy_id number, p_region_id number) return clob is
    cursor c_names is select json_objectagg('name' VALUE name) 
                      from ll_ad_per_tenancy_mvw
                      where tenancy_id = p_tenancy_id
                      and region_id = p_region_id
                      order by name desc;
    v_clob  clob;
    
  
  begin
  
    open c_names;
    fetch c_names into v_clob;
    close c_names;
                               
    return(v_clob);
    
  end;
