  function available_per_ad (p_tenancy_id number, p_region_id number, p_service_name varchar2, p_limit_name varchar2, p_compartment_ocid varchar2, p_ad varchar2 default NULL ) return number is
  
    v_clob           clob;
    v_host           varchar2(4000);
    v_method         varchar2(2000);
    v_query_string   varchar2(4000);
    v_available      number;
    
  begin
  
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'limits', 
                                         p_region_key => region_key (p_region_id)); 
                                         
    v_method := '/20190729/services/{service_name}/limits/{limit_name}/resourceAvailability';
    v_method := replace(v_method,'{service_name}',p_service_name);
    v_method := replace(v_method,'{limit_name}',p_limit_name);
    
    if p_ad is not null then
      v_query_string := 'availabilityDomain='||p_ad;
    end if;
  
    v_clob := ll_pkg_exec.get( p_tenancy_id     => p_tenancy_id,
                               p_host           => v_host,
                               p_method         => v_method,
                               p_compartment_id => p_compartment_ocid,
                               p_query_string   => v_query_string );
                               
    v_available := nvl(json_value(v_clob, '$.available'),0);
    
    return(v_available);
    
  end;
