  procedure clean_compartments_recyclebin (p_tenancy_id number default null, p_recyclebin_ocid varchar2 default null, p_available_ocid varchar2 default null) is
  
  -- Every tenancy get recyclebin OCID
  -- Every recyclebin OCID list the compartments
  -- For each compartment, start job of cleaning
    cursor c_tenancies is select id, home_region, recyclebin_ocid, available_ocid
                          from ll_tenancies
                          where recyclebin_ocid is not null 
                          and available_ocid is not null
                          and (id = p_tenancy_id or p_tenancy_id is null)
                          and active_flg='Y';
--   cursor c_compartments (p_tenancy_id number, p_compartment_ocid varchar2, p_host varchar2) is 
--                             select id, name, lifecyclestate, compartmentId
--                             from json_table( ll_pkg_exec.get (p_tenancy_id     => p_tenancy_id,
--                                                               p_host           => p_host,
--                                                               p_method         => '/20160918/compartments',
--                                                               p_query_string   => 'compartmentIdInSubtree=TRUE' ),
--                                             '$[*]' COLUMNS (id, name, lifecycleState, compartmentId))
--                             where lifecyclestate <> 'DELETED'
--                             and compartmentId = p_compartment_ocid;                          
                                                                      
    v_host                varchar2(4000);      
    v_compartments_json   clob;
    v_recyclebin_ocid     varchar2(400);
    v_available_ocid      varchar2(400);
                                             
  begin
  
    ll_pkg_log.log(10,'Initial call');
    for l_tenancies in c_tenancies loop 
      if p_recyclebin_ocid is not null and p_available_ocid is not null and p_tenancy_id is not null then
        v_recyclebin_ocid := p_recyclebin_ocid;
        v_available_ocid := p_available_ocid;
      else
        v_recyclebin_ocid := l_tenancies.recyclebin_ocid;
        v_available_ocid := l_tenancies.available_ocid;
      end if;
      ll_pkg_log.log(30, 'Cleaning Tenancy: ' || l_tenancies.id || ' home region: ' || l_tenancies.home_region || ' recyclebin_ocid: '|| l_tenancies.recyclebin_ocid);
    
      v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                           p_region_key => ll_pkg_admin.region_key (p_region_id => l_tenancies.home_region) ); 
      
      ll_pkg_log.log(30, 'Connecting to Host: ' || v_host);
--     for l_compartments in c_compartments (l_tenancies.id, l_tenancies.recyclebin_ocid, v_host) loop
--          ll_pkg_admin.create_job (p_type       => 'CLEAN_COMPARTMENT', 
--                                 p_parameters => '{"P1" : ' ||l_tenancies.id||','|| 
--                                                 ' "P2" : "'||l_compartments.id||'" }',
--                                 p_jobname    => 'COMPCLEAN');
      v_compartments_json := ll_pkg_exec.get (p_tenancy_id     => l_tenancies.id,
                                              p_host           => v_host,
                                              p_method         => '/20160918/compartments',
                                              p_compartment_id => v_recyclebin_ocid,
                                              p_query_string   => 'sortBy=NAME');
      ll_pkg_log.log(40,'Compartments search result: '||v_compartments_json);                                                                
      for l_compartments in ( select id, name, lifecyclestate, compartmentId
                              from json_table( v_compartments_json, '$[*]' COLUMNS (id, name, lifecycleState, compartmentId))
                              where lifecyclestate <> 'DELETED') loop
        ll_pkg_log.log(40, 'Creating job for id: ' || l_compartments.id ||  ' compartment_id: ' || l_compartments.compartmentId || ' name: ' || l_compartments.name ||  ' tenancyid: ' || l_tenancies.id 
                                                   || ' lifecyclestate: ' || l_compartments.lifecyclestate ||', available_ocid: '||v_available_ocid);
        ll_pkg_admin.create_job (p_type       => 'CLEAN_COMPARTMENT', 
                                 p_parameters => '{"P1" : ' ||l_tenancies.id||','|| 
                                                 ' "P2" : "'||l_compartments.id||'",'||
                                                 ' "P3" : "'||v_available_ocid||'" }',
                                 p_jobname    => 'COMPCLEAN');
                                 
      end loop;
      
    end loop;
    ll_pkg_log.log(10,'End call');
  end;
