  procedure move_compartment (p_tenancy_id number, p_compartment varchar2, p_dest varchar2) is 
    cursor c_tenancy is select nvl(default_compartment_ocid, tenancy_ocid), recyclebin_ocid, available_ocid, ll_pkg_admin.region_key (p_region_id => home_region ) as region_key
                        from ll_tenancies
                        where id = p_tenancy_id;
    v_recyclebin_ocid varchar2(2000);
    v_available_ocid  varchar2(2000);
    v_default_ocid    varchar2(2000);
    v_new_ocid        varchar2(2000);
    v_region_key      varchar2(10);
    v_payload         varchar2(2000); 
    v_payload_tag    varchar2(4000);
    v_clob            clob; 
    v_clob_tag        clob;
    v_host            varchar2(2000); 
    v_method          varchar2(2000); 
    v_method_tag      varchar2(2000); 
    v_counter         number  := 0;
    v_max_retry       number;
    v_retry           varchar2(1);
    v_check           clob;
  begin 
    ll_pkg_log.log(20, 'Begin of call');
    ll_pkg_security.set_security_group;
    open c_tenancy;
    fetch c_tenancy into v_default_ocid, v_recyclebin_ocid, v_available_ocid, v_region_key;
    close c_tenancy;
    case p_dest
      when 'AVAILABLE'  then v_new_ocid := v_available_ocid;
      when 'RECYCLEBIN' then v_new_ocid := v_recyclebin_ocid;
      when 'DEFAULT'    then v_new_ocid := v_default_ocid;
      else v_new_ocid := p_dest;
    end case;
    v_payload     := json_object( 'targetCompartmentId' value v_new_ocid);
    v_payload_tag := json_object( 'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS')));
    v_host := ll_pkg_admin.oci_endpoint (p_type       => 'identity', 
                                         p_region_key => v_region_key); 
                                         
    v_method     := '/20160918/compartments/'||p_compartment||'/actions/moveCompartment'; 
    v_method_tag := '/20160918/compartments/'||p_compartment; 
    v_max_retry  := nvl(ll_pkg_admin.is_number(ll_pkg_admin.system_parameter ('MAX_COMPARTMENT_RETRY')),20);
    
    v_retry := 'Y';
    while v_retry = 'Y'  and v_counter <= v_max_retry loop
      v_clob_tag := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                         p_type       => 'PUT',
                                         p_host       => v_host,
                                         p_method     => v_method_tag,
                                         p_body       => v_payload_tag );
      
      apex_util.pause(5);
      v_check := ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,
                                     p_host       => v_host,
                                     p_method     => v_method_tag);
      if json_value(v_check, '$.compartmentId') != v_new_ocid then
        ll_pkg_log.log(30, 'Moving compartment ' || p_compartment || ' to destintaion compartment ' || p_dest);
        v_clob := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                     p_type       => 'POST',
                                     p_host       => v_host,
                                     p_method     => v_method,
                                     p_body       => v_payload );
      else
        v_clob := null;
        ll_pkg_log.log(30, 'Compartment '||p_compartment ||' already in destination compartment ' || p_dest);
      end if;
                                     
      v_counter := v_counter + 1;                                     
                                   
      ll_pkg_log.log(40, 'Result of attempt '||v_counter||' for MOVE COMPARTMENT: '||v_clob);
      
      if v_clob is not null and nvl(JSON_VALUE(v_clob,'$.message'),'X') not like 'Destination compartment is already the parent of current compartment%' then
        v_retry := 'Y';
        apex_util.pause(5);
      else
        v_retry := 'N';
      end if;
      
      if v_clob is not null and (nvl(JSON_VALUE(v_clob,'$.message'),'X') like 'Compartment rename or move in progress' or nvl(JSON_VALUE(v_clob,'$.message'),'X') like 'Internal Service Error%' or nvl(JSON_VALUE(v_clob,'$.message'),'X') like '%is currently being modified%') then
        v_retry := 'Y';
        ll_pkg_log.log(40, 'Retrying move because of : '||nvl(JSON_VALUE(v_clob,'$.message'),'X'));
        apex_util.pause(10);
      else
        v_retry := 'N';
      end if;
                  
    end loop;
    if v_clob is not null then
      ll_pkg_log.log(1,'Issue Move Compartment: v_attempts='||v_counter||', result is '||v_clob);
    --   ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR', 
    --                                     p_event      => 'Compartment Move Failure', 
    --                                     p_message    => substr('OCID: '||p_compartment||chr(10)||'Result: '||v_clob,1,1000), 
    --                                     p_priority   => 1);
      raise_application_error(-20001, 'Failed move of compartment ' || p_compartment || ' in tenancy ' || p_tenancy_id);                                  
    end if;
    ll_pkg_log.log(20, 'End of call');
                                   
  end;
--  
