--
  procedure update_compartment (p_tenancy_id number, p_compartment varchar2, p_name varchar2, p_description varchar2, p_permissions varchar2 default null, p_owner varchar2 default null, p_workshop_id varchar2 default null, p_region varchar2 default null, p_event_id varchar2 default null) is 
    v_payload_tag    varchar2(4000);
    v_payload_fix    varchar2(4000);
    v_clob_tag        clob;
    v_clob_fix        clob;
    v_name_fix        varchar2(500);
    v_host            varchar2(2000); 
    v_method_tag      varchar2(2000); 
    v_compartment_fix varchar2(2000);
    v_method_fix      varchar2(2000);
    v_update_status   varchar2(4000);
    v_attempts        number           := 0;
    v_max_retry       number;
    v_code_clob       varchar2(500);
    v_region_id       number;
    v_check           clob;
    COMPARTMENT_ALREADY_EXISTS exception;
    
  begin 
    ll_pkg_log.log(20, 'Begin of call');
    v_payload_tag := json_object( 'name'         value p_name,
                                  'description'  value p_description,
                                  'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS')),
                                  'definedTags'  value json_object( 'Livelabs'     value JSON_OBJECT( 'Owner'  value nvl(p_owner,'Empty'),
                                                                                                      'Region'            value nvl(p_region,'Empty'),
                                                                                                      'Permissions'       value nvl(p_permissions,'Empty'),
                                                                                                      'WorkshopID'  value nvl(p_workshop_id, 'Empty'),
                                                                                                      'EventID'     value nvl(p_event_id, 'Empty')
                                                                                                   )
                                                                   )
                                );
    v_host := ll_pkg_admin.oci_endpoint (p_type       => 'identity', 
                                         p_region_key => home_region_key(p_tenancy_id)); 
                                         
    v_method_tag := '/20160918/compartments/'||p_compartment; 
    v_max_retry  := nvl(ll_pkg_admin.is_number(ll_pkg_admin.system_parameter ('MAX_COMPARTMENT_RETRY')),30);
    while v_attempts < v_max_retry and (nvl(v_update_status,'X') <> 'ACTIVE' or nvl(json_value(v_check, '$.name'), 'X') != p_name) loop
      v_attempts := v_attempts + 1;
      begin
          v_check :=  ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,
                                     p_host       => v_host,
                                     p_method     => v_method_tag);
          if nvl(json_value(v_check, '$.name'), 'X') != p_name then 
              v_clob_tag := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                                 p_type       => 'PUT',
                                                 p_host       => v_host,
                                                 p_method     => v_method_tag,
                                                 p_body       => v_payload_tag );
              v_code_clob := JSON_VALUE( v_clob_tag, '$.code');
              ll_pkg_log.log(30, 'Renaming compartment ' || p_compartment);
              if (v_code_clob = 'CompartmentAlreadyExists') then
                raise COMPARTMENT_ALREADY_EXISTS;
              end if;
          else
            ll_pkg_log.log(30, 'Compartment ' || p_compartment || ' already renamed');
            v_clob_tag := '';
          end if;
      exception
            when COMPARTMENT_ALREADY_EXISTS then
                select id into v_region_id from ll_oci_regions where region_key = p_region;
                v_compartment_fix := get_compartment_ocid(p_tenancy_id, p_name, v_region_id); 
                v_method_fix := '/20160918/compartments/' || v_compartment_fix;
                v_name_fix := 'IN_USE_' || dbms_random.string('U',4);
                v_payload_fix := json_object( 'name'         value v_name_fix,
                                              'description'  value p_description,
                                              'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS'))
                                            );
                v_clob_fix := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                             p_type       => 'PUT',
                                             p_host       => v_host,
                                             p_method     => v_method_fix,
                                             p_body       => v_payload_fix );
                ll_pkg_log.log(40, 'Compartment Already Exists, renaming ' || v_compartment_fix || ' to: ' || v_payload_fix);
                ll_pkg_log.log(40, 'Result of rename ' || v_clob_fix);
                apex_util.pause(10);
      end;
                                   
      ll_pkg_log.log(40, 'Result of attempt for update COMPARTMENT '||p_name||' ('||p_compartment||'): '||v_clob_tag);
      apex_util.pause(10);
      v_check :=  ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,
                                     p_host       => v_host,
                                     p_method     => v_method_tag);
      v_update_status := JSON_VALUE( v_check, '$.lifecycleState');
      if nvl(json_value(v_check, '$.name'), 'X') != p_name or nvl(v_update_status,'X') <> 'ACTIVE' then
        ll_pkg_log.log(30, 'Compartment not renamed, try again. Attempt# '||v_attempts);
        apex_util.pause(5);
      end if;
    end loop;
    if nvl(json_value(v_check, '$.name'),'X') != p_name or nvl(v_update_status,'X') <> 'ACTIVE' then
      v_code_clob := JSON_VALUE( v_clob_tag, '$.code');
      
        ll_pkg_log.log(1,'Issue Update Compartment: v_attempts='||v_attempts||', result is '||v_clob_tag);
        -- ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR', 
        --                         p_event      => 'Compartment Update Failure', 
        --                         p_message    => substr('OCID: '||p_compartment||chr(10)||'Result: '||v_clob_tag,1,1000), 
        --                         p_priority   => 1);
        raise_application_error(-20001,'Failed update of compartment ' || p_compartment || ' in tenancy ' || p_tenancy_id);
    end if;
    ll_pkg_log.log(20, 'End of call');
                                   
  end;
