  procedure send_warning_almost_expired is
    
    cursor c_reservations is select id
                             from ll_reservations_vw
                             where sysdate between stop_gmt-( (1/24) * 0.5) and stop_gmt
                             and active_flg='Y';
                             
    cursor c_mail (p_subject varchar2) is select 'Y' as is_there
                                          from apex_mail_queue
                                          where mail_subj like '%'||p_subject||'%'
                                          and mail_message_created > sysdate - ( (1/24) * 0.50 )
                                          union
                                          select 'Y' as is_there
                                          from apex_mail_log
                                          where mail_subj like '%'||p_subject||'%'
                                          and mail_message_created > sysdate - ( (1/24) * 0.50 );
                                          
    cursor c_template is select email_subject
                         from ll_email_template
                         where phase='LEASE_ALMOST_EXPIRED'
                         and name like 'Default%';
                                          
    v_subject      varchar2(500);
    v_already_send varchar2(1);
    v_status       varchar2(1);
    v_result       varchar2(4000);
                                          
  begin
  
    open c_template;
    fetch c_template into v_subject;
    close c_template;
  
    for x in c_reservations loop
      
      open c_mail (v_subject||' ('||x.id||')');
      fetch c_mail into v_already_send;
      if c_mail%NOTFOUND then
        ll_pkg_apex.send_template_email (p_reservation_id => x.id,
                                         p_phase          => 'LEASE_ALMOST_EXPIRED',
                                         p_status         => v_status,
                                         p_result         => v_result);
      end if;
      close c_mail;
      
    end loop;
  end;
