  procedure truncate_ll_logging (p_hours number) is
  
  begin
    -- delete ll_logging where log_date < sysdate - ((1/24)*p_hours);
    -- commit;
    delete ll_logging where log_date < sysdate - ((1/24)*p_hours) and log_level <> 01;
    commit;
    if p_hours < 24 then
        delete ll_logging where log_date < sysdate - 1 and log_level = 01;
        commit;
    else
        delete ll_logging where log_date < sysdate - ((1/24)*p_hours) and log_level = 01;
        commit;
    end if;    
  end;
