  function system_parameter (p_name varchar2) return varchar2 is
  
    cursor c_parameter is select value
                          from ll_system_parameters
                          where name = p_name;
                          
    v_return_value varchar2(200);
                          
  begin
    open c_parameter;
    fetch c_parameter into v_return_value;
    if c_parameter%NOTFOUND then
      v_return_value := 'EMPTY';
    end if;
    
    return(v_return_value);
    
  end;
