--
  function cut_off_at_space (p_string varchar2, p_max_characters number) return varchar2 is
  
    v_return_string   varchar2(4000);
    v_substring       varchar2(4000);
    v_space_position  number;
  
  begin
    v_substring := substr(p_string, 1, p_max_characters);
    v_space_position := instr(v_substring,' ', -1) -1;
    
    if v_space_position <= 0 then
      v_return_string := substr(p_string,1,p_max_characters);
    else
      v_return_string := substr(p_string,1,v_space_position);
    end if;
    
    if length(p_string) <= p_max_characters then
      v_return_string := p_string;
    else
      v_return_string := v_return_string || ' (..)';
    end if;
    return(v_return_string);
  end;
