  function is_number (p_value varchar2) return number is
    v_return_val number;
  begin
    
    v_return_val := to_number(p_value);
    
    return(v_return_val);
    
  exception
    when VALUE_ERROR then
      return(null);
  end;
-- This method will return the compartment ID with the given name, tenancy, region, and parent compartment (p_compartment_id) to search
-- Unless the tenancy is given as the parent compartment, it will not search subcompartments
function get_compartment_ocid(p_tenancy_id number, p_name varchar2, p_region_id varchar2, p_compartment_id varchar2 default null) return varchar2 is
    v_clob clob;
    v_tenancy_id varchar2(300);
    v_return varchar2(300);
    begin
        if p_compartment_id is not null then 
            v_clob := ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
                                                 p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                                 p_method         => '/20160918/compartments/',
                                                 p_compartment_id => p_compartment_id,
                                                 p_query_string   => 'name='||p_name);
            v_clob := JSON_VALUE(v_clob, '$.id');
        else 
            select tenancy_ocid into v_tenancy_id from ll_tenancies where id = p_tenancy_id;
            v_clob := ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
                                                 p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                                 p_method         => '/20160918/compartments/',
                                                 p_compartment_id => v_tenancy_id,
                                                 p_query_string   => 'compartmentIdInSubtree=true&accessLevel=ANY&name='||p_name);
            v_clob := regexp_substr(v_clob,'"id":"(.*)","name"', 1,1,NULL,1);
        end if;
            return v_clob;
    end;
-- Returns the parent compartment of a given compartment ocid, region, and tenancy
function get_parent_compartment(p_tenancy_id number, p_region_id varchar2, p_compartment_id varchar2) return varchar2 is
    v_clob clob;
    begin
        v_clob := ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
                                             p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                             p_method         => '/20160918/compartments/'|| p_compartment_id);
        v_clob := JSON_VALUE(v_clob, '$.compartmentId');
        return v_clob;
    end;
    
