--
  function get_marketplace_ocid (p_tenancy_id number, p_region_id number, p_listingid varchar2, p_resourceversion varchar2, p_compartment_id varchar2) return varchar2 is
--    cursor c_is_subscribed is select listingResourceId
--                              from JSON_TABLE( ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
--                                                               p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
--                                                               p_method         => '/20160918/appCatalogSubscriptions',
--                                                               p_compartment_id => p_compartment_id,
--                                                               p_query_string   => 'listingId='||p_listingid),
--                                              '$[*]' COLUMNS (listingId, signature, listingResourceVersion, listingResourceId, compartmentId ))
--                              and   listingresourceversion = p_resourceversion;
--    cursor c_agreements is select signature, oracletermsofuselink, timeretrieved
--                           from JSON_TABLE( ll_pkg_exec.get(p_tenancy_id => p_tenancy_id, 
--                                                            p_host       => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
--                                                            p_method => '/20160918/appCatalogListings/'||p_listingid||'/resourceVersions/'||p_resourceversion||'/agreements'),
--                                             '$[*]' COLUMNS (listingId, signature, oracleTermsOfUseLink, timeRetrieved ));
                                                                                          
    v_image_ocid       varchar2(1000);  
    v_is_subscribed    varchar2(1);
    v_payload          clob;
    v_host             varchar2(2000);
    v_method           varchar2(2000);
    v_clob             clob;
    v_signature        varchar2(1000);
    v_status           varchar2(1);
    v_result           varchar2(4000);
    v_oracleterms      varchar2(2000);
    v_timeretrieved    varchar2(1000);
    v_counter          number := 0;
    v_regions          varchar2(1000);
    v_shapes           varchar2(2000);
    
    v_agreement_clob   clob;
    v_subscribed_clob  clob;
    v_subscr_entries   number;
    v_image_version    varchar2(200);
                                           
  begin
  
    ll_pkg_log.log(20,'Initial call');
    v_subscribed_clob := ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
                                         p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                         p_method         => '/20160918/appCatalogSubscriptions',
                                         p_compartment_id => p_compartment_id,
                                         p_query_string   => 'listingId='||p_listingid);
                                         
    ll_pkg_log.log(40,v_subscribed_clob);                                         
                                         
    v_subscr_entries := 0;
    
    while v_image_ocid is null and v_subscr_entries < 5 loop
      v_image_version := JSON_VALUE( v_subscribed_clob, '$['||v_subscr_entries||'].listingResourceVersion');
      ll_pkg_log.log(40,'Attempt '||v_subscr_entries||': '||p_resourceversion||' compared to '||v_image_version);
      if v_image_version = p_resourceversion then
        v_image_ocid := JSON_VALUE( v_subscribed_clob, '$['||v_subscr_entries||'].listingResourceId');
        ll_pkg_log.log(40,'OCID found ! its: '||v_image_ocid);
      end if;
      v_subscr_entries := nvl(v_subscr_entries,5)+1;
    end loop;
    
    if v_image_ocid is null then
      ll_pkg_log.log(30,'Not subscribed to image');
      v_is_subscribed := 'N';
    else
      ll_pkg_log.log(30,'We are subscribed to image');
      v_is_subscribed := 'Y';
    end if;
    
    if v_is_subscribed='N' or v_image_ocid is null then
      ll_pkg_log.log(30,'Not subscribed or image ocid is null');
      
      v_agreement_clob :=  ll_pkg_exec.get(p_tenancy_id => p_tenancy_id, 
                                           p_host       => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                           p_method => '/20160918/appCatalogListings/'||p_listingid||'/resourceVersions/'||p_resourceversion||'/agreements');
                                           
      ll_pkg_log.log(40,'Result of agreement_clob is: '||v_agreement_clob);
      
      v_signature     := JSON_VALUE( v_agreement_clob, '$.signature');
      v_oracleterms   := JSON_VALUE( v_agreement_clob, '$.oracleTermsOfUseLink');
      v_timeretrieved := JSON_VALUE( v_agreement_clob, '$.timeRetrieved');
      ll_pkg_log.log(40,'Result of JSON_VALUE is signature: '||v_signature||', oracleterms: '||v_oracleterms||', v_timeretrieved: '||v_timeretrieved);
      if v_signature is null or v_oracleterms is null or v_timeretrieved is null then
        ll_pkg_log.log(30,'No agreement found for this resource version');
        v_status := 'N';
        v_result := 'Resourceversion not found in agreements';
      else 
        ll_pkg_log.log(30,'Payload created');
        v_payload := JSON_OBJECT ('compartmentId'          value p_compartment_id,
                                  'listingId'              value p_listingid,
                                  'listingResourceVersion' value p_resourceversion,
                                  'signature'              value v_signature,
                                  'timeRetrieved'          value v_timeretrieved,
                                  'oracleTermsOfUseLink'   value v_oracleterms );
                                  
        v_host := oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id));
        v_method := '/20160918/appCatalogSubscriptions';
        
        v_clob := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,  
                                       p_type       => 'POST',
                                       p_host       => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)),
                                       p_method     => v_method,
                                       p_body       => v_payload );
        ll_pkg_log.log(30,'Payload executed, waiting 30 seconds');
        apex_util.pause(30);
        ll_pkg_log.log(30,'Continuing - Check if agreement has been processed');
      
        while v_image_ocid is null and v_counter < 10 loop
          v_subscribed_clob := ll_pkg_exec.get(p_tenancy_id     => p_tenancy_id, 
                                               p_host           => oci_endpoint (p_type => 'iaas', p_region_key => region_key(p_region_id)), 
                                               p_method         => '/20160918/appCatalogSubscriptions',
                                               p_compartment_id => p_compartment_id,
                                               p_query_string   => 'listingId='||p_listingid);
                                         
          ll_pkg_log.log(40,v_subscribed_clob);                                         
                                         
          v_subscr_entries := 0;
    
          while v_image_ocid is null and v_subscr_entries < 5 loop
            v_image_version := JSON_VALUE( v_subscribed_clob, '$['||v_subscr_entries||'].listingResourceVersion');
            ll_pkg_log.log(40,'Attempt '||v_subscr_entries||': '||p_resourceversion||' compared to '||v_image_version);
            if v_image_version = p_resourceversion then
              v_image_ocid := JSON_VALUE( v_subscribed_clob, '$['||v_subscr_entries||'].listingResourceId');
              ll_pkg_log.log(40,'OCID found ! its: '||v_image_ocid);
            end if;
            v_subscr_entries := nvl(v_subscr_entries,5)+1;
          end loop;
        
          if v_image_ocid is null then
            ll_pkg_log.log(30,'Still not subscribed, waiting 15 seconds');
            apex_util.pause(15);
            v_counter := v_counter + 1;
            ll_pkg_log.log(30,'End of wait, lets try again');
          end if;
        end loop;
                                       
      end if;
    end if;
    
    ll_pkg_log.log(20,'End of call');
    return(v_image_ocid);
  
  end;
