--
  procedure send_eventcode_overview (p_ec_id number) is
    cursor c_ec       is select * from ll_vouchers_vw where id = p_ec_id;
    cursor c_ec_users is select rank() over (order by id) as users_rank, owner1, date_entered, ll_pkg_admin.get_country (owner1) as country 
                         from ll_voucher_users 
                         where voucher_id = p_ec_id order by 1;
    
    v_message        clob;
    v_subtext        clob;
    v_counter        number  := 0;
    v_subject        varchar2(200);
    v_to             varchar2(200);
    v_status         varchar2(1);
    v_result         varchar2(2000);
    v_marketing_code varchar2(200);
  begin
  
    for x in c_ec loop
    
      v_to := x.email_creator || case when x.email_requestor is not null then ','||x.email_requestor end;
      v_subject := 'Livelabs Event - '||case when x.reason is not null then x.reason||' (ID:'||x.id||')' 
                      else 'ID '||x.id end;
      v_marketing_code := JSON_VALUE(x.event_json,'$.EventTcValue');
  
      v_message := ll_pkg_admin.email_default_header('before')||
                   'Dear colleague,<br><br>Your LiveLabs Event is ';
      
      if sysdate > x.valid_to_gmt then
        v_message := v_message || 'in <b>CLOSED</b>';
      elsif sysdate between x.valid_from_gmt and x.valid_to_gmt then
        v_message := v_message || 'still in <b>OPEN</b>';
      elsif sysdate < x.valid_from_gmt then
        v_message := v_message || 'in <b>PREPARE</b>';
      end if;
      
      v_message := v_message || ' state. <br><br>'||
                   '<table style="text-align: left; width=100%;" border="0" cellpadding="2" cellspacing="0">'||
                   case when x.reason is not null then
                   '<tr><td>Event Name</td><td>:</td><td><b>'||x.reason||' (ID: '||x.id||')</b></td></tr>'
                   else
                   '<tr><td>Event ID</td><td>:</td><td><b>'||x.id||'</b></td></tr>' end||
                  '<tr><td>Start date</td><td>:</td><td><b>'||to_char(x.valid_from,'Day DD Month')||' midnight ('||x.valid_timezone||')</b></td></tr>'||
                  '<tr><td>End date</td><td>:</td><td><b>'||to_char(x.valid_to,'Day DD Month')||' midnight ('||x.valid_timezone||')</b></td></tr>'||
                  case when v_marketing_code is not null then
                  '<tr><td>Marketing Code</td><td>:</td><td><b>'||v_marketing_code||'</b></td></tr>' end ||
                  '<table><br>';
      v_message := v_message || 'At the time of generation of this report, <b>'||x.users_registered||'</b> user'||
                     case x.users_registered when 1 then ' has' else 's have' end || ' entered the LiveLabs Event Code.<br><br>';
      
      -- Piece of numbers for people using LL environments
      
      v_subtext := 'Below is a detailed list of users who registered the Event Code in the LiveLabs system:<br><br>';
      
      v_subtext := v_subtext || '<table style="text-align: left; width=100%;" border="1" cellpadding="5" cellspacing="0"><tr><td>&nbsp</td><td><b>Email Domain</b></td><td><b>Country</b></td><td><b>Date Registered</b></td></tr>';
      
      for y in c_ec_users loop
        v_counter := v_counter + 1;
        v_subtext := v_subtext || '<tr><td>'||y.users_rank||'</td><td>'||lower(substr(y.owner1, instr(y.owner1, '@')+1, length(y.owner1)))||'</td><td>'||y.country||'</td><td>'||to_char(y.date_entered,'DD-MON-YYYY HH24:MI:SS')||' GMT</td></tr>';
        if v_counter > 30 or ((length(v_message) + length(v_subtext)) > 5000) then
           exit;
        end if;
      end loop;
      
      v_subtext := v_subtext || '</table><br>';
      
      if v_counter > 30 or ((length(v_message) + length(v_subtext)) > 5000) then
        v_subtext := v_subtext || 'This is not the complete list of users. For a more complete list, please email livelabs-help-db_us@oracle.com.<br>';
      end if;
      if v_counter > 0 then
        v_message := v_message || v_subtext;
      end if;
      
      v_message := v_message || 'If you have questions, please contact the LiveLabs team using the slack channel #workshop-authors-help.<br><br>Kind regards,<br>The LiveLabs team<br>'||
                   ll_pkg_admin.email_default_header('after');
      
    end loop;
    begin
        send_email (p_to        => v_to,
                    p_subject   => v_subject,
                    p_body_html => v_message,
                    p_status    => v_status,
                    p_result    => v_result);
    exception
        when others then 
            ll_pkg_log.log(1, 'Event Code Email failed to send');
    end;
    
    
  end;
  
