  procedure send_eventcode_overviews is
  
    cursor c_ec is select id, valid_from_gmt, valid_to_gmt
                   from ll_vouchers_vw v
                   left join ( -- Querying for the events that have had new users since 7 days ago
                        select distinct voucher_id
                        from ll_voucher_users
                        where date_entered + 7 > sysdate
                   ) u on u.voucher_id = v.id
                   where valid_from_gmt < sysdate
                   and (    (valid_to_gmt < sysdate and nvl(last_overview_send,valid_to_gmt-1) < valid_to_gmt) -- EC ended but no last overview send
                         or (valid_to_gmt > sysdate and nvl(last_overview_send, valid_from_gmt) + 7 < sysdate and voucher_id is not null) --Long running EC, still open, weekly overview, must have had new user(s) in past week
                       );
  begin
    for x in c_ec loop
      send_eventcode_overview (p_ec_id => x.id);
      update ll_vouchers set last_overview_send=sysdate where id=x.id;
    end loop;
    commit;
  end;
