  procedure setup_default_jobs (p_code varchar2) is
  
  begin
  
    if p_code='LiveLabsRulez' then
      ll_pkg_admin.create_job( p_type => 'EVERY10MIN', p_parameters => null, p_jobname => 'E10MIN', p_repeat => 'FREQ=MINUTELY; BYSECOND=0; INTERVAL=10');
      ll_pkg_admin.create_job( p_type => 'EVERY1HOUR', p_parameters => null, p_jobname => 'E1HOUR', p_repeat => 'FREQ=HOURLY; BYMINUTE=2');
      ll_pkg_admin.create_job( p_type => 'EVERY1DAY', p_parameters => null, p_jobname => 'E1DAY', p_repeat => 'FREQ=DAILY; BYHOUR=17; BYMINUTE=6');
      ll_pkg_admin.create_job( p_type => 'BACKUP', p_parameters => '{"P1":9133}', p_jobname => 'BACKUP', p_repeat => 'FREQ=HOURLY; BYMINUTE=15; INTERVAL=2');
    end if;
  end;
