  function ad_name( p_tenancy_id number, p_region_id number, p_ad number) return varchar2 is
  
    cursor c_region is select ad_prefix||':'||ad_name||p_ad
                       from ll_oci_regions llor, ll_tenancies llt
                       where llt.id = p_tenancy_id
                       and llor.id = p_region_id;
    
    v_return_value     varchar2(100);
    
  begin
  
    ll_pkg_log.log(20,'Initial call');
    
    open c_region;
    fetch c_region into v_return_value;
    if c_region%NOTFOUND then
      ll_pkg_log.log(30,'No AD Name found.');
      ll_pkg_log.log(40,'Tenancy ID='||p_tenancy_id||', Region ID='||p_region_id||', AD number='||p_ad);
    end if;
    close c_region;
    
    return(v_return_value);
    ll_pkg_log.log(20,'End of call');
  end;
