--  ##     ## ##     ## ##    ## ##       ##     ##       ##  ##       ##   ### ##    ## ##     ## ##     ## ##       
--  ########  ##     ##  ######  ########  #######        ##  ######## ##    ##  ######   #######  ########  ########
--
  function base64encode(p_blob IN BLOB) RETURN CLOB is 
    v_clob CLOB;
    v_step PLS_INTEGER := 1200; -- make sure you set a multiple of 3 not higher than 24573
  begin
    for x IN 0 .. trunc((DBMS_LOB.getlength(p_blob) - 1 )/v_step) loop
      v_clob := v_clob || UTL_RAW.cast_to_varchar2(UTL_ENCODE.base64_encode(DBMS_LOB.substr(p_blob, v_step, x * v_step + 1)));
    end loop;
    v_clob := replace(v_clob,'\r\n','');
    v_clob := replace(v_clob,chr(10),'');
    v_clob := replace(v_clob,chr(13),'');
    
    return(v_clob);
  end;
