  function get_country (p_app_user varchar2) return varchar2 is
    cursor c_system_parameters is select name, value
                                  from ll_system_parameters
                                  where name in ('LDAP_HOST','LDAP_PORT','LDAP_USER','LDAP_PASSWORD');
    v_ldap_host     VARCHAR2(100); -- := 'wwldap.oracle.com';
    v_user_dn       VARCHAR2(100); -- := 'cn=livelabs_us,l=amer,dc=oracle,dc=com';
    v_user_pw       VARCHAR2(100); -- := '****';
    v_ldap_port     NUMBER       ; -- := 636;
    v_use_ssl       VARCHAR2(100) := 'Y';
    v_search_base   VARCHAR2(100) := 'dc=oracle,dc=com';
    v_country       VARCHAR2(100);
  begin
    for x in c_system_parameters loop
      case x.name
        when 'LDAP_HOST'     then v_ldap_host := x.value;
        when 'LDAP_PORT'     then v_ldap_port := x.value;
        when 'LDAP_USER'     then v_user_dn   := 'cn='||x.value||',l=amer,dc=oracle,dc=com';
        when 'LDAP_PASSWORD' then v_user_pw   := ll_pkg_security.decrypt(x.value);
      end case;
    end loop;
  
    begin 
      select val into v_country
      from TABLE ( apex_ldap.search( p_host            => v_ldap_host,
                                     p_username        => v_user_dn,
                                     p_pass            => v_user_pw,
                                     p_port            => v_ldap_port,
                                     p_use_ssl         => v_use_ssl,
                                     p_search_base     => v_search_base,
                                     p_search_filter   =>'&(mail='||apex_escape.ldap_search_filter(p_app_user)||')(objectclass=inetorgperson)',
                                     p_attribute_names => 'c'));
      exception
        when OTHERS then null;
      end;                                     
    return(upper(v_country));
  end;
 
