  procedure stress_test_build (p_workshop_id number, p_prefix varchar2, p_num_environments number, p_delay number default 0, p_start_number number default 1, p_ssh_key varchar2 default null) is
    cursor c_reservations is select id 
                             from ll_reservations_vw llr
                             where reason='Stresstest'
                             and owner1 like 'STRESS-'||p_prefix||'%'
                             and not exists (select null from ll_reservation_steps llrs where llrs.reservation_id = llr.id);
												  
      v_dummy varchar2(1);								
								
    begin
      ll_pkg_log.log(10,'Initial Call');
      -- Setup the security group 
      ll_pkg_security.set_security_group;
      -- Setup the ll_reservations lines
      for x in p_start_number..p_start_number+p_num_environments-1 loop
        insert into ll_reservations (REASON, OWNER1, WORKSHOP_ID, START_DATE, START_TIMEZONE, ACTIVE_FLG, PUBLIC_KEY) 
                                     values
                                    ('Stresstest', replace('STRESS-'||p_prefix||'-'||to_char(x,'000'),' ',''), p_workshop_id, sysdate, 'GMT', 'Y', p_ssh_key);
        commit;                                    
      end loop;
      -- Initiate the build and run process 
      for x in c_reservations loop
        ll_pkg_admin.create_job (p_type        => 'CREATE_AND_PROCESS_RES',
                                 p_parameters  => json_object( 'P1' value x.id),
    			                       p_jobname     => 'SETUP'||x.id,
                                 p_start_date  => sysdate + (nvl(p_delay,0) / 60 /60 / 24));
        commit;
                                          
      end loop;
  end;
-- 
-- ===============================================================================
--
  procedure stress_test_destroy (p_prefix varchar2) is
    cursor c_reservations is select id, stop_date
                             from ll_reservations_vw llr 
                             where owner1 like 'STRESS-'||p_prefix||'%' 
                             and exists (select null
                                         from ll_reservation_steps llrs
                                         where llrs.reservation_id = llr.id
                                         and delete_order is not null
                                         and (delete_success is null or (delete_success = 'N' and delete_retry < 5)))
                             for update of stop_date;
                                         
    v_status varchar2(1);
    v_result varchar2(400);
                                         
  begin
  
    for x in c_reservations loop
      ll_pkg_log.log(20,'Create job for object clean reservation '||x.id, x.id);
      if x.stop_date is null then
        update ll_reservations set stop_date=sysdate where current of c_reservations;
        commit;
      end if;
      ll_pkg_admin.create_job (p_type        => 'CLEAN_RES_OBJECTS',
                               p_parameters  => json_object('P1' value x.id),
                               p_jobname     => replace('CLEANOBJ_'||x.id,' ',''));
    end loop;
    commit;                               
  end;
