  function limit_definitions_query (p_tenancy_id number, p_servicename varchar2 default null) return varchar2 is 
    v_query   varchar2(4000);
    v_host    varchar2(500) ;
  begin
    v_host := oci_endpoint( 'limits', home_region_key (p_tenancy_id));
    v_query := 'select NAME,SERVICENAME,DESCRIPTION,SCOPETYPE,AREQUOTASSUPPORTED,ISRESOURCEAVAILABILITYSUPPORTED '||
               'from JSON_TABLE (ll_pkg_exec.get( '||
                      'p_tenancy_id => '||p_tenancy_id||', '||
                      'p_host       => '||chr(39)||v_host||chr(39)||', '||
                      'p_method     => '||chr(39)||'/20190729/limitDefinitions'||chr(39)||'),'||
                    chr(39)||'$[*]'||chr(39)||' COLUMNS (name, serviceName, description, scopeType, areQuotasSupported, isResourceAvailabilitySupported)) '||
                    'where 1=1 ';
    if p_servicename is not null then
      v_query := v_query || 'and servicename = '||chr(39)||p_servicename||chr(39)||' ';
    end if;                    
    return(v_query);
  end;   
