  function home_region_key (p_tenancy_id number) return varchar2 is
    cursor c_tenancy is select lloc.region_key 
                        from ll_tenancies llt, ll_oci_regions lloc 
                        where lloc.id = llt.home_region
                        and llt.id = p_tenancy_id;
    v_return_value varchar2(100);
