  procedure delete_reservation_steps is
    v_days     number;
  begin
    v_days := ll_pkg_admin.system_parameter('RES_STEPS_HISTORY_DAYS');
    if v_days < 60 then
      v_days := 60;
    end if;
    delete ll_reservation_steps where ( create_date < sysdate-v_days and 
                                        ( (create_success is null) or
                                          (create_success='Y' and delete_success='Y') or
                                          (create_success='Y' and delete_order is null) ))
                                      or create_date < sysdate-365;
    commit;
  end;
