  procedure pause (p_seconds number) is
    v_iteration    number;
    v_seconds_left number;
    v_max_seconds  number := 120;
  begin
    v_seconds_left := mod(p_seconds, v_max_seconds);
    v_iteration := (p_seconds-v_seconds_left)/v_max_seconds;
  
    for x in 1..v_iteration loop
      apex_util.pause(v_max_seconds);
    end loop;
    apex_util.pause(v_seconds_left);
  end;
