--
  function distance_country_dc (p_country_code varchar2, p_region_id number) return number is
    cursor c_region is select latitude, longitude from ll_oci_regions where id = p_region_id;
    cursor c_country is select latitude, longitude from ll_countries where country_code=p_country_code;
    v_distance          number;
    v_retrieval_error   varchar2(1)   := 'N';
    v_region_latitude   number(10,6);
    v_region_longitude  number(10,6);
    v_country_latitude  number(10,6);
    v_country_longitude number(10,6);
  begin
    
    open c_region;
    fetch c_region into v_region_latitude, v_region_longitude;
    if c_region%NOTFOUND then
      v_retrieval_error := 'Y';
    end if;
    close c_region;
    if v_retrieval_error = 'N' then
      open c_country;
      fetch c_country into v_country_latitude, v_country_longitude;
      if c_country%NOTFOUND then
        v_retrieval_error := 'Y';
      end if;
      close c_country;
    end if;
    if v_retrieval_error ='N' then
      v_distance := sdo_geom.sdo_distance(         --  longitude,  Latitude 
                                            sdo_geometry(2001, 4326, sdo_point_type(v_country_longitude, v_country_latitude, null), null, null),
                                            sdo_geometry(2001, 4326, sdo_point_type(v_region_longitude, v_region_latitude, null), null, null),
                                            0.01,
                                            'unit=KM' );
    else
      v_distance := -1;
    end if;
    return(v_distance);
  end;
