procedure yum_repo_endpoints as
  cursor c_regions is select region_identifier, 'yum-'||region_identifier||'.oracle.com' as yum_url from ll_oci_regions;
  cursor c_static_cidrs (p_region in varchar2) is select 'Y' from LL_OCI_DEFAULT_CIDRS where region = p_region;
  v_source       varchar2(1000) := 'https://dns-lookup5.p.rapidapi.com/simple';
  v_recordtype   varchar2(1)    := 'A';
  v_url          varchar2(1000);
  v_clob         clob;
  v_ip           varchar2(100);
  v_exists       varchar2(1);
  
begin
  apex_web_service.g_request_headers.delete(); 
  apex_web_service.g_request_headers(1).name := 'x-rapidapi-host'; 
  apex_web_service.g_request_headers(1).value := 'dns-lookup5.p.rapidapi.com';
  apex_web_service.g_request_headers(2).name := 'x-rapidapi-key'; 
  apex_web_service.g_request_headers(2).value := '4f21533ce1msh5460413c9ef2336p1a0e05jsn145f8bcd023e'; 
  for x in c_regions loop
    v_url := v_source || '?domain='||x.yum_url||'&recordType=A';
  
    v_clob := APEX_WEB_SERVICE.MAKE_REST_REQUEST(
                      p_url            => v_url,
                      p_http_method    => 'GET');-- p_proxy_override => 'appoci-proxy01-vip.oraclevcn.com'
    v_ip := json_value(v_clob,'$.records[0].data');
    commit;
    apex_util.pause(1); -- The Free account for the rapidapi only allows 1 request per second.
    if v_ip is not null then
      open c_static_cidrs(x.region_identifier);
      fetch c_static_cidrs into v_exists;
      if c_static_cidrs%NOTFOUND then
        v_exists := 'N';
      end if;
      close c_static_cidrs;
      if v_exists = 'N' then
        insert into LL_OCI_DEFAULT_CIDRS (region, hostname, cidr, tag, protocol) values (x.region_identifier, x.yum_url, v_ip, 'YUM', 'TCP');
      else
        update LL_OCI_DEFAULT_CIDRS set cidr=v_ip where hostname = x.yum_url;
      end if;
    end if;
  end loop;
  dbms_mview.refresh('LL_OCI_SERVICE_CIDRS_MVW');
end;
