procedure generate_sitemap is
    v_xml               CLOB;
    v_domain            varchar2(100);
    v_host              varchar2(100);
    v_workspace         varchar2(100);
    v_obj_name          varchar2(100);
    v_endpoint_host     varchar2(300);
    v_result            clob;
    v_tenancy           number;
    v_username          varchar2(100);
    v_auth_token        varchar2(100);
    v_namespace         varchar2(100);
    v_region_identifier varchar2(100);
    v_proxy             varchar2(100);
    v_bucketname       varchar2(100);
    v_region_key        varchar2(10);
    v_env               varchar2(10);
    BEGIN
        ll_pkg_security.set_security_group;
        select id into v_tenancy from ll_tenancies where lower(tenancy_name) like '%c4u02%';
        v_region_key := 'IAD';
        v_endpoint_host := ll_pkg_admin.oci_endpoint( p_type => 'objectstorage', p_region_key => v_region_key);
        v_xml := '<?xml version="1.0" encoding="UTF-8"?>' || CHR(10) ||
                   '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' || CHR(10);
          
        select value into v_env from ll_system_parameters where name = 'ENV';
        SELECT WORKSPACE into v_workspace FROM APEX_WORKSPACES where rownum = 1;
        v_bucketname := 'LiveLabs-Markdown-Bucket';

        if v_env = 'DEV' then
            v_domain := 'https://livelabs-dev.oracle.com/ords/r/dbpm/livelabs/view-workshop?wid=';
            v_obj_name := 'files/stg_sitemap.xml';
        elsif v_env = 'STAGE' then
            v_domain := 'https://livelabs-stg.oracle.com/ords/r/dbpm/livelabs/view-workshop?wid=';
            v_obj_name := 'files/dev_sitemap.xml';
        else
            v_domain := 'https://livelabs.oracle.com/pls/apex/r/dbpm/livelabs/view-workshop?wid=';
            v_obj_name := 'files/sitemap.xml';
        end if;

        FOR r IN (
            SELECT v_domain || id AS loc, TO_CHAR(CREATED_DATE, 'YYYY-MM-DD') AS lastmod
            FROM ll_workshops
            WHERE active_flg = 'Y' 
        ) LOOP
        v_xml := v_xml ||
            '  <url>' || CHR(10) ||
            '    <loc>' || r.loc || '</loc>' || CHR(10) ||
            '    <lastmod>' || r.lastmod || '</lastmod>' || CHR(10) ||
            '    <changefreq>monthly</changefreq>' || CHR(10) ||
            '    <priority>0.8</priority>' || CHR(10) ||
            '  </url>' || CHR(10);
        END LOOP;

        v_xml := v_xml || '</urlset>';

        for x in (select name, value from ll_system_parameters
                  where name in ('BACKUP_USERNAME', 'BACKUP_PASSWORD','BACKUP_NAMESPACE','BACKUP_REGION_IDENTIFIER','BACKUP_PROXY')) loop
          case x.name
            when 'BACKUP_USERNAME' then v_username := x.value;
            when 'BACKUP_PASSWORD' then v_auth_token := ll_pkg_security.decrypt(x.value);
            when 'BACKUP_NAMESPACE' then v_namespace := x.value;
            when 'BACKUP_REGION_IDENTIFIER' then v_region_identifier := x.value;
            when 'BACKUP_PROXY' then v_proxy := x.value;
          end case;
        end loop;

        v_endpoint_host := 'https://swiftobjectstorage.'||v_region_identifier||'.oraclecloud.com/v1/'||v_namespace||'/'||v_bucketname||'/'||v_obj_name;

        ll_pkg_log.log(30,'Second Endpoint host is '||v_endpoint_host);
        ll_pkg_log.log(30,'Size of v_xml '||length(v_xml));

        apex_web_service.g_request_headers.delete();
        apex_web_service.g_request_headers(1).name := 'content-type'; 
        apex_web_service.g_request_headers(1).value := 'application/xml'; 

        -- proxy should be null from system params 
        v_result := apex_web_service.make_rest_request (
            p_url               => v_endpoint_host,
            p_http_method       => 'PUT',
            p_username          => v_username,
            p_password          => v_auth_token,
            p_proxy_override    => v_proxy,
            p_body              => v_xml);

    END;
    
    function subscribed_regions(p_tenancy_id number) return clob is
        v_clob              clob;
        v_host              varchar2(4000);
        v_method            varchar2(2000);
        v_tenancy_ocid      varchar2(200);
        v_region_key        number;
        v_tenancy_id        number;
    begin
        v_tenancy_id := p_tenancy_id;
        select tenancy_ocid into v_tenancy_ocid from ll_tenancies where id = v_tenancy_id; 
        select home_region into v_region_key from ll_tenancies where id = v_tenancy_id; 
     
        v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                             p_region_key => ll_pkg_admin.region_key(v_region_key)); 
                                             
        v_method := '/20160918/tenancies/{tenancyId}/regionSubscriptions';
        v_method := replace(v_method, '{tenancyId}', v_tenancy_ocid);
        
        v_clob := ll_pkg_exec.get(p_tenancy_id => v_tenancy_id, p_host => v_host, p_method => v_method);
        return v_clob;
    end;
     

END LL_PKG_ADMIN;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_AI" AS

    -- -------------------------------------------------------------------------
    -- Returns a VECTOR embedding for the given text using the configured
    -- APEX Vector Provider (multilingual_e5_small_model).
    -- -------------------------------------------------------------------------
    FUNCTION get_embedding (p_text IN clob) RETURN VECTOR IS
    BEGIN
        RETURN apex_ai.get_vector_embeddings(
            p_value             => p_text,
            p_service_static_id => ll_pkg_admin.system_parameter('DATABASE_VECTOR_PROVIDER')
        );
    END get_embedding;
   

    FUNCTION get_search_embedding (p_text IN clob) RETURN VECTOR IS
        v_clean clob;
    BEGIN
        -- remove non-alphanumeric and non-dash characters 
        v_clean := REGEXP_REPLACE(p_text, '[^A-Za-z0-9 -]', ' ');
        -- make multiple dashes into 1 dash
        v_clean := REGEXP_REPLACE(v_clean, '-{2,}', '-');
        -- remove multiple whitespace for single whitespace
        v_clean := trim(REGEXP_REPLACE(v_clean, '\s+', ' '));
        -- substr to at most 200 chars
        v_clean := substr(v_clean, 1, 200);
        RETURN apex_ai.get_vector_embeddings(
            p_value             => v_clean,
            p_service_static_id => ll_pkg_admin.system_parameter('DATABASE_VECTOR_PROVIDER')
        );
    END get_search_embedding;

    -- -------------------------------------------------------------------------
    -- Calls the OCI GenAI Llama 3.3 service to generate a natural language
    -- answer grounded in the provided workshop context (RAG).
    -- -------------------------------------------------------------------------
    FUNCTION ai_search_response (
        p_query   IN VARCHAR2,
        p_context IN CLOB
    ) RETURN CLOB IS

        l_system_prompt VARCHAR2(4000) :=
            'You are a helpful assistant for Oracle LiveLabs, a free workshop platform. ' ||
            'A user has submitted a search query and you have been provided with the most ' ||
            'semantically relevant workshops and sprints from the catalog. ' ||

            'Workshops are in-depth, multi-step learning experiences typically lasting 1 or more hours. ' ||
            'Sprints are short, focused guides that answer a single specific question or task. ' ||
            'LiveStacks are collections of workshops and related materials, intended to guide a user from demo to deployment or provide a learning path. ' ||

            'Your job is to: ' ||
            '1. Briefly answer or acknowledge the user''s intent in 1-2 sentences. ' ||
            '2. Recommend the most appropriate content from what you have been given, ' ||
            '   prioritizing Workshops or LiveStacks for broad or learning-focused queries and Sprints for ' ||
            '   specific how-to questions. Explain why each recommendation fits the user''s needs. ' ||
            '3. Keep your response concise, friendly, and focused on the content given. ' ||
            'Do not invent workshops, LiveStacks, sprints, or details that are not in the provided context. ' ||
            'If none of the provided content is a good match, say so honestly. ' ||

            'Your response should be in HTML format. Do not add any CSS styling, but use div, span, or p tags as needed. You can also use ul and li tags if needed.' ||

            'Anytime you reference a LiveStack, workshop, or sprint, hyperlink it with HTML using the Content URL provided in the context. ' ||
            'Do not include the content ID in displayed text as a part of the HTML. Only use the ID in links. ' ||

            'You are a response on a search page, so act as if speaking to the user in second person. ' ||
            'If the query is broad or asks for a guided path, focus your recommendation on LiveStacks and Workshops. ' ||
            'If the query is a specific task or how-to question, Sprints may be the best answer. ' ||
            'If multiple types are relevant, recommend the most useful ones from each. ' ||
            'If there are additional relevant results beyond those you mention, note that more LiveStacks, workshops, and sprints are available in the other region below.';

        l_user_prompt CLOB;

    BEGIN
        l_user_prompt :=
            'User Query: ' || p_query                             || CHR(10) ||
            CHR(10)                                                          ||
            'Relevant LiveLabs Catalog Content:'                  || CHR(10) ||
            p_context                                             || CHR(10) ||
            CHR(10)                                                          ||
            'Please provide a helpful response based only on the catalog content above.';

        RETURN apex_ai.generate(
            p_prompt             => l_user_prompt,
            p_system_prompt      => l_system_prompt,
            p_service_static_id  => ll_pkg_admin.system_parameter('GEN_AI_MODEL_PROVIDER'),
            p_temperature        => to_number(ll_pkg_admin.system_parameter('GEN_AI_MODEL_TEMP'))
        );

    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'AI response unavailable at this time. Please use the keyword search below.';
    END ai_search_response;


    -- -------------------------------------------------------------------------
    -- Main entry point: embeds the query, runs vector similarity search against
    -- the workshops table, builds RAG context, and returns the AI answer plus
    -- the ordered list of matching workshop IDs.
    --
    -- NOTE: Adjust the table name, vector column, and context columns below
    --       to match your actual workshops table schema.
    -- -------------------------------------------------------------------------
    PROCEDURE search_workshops_ai (
        p_query        IN  VARCHAR2,
        p_ai_answer    OUT CLOB,
        p_workshop_ids OUT SYS.ODCINUMBERLIST
    ) IS

        c_top_k        CONSTANT PLS_INTEGER := 6;

        l_query_vector VECTOR;
        l_context      CLOB := '';

    BEGIN
        p_workshop_ids := SYS.ODCINUMBERLIST();

        -- 1. Embed the user query using the configured vector provider
        l_query_vector := get_search_embedding(p_query);

        -- 2. Vector similarity search — update table/column names as needed
        FOR rec IN (
            WITH catalog_matches AS (
                SELECT
                    w.id AS content_id,
                    w.name,
                    w.desc_long,
                    w.desc_short,
                    CASE
                      WHEN nvl(json_value(w.workshop_json, '$.SprintEnabled'), 'N') = 'Y'
                      THEN 'Sprint'
                      ELSE 'Workshop'
                    END AS content_type,
                    'WORKSHOP' AS source_type,
                    'https://livelabs.oracle.com/ords/r/dbpm/livelabs/view-workshop?wid=' || w.id AS content_url,
                    MIN(VECTOR_DISTANCE(v.embedding, l_query_vector, COSINE)) AS distance
                FROM
                    ll_workshops w
                    INNER JOIN ll_workshop_vectors v ON v.workshop_id = w.id
                WHERE
                    w.active_flg = 'Y'
                GROUP BY
                    w.id,
                    w.name,
                    w.desc_long,
                    w.desc_short,
                    CASE
                      WHEN nvl(json_value(w.workshop_json, '$.SprintEnabled'), 'N') = 'Y'
                      THEN 'Sprint'
                      ELSE 'Workshop'
                    END,
                    'WORKSHOP',
                    'https://livelabs.oracle.com/ords/r/dbpm/livelabs/view-workshop?wid=' || w.id

                UNION ALL

                SELECT
                    ls.id AS content_id,
                    ls.name,
                    ls.desc_long,
                    ls.desc_short,
                    'LiveStack' AS content_type,
                    'LIVESTACK' AS source_type,
                    'https://livelabs.oracle.com/ords/r/dbpm/livelabs/livestack-landing-page?p400_id=' || ls.id AS content_url,
                    MIN(VECTOR_DISTANCE(v.embedding, l_query_vector, COSINE)) AS distance
                FROM
                    ll_livestacks_vw ls
                    INNER JOIN ll_livestack_vectors v ON v.livestack_id = ls.id
                WHERE
                    ls.active_flg = 'Y'
                GROUP BY
                    ls.id,
                    ls.name,
                    ls.desc_long,
                    ls.desc_short,
                    'LiveStack',
                    'LIVESTACK',
                    'https://livelabs.oracle.com/ords/r/dbpm/livelabs/livestack-landing-page?p400_id=' || ls.id
            )
            SELECT
                content_id,
                name,
                desc_long,
                desc_short,
                content_type,
                source_type,
                content_url,
                distance
            FROM catalog_matches
            ORDER BY distance ASC
            FETCH FIRST c_top_k ROWS ONLY
        ) LOOP
            -- Collect result keys in ranked order. LiveStacks are encoded as negative IDs.
            p_workshop_ids.EXTEND;
            p_workshop_ids(p_workshop_ids.COUNT) :=
                CASE
                    WHEN rec.source_type = 'LIVESTACK' THEN -rec.content_id
                    ELSE rec.content_id
                END;

            -- Build RAG context block for this catalog item.
            l_context := l_context
                || 'Title: '             || rec.name                     || CHR(10)
                || 'Type: '              || rec.content_type             || CHR(10)
                || 'Content ID: '        || rec.content_id               || CHR(10)
                || 'Content URL: '       || rec.content_url              || CHR(10)
                || 'Short Description: ' || nvl(rec.desc_short, 'N/A')   || CHR(10)
                || 'Long Description: '  || NVL(rec.desc_long, 'N/A')    || CHR(10)
                || '---'                                                 || CHR(10);
        END LOOP;

        -- 3. Generate the AI answer using the retrieved context
        IF p_workshop_ids.COUNT > 0 THEN
            p_ai_answer := ai_search_response(
                p_query   => p_query,
                p_context => l_context
            );
        ELSE
            p_ai_answer := 'No workshops were found matching your query. '
                        || 'Try different keywords or browse the catalog below.';
        END IF;


    EXCEPTION
        WHEN OTHERS THEN
            p_ai_answer    := 'An error occurred during AI search: ' || SQLERRM;
            p_workshop_ids := SYS.ODCINUMBERLIST();
    END search_workshops_ai;



    FUNCTION format_ctx_query(p_query IN VARCHAR2) RETURN VARCHAR2 IS
    l_words   APEX_T_VARCHAR2;
    l_result  VARCHAR2(4000) := '';
    l_clean   VARCHAR2(4000);
    BEGIN
        IF p_query IS NULL OR TRIM(p_query) IS NULL THEN
            RETURN NULL;
        END IF;

        -- Strip Oracle Text special characters first
        l_clean := REGEXP_REPLACE(p_query, '[&|!();,\-]', ' ');
        l_words  := APEX_STRING.SPLIT(TRIM(l_clean), ' ');

        -- wrap each word in brackets to make search fuzzy 
        FOR i IN 1..l_words.COUNT LOOP
            IF TRIM(l_words(i)) IS NOT NULL THEN
                l_result := l_result
                            || CASE WHEN l_result IS NOT NULL THEN ' OR ' END
                            || '{' || TRIM(l_words(i)) || '}';
            END IF;
        END LOOP;
        if l_result = '' then
            return null;
        else
            RETURN l_result;
        end if;
    END format_ctx_query;



    FUNCTION BUILD_WORKSHOP_CLOB(
        p_name       IN VARCHAR2,
        p_desc_short IN VARCHAR2,
        p_desc_long  IN VARCHAR2
    ) RETURN CLOB AS
        v_result CLOB := '';
    BEGIN
        v_result := v_result || 'Title: '             || NVL(p_name,       'N/A') || CHR(10);
        v_result := v_result || 'Short Description: ' || NVL(p_desc_short, 'N/A') || CHR(10);
        v_result := v_result || 'Long Description: '  || NVL(p_desc_long,  'N/A') || CHR(10);
        RETURN v_result;
    END BUILD_WORKSHOP_CLOB;




    FUNCTION CHUNK_TEXT(
        p_content   IN CLOB,
        p_max_words IN NUMBER DEFAULT -1,
        p_overlap   IN NUMBER DEFAULT -1
    ) RETURN VECTOR_ARRAY_T AS
        v_chunk_params VARCHAR2(500);
        v_max_words number;
        v_overlap number;
    BEGIN
        if p_max_words = -1 then 
            v_max_words := to_number(ll_pkg_admin.system_parameter('EMBED_MAX_WORDS'));
        else
            v_max_words := p_max_words;
        end if;
        if p_overlap = -1 then
            v_overlap := to_number(ll_pkg_admin.system_parameter('EMBED_OVERLAP'));
        else
            v_overlap := p_overlap;
        end if;
        
        v_chunk_params := JSON_OBJECT(
            'by'        VALUE 'words',
            'max'       VALUE TO_CHAR(v_max_words),
            'overlap'   VALUE TO_CHAR(v_overlap),
            'split'     VALUE 'sentence',
            'language'  VALUE 'american',
            'normalize' VALUE 'all'
        );

        RETURN DBMS_VECTOR.UTL_TO_CHUNKS(
            DATA   => p_content,
            PARAMS => json(v_chunk_params)
        );
    END CHUNK_TEXT;
    


    FUNCTION VECTORIZE_CHUNKS(
        p_chunks IN VECTOR_ARRAY_T,
        p_model  IN VARCHAR2 DEFAULT NULL
    ) RETURN VECTOR_ARRAY_T AS
        v_params VARCHAR2(200);
        v_model varchar2(4000);
    BEGIN
        if p_model is null then 
            v_model := ll_pkg_admin.system_parameter('DATABASE_EMBEDDING_MODEL');
        else
            v_model := p_model;
        end if;
        v_params := JSON_OBJECT('provider' VALUE 'database', 'model' VALUE v_model);

        RETURN DBMS_VECTOR.UTL_TO_EMBEDDINGS(
            DATA   => p_chunks,
            PARAMS => json(v_params)
        );
    END VECTORIZE_CHUNKS;
    


    PROCEDURE VECTORIZE_WORKSHOP(
        p_workshop_id IN NUMBER,
        p_name        IN VARCHAR2,
        p_desc_short  IN VARCHAR2,
        p_desc_long   IN VARCHAR2,
        p_model       IN VARCHAR2 DEFAULT NULL,
        p_max_words   IN NUMBER   DEFAULT -1,
        p_overlap     IN NUMBER   DEFAULT -1
    ) AS
        v_combined   CLOB;
        v_chunks     VECTOR_ARRAY_T;
        v_embeddings VECTOR_ARRAY_T;
        v_chunk_json CLOB;
        v_embed_json CLOB;
        v_chunk_text VARCHAR2(4000);
        v_chunk_id   NUMBER;
        v_embedding  VECTOR;
        v_model      varchar2(4000);
    BEGIN
        if p_model is null then 
            v_model := ll_pkg_admin.system_parameter('DATABASE_EMBEDDING_MODEL');
        else
            v_model := p_model;
        end if;
        -- Step 1: Build the combined CLOB
        v_combined := BUILD_WORKSHOP_CLOB(p_name, p_desc_short, p_desc_long);

        -- Step 2: Chunk the CLOB
        v_chunks := CHUNK_TEXT(v_combined, p_max_words, p_overlap);

        -- Step 3: Vectorize all chunks in one batch call
        v_embeddings := VECTORIZE_CHUNKS(v_chunks, v_model);

        -- Step 4: Delete existing vectors for this workshop
        DELETE FROM ll_workshop_vectors WHERE workshop_id = p_workshop_id;

        -- Step 5: Insert chunk text + embedding together
        -- v_chunks and v_embeddings are parallel arrays indexed by chunk_id
        FOR i IN 1 .. v_chunks.COUNT LOOP
            v_chunk_json := v_chunks(i);
            v_embed_json := v_embeddings(i);

            SELECT JSON_VALUE(v_chunk_json, '$.chunk_id'      RETURNING NUMBER),
                   JSON_VALUE(v_chunk_json, '$.chunk_data'    RETURNING VARCHAR2(4000))
            INTO v_chunk_id, v_chunk_text
            FROM DUAL;

            -- embed_vector is a CLOB in the embeddings array output
            SELECT TO_VECTOR(JSON_VALUE(v_embed_json, '$.embed_vector' RETURNING CLOB))
            INTO v_embedding
            FROM DUAL;

            INSERT INTO ll_workshop_vectors (workshop_id, chunk_index, chunk_text, embedding)
            VALUES (p_workshop_id, v_chunk_id, v_chunk_text, v_embedding);
        END LOOP;

    END VECTORIZE_WORKSHOP;
    
    PROCEDURE VECTORIZE_LIVESTACK (
        p_livestack_id IN NUMBER,
        p_name        IN VARCHAR2,
        p_desc_short  IN VARCHAR2,
        p_desc_long   IN VARCHAR2,
        p_model       IN VARCHAR2 DEFAULT NULL,
        p_max_words   IN NUMBER   DEFAULT -1,
        p_overlap     IN NUMBER   DEFAULT -1
    ) AS
        v_combined   CLOB;
        v_chunks     VECTOR_ARRAY_T;
        v_embeddings VECTOR_ARRAY_T;
        v_chunk_json CLOB;
        v_embed_json CLOB;
        v_chunk_text VARCHAR2(4000);
        v_chunk_id   NUMBER;
        v_embedding  VECTOR;
        v_model      varchar2(4000);
    BEGIN
        if p_model is null then 
            v_model := ll_pkg_admin.system_parameter('DATABASE_EMBEDDING_MODEL');
        else
            v_model := p_model;
        end if;
        -- Step 1: Build the combined CLOB
        v_combined := BUILD_WORKSHOP_CLOB(p_name, p_desc_short, p_desc_long);

        -- Step 2: Chunk the CLOB
        v_chunks := CHUNK_TEXT(v_combined, p_max_words, p_overlap);

        -- Step 3: Vectorize all chunks in one batch call
        v_embeddings := VECTORIZE_CHUNKS(v_chunks, v_model);

        -- Step 4: Delete existing vectors for this workshop
        DELETE FROM LL_LIVESTACK_VECTORS WHERE livestack_id = p_livestack_id;

        -- Step 5: Insert chunk text + embedding together
        -- v_chunks and v_embeddings are parallel arrays indexed by chunk_id
        FOR i IN 1 .. v_chunks.COUNT LOOP
            v_chunk_json := v_chunks(i);
            v_embed_json := v_embeddings(i);

            SELECT JSON_VALUE(v_chunk_json, '$.chunk_id'      RETURNING NUMBER),
                   JSON_VALUE(v_chunk_json, '$.chunk_data'    RETURNING VARCHAR2(4000))
            INTO v_chunk_id, v_chunk_text
            FROM DUAL;

            -- embed_vector is a CLOB in the embeddings array output
            SELECT TO_VECTOR(JSON_VALUE(v_embed_json, '$.embed_vector' RETURNING CLOB))
            INTO v_embedding
            FROM DUAL;

            INSERT INTO LL_LIVESTACK_VECTORS (livestack_id, chunk_index, chunk_text, embedding)
            VALUES (p_livestack_id, v_chunk_id, v_chunk_text, v_embedding);
        END LOOP;

    END VECTORIZE_LIVESTACK;
    

END "LL_PKG_AI";
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_APEX" as
-- Generate banners with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE 
 
/* 
  LOG levels 
 
   1 = Serious errors 
  10 = Start and stop of high level packages 
  20 = Start and stop of subroutines 
  30 = Steps inside subroutines 
  40 = Details steps inside subroutes (contains values) 
  50 = Start and stop of REST statements to OCI (exec_get etc) 
  60 = Detailed steps of REST commands 
  70 = Sign steps for REST commands 
  80 = Sign details (contains values) 
*/ 
--
--        ##    ###    ##     ##    ###     ######   ######  ########  #### ########  ########          ######   #######  ##     ## ##    ## ######## ########   #######  ##      ## ##    ## 
--        ##   ## ##   ##     ##   ## ##   ##    ## ##    ## ##     ##  ##  ##     ##    ##            ##    ## ##     ## ##     ## ###   ##    ##    ##     ## ##     ## ##  ##  ## ###   ## 
--        ##  ##   ##  ##     ##  ##   ##  ##       ##       ##     ##  ##  ##     ##    ##            ##       ##     ## ##     ## ####  ##    ##    ##     ## ##     ## ##  ##  ## ####  ## 
--        ## ##     ## ##     ## ##     ##  ######  ##       ########   ##  ########     ##            ##       ##     ## ##     ## ## ## ##    ##    ##     ## ##     ## ##  ##  ## ## ## ## 
--  ##    ## #########  ##   ##  #########       ## ##       ##   ##    ##  ##           ##            ##       ##     ## ##     ## ##  ####    ##    ##     ## ##     ## ##  ##  ## ##  #### 
--  ##    ## ##     ##   ## ##   ##     ## ##    ## ##    ## ##    ##   ##  ##           ##            ##    ## ##     ## ##     ## ##   ###    ##    ##     ## ##     ## ##  ##  ## ##   ### 
--   ######  ##     ##    ###    ##     ##  ######   ######  ##     ## #### ##           ##    #######  ######   #######   #######  ##    ##    ##    ########   #######   ###  ###  ##    ## 
--
    
   function javascript_countdown (p_hours_remaining number, p_id varchar2, p_text varchar2 default null, p_expired_text varchar2 default null, p_action varchar2 default null) return varchar2 is 
    v_javascript_clock varchar2(4000);
    v_remaining        number;
    v_h_remaining      number;
    v_m_remaining      number;
    v_s_remaining      number;
   begin
    if nvl(p_hours_remaining,5/60) < 0 then
      v_remaining := 5/60;
    else
      v_remaining := p_hours_remaining;
    end if;
    v_h_remaining := trunc(v_remaining);
    v_m_remaining := (v_remaining - v_h_remaining) * 60;
    v_s_remaining := (v_m_remaining - trunc(v_m_remaining)) * 60; 
    v_javascript_clock := '// Set the date were counting down to'||chr(10)||
                          'var countDownDate = new Date();'||chr(10)||
                          'countDownDate.setHours(countDownDate.getHours() + '||v_h_remaining||' );'||chr(10)||
                          'countDownDate.setMinutes(countDownDate.getMinutes() + '||trunc(v_m_remaining)||' );'||chr(10)||
                          'countDownDate.setSeconds(countDownDate.getSeconds() + '||trunc(v_s_remaining)||' );'||chr(10)||
                          '// Update the count down every 1 second'||chr(10)||
                          'var x = setInterval(function() {'||chr(10)||
                          '// Get todays date and time'||chr(10)||
                          'var now = new Date().getTime();'||chr(10)||
                          '// Find the distance between now and the count down date'||chr(10)||
                          'var distance = countDownDate - now;'||chr(10)||
                          '// Time calculations for days, hours, minutes and seconds'||chr(10)||
                          'var days = Math.floor(distance / (1000 * 60 * 60 * 24));'||chr(10)||
                          'var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));'||chr(10)||
                          'var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));'||chr(10)||
                          'var seconds = Math.floor((distance % (1000 * 60)) / 1000);'||chr(10)||
                          '// Output the result in an element with id="demo"'||chr(10)||
                          'document.getElementById("'||p_id||'").innerHTML = "'||nvl(p_text,'<B>Time Remaining:</b>')||' "';
    if trunc(v_h_remaining/24) > 0 then v_javascript_clock := v_javascript_clock ||' + days + "d " '; end if;
    if mod(v_h_remaining,24) * 24 > 0 or trunc(v_h_remaining/24) > 0 then v_javascript_clock := v_javascript_clock || '+ hours + "h " '; end if;
    v_javascript_clock := v_javascript_clock ||'+ minutes + "m " + seconds + "s ";'||chr(10)||
                          '// If the count down is over, write some text '||chr(10)||
                          'if (distance < 0) {'||chr(10)||
                          'clearInterval(x);'||chr(10);
    if p_action = 'REFRESH' then
      v_javascript_clock := v_javascript_clock || 'location.reload();'||chr(10);
    else
      v_javascript_clock := v_javascript_clock || 'document.getElementById("'||p_id||'").innerHTML = "'||nvl(p_expired_text,'EXPIRED')||'";'||chr(10);
    end if;
    v_javascript_clock := v_javascript_clock || '  } '||chr(10)||
                          '}, 1000);'||chr(10);
    return(v_javascript_clock);                          
   end;
   procedure display_javascript_clock (p_res_id number) is
        v_time number;
        v_hold varchar2(4000);
    begin
        v_time := ll_pkg_reservation.time_remaining(p_reservation_id => p_res_id);
        v_hold := javascript_countdown(p_hours_remaining => v_time, p_id => 'demo');
        htp.script(v_hold, 'Javascript');
    end;
