  procedure display_attendee_details (p_reservation_id number, p_attendee_id number default 1) is
    cursor c_requires is select nvl(llr.description, llr.name) || ' (' || llwr.num_required || 'x ) ' as description
                         from ll_workshop_requires llwr, ll_resources llr, ll_reservations llres
                         where llwr.resource_id = llr.id
                         and llwr.workshop_id = llres.workshop_id
                         and llres.id = p_reservation_id;
    cursor c_novnc is select JSON_VALUE(workshop_json,'$.NoVNC') as novnc 
                      from ll_reservations llr, ll_workshops llw
                      where llr.workshop_id = llw.id
                      and llr.id = p_reservation_id;
    cursor c_res_steps (p_type varchar2) is select flow_step_result, nvl(JSON_VALUE(flow_step_param, '$.param1'),JSON_QUERY(flow_step_param, '$.param1'))  as param1, flow_step_param
                                            from ll_reservation_steps
                                            where JSON_VALUE(flow_step_param,'$.type') = p_type
                                            and reservation_id = p_reservation_id;
    cursor c_tf_variables (p_tf_id number) is select variable_name, variable_source
                                              from ll_tf_script_variables
                                              where tf_script_id = p_tf_id
                                              order by variable_name;
                         
    v_tenancy_name     varchar2(200);
    v_tenancy_id       number;
    v_login_url        varchar2(200);
    v_username         varchar2(1000);
    v_password         varchar2(1000);
    v_compartment      varchar2(1000);
    v_compartment_ocid varchar2(1000);
    v_region           varchar2(1000);
    v_region_id        varchar2(200);
    v_remaining        varchar2(200);
    v_instances        varchar2(4000);
    v_t_remaining      number;
    v_h_remaining      number;
    v_m_remaining      number;
    v_s_remaining      number;
    
    v_quota              varchar2(4000);
    v_running_clock      varchar2(4000);
    v_javascript_clock   varchar2(4000);
    v_search_parameter   varchar2(200);
    v_search_result      varchar2(500);
    v_novnc_password     varchar2(4000);
    v_novnc_enabled      varchar2(4000);
    v_novnc_url          varchar2(4000);
    v_auth_token         varchar2(100);
    
    v_html         clob;
    
    procedure print_line (p_description varchar2, p_value varchar2, p_id varchar2) is
    begin
      if substr(p_value,1,5) <> 'Error' then
        htp.p('<tr><td style="vertical-align: top;"><b>'||p_description||'</b></td>'||
              '<td style="vertical-align: top;">:</td>'||
              '<td style="width:auto; vertical-align: top;" id="'||p_id||'">');
              htp.p(p_value);
        if p_id is not null then
          htp.p('<span style="margin-left:20px;color:#446672"><button id="ll_'||p_id||'" type="button" style="width:150px; background-color:white;border:dotted; border-width: 1px; font-size: 12px; font-weight: light;" '||
                'onclick="copyToClipboard('||chr(39)||p_value||chr(39)||')"><span class="fa fa-copy" style="vertical-align:middle"></span>&nbsp;Copy '||p_id||'</button></span>');
        end if;
              
        htp.p('</td></tr>');
      end if;
      
    end;
  begin
    v_tenancy_id := ll_pkg_admin.is_number(ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id));
    v_tenancy_name := ll_pkg_reservation.tenancy_name(p_tenancy_id => v_tenancy_id); 
    v_login_url    := ll_pkg_admin.oci_endpoint( p_type => 'console', p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    
    v_username    := ll_pkg_reservation.user_object_name (p_reservation_id => p_reservation_id,
                                                          p_param_type     => 'ociUser');
    v_password    := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,
                                                          p_param_type     => 'ociUserPassword');
                                                          
    v_compartment := ll_pkg_reservation.user_object_name (p_reservation_id => p_reservation_id,
                                                          p_param_type     => 'ociCompartment');
                                                          
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,
                                                               p_param_type     => 'ociCompartment');
    v_novnc_password := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,
                                                               p_param_type     => 'NoVncPassword');


    v_auth_token := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,
                                                         p_param_type     => 'ociUserAuthToken');

    v_region      :=   ll_pkg_admin.region_name (p_region_key => ll_pkg_reservation.region_key(p_reservation_id));
    v_region_id    := ll_pkg_admin.region_identifier_with_key (p_region_key => ll_pkg_reservation.region_key(p_reservation_id));
    
    v_remaining := ll_pkg_admin.hours_readable (p_hours   => ll_pkg_reservation.time_remaining (p_reservation_id => p_reservation_id),
                                                p_size    => 'LONG', 
                                                p_add_and => 'Y');
    v_t_remaining := ll_pkg_reservation.time_remaining (p_reservation_id => p_reservation_id);
    v_javascript_clock :=  javascript_countdown (p_hours_remaining => v_t_remaining, p_id => 'demo');
    v_running_clock := '<p id="demo"></p>';
                                                
    for x in c_requires loop
      v_quota := v_quota || x.description || '<br>';
    end loop;
    open c_novnc;
    fetch c_novnc into v_novnc_enabled;
    if c_novnc%NOTFOUND then
      v_novnc_enabled := 'N';
    end if;
    close c_novnc;
    for x in c_res_steps ('ociInstance') loop
      v_instances := v_instances || '<tr>'||
                     '<td>'||JSON_VALUE(x.flow_step_result,'$.publicIp')||'</td>'||
                     '<td>&nbsp;</td>'||
                     '<td>'||JSON_VALUE(x.flow_step_result,'$.displayname')||'</td>';
      if nvl(v_novnc_enabled,'N') = 'Y' and JSON_VALUE(x.param1,'$.novnc_enabled') = 'Y' then
        v_novnc_url := 'http://'||JSON_VALUE(x.flow_step_result,'$.publicIp')||':6080/vnc.html?password='||v_novnc_password||'&resize=scale&quality=9&autoconnect=true';
      end if;
      
      v_instances := v_instances || '<td>'||initcap(JSON_VALUE(x.flow_step_result,'$.livecyclestate'))||'</td></tr>';
    end loop;
    
    if v_instances is not null then
      v_instances := '<table role=presentation style="text-align: left; table-layout: auto; border-collapse: collapse;" border="0" cellpadding="2" cellspacing="0"><tbody>' ||
                     v_instances ||
                     '</table>';
    end if;
    htp.p('<script>function copyToClipboard(text) { var dummy = document.createElement('||chr(39)||'textarea'||chr(39)||'); dummy.value = text; '||
          'document.body.appendChild(dummy); dummy.select(); document.execCommand("copy"); document.body.removeChild(dummy); } </script>');
    htp.p('<table role=presentation style="text-align: left; table-layout: auto; border-collapse: collapse;" border="0" cellpadding="3" cellspacing="0"><tbody>');
    if substr(v_username,1,5) <> 'Error' then
      htp.p('<tr><td><b>Login URL</b></td><td>:</td><td style="width:auto"><a href="'||
            'https://'||v_login_url||'&tenant='||v_tenancy_name||'&username='||v_username||'" target="_blank">'||
            'https://'||v_login_url||'&tenant='||v_tenancy_name||'&username='||v_username||'');
                   
      htp.p('<span style="margin-left:20px;color:white; "><a type="button" style="width:150px; color:white; '||
            'background-color:#759C6C;border:none; border-width: 1px; padding:3px 20px 3px 0px;font-size: 12px; font-weight: bold;" '||
            'href="' || 'https://'||v_login_url||'&tenant='||v_tenancy_name||'&username='||v_username|| '" target="_blank"  '||
            'class="button"><span class="fa fa-cloud-user" style="vertical-align:middle; padding-left:20px;"></span>&nbsp;Launch Console</a>');
      htp.p('</td><td></td></tr>');
      print_line('Tenancy name        ',v_tenancy_name, null);
      print_line('Region              ',CONCAT(CONCAT(CONCAT(v_region,' ('),v_region_id), ')')      , null);
      print_line('User name           ',v_username    , null);
      print_line('Initial password    ',apex_escape.html(v_password)    ,'Password');
      print_line('Compartment         ',v_compartment ,null);
      print_line('Compartment OCID    ',v_compartment_ocid, 'OCID');
      if (v_auth_token not like 'Error%') then
        print_line('User Auth Token    ',v_auth_token, 'OCID');
      end if;
    end if;
    if v_instances is not null then
      print_line('Instances', v_instances, null);
    end if;
    if  v_novnc_url is not null then
      print_line('Remote Desktop', '<a href="'||v_novnc_url||'" target="_blank">'||v_novnc_url||'</a>', null);
    end if;
    
    -- If there is a Terraform script, retrieve the variables that need to be displayed on the screen
    for x in c_res_steps ('ociTfCheckStatus') loop
      for y in c_tf_variables(x.param1) loop
        v_search_parameter := '$.'||y.variable_source||'.value';
        v_search_result := JSON_QUERY(x.flow_step_result, v_search_parameter);
        v_search_result := replace(v_search_result,'[','');
        v_search_result := replace(v_search_result,']','');
        v_search_result := replace(v_search_result,'"','');
        if substr(v_search_result,1,4) = 'http' then
          v_search_result := '<a href="'||v_search_result||'" target="_blank">'||v_search_result||'</a>';
          print_line(y.variable_name, v_search_result , null);
        elsif v_search_result is not null then
          print_line(y.variable_name, v_search_result , 'value');
        end if;
      end loop;
    end loop;
        
    if ll_pkg_admin.system_parameter('DISPLAY_ATTENDEE_QUOTA') = 'TRUE' then
      print_line('Resources allocated ',v_quota       ,null);
    end if;
    htp.p('</tbody></table>');
    htp.script (v_javascript_clock, 'Javascript');
       
  end;
