  procedure send_template_email (p_reservation_id IN number, p_phase IN varchar2, p_status OUT varchar2, p_result  OUT varchar2) is
  
    cursor c_template (p_workshop_id number) is 
                         select email_html, email_subject
                         from ll_email_template llet
                         where exists (select null
                                       from ll_workshop_emails llwe
                                       where workshop_id = p_workshop_id
                                       and llwe.email_template_id = llet.id)
                         and phase = p_phase;
    cursor c_default is select email_html, email_subject
                         from ll_email_template llet
                         where name like 'Default%'
                         and phase = p_phase;
    cursor c_reservation is select  llr.owner1, llr.workshop_id, llr.start_gmt, llr.stop_gmt, llr.start_timezone
                            from ll_reservations_vw llr
                            where llr.id = p_reservation_id ;
                            
    cursor c_workshop (p_workshop_id number) is 
                         select name, time_available
                         from ll_workshops
                         where id = p_workshop_id;
                            
    v_body_html  clob;
    v_subject    varchar2(200);
    v_to         varchar2(200);
    
    v_owner1         varchar2(100);
    v_owner2         varchar2(100);
    v_workshop_id    varchar2(100);
    v_ws_name        varchar2(200);
    v_time_available varchar2(200);
    v_start_gmt      date;
    v_stop_gmt       date;
    v_timezone       varchar2(100);
    
    v_before     varchar2(4000)  := ll_pkg_admin.email_default_header('before');
    v_after      varchar2(4000)  := ll_pkg_admin.email_default_header('after');
    
  begin
  
    open c_reservation;
    fetch c_reservation into v_owner1, v_workshop_id, v_start_gmt, v_stop_gmt, v_timezone;
    close c_reservation;
    open c_workshop (v_workshop_id);
    fetch c_workshop into v_ws_name, v_time_available;
    close c_workshop;
    open c_template (v_workshop_id);
    fetch c_template into v_body_html, v_subject;
    close c_template;
      
    if v_body_html is null or v_subject is null then
      open c_default;
      fetch c_default into v_body_html, v_subject;
      close c_default;
    end if;
      
    v_body_html := v_before || v_body_html || v_after;
    v_body_html := replace(v_body_html,'{reservation_id}', to_char(p_reservation_id,'9999000'));
    v_body_html := replace(v_body_html,'{workshop_name}' , ll_pkg_admin.cut_off_at_space (v_ws_name, 50) );
    v_body_html := replace(v_body_html,'{workshop_start_dt}', LL_PKG_RESERVATION.date_full(p_start_gmt => v_start_gmt, p_timezone => v_timezone));
    v_body_html := replace(v_body_html,'{workshop_end_dt}', LL_PKG_RESERVATION.date_full(p_start_gmt => v_stop_gmt, p_timezone => v_timezone));
    v_body_html := replace(v_body_html,'{time_remaining}', ll_pkg_admin.hours_readable((v_stop_gmt - sysdate) * 24, 'LONG', 'Y')) ;
      
    v_to := v_owner1 || case nvl(v_owner2,'XX') when 'XX' then null else ','||v_owner2 end;
    v_subject := v_subject || ' ('||p_reservation_id||')';
    if instr(v_to,'@') = 0 then
      v_to := 'livelabs-support_us@oracle.com';
    end if;
  
    ll_pkg_admin.send_email (p_to        => v_to,
                             p_subject   => v_subject,
                             p_body_html => v_body_html,
                             p_status    => p_status,
                             p_result    => p_result );
                               
  end;
