function url_replace (p_string clob) return clob as
v_string clob := p_string;
begin
v_string := replace(v_string, '\u002F', '/');
v_string := replace(v_string, '\u0026', '&');
v_string := replace(v_string, '''+''', '');
v_string := replace(v_string, '{', '''{');
v_string := replace(v_string, '}', '}''');
return v_string;
end;
  function my_reservation_links( p_workshop_id number, p_reservation_id number, p_status varchar2, p_voucher_code varchar2 default null ) return clob as
  
    v_edit   clob := '<a href="' || APEX_PAGE.GET_URL (
            p_page        => 320,
            p_clear_cache => 320,
            p_items       => 'P320_ID',
            p_values      => p_reservation_id) 
            || '"><span class="fa fa-calendar-edit"></span>Edit Reservation</a>';
   v_view   clob := '<a href="' || APEX_PAGE.GET_URL (
            p_page        => 180,
            p_clear_cache => 180,
            p_items       => 'WID',
            p_values      => p_workshop_id)
            || '"><span class="fa fa-list-alt"></span>Details</a>';
   v_view_voucher   clob := '<a href="' || APEX_PAGE.GET_URL (
            p_page        => 180,
            p_clear_cache => 180,
            p_items       => 'WEC',
            p_values      => p_voucher_code)
            || '"><span class="fa fa-list-alt"></span>Details</a>';
            --&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 
    v_delete clob := '<a onclick="'|| url_replace(substr(APEX_PAGE.GET_URL (
            p_page        => 350,
            p_clear_cache => 350,
            p_items       => 'P350_ID',
            p_values      => p_reservation_id), 12))
            || ';"><span class="fa fa-trash-o"></span>Remove</a>';
 
    v_attend clob := '<a href="' || APEX_PAGE.GET_URL (
            p_page        => 200,
            p_clear_cache => 200,
            p_items       => 'P200_ID',
            p_values      => p_reservation_id)
            || '"><span class="fa fa-cloud-user"></span>Launch Workshop</a>';
    
    v_return_value  clob;
  
  begin
  
    if p_status in ('Scheduled') then
      v_return_value := v_return_value || v_edit;
    end if;
    
    if p_status in ('Available') then
      v_return_value := v_return_value || v_attend;
    end if;
    
--    if p_status in ('Available','Scheduled', 'Pending creation' ) then
--      v_return_value := v_return_value || v_delete;
--    end if;
    
    if p_status in ('Completed', 'Terminating', 'Available', 'Scheduled', 'Pending creation') then
      if p_voucher_code is not null then
        v_return_value := v_return_value || v_view_voucher;
      else
        v_return_value := v_return_value || v_view;     
      end if;
    end if;
    
    if p_status in ('Available','Scheduled', 'Completed' ) then --or v_return_value is null then
      v_return_value := v_return_value || v_delete;
    end if;
    return(v_return_value);
  
  end;
