  function requires_pub_key (p_workshop_id number, p_event_id number default null) return varchar2 is
  
    cursor c_ws_images is select nvl(pubkey_req,'Y')
                          from ll_images
                          where id in (select image_id 
                                      from ll_workshop_images
                                      where workshop_id = p_workshop_id);
    cursor c_terraform is select nvl(ssh_key_req,'N') 
                          from ll_tf_scripts 
                          where id in ( select parameters
                                        from ll_workshop_flow
                                        where workshop_id = p_workshop_id
                                        and step_id = (select id 
                                                       from ll_flow_steps 
                                                       where step_code='ociTerraform'));
    cursor c_preprov is select 'N'
                            from ll_reservations_vw r 
                            where r.voucher_id = p_event_id
                                and r.owner1 = (select voucher_code from ll_vouchers where id = p_event_id)||'@LIVELABS.COM' 
                                and r.start_gmt < sysdate 
                                and r.stop_gmt > sysdate 
                                and r.active_flg = 'Y' 
                                and (select count(*) from ll_reservation_steps where reservation_id = r.id) > 0 
                                and (select count(*) from ll_reservation_steps where reservation_id = r.id and create_order is not null and create_success='N') = 0 fetch first 1 rows only;                   
    
    v_return_value varchar2(1);
    
  begin
  
    open c_ws_images;
    fetch c_ws_images into v_return_value;
    if c_ws_images%notfound then
      v_return_value := 'N';
    end if;
    close c_ws_images;
    if v_return_value='N' then
      open c_terraform;
      fetch c_terraform into v_return_value;
      if c_terraform%NOTFOUND then
        v_return_value := 'N';
      end if;
    end if;

    -- don't need ssh key if workshop is pre-provisioned 
    if v_return_value = 'Y' and p_event_id is not null then 
       open c_preprov;
       fetch c_preprov into v_return_value;
       if c_preprov%notfound then 
            v_return_value := 'Y';
       end if;
       close c_preprov;
    end if;   

    return(v_return_value);
    
  end;
