  function user_last_timezone (p_app_user varchar2) return varchar2 is
  
    cursor c_tz is select start_timezone
                   from ll_reservations
                   where id = (select max(id)
                               from ll_reservations
                               where owner1 = p_app_user);
                               
    v_return_val  varchar2(100);
    
  begin
    open c_tz;
    fetch c_tz into v_return_val;
    if c_tz%NOTFOUND then
      v_return_val := 'US/Pacific';
    end if;
    close c_tz;
    
    return(v_return_val);
  end;
