  function reservation_status (p_reservation_id number) return varchar2 is
  
    cursor c_reservation is select * 
                            from ll_reservations_vw
                            where id = p_reservation_id;
                            
    cursor c_reservation_steps is select sum(case create_success when 'Y' then 1 else 0 end) as create_success,
                                         sum(case create_success when 'N' then 1 else 0 end) as create_error,
                                         sum(case when create_success is null then create_seconds else 0 end) as seconds_left,
                                         sum(case when JSON_VALUE(flow_step_param,'$.type')='CustomWaitSeconds' then to_number(JSON_VALUE(flow_step_param,'$.param1')) else 0 end) as CustomWaitSeconds,
                                         max(case when create_success in ('Y','W') then create_date else null end) as last_succes_date
                                  from ll_reservation_steps llrs, ll_flow_steps llfs 
                                  where llrs.flow_step_id = llfs.id
                                  and llrs.reservation_id = p_reservation_id;
    cursor c_Terraform_steps is select sum(nvl(max_duration_minutes/60/24,0) - (case when llrs.create_date is not null then sysdate - llrs.create_date else 0 end))*60*60*24 seconds_left
                                from ll_reservation_steps llrs, ll_tf_scripts llts
                                where JSON_VALUE( llrs.flow_step_param,'$.type') = 'ociTfCheckStatus'
                                and JSON_VALUE( llrs.flow_step_param,'$.param1') = llts.id
                                and nvl(llrs.create_success,'N') <> 'Y'
                                and llrs.reservation_id = p_reservation_id;                                
    v_create_percentage     number;
    v_delete_percentage     number;
    v_return_val            varchar2(4000);
    v_javascript_clock      varchar2(4000);
    v_running_clock         varchar2(200);
    v_t_remaining           number;
    v_real_remaining        number;
    v_tf_remaining          number;
                                  
  begin
    for l_res in c_reservation loop
      for l_step in c_reservation_steps loop
        if l_res.stop_gmt < sysdate then
          v_return_val := 'Completed';
        elsif sysdate between l_res.start_gmt and l_res.stop_gmt and l_step.seconds_left > 0 then
          open c_terraform_steps;
          fetch c_terraform_steps into v_tf_remaining;
          close c_terraform_steps;
          v_t_remaining := l_step.seconds_left + l_step.CustomWaitSeconds + nvl(v_tf_remaining,0);
          v_real_remaining := (l_step.last_succes_date + (nvl(v_t_remaining,0)/60/60/24)) - sysdate;
          v_return_val := 'Estimated Time Remaining: ' || ll_pkg_admin.hours_readable(nvl(v_real_remaining*24, 5/60), 'SHORT');
        --   v_real_remaining := v_real_remaining *24;
        --   v_javascript_clock :=  javascript_countdown (p_hours_remaining => v_real_remaining, 
        --                                                p_id => 'setup_remaining', 
        --                                               p_text => 'Estimated remaining setup time:', 
        --                                               p_expired_text => 'Please refresh page for details',
        --                                               p_action => 'REFRESH');
        --   v_running_clock := '<span id="setup_remaining"></span>';
        --   v_return_val := v_running_clock || chr(10) || '<script>'||v_javascript_clock||'</script>';
        elsif sysdate between l_res.start_gmt and l_res.stop_gmt and l_step.seconds_left = 0 then
          v_return_val := 'Available';
        elsif sysdate between l_res.start_gmt and l_res.stop_gmt then
        --   v_return_val := 'Pending creation <div class="pending_creation"></div>';
        v_return_val := 'Pending creation';
        elsif l_res.start_gmt > sysdate then
          v_return_val := 'Scheduled';
        else
          v_return_val := 'Unknown status';
        end if;
      end loop;
    end loop;
    
    return(v_return_val);
    
  end;
