--  ##        ##     ## ##     ## ##     ## ######## ######## ######## ########    ##     ## ########  ######  ######## ##     ##    ###    ##     ##    ##    ####  #######  ##    ##
--
  function parallel_reservation (
    p_res_id number, 
    p_owner varchar2, 
    p_start_date date, 
    p_start_time varchar2, 
    p_start_timezone varchar2,
    p_event_id number default null
    ) return varchar2 is

    cursor c_reservations (p_start_gmt date) is
        select voucher_id
        from ll_reservations_vw
        where p_start_gmt between start_gmt and stop_gmt
        and owner1 = p_owner
        and active_flg='Y'
        and id <> nvl(p_res_id,-1)
        and (ll_pkg_security.am_i_allowed(
               p_apex_user => SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 
               p_access_type => 'PARALLEL', 
               p_access_value => 'ALLOWED') <> 'Y');

    v_return_value    varchar2(1);
    v_voucher_id      number;
    v_start_gmt       date;
    v_reservation_count number := 0;

  begin
    ll_pkg_log.log(20,'Initial call');

    if p_start_date is null then
        v_start_gmt := sysdate;
        ll_pkg_log.log(30,'Using sysdate as start_date is empty');
    else
        v_start_gmt := ll_pkg_reservation.date_gmt(
                         p_date => p_start_date, 
                         p_time => p_start_time, 
                         p_timezone => p_start_timezone);
        ll_pkg_log.log(30,'Using start_date as it is not empty');
        ll_pkg_log.log(40,'Start date is '||to_char(p_start_date,'DD-MM-YYYY HH24:MI:SS'));
    end if;

    ll_pkg_log.log(40,'Start date GMT is '||to_char(v_start_gmt,'DD-MM-YYYY HH24:MI:SS'));

    -- Check all parallel reservations
    open c_reservations(v_start_gmt);
    loop
        fetch c_reservations into v_voucher_id;
        exit when c_reservations%notfound;

        v_reservation_count := v_reservation_count + 1;

        -- If more than one reservation exists, block
        if v_reservation_count > 1 then
            v_return_value := 'Y';
            ll_pkg_log.log(30,'Multiple parallel reservations found - blocking');
            exit;
        end if;

        -- If exactly one reservation and either is not an event, block
        if v_voucher_id is null or p_event_id is null then
            v_return_value := 'Y';
            ll_pkg_log.log(30,'Parallel reservation found (non-event scenario)');
            exit;
        end if;
    end loop;

    close c_reservations;
    if v_voucher_id = p_event_id then 
        v_return_value := 'Y';  
        ll_pkg_log.log(30,'Parallel reservation found - same event "requested" twice');
        ll_pkg_log.log(20,'End of call');
        return v_return_value;
    end if;
    if v_reservation_count = 0 then
        v_return_value := 'N';
        ll_pkg_log.log(30,'No reservations found in parallel for this user');
    elsif v_reservation_count = 1 and v_voucher_id is not null and p_event_id is not null then
        v_return_value := 'N';
        ll_pkg_log.log(30,'Single parallel event reservation found - allowing another event');
    end if;

    ll_pkg_log.log(20,'End of call');

    return(nvl(v_return_value,'N'));
  exception when others then
    return 'N';
  end;
   
--
--  ########  ########  ######  ######## ########  ##     ##    ###    ######## ####  #######  ##    ##  ######     ########  ######## ########     ##     ##  #######  ##    ## ######## ##     ## 
--  ##     ## ##       ##    ## ##       ##     ## ##     ##   ## ##      ##     ##  ##     ## ###   ## ##    ##    ##     ## ##       ##     ##    ###   ### ##     ## ###   ##    ##    ##     ## 
--  ##     ## ##       ##       ##       ##     ## ##     ##  ##   ##     ##     ##  ##     ## ####  ## ##          ##     ## ##       ##     ##    #### #### ##     ## ####  ##    ##    ##     ## 
--  ########  ######    ######  ######   ########  ##     ## ##     ##    ##     ##  ##     ## ## ## ##  ######     ########  ######   ########     ## ### ## ##     ## ## ## ##    ##    ######### 
--  ##   ##   ##             ## ##       ##   ##    ##   ##  #########    ##     ##  ##     ## ##  ####       ##    ##        ##       ##   ##      ##     ## ##     ## ##  ####    ##    ##     ## 
--  ##    ##  ##       ##    ## ##       ##    ##    ## ##   ##     ##    ##     ##  ##     ## ##   ### ##    ##    ##        ##       ##    ##     ##     ## ##     ## ##   ###    ##    ##     ## 
--  ##     ## ########  ######  ######## ##     ##    ###    ##     ##    ##    ####  #######  ##    ##  ######     ##        ######## ##     ##    ##     ##  #######  ##    ##    ##    ##     ##
--
  function reservations_per_month (p_res_id number, p_owner varchar2, p_start_date date, p_start_time varchar2, p_start_timezone varchar2 ) return number is
   
    cursor c_reservations (p_start_gmt date) is
                             select count(*)
                             from ll_reservations_vw
                             where to_char(p_start_gmt,'MMYYYY') = to_char(start_gmt,'MMYYYY')
                             and owner1 = p_owner
                             and id <> nvl(p_res_id,-1)
                             and voucher_id is not null
                             and workshop_id not in (select workshop_id 
                                                     from ll_vouchers 
						                                         where instr(upper(email_creator), upper(p_owner)) > 0 
						                                            or instr(upper(email_requestor), upper(p_owner)) > 0 ) ;
   
    v_return_value    number;
    v_start_gmt       date;
   
  begin
    ll_pkg_log.log(20,'Initial call');
    
    if p_start_date is null then
      v_start_gmt := sysdate;
      ll_pkg_log.log(30,'Using sysdate as start_date is empty');
    else
      v_start_gmt := ll_pkg_reservation.date_gmt(p_date => p_start_date, p_time => p_start_time, p_timezone => p_start_timezone );
      ll_pkg_log.log(30,'Using start_date as it is not empty');
      ll_pkg_log.log(40,'Start date is '||to_char(p_start_date,'DD-MM-YYYY HH24:MI:SS'));
    end if;
    
    ll_pkg_log.log(40,'Start date GMT is '||to_char(v_start_gmt,'DD-MM-YYYY HH24:MI:SS'));
                   
    open c_reservations(v_start_gmt);
    fetch c_reservations into v_return_value;
    if c_reservations%notfound then
      v_return_value:=0;
    end if;
    close c_reservations;
    ll_pkg_log.log(20,'End of call');
    
    return(v_return_value);
   
   end;
--
--        ##  ######   #######  ##    ##         ##       ####  ######  ########    ########     ###    ######## ########  ######  
--        ## ##    ## ##     ## ###   ##         ##        ##  ##    ##    ##       ##     ##   ## ##      ##    ##       ##    ## 
--        ## ##       ##     ## ####  ##         ##        ##  ##          ##       ##     ##  ##   ##     ##    ##       ##       
--        ##  ######  ##     ## ## ## ##         ##        ##   ######     ##       ##     ## ##     ##    ##    ######    ######  
--  ##    ##       ## ##     ## ##  ####         ##        ##        ##    ##       ##     ## #########    ##    ##             ## 
