  function json_list_dates (p_start_date date, p_minutes_apart number, p_end_date date default sysdate ) return clob is
  
    v_date                date;
    v_json                clob;
    v_steps               number;
  begin
    v_steps := floor(((p_end_date - p_start_date) * 60 * 24) / p_minutes_apart);
  
    v_json := '[';
    for x in 1..v_steps loop
      v_date := p_start_date + ((x*p_minutes_apart)/60/24);
      v_json := v_json || json_object ('ref_date'  value to_char(v_date,'DD-MM HH24:MI:SS'),
                                       'ref_order' value to_char(x)) || ',';
    end loop;
  
    v_json := substr(v_json, 1, length(v_json)-1) || ']'; 
    return(v_json);
 
  end;
  
--
-- ===========================================================================================================
--
  function check_voucher (p_username varchar2, p_voucher varchar2, p_start_gmt date) return varchar2 is
  
    cursor c_vouchers is select (users_maximum - users_concurrent) as available_users, valid_from_gmt, valid_to_gmt, 'Y' as voucher_exists, id
                         from ll_vouchers_vw
                         where voucher_code = p_voucher;
                         
    cursor c_voucher_user is select 'Y'
                             from ll_voucher_users
                             where owner1 = p_username
                             and voucher_id in (select id
                                                from ll_vouchers
                                                where voucher_code = p_voucher);
  
    v_result           varchar2(4000);
    v_user_exists      varchar2(1);
    v_available_users  number;
    v_valid_from_gmt   date;
    v_valid_to_gmt     date;
    v_voucher_exists   varchar2(1);
    v_voucher_id       number;
    v_start_date       date;
  
  begin
  
    if p_start_gmt is null then
      v_start_date := sysdate;
    else
      v_start_date := p_start_gmt;
    end if;
  
    open c_voucher_user;
    fetch c_voucher_user into v_user_exists;
    close c_voucher_user;
    
    open c_vouchers;
    fetch c_vouchers into v_available_users, v_valid_from_gmt, v_valid_to_gmt, v_voucher_exists, v_voucher_id;
    if c_vouchers%NOTFOUND then
      v_voucher_exists := 'N';
    end if;
    close c_vouchers;
-- Check user already has the voucher and voucher is active
    if nvl(v_user_exists,'N') = 'Y' and v_start_date between v_valid_from_gmt and v_valid_to_gmt then -- User exists and date matches
      v_result := 'Y';   
    elsif nvl(v_result,'N') <> 'Y' and v_voucher_exists = 'Y' and v_start_date < v_valid_from_gmt then -- Voucher exists but it is too early
      v_result := 'This voucher is not yet active. Please speak with your Oracle contact for more information.';
    elsif nvl(v_result,'N') <> 'Y' and v_voucher_exists = 'Y' and v_start_date > v_valid_to_gmt then -- Voucher exists but the voucher has expired
      v_result := 'This voucher has expired. Please speak with your Oracle contact for more information.';
    elsif nvl(v_result,'N') <> 'Y' and v_start_date between v_valid_from_gmt and v_valid_to_gmt and v_available_users <= 0 then -- Voucher valid but no available users
      v_result := 'Too many people have used this voucher. Please speak with your Oracle contact for more information.';
    elsif nvl(v_result,'N') <> 'Y' and v_start_date between v_valid_from_gmt and v_valid_to_gmt and v_available_users > 0 and v_voucher_exists='Y' then -- Voucher valid and users exist
      insert into ll_voucher_users (VOUCHER_ID, OWNER1, DATE_ENTERED) values ( v_voucher_id, p_username, sysdate);
      commit;
      v_result := 'Y';
    elsif v_voucher_exists = 'N' then -- Voucher does not exist at all
      v_result := 'This voucher does not exist.';
    end if;
    
    return(v_result);
  end;
