  function voucher_qr_url (p_voucher_code varchar2) return varchar2 is
    host_url varchar2(200);
    source_url varchar2(2000);
    v_url    varchar2(2000);
  
  begin
--  v_url := 'https://apex.oraclecorp.com/'||APEX_PAGE.GET_URL ( p_page   => 180, p_items  => 'P180_VOUCHER_CODE', p_values => p_voucher_code);
