    host_url := apex_util.host_url('NULL');
    source_url := substr(apex_page.get_url (p_page   => 180,
                                              p_items  => 'WEC',
                                              p_values => p_voucher_code),48);                                       
    source_url := replace(source_url,'%3A',':'); 
    source_url := substr(source_url,1,instr(source_url,'&session')-1);
    v_url := host_url || source_url ;
    return(v_url);
  
  end;
