FUNCTION clean_searchstr  (p_search IN VARCHAR2)
RETURN VARCHAR2
IS
    --l_sql VARCHAR2(4000);
     l_stop_words_arr apex_t_varchar2; 
     l_stop_words_str varchar2(4000);  
     l_search_str     varchar2(4000) := ' '||upper(p_search)||' ';  
   -- l_return_str     varchar2(4000);
     l_temp_str varchar2(4000);
    Cursor C_1 Is  select  upper(KEY_VALUE_LONG) KEY_VALUE_LONG from ll_keys where key_name='STOPWORDS'; 
BEGIN
   For row_1 In C_1 Loop
        l_stop_words_str := row_1.KEY_VALUE_LONG;
    End loop;
    l_stop_words_arr := apex_string.split(p_str => l_stop_words_str, p_sep => ':');  
    for i in 1 .. l_stop_words_arr.count
    loop 
        if instr(l_search_str, l_stop_words_arr(i) || ' ') > 0 then 
            l_search_str := REGEXP_REPLACE (l_search_str, ' '||l_stop_words_arr(i)||' ', ' ');  
        end if;
    end loop;
    dbms_output.put_line(l_temp_str); 
     RETURN trim(l_search_str); 
END;
