FUNCTION search_sql_new  (p_search IN VARCHAR2)
return varchar2
IS
    l_sql VARCHAR2(4000);
    l_sql2 VARCHAR2(4000);
     l_select_sql VARCHAR2(4000) := 'Select A.ID, null header ,
     "NAME" card_title,
     ll_pkg_admin.cut_off_at_space (A.DESC_SHORT, 100) card_text,
     ll_pkg_admin.hours_readable (A.TIME_IN_HOURS, ''SHORT'', ''N'') card_subtext,
     null card_icon,
     (
        CASE
           WHEN B.TAG_ID = (select ID from LL_TAGS where LEVEL2 = ''Sprints'') THEN APEX_PAGE.GET_URL (
                                        p_page   => 210,
                                        p_clear_cache => 210,
                                        p_items  => ''p210_workshop_id,p210_type,sc'',
                                        p_values => A.ID||'',''||1||'',''||1)
           ELSE APEX_PAGE.GET_URL (
                    p_page   => 180,
                    p_clear_cache => 180,
                    p_items  => ''WID'',
                    p_values => A.ID)
        END  
     ) card_link,
      (
       CASE
           WHEN A.pg_views < 500 THEN ''''
           ELSE A.pg_views || '' Views''
        END
    ) card_views,
    (
       CASE
           WHEN A.pg_views < 500 THEN ''''
           ELSE ''fa fa-eye''
        END
    ) card_views_eye,
    null as bookmark_enable,
    ll_pkg_apex.user_attended_ws (p_workshop_id => A.id, p_username => :app_user) as workshop_attended,
    ll_pkg_apex.card_ribbon ( p_workshop_id => A.id, p_username => :app_user) as card_ribbon ,
    (select key_value from ll_keys C where C.key_type=''CARD_RIBBON'' and C.key_name=ll_pkg_apex.card_ribbon ( p_workshop_id => A.id, p_username => :app_user)) as card_ribbon_color,
    ''star_0_0.png'' star_rating,
     null star_votes,
     nvl2(A.TIME_IN_HOURS, ''fa fa-clock-o'', null) as time_display,
     null card_image,
     A.pg_views
     from ll_workshops A 
     left join (select WORKSHOP_ID, TAG_ID from LL_WORKSHOP_TAGS llwt, LL_TAGS llt where llwt.TAG_ID = llt.ID and llt.level2 = ''Sprints'') B
     on A.ID = B.WORKSHOP_ID
     where A.ACTIVE_FLG=''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_ROLE) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_LEVEL) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_SALES_PLAY) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_FOCUS_AREA) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_PRODUCT) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_SALES_FOCUS) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_WORKSHOP_TYPE) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_CERTIFICATION) = ''Y''
     AND LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( A.ID, :P100_WORKSHOP_SERIES) = ''Y''';
    l_splitvars varchar2(4000);
    p_tempsearch varchar2(100) := p_search;
    p_retsearch varchar2(4000) ;
    workshop_id varchar2(4000);
    first_loop number :=0;
    
BEGIN
    l_sql := l_select_sql;
    l_sql2 := '';
    if (p_search is null) then
        return l_sql;
    end if;
    --l_select_sql := 'select * from ll_workshops llw where active_flg = ''Y''';
    --Clean up input search, get rid of single quote
    p_tempsearch := REGEXP_REPLACE(p_tempsearch,chr(39),'');
    p_tempsearch := REGEXP_REPLACE(p_tempsearch,chr(38),'');
       
    --This takes out all of the stop words
    p_retsearch := ll_pkg_apex.clean_searchstr(p_tempsearch);
    
    if(p_retsearch is null) then
        return l_sql;
    end if;
    --Create a pipe separated list for the tag string regular expression
    l_splitvars :=  upper(REGEXP_REPLACE ( '' ||p_retsearch|| '',' ',' | ')) ;
    l_splitvars := upper(l_splitvars);
    l_splitvars := REGEXP_REPLACE(l_splitvars,' ','');
    p_retsearch := ltrim(rtrim(p_retsearch));
    --Convert to a comma separated list
    p_retsearch := REGEXP_REPLACE(p_retsearch,' ',',');
    --For each search word add a where clause
    first_loop := 0;
    l_sql := ''||l_select_sql||' and ((';
    
    for x in (select column_value from table(apex_string.split(p_retsearch, ','))) loop
    
    if(first_loop != 0) then
       l_sql := l_sql || ' and ';
       l_sql2 := l_sql2 || ' or ';
    end if;
    l_sql :=  l_sql || '(upper('' '' || NAME || '' '') like  upper(''% '||x.column_value||' %'')   )';
    l_sql2 := l_sql2 || '(upper('' '' || b.level1 || '' '') like  upper(''% '||x.column_value||' %'')   ) or';
    l_sql2 := l_sql2 || '(upper('' '' || b.level2 || '' '') like  upper(''% '||x.column_value||' %'')   ) or';
    l_sql2 := l_sql2 || '(upper('' '' || b.level3 || '' '') like  upper(''% '||x.column_value||' %'')   )';
    first_loop := 1;
    end loop;
    l_sql := l_sql || ') or A.id in
            (select a.workshop_id
             from ll_workshop_tags a, ll_tags b 
             where a.tag_id = b.id 
             and (' || l_sql2 || ')))' ;
    RETURN l_sql;
END;
