FUNCTION filter_sql  (p_search IN VARCHAR2, p_filter IN VARCHAR2)
return varchar2
IS
    l_select_sql VARCHAR2(4000) := '';
    l_splitvars varchar2(4000);
    p_tempsearch varchar2(100) := p_search;
    p_retsearch varchar2(4000) ;
    workshop_id varchar2(4000);
    first_loop number :=0;
    l_sql varchar2(4000);
    l_sql2 varchar2(4000);
    
BEGIN
  l_sql2 := '';
  if((p_filter = 'PRODUCT') or (p_filter = 'FOCUS')) then
    l_sql := 'select nvl(llt.level3,llt.level2)||'' (''||count(*)||'')'', llt.id ';
  else
    l_sql := 'select llt.level2 ||'' (''||count(*)||'')'', llt.id ';
  end if;
  l_sql := l_sql || 'from ll_workshop_tags llwt, ll_workshops llw, ll_tags llt
    where llwt.workshop_id = llw.id
    and llwt.tag_id = llt.id
    and llw.active_flg=''Y''
    and llt.active_flg=''Y''
    and upper(llt.level1) = '''||upper(p_filter)||''' ';
    if(p_filter != 'WORKSHOP SERIES') then
        l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_WORKSHOP_SERIES) = ''Y'' ';
    end if;
    if(p_filter != 'ROLE') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_ROLE) = ''Y'' ';
    end if;
    
    if(p_filter != 'LEVEL') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_LEVEL) = ''Y'' ';
    end if;
    
    if(p_filter != 'FOCUS') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_FOCUS_AREA) = ''Y'' ';
    end if;
    
    if(p_filter != 'WORKSHOP SERIES') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_WORKSHOP_TYPE) = ''Y'' ';
    end if;
    
    if(p_filter != 'CERTIFICATION') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_CERTIFICATION) = ''Y'' ';
    end if;
    
    if(p_filter != 'SALES PLAY') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_SALES_PLAY) = ''Y'' ';
    end if;
    
    if(p_filter != 'SALES FOCUS') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_SALES_FOCUS) = ''Y'' ';
    end if;
    
    if(p_filter != 'PRODUCT') then
    l_sql := l_sql || 'and LL_PKG_ADMIN.COMPARE_CATEGORY_TAGS ( llw.ID, :P100_PRODUCT) = ''Y'' ';
    end if;
    
    if((p_filter = 'SALES FOCUS') or (p_filter = 'SALES PLAY')) then
        l_sql := l_sql || 'and instr(upper(:app_user),''@ORACLE.COM'')>0 ';
    end if;
   if(p_search is not null) then
    --l_select_sql := 'select * from ll_workshops llw where active_flg = ''Y''';
    --Clean up input search, get rid of single quote
    p_tempsearch := REGEXP_REPLACE(p_tempsearch,chr(39),'');
    p_tempsearch := REGEXP_REPLACE(p_tempsearch,chr(38),'');
       
    --This takes out all of the stop words
    p_retsearch := ll_pkg_apex.clean_searchstr(p_tempsearch);
    if(p_retsearch is not null) then
        
    --Create a pipe separated list for the tag string regular expression
    l_splitvars :=  upper(REGEXP_REPLACE ( '' ||p_retsearch|| '',' ',' | ')) ;
    l_splitvars := upper(l_splitvars);
    l_splitvars := REGEXP_REPLACE(l_splitvars,' ','');
    p_retsearch := ltrim(rtrim(p_retsearch));
    --Convert to a comma separated list
    p_retsearch := REGEXP_REPLACE(p_retsearch,' ',',');
    --For each search word add a where clause
    first_loop := 0;
    l_sql := ''||l_sql||' and (:SEARCH IS NULL or ((';
    
    for x in (select column_value from table(apex_string.split(p_retsearch, ','))) loop
    
    if(first_loop != 0) then
       l_sql := l_sql || ' and ';
       l_sql2 := l_sql2 || ' or ';
    end if;
    l_sql :=  l_sql || '(upper('' '' || llw.NAME || '' '') like  upper(''% '||x.column_value||' %'')   )';
    l_sql2 := l_sql2 || '(upper('' '' || b.level1 || '' '') like  upper(''% '||x.column_value||' %'')   ) or';
    l_sql2 := l_sql2 || '(upper('' '' || b.level2 || '' '') like  upper(''% '||x.column_value||' %'')   ) or';
    l_sql2 := l_sql2 || '(upper('' '' || b.level3 || '' '') like  upper(''% '||x.column_value||' %'')   )';
    first_loop := 1;
    end loop;
    l_sql := l_sql || ') or llw.id in
            (select a.workshop_id
             from ll_workshop_tags a, ll_tags b 
             where a.tag_id = b.id 
             and (' || l_sql2 || '))))' ;
    end if;
    else
        l_sql := ''||l_sql||' and (:SEARCH IS NULL) ';
    end if;
    if((p_filter = 'PRODUCT') or (p_filter = 'FOCUS')) then
        l_sql := l_sql || ' group by llt.level3, llt.level2, llt.id ';
    else
        l_sql := l_sql || ' group by llt.level2, llt.id ';
    end if;    
        l_sql := l_sql || ' having count(*) > 0 order by 1';
        --insert into sql_dump values (l_sql);
    RETURN l_sql;
END;
