  function user_attended_ws (p_workshop_id number, p_username varchar2) return varchar2 is --RESULT_CACHE RELIES_ON (ll_reservations) is
    cursor c_attended is select 'Y'
                        from ll_reservations
                        where owner1=p_username
                        and workshop_id = p_workshop_id;
    v_attended      varchar2(1);
    v_return_value  varchar2(100);
  begin
    if upper(p_username) = 'NOBODY' then
      v_return_value := '';
    else
      open c_attended;
      fetch c_attended into v_attended;
      if c_attended%FOUND then
        v_return_value := 'fa fa-check-circle';
      else
        v_return_value := '';
        --v_return_value := 'fa fa-check-circle-o';
      end if;
      close c_attended;
    end if;
    return(v_return_value);
  end;
