  function card_ribbon ( p_workshop_id number, p_username varchar2) return varchar2 is
  -- For now, we retrieve the values from LL_TAGS and LL_WORKSHOP_TAGS
    cursor c_tag is select level2
                    from LL_TAGS
                    where level1 = 'Featured'
                    and id in (select tag_id from ll_workshop_tags where workshop_id = p_workshop_id);
    v_return_value   varchar2(100);
  begin
    open c_tag;
    fetch c_tag into v_return_value;
    close c_tag;
    return(v_return_value);
  end;
