  procedure store_tc_info (p_workshop_id number, p_wec varchar2, p_tc_value varchar2) is 
    cursor c_tc_values (v_app_user varchar2) is select 'Y'
                                                from LL_TC_VALUES
                                                where app_user = v_app_user
                                                and nvl(wec,'X') = nvl(p_wec,'X')
                                                and nvl(p_workshop_id,-1) = nvl(workshop_id,-1)
                                                and tc_value = p_tc_value; 
    v_session  number        := SYS_CONTEXT ('USERENV', 'SESSIONID');
    v_app_user varchar2(200) := SYS_CONTEXT ('APEX$SESSION','APP_USER');
    v_dummy    varchar2(1);
  begin
    if upper(v_app_user) = 'NOBODY' then
      v_app_user := v_app_user||'-'||v_session;
    end if;
    open c_tc_values(v_app_user);
    fetch c_tc_values into v_dummy;
    if c_tc_values%NOTFOUND then
      insert into LL_TC_VALUES (workshop_id, wec, tc_value, session_id, app_user, date_entry) values ( p_workshop_id, p_wec, p_tc_value, v_session, v_app_user, sysdate );
    end if;
    close c_tc_values;
    commit;
  end;
--
-- =============================================================================================================
--
  function check_availability (p_workshop_id number, p_tenancy_id number, p_region_id number, p_start_date_gmt date, p_stop_date_gmt date, p_voucher_id number default null) return number is
  cursor c_check is select min(floor((a.num_provided - nvl(b.num_required,0)) / c.environments)) as env_available
                    from
     -- Resources num_available
                    ( select tenancy_id, region_id, resource_id, num_available as num_provided 
                      from ll_res_tenancy_provides_vw
                      where tenancy_id = p_tenancy_id ) a,
     -- Resources already scheduled through existing vouchers
                    ( select llv.tenancy_id, llv.region_id, llwrr.resource_id, sum(llwrr.environments*llv.users_maximum) as num_required
                      from ll_vouchers_vw llv, ll_ws_resources_required_vw llwrr 
                      where llv.workshop_id = llwrr.workshop_id
                      and (    p_start_date_gmt between valid_from_gmt and valid_to_gmt
                            or p_stop_date_gmt between valid_from_gmt and valid_to_gmt
                            or (valid_from_gmt < p_start_date_gmt and valid_to_gmt > p_stop_date_gmt)
                          ) 
--                      and (p_voucher_id is null or llv.id <> p_voucher_id)
                      group by id, tenancy_id, region_id, resource_id ) b,
    -- Resources required per workshop
                      ll_ws_resources_required_vw c
                    where a.tenancy_id = b.tenancy_id(+)
                      and a.region_id = b.region_id(+)
                      and a.resource_id = b.resource_id(+)
                      and a.resource_id = c.resource_id
                      and c.workshop_id = p_workshop_id
                      and a.tenancy_id = p_tenancy_id
                      and a.region_id = p_region_id
                      group by c.workshop_id, a.tenancy_id, a.region_id;
    v_return_value   number;                      
  begin
    open c_check;
    fetch c_check into v_return_value;
    if c_check%NOTFOUND then
      v_return_value := 0;
    end if;
    close c_check;
    return(v_return_value);
  end;
 
