--
procedure update_workshop_page_views is
  begin
    -- update workshops
    update ll_workshops set pg_views = 0 where pg_views is null;
    for x in (select workshop_id, count(*) pg_views from LL_PAGE_VISITS where page_id in (180,200,210,320) group by workshop_id) loop
      update ll_workshops set pg_views = x.pg_views where id = x.workshop_id;
    end loop;

    -- update livestacks
    update ll_livestacks set pg_views = 0 where pg_views is null;
    for x in (select workshop_id, count(*) pg_views from LL_PAGE_VISITS where page_id in (400,410,420) group by workshop_id) loop
      update ll_livestacks set pg_views = x.pg_views where id = x.workshop_id;
    end loop;
  end;
