function getWorkshopCardIcon(p_workshop_id number) return blob is
    cursor c_icon(p_json clob) is 
                    select PrimaryProduct from json_table(p_json, '$' COLUMNS PrimaryProduct);
    v_icon_title varchar2(100);
    v_icon_blob blob;
    v_json clob;
    begin
        if p_workshop_id is null then
            select icon_blob into v_icon_blob from ll_workshop_icons where title = 'Other';
            return v_icon_blob;
        end if;
        select workshop_json into v_json from ll_workshops where id = p_workshop_id;
        v_icon_title := json_value(v_json, '$.PrimaryProduct');
        if v_icon_title is null then
            select icon_blob into v_icon_blob from ll_workshop_icons where title = 'Other';
            return v_icon_blob;
        end if;
        select icon_blob into v_icon_blob from ll_workshop_icons where title = v_icon_title;
        return v_icon_blob;
    exception 
        when others then
            select icon_blob into v_icon_blob from ll_workshop_icons where title = 'Other';
            return v_icon_blob;
    end;

function getWorkshopCardIconPAR(p_workshop_id number) return varchar2 is
    cursor c_icon(p_json clob) is 
                    select PrimaryProduct from json_table(p_json, '$' COLUMNS PrimaryProduct);
    v_icon_title varchar2(100);
    v_par_link varchar2(1000);
    v_json clob;
    begin
        if p_workshop_id is null then
            select par_link into v_par_link from ll_workshop_icons where title = 'Other';
            return v_par_link;
        end if;
        select workshop_json into v_json from ll_workshops where id = p_workshop_id;
        v_icon_title := json_value(v_json, '$.PrimaryProduct');
        if v_icon_title is null then
            select par_link into v_par_link from ll_workshop_icons where title = 'Other';
            return v_par_link;
        end if;
        select par_link into v_par_link from ll_workshop_icons where title = v_icon_title;
        return v_par_link;
    exception 
        when others then
            select par_link into v_par_link from ll_workshop_icons where title = 'Other';
            return v_par_link;
    end;

procedure setWorkshopCardIconIDs is
    cursor c_icon(p_json clob) is 
                    select PrimaryProduct from json_table(p_json, '$' COLUMNS PrimaryProduct);
    v_icon_title varchar2(100);
    v_id number;
    v_json clob;
    begin
        for ws in (select * from ll_workshops) loop
            select workshop_json into v_json from ll_workshops where id = ws.id;
            v_icon_title := json_value(v_json, '$.PrimaryProduct');
            if v_icon_title is null then
                update ll_workshops set icon_id = (select id from ll_workshop_icons where title = 'Other') where id=ws.id;
                continue;
            end if;
            update ll_workshops set icon_id = (select id from ll_workshop_icons  where title = v_icon_title) where id=ws.id;
        end loop;
    end setWorkshopCardIconIDs;

function getWorkshopVideo(p_workshop_id number) return varchar2 is
    cursor c_icon(p_json clob) is 
                    select PrimaryProduct from json_table(p_json, '$' COLUMNS PrimaryProduct);
    v_youtube varchar2(1000);
    v_icon_title varchar2(100);
    v_json clob;
    begin
        select workshop_json into v_json from ll_workshops where id = p_workshop_id;
        v_icon_title := json_value(v_json, '$.PrimaryProduct');
        if v_icon_title is null then
            select youtube_link into v_youtube from ll_workshop_icons where title = 'Other';
            return v_youtube;
        end if;
        select youtube_link into v_youtube from ll_workshop_icons where title = v_icon_title;
        return v_youtube;
    exception 
        when others then
            select youtube_link into v_youtube from ll_workshop_icons where title = 'Other';
            return v_youtube;
    end;
 
end;
