  procedure commit_gitlab (p_file IN clob, p_filename IN varchar2, p_base64 OUT clob) is
    v_token           varchar2(50)   := 'ip-7b_JL-zgo9bxNXzkd';
    v_host            varchar2(2000) := 'https://orahub.oci.oraclecorp.com/api/v4';
    v_method          varchar2(2000);
    v_clob            clob;
    v_payload         clob;
    v_content_base64  clob;
    v_file_txt        clob;
    v_file_base64     clob;
    
    v_buffer_size     number    := 48;
    v_offset          number    := 1;
    v_buffer          varchar2(2000);
    v_buffer_raw      raw(2000);
    v_buffer_char     varchar2(4000);
    v_myfile_position number;
    
  begin
    for x in 1..ceil(dbms_lob.getlength(p_file) / v_buffer_size ) loop
      dbms_lob.read (p_file, v_buffer_size, v_offset, v_buffer);
      v_buffer_raw := utl_raw.cast_to_raw(REGEXP_REPLACE(ASCIISTR(v_buffer), '\\[[:xdigit:]]{4}', '?'));
      v_buffer_char := utl_raw.cast_to_varchar2(utl_encode.base64_encode(v_buffer_raw));  
      v_content_base64 := v_content_base64 || v_buffer_char;
      v_offset := v_offset + length(v_buffer);
    end loop;
    v_payload := JSON_OBJECT ('branch'    value '2.1.1',
                              'commit_message'  value 'Automatic upload '||to_char(sysdate,'YYYYMMDD_HH24MISS'),
                              'actions'         value JSON_ARRAY ( JSON_OBJECT ( 'action'     value 'update',
                                                                                 'file_path'  value p_filename,
                                                                                 'encoding'   value 'base64',
                                                                                 'content'    value '@myfile@') ) );
                                                                                 
    v_myfile_position := instr(v_payload,'@myfile@');
    
    v_payload := substr(v_payload,1,v_myfile_position-1) || v_content_base64 || substr(v_payload, v_myfile_position+8);
    
    p_base64 := v_payload;
    apex_web_service.g_request_headers.delete(); 
    apex_web_service.g_request_headers(1).name := 'PRIVATE-TOKEN'; 
    apex_web_service.g_request_headers(1).value := v_token; 
    apex_web_service.g_request_headers(2).name := 'Content-Type'; 
    apex_web_service.g_request_headers(2).value := 'application/json';
    v_method := '/projects/19902/repository/commits';
    
    v_clob := apex_web_service.make_rest_request ( p_url          => v_host || v_method,
                                                   p_http_method  => 'POST',
                                                   p_body         => v_payload );
  end;
