  procedure upload_to_bucket (p_filename varchar2, p_clob clob) is
  
    cursor c_parameters is select name, value
                           from ll_system_parameters
                           where name in ('BACKUP_USERNAME', 'BACKUP_PASSWORD','BACKUP_NAMESPACE','BACKUP_BUCKETNAME','BACKUP_REGION_IDENTIFIER','BACKUP_PROXY','BACKUP_PREFIX');
  
  
    v_clob               clob;
    v_username           varchar2(100); --  := 'livelabs-stage-user';
    v_auth_token         varchar2(100); --  := 'a;BT[06[nlN4#ItBKQdp';
    v_namespace          varchar2(500); --  := 'c4u03';
    v_bucketname         varchar2(500); --  := 'DevelopmentStage';
    v_proxy              varchar2(500);
    v_backup_prefix      varchar2(500);
    v_region_identifier  varchar2(100);
    v_filename           varchar2(200);
    
    v_host       varchar2(1000);
    
    v_blob_uncompressed  blob;
    v_blob_compressed    blob;
    
    v_payload            clob;
    v_base64             clob;
    v_sql_errm           varchar2(2000);
    g_timedir varchar2(100);
    
  begin
  
    for x in c_parameters loop
      case x.name
        when 'BACKUP_USERNAME' then v_username := x.value;
        when 'BACKUP_PASSWORD' then v_auth_token := ll_pkg_security.decrypt(x.value);
        when 'BACKUP_NAMESPACE' then v_namespace := x.value;
        when 'BACKUP_BUCKETNAME' then v_bucketname := x.value;
        when 'BACKUP_REGION_IDENTIFIER' then v_region_identifier := x.value;
        when 'BACKUP_PROXY' then v_proxy := x.value;
        when 'BACKUP_PREFIX' then v_backup_prefix := x.value;
        else dbms_output.put_line(x.name ||'-'||x.value);
      end case;
    end loop;
    
    g_timedir := replace(g_timestamp,'_','/');
    --v_host :=  'https://swiftobjectstorage.'||v_region_identifier||'.oraclecloud.com/v1/'||v_namespace||'/'||v_bucketname||'/'||v_backup_prefix||'_'||g_timestamp||'_'||p_filename;
    v_host :=  'https://swiftobjectstorage.'||v_region_identifier||'.oraclecloud.com/v1/'||v_namespace||'/'||v_bucketname||'/'||v_backup_prefix||'/'||g_timedir||'/'||v_backup_prefix||'_'||g_timestamp||'_'||p_filename;
    
    v_payload := p_clob;
    v_payload := replace (v_payload, chr(34)||'DBPM'||chr(34)||'.', '');
    v_payload := replace (v_payload, chr(34)||'DBPMDEV'||chr(34)||'.', '');
    v_payload := replace (v_payload, chr(34)||'LIVELABSDEV'||chr(34)||'.', '');
    v_payload := replace (v_payload, chr(32)||'EDITIONABLE', '');
    v_payload := replace (v_payload, chr(32)||'FORCE', '');
    
    apex_web_service.g_request_headers.delete();
    apex_web_service.g_request_headers(1).name := 'content-type'; 
    apex_web_service.g_request_headers(1).value := 'plain/text'; 
    -- proxy should be null in system params
    v_clob := apex_web_service.make_rest_request (
        p_url               => v_host,
        p_http_method       => 'PUT',
        p_username          => v_username,
        p_password          => v_auth_token,
        p_proxy_override    => v_proxy,
        p_body              => v_payload);
  end;
