  procedure create_apex_app_backup (p_app_id number) is
    v_payload       clob;
    v_filename      varchar2(500);
    v_workspace_id  number;
  begin
    ll_pkg_security.set_security_group;
    
    v_payload := wwv_flow_utilities.export_application_to_clob (p_application_id => p_app_id);
    v_filename := '08_APP_EXPORT_P'||p_app_id||'.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
    
  end;           
