--
  function generate_inserts (p_table_name varchar2, p_new_table_name varchar2 default null) return CLOB is
    CURSOR c1 IS SELECT column_name, data_type, rownum
                 FROM user_tab_columns
                 WHERE table_name = p_table_name ORDER BY column_id;
    TYPE num_t IS TABLE OF number index by binary_integer;
    l_count_t    NUM_T;
    table_nam    VARCHAR2(34);
    l_count      NUMBER;
    v_column_list       CLOB := null;
    v_insert_list       CLOB;
    v_ref_cur_columns   CLOB := null;
    v_ref_cur_query     CLOB;
    v_ref_cur_output    CLOB;
    v_ref_cur_output1   CLOB := null;
    v_ref_cur_output2   CLOB := null;
    v_column_name       VARCHAR2(256);
    refcur              sys_refcursor; 
    v_error             VARCHAR2(4000);
    v_return_value      clob;
    v_counter           number := 0;
    
    v_new_string        varchar2(100) := '||chr(39)||';
    v_search_string     varchar2(100) := '@<second_column>@';
    v_concat_string     varchar2(100) := '||'||chr(39)||','||chr(39)||'||';
    
  BEGIN
  
    FOR i IN c1 LOOP
    v_counter := v_counter + 1;
      v_column_list := v_column_list||','||i.column_name;
      IF i.data_type = 'NUMBER' THEN
        v_column_name := 'nvl(to_char('||i.column_name||'), '||chr(39)||'null'||chr(39)||')';
      ELSIF i.data_type = 'TIMESTAMP(6)' THEN
        v_column_name := 'chr(39)||'|| i.column_name ||'||chr(39)';
      ELSIF i.data_type = 'CLOB' or i.data_type='VARCHAR2' or i.data_type='CHAR' THEN
        -- Following line will handle single quote in text data.
        v_column_name := 'chr(39) ||' ||'replace('||i.column_name||', chr(39), chr(39)||'||chr(39)|| v_new_string || chr(39) ||  ' || chr(39) ) || chr(39) ' ;
      ELSIF i.data_type = 'DATE' THEN
        v_column_name := chr(39)||'to_date('||chr(39)||'||chr(39)'||'||to_char('||i.column_name||','||
        chr(39)||'dd/mm/yyyy hh24:mi:ss'||chr(39)||')||chr(39)||'||chr(39)||', '||chr(39)||'||chr(39)||'||
        chr(39)||'dd/mm/rrrr hh24:mi:ss'||chr(39)||'||chr(39)||'||chr(39)||')'||chr(39);
      END IF;
      
     v_ref_cur_columns := v_ref_cur_columns||'||'||chr(39)||','||chr(39)||'||'||v_column_name||chr(10);
     
     if v_counter = 10 then
       v_ref_cur_columns := v_ref_cur_columns || v_search_string;
     end if;
    END LOOP;
    
    if instr(v_ref_cur_columns,v_search_string) = 0 then
      v_ref_cur_columns := v_ref_cur_columns || v_search_string;
    end if;
    
    v_ref_cur_columns := replace(v_ref_cur_columns, v_search_string||v_concat_string,','||chr(10));
    v_ref_cur_columns := replace(v_ref_cur_columns, v_search_string, ', null');
    IF v_column_list is null then
      v_return_value := v_return_value || '--Table '|| p_table_name || ' does not exist'||chr(10);
    ELSE
      v_column_list     := LTRIM(v_column_list,',');
      v_ref_cur_columns := SUBSTR(v_ref_cur_columns,8);
      v_insert_list     := 'INSERT INTO '||nvl(p_new_table_name, p_table_name)||' ('||v_column_list||') '||chr(13)||'  VALUES';
      v_ref_cur_query   := 'SELECT '||v_ref_cur_columns||' FROM '||p_table_name;
--      dbms_output.put_line(v_ref_cur_query);
--      return(v_ref_cur_query);
      OPEN refcur FOR v_ref_cur_query;
      LOOP 
        FETCH refcur INTO v_ref_cur_output1, v_ref_cur_output2; 
        EXIT WHEN refcur%NOTFOUND;
        
        v_ref_cur_output := v_ref_cur_output1||case nvl(v_ref_cur_output2,'Empty_String') when 'Empty_String' then null else ','||v_ref_cur_output2 end;
        v_ref_cur_output := '('||v_ref_cur_output||');'; 
        v_ref_cur_output := REPLACE(v_ref_cur_output,chr(39)||chr(39),'null');       
        v_ref_cur_output := REPLACE(v_ref_cur_output,',,',',null,');
        v_ref_cur_output := REPLACE(v_ref_cur_output,',,',',null,');
        v_ref_cur_output := REPLACE(v_ref_cur_output,'(,','(null,');
        v_ref_cur_output := REPLACE(v_ref_cur_output,',,)',',null)');
        v_ref_cur_output := REPLACE(v_ref_cur_output,'null,)','null,null)');
        v_ref_cur_output := v_insert_list||chr(13)||v_ref_cur_output; 
        v_return_value := v_return_value || v_ref_cur_output ||chr(10)||chr(10);
      END LOOP; 
      IF v_ref_cur_output is null then
        v_return_value := v_return_value || '-- No data in '||p_table_name|| chr(10);
      END IF;
    END IF;
    return(v_return_value);
  EXCEPTION
    When others then
      begin
        v_error := sqlerrm;
        return ('Error='||v_error||' for table '||p_table_name);
      end;
  END generate_inserts;
--
