  procedure create_DATA_backup is
    cursor c_tables is select table_name
                       from user_tables
                       where table_name in ('OMP_LISTINGS')
                       or (table_name like 'LL%' and table_name not in ('LL_PAGE_VISITS', 'LL_PAGE_VISITS_BACKUP', 'LL_RESERVATION_TF_LOG','LL_APEXAPPS_LOG'))
                       order by table_name;
    v_payload   clob;
    v_filename  varchar2(200);
    
  begin
  
    for x in c_tables loop
      v_payload := v_payload || generate_inserts(x.table_name);
      v_payload := v_payload || chr(10) || 'commit' || chr(10) || '/' ||chr(10) || chr(10);
    end loop;
    
    v_filename := '03_DATA.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
  end;



procedure create_apexapps_log_backup is
