 FUNCTION generate_page_visits_inserts(p_mod number) RETURN CLOB IS
   v_clob        CLOB;
  v_buffer      VARCHAR2(4000);
  v_page_id     varchar2(100);
  v_workshop_id     varchar2(100);
  v_date_str    VARCHAR2(100);
  v_app_session     varchar2(100);
  
BEGIN
  DBMS_LOB.CREATETEMPORARY(v_clob, TRUE);

  FOR rec IN (
    SELECT PAGE_ID, WORKSHOP_ID, ENTRY_DATE, APP_SESSION
    FROM LL_PAGE_VISITS
    where mod(CAST(TO_CHAR(ENTRY_DATE, 'DDD')  AS integer),p_mod) = mod(CAST(TO_CHAR(sysdate, 'DDD')  AS integer),p_mod)
    ORDER BY ENTRY_DATE
  ) LOOP
    -- Format the date
    v_page_id := NVL(TO_CHAR(rec.PAGE_ID), 'null');
    v_workshop_id := NVL(TO_CHAR(rec.WORKSHOP_ID), 'null');
    v_date_str := TO_CHAR(rec.ENTRY_DATE, 'dd/mm/yyyy hh24:mi:ss');
    v_app_session := REPLACE(rec.APP_SESSION, '''', '''''');

    -- Build the insert statement safely
    v_buffer :=
      'INSERT INTO LL_PAGE_VISITS (PAGE_ID,WORKSHOP_ID,ENTRY_DATE,APP_SESSION) ' || CHR(10) ||
      '  VALUES (' ||
        v_page_id || ',' ||
        v_workshop_id || ',' ||
        'to_date(''' || v_date_str || ''', ''dd/mm/rrrr hh24:mi:ss''),' ||
        '''' || v_app_session || '''' ||
      ');' || CHR(10) || CHR(10);

    DBMS_LOB.WRITEAPPEND(v_clob, LENGTH(v_buffer), v_buffer);
  END LOOP;
  RETURN v_clob;
END;

FUNCTION generate_RESERVATION_TF_LOG_inserts(p_mod NUMBER) RETURN CLOB IS
  v_clob          CLOB;
  v_line          VARCHAR2(4000);
  v_date_str      VARCHAR2(100);
  v_id            VARCHAR2(100);
  v_reservation_id VARCHAR2(100);
  v_tenancy_id    VARCHAR2(100);
  v_job_ocid      VARCHAR2(4000);
  v_log_type      VARCHAR2(100);
  v_log_level     VARCHAR2(100);
  v_log_timestamp VARCHAR2(100);
  v_log_message   VARCHAR2(4000);
BEGIN
  DBMS_LOB.CREATETEMPORARY(v_clob, TRUE);

  FOR rec IN (
    SELECT ID, RESERVATION_ID, TENANCY_ID, JOB_OCID, LOG_TYPE, LOG_LEVEL, LOG_TIMESTAMP, LOG_MESSAGE
    FROM LL_RESERVATION_TF_LOG
    WHERE MOD(CAST(TO_CHAR(to_timestamp(LOG_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"'), 'DDD') as integer), p_mod) =
          MOD(CAST(TO_CHAR(SYSDATE, 'DDD') AS INTEGER), p_mod) 
    ORDER BY LOG_TIMESTAMP
  ) LOOP
    -- Format each field safely
    v_id             := NVL(TO_CHAR(rec.ID), 'null');
    v_reservation_id := NVL(TO_CHAR(rec.RESERVATION_ID), 'null');
    v_tenancy_id     := NVL(TO_CHAR(rec.TENANCY_ID), 'null');
    v_job_ocid       := CASE WHEN rec.JOB_OCID IS NULL THEN 'null' ELSE '''' || REPLACE(rec.JOB_OCID, '''', '''''') || '''' END;
    v_log_type       := CASE WHEN rec.LOG_TYPE IS NULL THEN 'null' ELSE '''' || REPLACE(rec.LOG_TYPE, '''', '''''') || '''' END;
    v_log_level      := CASE WHEN rec.LOG_LEVEL IS NULL THEN 'null' ELSE '''' || REPLACE(rec.LOG_LEVEL, '''', '''''') || '''' END;
    v_log_timestamp := CASE WHEN rec.LOG_TIMESTAMP IS NULL THEN 'null' ELSE '''' || REPLACE(rec.LOG_TIMESTAMP, '''', '''''') || '''' END;
    v_log_message    := CASE WHEN rec.LOG_MESSAGE IS NULL THEN 'null' ELSE '''' || REPLACE(rec.LOG_MESSAGE, '''', '''''') || '''' END;

    -- Build the insert statement line
    v_line :=
      'INSERT INTO LL_RESERVATION_TF_LOG (ID,RESERVATION_ID,TENANCY_ID,JOB_OCID,LOG_TYPE,LOG_LEVEL,LOG_TIMESTAMP,LOG_MESSAGE)' || CHR(10) ||
      '  VALUES (' ||
        v_id || ',' ||
        v_reservation_id || ',' ||
        v_tenancy_id || ',' ||
        v_job_ocid || ',' ||
        v_log_type || ',' ||
        v_log_level || ',' ||
        v_log_timestamp || ',' ||
        v_log_message ||
      ');' || CHR(10) || CHR(10);

    DBMS_LOB.WRITEAPPEND(v_clob, LENGTH(v_line), v_line);
  END LOOP;



    return v_clob;
END;



