  procedure create_remaining_ddl_backup is
    cursor c_test is select dbms_metadata.get_ddl(object_type, object_name) as mycode 
                     from ( select object_name,
                                   decode(object_type,
                                          'PROGRAM',            'PROCOBJ',
                                          'PACKAGE',            'PACKAGE_SPEC',
                                          'PACKAGE BODY',       'PACKAGE_BODY',
                                          'MATERIALIZED VIEW',  'MATERIALIZED_VIEW',
                                          'JAVA CLASS',         'JAVA_CLASS',
                                          'JAVA TYPE',          'JAVA_TYPE',
                                          'JAVA SOURCE',        'JAVA_SOURCE',
                                          'JAVA RESOURCE',      'JAVA_RESOURCE',
                                          object_type ) object_type
                             from user_objects 
                             where object_type in ('JAVA_CLASS','JAVA SOURCE','JAVA_RESOURCE', 'INDEX')
                             and   object_type not in ('INDEX PARTITION','INDEX SUBPARTITION', 'LOB','LOB PARTITION','TABLE PARTITION','TABLE SUBPARTITION')
                             and   object_name not in (select table_name from user_nested_tables)
                             and   object_name not in (select table_name from user_tables where iot_type = 'IOT_OVERFLOW') 
                             and   object_name like 'LL%'
                             and   substr(object_name, length(object_name)-2) <> '_PK' ) 
                             order by case object_type when 'JAVA_CLASS' then 1 when 'JAVA_SOURCE' then 2 when 'INDEX' then 3 else 4 end, object_type, object_name;
    v_payload   clob;
    v_filename  varchar2(200);
    v_newline   varchar2(10) := chr(10) || '/' || chr(10) || chr(10);
  begin 
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'STORAGE',FALSE);
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'SEGMENT_ATTRIBUTES',FALSE);
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'SQLTERMINATOR',TRUE);
    for x in c_test loop
      v_payload := v_payload || x.mycode; -- || x.mycomment;
    end loop;
    
    v_filename := '04_REMDDL.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
  end;
--  
--   ######  ########  ########    ###    ######## ########    ########    ###    ########  ##       ########    ##     ## #### ######## ##      ##    ########     ###     ######  ##    ## ##     ## ########  
--  ##    ## ##     ## ##         ## ##      ##    ##             ##      ## ##   ##     ## ##       ##          ##     ##  ##  ##       ##  ##  ##    ##     ##   ## ##   ##    ## ##   ##  ##     ## ##     ## 
--  ##       ##     ## ##        ##   ##     ##    ##             ##     ##   ##  ##     ## ##       ##          ##     ##  ##  ##       ##  ##  ##    ##     ##  ##   ##  ##       ##  ##   ##     ## ##     ## 
--  ##       ########  ######   ##     ##    ##    ######         ##    ##     ## ########  ##       ######      ##     ##  ##  ######   ##  ##  ##    ########  ##     ## ##       #####    ##     ## ########  
--  ##       ##   ##   ##       #########    ##    ##             ##    ######### ##     ## ##       ##           ##   ##   ##  ##       ##  ##  ##    ##     ## ######### ##       ##  ##   ##     ## ##        
--  ##    ## ##    ##  ##       ##     ##    ##    ##             ##    ##     ## ##     ## ##       ##            ## ##    ##  ##       ##  ##  ##    ##     ## ##     ## ##    ## ##   ##  ##     ## ##        
--   ######  ##     ## ######## ##     ##    ##    ########       ##    ##     ## ########  ######## ########       ###    #### ########  ###  ###     ########  ##     ##  ######  ##    ##  #######  ##        
--
  procedure create_table_view_backup is
    cursor c_tbl is select object_type, object_name, 
                            dbms_metadata.get_ddl(object_type, object_name) as mycode 
                     from ( select object_name, object_type
                             from user_objects 
                             where object_type = 'TABLE'
                             and   object_type not in ('INDEX PARTITION','INDEX SUBPARTITION', 'LOB','LOB PARTITION','TABLE PARTITION','TABLE SUBPARTITION')
                             and   object_name not in (select table_name from user_nested_tables)
                             and   object_name not in (select table_name from user_tables where iot_type = 'IOT_OVERFLOW') 
                             and   (object_name like 'LL%' or object_name = 'OMP_LISTINGS'))
                             order by case object_type when 'TABLE' then 1 when 'TRIGGER' then 2 when 'VIEW' then 3 else 4 end, object_type, object_name;
    cursor c_view is select object_type, object_name, 
                            dbms_metadata.get_ddl(object_type, object_name) as mycode 
                     from ( select object_name, object_type
                             from user_objects 
                             where object_type in ('VIEW', 'MATERIALIZED_VIEW')
                             and   object_type not in ('INDEX PARTITION','INDEX SUBPARTITION', 'LOB','LOB PARTITION','TABLE PARTITION','TABLE SUBPARTITION')
                             and   object_name not in (select table_name from user_nested_tables)
                             and   object_name not in (select table_name from user_tables where iot_type = 'IOT_OVERFLOW') 
                             and   object_name like 'LL%')
                             order by case object_type when 'TABLE' then 1 when 'TRIGGER' then 2 when 'VIEW' then 3 else 4 end, object_type, object_name;
    cursor c_trig is select object_type, object_name, 
                            dbms_metadata.get_ddl(object_type, object_name) as mycode 
                     from ( select object_name, object_type
                             from user_objects 
                             where object_type = 'TRIGGER'
                             and   object_name not in (select table_name from user_nested_tables)
                             and   object_name not in (select table_name from user_tables where iot_type = 'IOT_OVERFLOW') 
                             and   object_name like 'LL%')
                             order by case object_type when 'TABLE' then 1 when 'TRIGGER' then 2 when 'VIEW' then 3 else 4 end, object_type, object_name;
    cursor c_constraints is select dbms_metadata.get_ddl('REF_CONSTRAINT', constraint_name) as mycode
                            from user_constraints
                            where  table_name like 'LL%'
                            and constraint_type='R';
                            
    cursor c_sequences is  select 'CREATE SEQUENCE  "'||sequence_name||'"  START WITH '||to_char(to_number(last_number)+1)||case cache_size when 0 then ' nocache' else ' cache '||cache_size end ||'; ' as mycode
                           from user_sequences
                           where sequence_name like 'LL%';
     
    v_payload   clob;
    v_comments  clob;
    v_filename  varchar2(200);
    v_newline   varchar2(10) := chr(10) ;
  begin 
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'STORAGE',FALSE);
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'SEGMENT_ATTRIBUTES',FALSE);
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'SQLTERMINATOR',TRUE);
    DBMS_METADATA.SET_TRANSFORM_PARAM(DBMS_METADATA.SESSION_TRANSFORM,'REF_CONSTRAINTS',FALSE);
    for x in c_sequences loop
      v_payload := v_payload || x.mycode || v_newline; 
    end loop;
    
    v_filename:='01_SEQUENCES.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
    v_payload := '';
    for x in c_tbl loop
      v_payload := v_payload || x.mycode; 
      v_comments := '';
      begin
        v_comments := dbms_metadata.get_dependent_ddl('COMMENT', x.object_name) || v_newline;
      exception
        when others then null;
      end;
      
      if v_comments is not null then
        v_payload := v_payload || v_comments || v_newline;
      end if;
    end loop;
    for x in c_view loop
      v_payload := v_payload || x.mycode; 
    end loop;
-- Doing the create view twice to solve dependencies
    for x in c_view loop
      v_payload := v_payload || x.mycode; 
    end loop;
    v_filename:='02_TABLES_VIEWS.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
    v_payload := '';
    for x in c_trig loop
      v_payload := v_payload || x.mycode || v_newline; 
    end loop;
    v_filename:='06_TRIGGERS.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
    v_payload := '';
    for x in c_constraints loop
      v_payload := v_payload || x.mycode || v_newline; 
    end loop;
    v_filename:='07_CONSTRAINTS.sql';
    upload_to_bucket (p_filename => v_filename, p_clob => v_payload);
  end;


