  procedure backup_all (p_app_id number) is
  begin
    ll_pkg_log.log(10,'Initiate full backup for P'||p_app_id);
    ll_pkg_log.log(20,'Start Apex App backup');
    create_apex_app_backup (p_app_id => p_app_id);
    ll_pkg_log.log(20,'Start Packages backup');
    create_packages_backup;
    create_packages_backup_unwrapped;
    ll_pkg_log.log(20,'Start DATA App backup');
    create_data_backup;
    create_apexapps_log_backup;
    ll_pkg_log.log(20,'Start TABLES and VIEWS backup');
    create_table_view_backup;
    ll_pkg_log.log(20,'Start Remaining backup');
    create_remaining_DDL_backup;
    ll_pkg_log.log(10,'End of call');  
  end;
--
--  ########     ###     ######  ##    ## ##     ## ########     ########  ##     ##  ######  ##     ## 
--  ##     ##   ## ##   ##    ## ##   ##  ##     ## ##     ##    ##     ## ##     ## ##    ## ##     ## 
--  ##     ##  ##   ##  ##       ##  ##   ##     ## ##     ##    ##     ## ##     ## ##       ##     ## 
--  ########  ##     ## ##       #####    ##     ## ########     ########  ##     ##  ######  ######### 
--  ##     ## ######### ##       ##  ##   ##     ## ##           ##        ##     ##       ## ##     ## 
--  ##     ## ##     ## ##    ## ##   ##  ##     ## ##           ##        ##     ## ##    ## ##     ## 
--  ########  ##     ##  ######  ##    ##  #######  ##           ##         #######   ######  ##     ## 
--
  procedure backup_push (p_app_id number) is
  
  begin
    ll_pkg_log.log(10,'Start Backup push for p_app_id: '||p_app_id);
    ll_pkg_log.log(20,'Start Apex App backup');
    create_apex_app_backup (p_app_id => p_app_id);
    ll_pkg_log.log(20,'Start Packages backup');
    create_packages_backup;
    create_packages_backup_unwrapped;
    ll_pkg_log.log(10,'End of call');  
  end;
  
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_BATCH" as

    function get_max_preference_points(p_environments_json clob) return number is
            v_max_pref_points number;
        begin
            select max(preference_points) into v_max_pref_points from JSON_TABLE (p_environments_json, '$[*]' COLUMNS (tenancy_id, region_id, environments, preference_points));
            return v_max_pref_points;
        end;

    function get_preferred_environment_count(p_environments_json clob) return number is
            v_preferred_ct number;
        begin
            select count(*) into v_preferred_ct from JSON_TABLE (p_environments_json, '$[*]' COLUMNS (tenancy_id, region_id, environments, preference_points)) where preference_points = (get_max_preference_points(p_environments_json));
            return v_preferred_ct;
        end;

    function create_default_schedule( p_workshop_id number, p_reservation_size number, p_batch_size number, p_interval number, p_start_time date, p_environments varchar2) return clob is
        v_avail_environments clob;
        v_schedule_json      json_array_t;
        v_schedule_object    json_object_t;
        v_tenancy_id number;
        v_region_id number;

        -- round-robin env list
        type t_env_rec is record (
            tenancy_id        number,
            region_id         number,
            preference_points number
        );
        type t_env_tab is table of t_env_rec index by pls_integer;

        v_envs          t_env_tab;
        v_env_ct        pls_integer := 0;

        v_batches       pls_integer;
        v_size          number;
        v_batch_time    timestamp;
        v_env_idx       pls_integer;
    begin
        -- Find available envs for this workshop
        ll_pkg_reservation.find_available_tenancy(
            p_tenancy_id     => v_tenancy_id,
            p_region_id      => v_region_id,
            p_available_json => v_avail_environments,
            p_workshop_id    => p_workshop_id
        );

        -- Collect only the envs the caller allowed (p_environments = 'TENANCY-REGION,...')
        for r in (
            select tenancy_id, region_id, preference_points
            from json_table(
                   v_avail_environments, '$[*]'
                   columns (
                     tenancy_id        number path '$.tenancy_id',
                     region_id         number path '$.region_id',
                     preference_points number path '$.preference_points'
                   )
                 )
            where tenancy_id || '-' || region_id in (
                    select column_value
                    from table(apex_string.split(p_environments, ','))
                  )
            order by preference_points desc
        )
        loop
            v_env_ct := v_env_ct + 1;
            v_envs(v_env_ct).tenancy_id        := r.tenancy_id;
            v_envs(v_env_ct).region_id         := r.region_id;
            v_envs(v_env_ct).preference_points := r.preference_points;
        end loop;

        if v_env_ct = 0 then
            return null;
        end if;

        -- Number of batches (e.g., 12/4 = 3)
        v_batches := ceil(p_reservation_size / p_batch_size);

        v_schedule_json := json_array_t();

        for j in 1 .. v_batches loop
            -- batch size (last batch may be smaller if not divisible)
            v_size := least(p_batch_size, p_reservation_size - (j-1) * p_batch_size);

            -- round-robin environment: 1..v_env_ct, then wrap
            v_env_idx := ((j-1) mod v_env_ct) + 1;

            -- start time for batch j
            v_batch_time := cast(p_start_time as timestamp)
                            + numtodsinterval(p_interval * (j-1), 'MINUTE');

            -- one JSON object per batch
            v_schedule_object := json_object_t.parse(
                '{' ||
                  '"batch_number":"'      || j || '",' ||
                  '"start_date":"'        || to_char(v_batch_time, 'MM/DD/YYYY') || '",' ||
                  '"start_time":"'        || to_char(v_batch_time, 'HH:MI AM')   || '",' ||
                  '"batch_size":"'        || v_size || '",' ||
                  '"tenancy_id":"'        || v_envs(v_env_idx).tenancy_id || '",' ||
                  '"region_id":"'         || v_envs(v_env_idx).region_id  || '",' ||
                  '"preference_points":"' || v_envs(v_env_idx).preference_points || '"' ||
                '}'
            );

            v_schedule_json.append(v_schedule_object);
        end loop;

        return v_schedule_json.to_clob();
    end create_default_schedule;


