    --                 FROM TABLE( APEX_STRING.SPLIT(p_environments, ',')));
        
    --     if v_env_ct = 0 then
    --         return null;
    --     end if;
    --     dbms_output.put_line('Count: ' || v_env_ct);

    --     -- What's the even distribution of reservations per env?
    --     v_base_per_env := floor(p_reservation_size/v_env_ct);

