  procedure new_group (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
   
    v_host              varchar2(200); 
    v_name              varchar2(100); 
    v_method            varchar2(200); 
