  procedure add_user_group (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
 
    v_host          varchar2(200); 
    v_method        varchar2(200) := '/20160918/userGroupMemberships'; 
    v_body          clob; 
    v_clob          clob; 
    v_memb_ocid     varchar2(200); 
 
    v_user_environments  number; 
    v_group_environments number; 
     
    v_user_ocid     varchar2(200); 
    v_group_ocid    varchar2(200); 
     
    function f_number (p_param_type varchar2) return number is 
      v_sqlstatement      varchar2(4000); 
      v_return_character  varchar2(10); 
      v_return_number     number; 
      begin 
        v_sqlstatement := 'select count(*) '||
                          'from ll_reservation_steps '|| 
                          'where reservation_id = '||p_reservation_id||' '||
                          'and JSON_VALUE(flow_step_param, '||dbms_assert.enquote_literal('$.type')||') = '||dbms_assert.enquote_literal(p_param_type);  
                          
        execute immediate v_sqlstatement into v_return_character;
        
        ll_pkg_log.log(40,'Result of count is: '||v_return_character); 
        v_return_number := to_number(v_return_character); 
        ll_pkg_log.log(40,'Numeric value of count is: '||v_return_number); 
         
        return(v_return_number); 
      end; 
 
  begin 
 
    ll_pkg_log.log(20,'Initial call'); 
 
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                          
    ll_pkg_log.log(40,'Host is: '||v_host); 
 
    v_user_environments  := f_number('ociUser'); 
    ll_pkg_log.log(40,'User environments is: '||v_user_environments); 
    v_group_environments := f_number('ociGroup'); 
    ll_pkg_log.log(40,'Group environments is: '||v_group_environments); 
 
    v_user_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociUser'); 
 
    ll_pkg_log.log(40,'user OCID for this step is: '||v_user_ocid); 
 
    v_group_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                          p_param_type     => 'ociGroup'); 
     
    if v_group_ocid is not null and v_user_ocid is not null then 
 
      v_body := JSON_OBJECT( 'userId'   value  v_user_ocid, 
                             'groupId'  value  v_group_ocid); 
                                
      v_clob := ll_pkg_exec.put_post(p_tenancy_id  => ll_pkg_reservation.tenancy_id(p_reservation_id), 
                                     p_type        => 'POST',  
                                     p_host        => v_host,  
                                     p_method      => v_method,  
                                     p_body        => v_body); 
 
      p_ocid := ll_pkg_admin.get_id(v_clob); 
  
      if p_ocid like 'ocid%' then 
        p_status := 'Y'; 
      else 
        p_status := 'N'; 
        p_result := v_clob; 
      end if; 
    else 
      p_status  := 'N'; 
      p_result  := 'Error - Group and/or user OCID not found'; 
    end if; 
     
  end;        
-- 
