-- 
  procedure user_password (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_user_ocid    varchar2(200);
    v_method       varchar2(2000);
    v_host         varchar2(500);
    v_password     varchar2(100);
    v_body         clob;
    v_clob         clob;
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                                             
    v_user_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociUser' ); 
                                                       
    v_method := '/20160918/users/' || v_user_ocid || '/uiPassword'; 
    v_body := '{}'; 
    v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                    p_type         => 'POST', 
                                    p_host         => v_host, 
                                    p_method       => v_method, 
                                    p_body         => v_body); 
    if v_clob is json then
      p_ocid := json_value(v_clob, '$.password' );
    end if;
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
    end if;
    
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
  end;
--  
--  ##     ##  ######  ######## ########        ###    ##     ## ######## ##     ##    ########  #######  ##    ## ######## ##    ## 
