--   #######   ######  ######## ##     ##    ##     ##  #######     ##    ##     ##       ##     #######  ##    ## ######## ##    ##
--
  procedure user_auth_token (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_user_ocid    varchar2(200);
    v_method       varchar2(2000);
    v_host         varchar2(500);
    v_body         clob;
    v_clob         clob;
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                                             
    v_user_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociUser' ); 
    v_method := '/20160918/users/' || v_user_ocid || '/authTokens/'; 
    v_body := JSON_OBJECT( 'description'   value 'Auth token for Livelabs reservation '||p_reservation_id); 
    v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                    p_type         => 'POST', 
                                    p_host         => v_host, 
                                    p_method       => v_method, 
                                    p_body         => v_body); 
    if v_clob is json then
      p_ocid := json_value(v_clob, '$.token' );
    end if;
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
    end if;
    
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
  end;
--  
--  ##     ##  ######  ######## ########        ###    ########  ####    ##    ## ######## ##    ## 
--  ##     ## ##    ## ##       ##     ##      ## ##   ##     ##  ##     ##   ##  ##        ##  ##  
--  ##     ## ##       ##       ##     ##     ##   ##  ##     ##  ##     ##  ##   ##         ####   
--  ##     ##  ######  ######   ########     ##     ## ########   ##     #####    ######      ##    
--  ##     ##       ## ##       ##   ##      ######### ##         ##     ##  ##   ##          ##    
--  ##     ## ##    ## ##       ##    ##     ##     ## ##         ##     ##   ##  ##          ##    
--   #######   ######  ######## ##     ##    ##     ## ##        ####    ##    ## ########    ##   
--
  procedure user_api_key (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_user_ocid    varchar2(200);
    v_method       varchar2(2000);
    v_host         varchar2(500);
    v_body         clob;
    v_clob         clob;
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                                             
    v_user_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociUser' ); 
                                                       
    v_method := '/20160918/users/' || v_user_ocid || '/apiKeys'; 
    v_body := JSON_OBJECT( 'key'   value ll_pkg_reservation.public_key (p_reservation_id => p_reservation_id)); 
    v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                    p_type         => 'POST', 
                                    p_host         => v_host, 
                                    p_method       => v_method, 
                                    p_body         => v_body); 
    if v_clob is json then
      p_ocid := json_value(v_clob, '$.fingerprint' );
    end if;
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
    end if;
    
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
  end;


  procedure check_old_comp (p_reservation_id IN number, p_comp_id OUT varchar2, p_renamed OUT boolean, p_moved OUT boolean) AS
    cursor c_tenancies (p_tenancy_id number) is 
                          select available_ocid, DEFAULT_COMPARTMENT_OCID
                          from ll_tenancies
                          where id = p_tenancy_id
                          and available_ocid is not null;
    
    v_response clob;
    v_available_ocid varchar2(4000);
    v_default_ocid varchar2(4000);
  begin
    open c_tenancies(ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id));
    fetch c_tenancies into v_available_ocid, v_default_ocid;
    close c_tenancies;
    v_response := ll_pkg_exec.get (p_tenancy_id     => ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id),
                                  p_host           => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)),
                                  p_compartment_id => v_available_ocid,
                                  p_method         => '/20160918/compartments',
                                  p_query_string   => 'name=LL'||p_reservation_id||'-COMPARTMENT',
                                  p_multiple_page  => 'Y' );     
    if json_value(v_response, '$[0].id') is not null then 
        p_renamed := true;
        p_moved := false;
        p_comp_id := json_value(v_response, '$[0].id');
        return;
    else 
        v_response := ll_pkg_exec.get (p_tenancy_id     => ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id),
                                  p_host           => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)),
                                  p_compartment_id => v_default_ocid,
                                  p_method         => '/20160918/compartments',
                                  p_query_string   => 'name=LL'||p_reservation_id||'-COMPARTMENT',
                                  p_multiple_page  => 'Y' );     
        if json_value(v_response, '$[0].id') is not null  then
            p_renamed := true;
            p_moved := true;
            p_comp_id := json_value(v_response, '$[0].id');
            return;
        else
            p_renamed := false;
            p_moved := false;
            p_comp_id := null;
            return;
        end if;
    end if;
  exception when others then 
    p_renamed := false;
    p_moved := false;
    p_comp_id := null;
  end;

-- 
--     ######   #######  ##     ## ########     ###    ########  ######## ##     ## ######## ##    ## ########  
--    ##    ## ##     ## ###   ### ##     ##   ## ##   ##     ##    ##    ###   ### ##       ###   ##    ##     
--    ##       ##     ## #### #### ##     ##  ##   ##  ##     ##    ##    #### #### ##       ####  ##    ##     
--    ##       ##     ## ## ### ## ########  ##     ## ########     ##    ## ### ## ######   ## ## ##    ##     
--    ##       ##     ## ##     ## ##        ######### ##   ##      ##    ##     ## ##       ##  ####    ##     
--    ##    ## ##     ## ##     ## ##        ##     ## ##    ##     ##    ##     ## ##       ##   ###    ##     
--     ######   #######  ##     ## ##        ##     ## ##     ##    ##    ##     ## ######## ##    ##    ##       
--
  procedure compartment (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    cursor c_tenancies (p_tenancy_id number) is 
                          select available_ocid
                          from ll_tenancies
                          where id = p_tenancy_id
                          and available_ocid is not null;
    cursor c_policies is select listagg(policy_tag_code,',')
                         from ll_policies
                         where id in (select policy_id
                                      from ll_workshop_policies
                                      where workshop_id in (select workshop_id
                                                            from ll_reservations
                                                            where id = p_reservation_id ));                             
    v_tenancy_id            number;
    v_host                  varchar2(4000);
    v_region_key            varchar2(100);
    v_method                varchar2(2000);
    v_default_ocid          varchar2(200);
    v_compartment_name      varchar2(100);
    v_description           varchar2(4000);
    v_owner                 varchar2(100);
    v_permissions           varchar2(2000);
    v_workshop_id           varchar2(100);
    v_event_id              varchar2(100);
    v_compartments_clob  clob;
    v_compartment_limit  number;
    v_available_ocid     varchar2(500);
    v_repeat             number;
    v_body               clob;
    v_clob               clob;
    v_sto_compartments_clob_len number;
    v_sto_compartments_clob_json varchar2(4000);
    v_sto_repeat1 number;
    v_sto_p_ocid varchar2(4000);
    type t_refcurtype IS REF CURSOR;
    c_compartments     t_refcurtype;

    v_comp_id           varchar2(4000);
    v_renamed           boolean := false;
    v_moved             boolean := false;
    v_retry             number;                                        
  begin
  
    ll_pkg_log.log(20,'Initial call: p_reservation_id: '||p_reservation_id||', p_res_step_id: '||p_res_step_id);
    ll_pkg_security.set_security_group;
    
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id);
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
    v_region_key := ll_pkg_reservation.region_key(p_reservation_id);
    v_default_ocid := ll_pkg_reservation.default_comp_ocid (p_reservation_id => p_reservation_id);
    ll_pkg_log.log(40,'v_tenancy_id: '||v_tenancy_id);
    if v_default_ocid is null then
      v_default_ocid := ll_pkg_reservation.tenancy_ocid(p_reservation_id => p_reservation_id);
    end if;
    ll_pkg_log.log(40,'Default compartment OCID: '||v_default_ocid);
    v_compartment_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                           p_res_step_id    => p_res_step_id,
                                                           p_json_name      => 'name');
                                                           
    v_description :=  'Compartment for Livelabs reservation '||p_reservation_id;  
    v_owner      := ll_pkg_reservation.user_object_name (p_reservation_id  => p_reservation_id,
                                                         p_param_type      => 'ociUser');
-- Retrieve the OCID of the AVAILABLE compartment for this environment and tenancy
    open c_tenancies(v_tenancy_id);
    fetch c_tenancies into v_available_ocid;
    close c_tenancies;
    ll_pkg_log.log(40,'v_available_ocid: '||v_available_ocid);
-- Retrieve permissions for the reservation for the compartment
    open c_policies;
    fetch c_policies into v_permissions;
    close c_policies;
-- on retrys, attempt to find an already renamed comp 
    select create_retry into v_retry from ll_reservation_steps where id = p_res_step_id;
    if nvl(v_retry, 0) > 0 then 
        apex_util.pause(120 + dbms_random.value(1, 30));  
        check_old_comp(p_reservation_id => p_reservation_id, p_comp_id => v_comp_id, p_renamed => v_renamed, p_moved => v_moved);
        p_ocid := v_comp_id;
    end if;
    if nvl(v_retry, 0) = 0 or p_ocid is null then 
-- Retrieve list of compartments in the AVAILABLE list
        v_repeat := 0;
        ll_pkg_log.log(30,'Fetching list of compartments in the AVAILABLE compartment for this tenancy');
        v_compartment_limit := nvl(ll_pkg_admin.is_number(ll_pkg_admin.system_parameter('FETCH_COMPARTMENT_LIMIT')),10);
        while ( length(v_compartments_clob) < 10 or JSON_VALUE(v_compartments_clob,'$.code') = 'NotAuthorizedOrNotFound' or v_compartments_clob is null) and v_repeat <= 5 loop
          v_compartments_clob := ll_pkg_exec.get (p_tenancy_id     => v_tenancy_id,
                                                  p_host           => v_host,
                                                  p_compartment_id => v_available_ocid,
                                                  p_method         => '/20160918/compartments',
                                                  p_query_string   => 'sortBy=NAME&limit='||v_compartment_limit,
                                                  p_multiple_page  => 'Y' );                                              
          v_repeat := v_repeat + 1;
          ll_pkg_log.log(40,'v_repeat: '||v_repeat);
          ll_pkg_log.log(40,'v_compartments_clob: '||substr(v_compartments_clob,1,3500));
          ll_pkg_log.log(40,'length v_compartments_clob: '||length(v_compartments_clob));
        end loop;
        v_sto_compartments_clob_len := length(v_compartments_clob);
        v_sto_compartments_clob_json := JSON_VALUE(v_compartments_clob,'$.code');
        v_sto_repeat1 := v_repeat;
    -- Get OCID from compartment not on the used list
        ll_pkg_log.log(30,'Trying to find compartment on AVAILABLE list');
        v_repeat := 0;
        open c_compartments for q'@select id 
                               from json_table( :v, '$[*]' COLUMNS (id, name, lifecycleState))
                               where lifecyclestate <> 'DELETED'
                               order by name asc@' using v_compartments_clob;
        while (p_ocid is null and c_compartments%FOUND) or v_repeat = 0 loop
          fetch c_compartments into p_ocid;
          if c_compartments%found then
            begin
              ll_pkg_log.log(40,'v_repeat: '||v_repeat||', Compartment '||p_ocid||' found, attempt to insert on compartments used list');
              insert into ll_compartments_used (compartment_ocid, reservation_id, date_allocated, status, tenancy_id) values (p_ocid, p_reservation_id, sysdate, 'RESERVED', v_tenancy_id);
              commit;
              ll_pkg_log.log(40,'Compartment '||p_ocid||' has been succesfully inserted !');
            exception
              when DUP_VAL_ON_INDEX then
                begin
                  ll_pkg_log.log(30,'We have a DUP_VAL_ON_INDEX error, trying next compartment');
                  p_ocid := '';
                end;
            end;
          else
            ll_pkg_log.log(40,'v_repeat: '||v_repeat||', No more compartments found');
          end if;
          v_repeat := 1;
        end loop;
    -- If we have an OCID at this moment, it has been inserted into the table and nobody else is using it. So we can continue..    
        close c_compartments;
        v_sto_p_ocid := p_ocid;
    end if;
    select workshop_id into v_workshop_id
                                                            from ll_reservations
                                                            where id = p_reservation_id;
    
    -- get event id if one exists
    select voucher_id into v_event_id 
            from ll_reservations 
            where id = p_reservation_id;
  
    if p_ocid is not null and v_renamed = false then
      ll_pkg_log.log(30,'Compartment '||p_ocid||' has been found, no need for a new compartment');
      ll_pkg_admin.update_compartment (p_tenancy_id   => v_tenancy_id,
                                       p_compartment  => p_ocid,
                                       p_name         => v_compartment_name,
                                       p_description  => v_description,
                                       p_owner        => v_owner,
                                       p_region       => v_region_key,
                                       p_permissions  => v_permissions,
                                       p_workshop_id  => v_workshop_id,
                                       p_event_id     => v_event_id);
 
     /* Wrap update in a catch block, if Code is CompartmentAlreadyExists then take the v_compartment_name, 
        find the ocid of the v_compartment_name that is currently in use and rename it, pause 5 seconds
        then rerun the above command. If not move that logic down into the update compartment procedure in the attempt block of that
        procedure.Check the result there and handle it. */
    end if;
    if p_ocid is not null and v_moved = false then
      apex_util.pause(5);                                           
      ll_pkg_admin.move_compartment (p_tenancy_id   => v_tenancy_id,
                                       p_compartment  => p_ocid,
                                       p_dest         => 'DEFAULT');                              
                                       
    end if;
-- If we get here and the p_ocid is null, we cannot re-use an existing compartment.
-- In order to continue, we need to create a new compartment in the tenancy.    
    if p_ocid is null then
      -- Create new compartment
      ll_pkg_log.log(30,'Creating new compartment');
      ll_pkg_log.log(1,'New Compartment - Clob Length:' || v_sto_compartments_clob_len || ' Clob Json: ' || v_sto_compartments_clob_json || ' Repeat: ' || v_sto_repeat1 ||  ' OCID: ' || v_sto_p_ocid);
    --   ll_pkg_exec.send_prowl (p_error_type => 'COMPARTMENT-CREATE', 
    --                                     p_event      => 'Compartment Created', 
    --                                     p_message    => 'New Compartment - Clob Length:' || v_sto_compartments_clob_len || ' Clob Json: ' || v_sto_compartments_clob_json || ' Repeat: ' || v_sto_repeat1 ||  ' OCID: ' || v_sto_p_ocid, 
    --                                     p_priority   => 1);
      v_method := '/20160918/compartments'; 
    --   v_body := JSON_OBJECT ('compartmentId'    value v_default_ocid,
    --                          'description'      value v_description,
    --                          'name'             value v_compartment_name);
      v_body := json_object( 'compartmentId'    value v_default_ocid,
                             'description'      value v_description,
                             'name'             value v_compartment_name,
                             'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS')),
                             'definedTags'  value json_object( 'Livelabs'     value JSON_OBJECT( 'Owner'  value nvl(v_owner,'Empty'),
                                                                                                 'Region'            value nvl(v_region_key,'Empty'),
                                                                                                 'Permissions'       value nvl(v_permissions,'Empty'),
                                                                                                 'WorkshopID'  value nvl(v_workshop_id, 'Empty'),
                                                                                                 'EventID'     value nvl(v_event_id, 'Empty')
                                                                                               )
                                                             )
                           );
                             
      v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                      p_type         => 'POST', 
                                      p_host         => v_host, 
                                      p_method       => v_method, 
                                      p_body         => v_body); 
      p_ocid := ll_pkg_admin.get_id(v_clob);  
    --   ll_pkg_admin.update_compartment (p_tenancy_id   => v_tenancy_id,
    --                                    p_compartment  => p_ocid,
    --                                    p_name         => v_compartment_name,
    --                                    p_description  => v_description,
    --                                    p_owner        => v_owner,
    --                                    p_region       => v_region_key,
    --                                    p_permissions  => v_permissions,
    --                                    p_workshop_id  => v_workshop_id,
    --                                    p_event_id     => v_event_id);
    end if;
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
--  
--  ########   #######  ##       ####  ######  ##    ## 
--  ##     ## ##     ## ##        ##  ##    ##  ##  ##  
--  ##     ## ##     ## ##        ##  ##         ####   
--  ########  ##     ## ##        ##  ##          ##    
--  ##        ##     ## ##        ##  ##          ##    
--  ##        ##     ## ##        ##  ##    ##    ##    
--  ##         #######  ######## ####  ######     ##   
--
  procedure policy (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    cursor c_ws_policies is select llp.policy_text, nvl(llp.restrict_region, llwp.restrict_region) as restrict_region, apply_using_tags
                            from ll_workshop_policies llwp, ll_policies llp
                            where llwp.policy_id = llp.id
                            and nvl(llp.active_flg,'Y') = 'Y'
                            and nvl(llwp.active_flg,'Y') = 'Y'
                            and llwp.workshop_id = (select workshop_id from ll_reservations where id = p_reservation_id);
    cursor c_sysparam is select /*+ RESULT_CACHE */ replace(value,'TRUE','Y') from ll_system_parameters where name='POLICY_TAGS'; 
    v_comp_ocid           varchar2(200);
    v_grp_ocid            varchar2(200);
    v_method              varchar2(2000);
    v_host                varchar2(500);
    v_region              varchar2(50);
    v_name                varchar2(200);
    v_body                clob;
    v_clob                clob;
    v_num_lines           number := 0;
    v_skipped_lines       number := 0;
    v_tenancy_ocid        varchar2(2000);
    v_policy_line         varchar2(1000);
    v_service_id          varchar2(200);
    v_dynamic_group_name  varchar2(200);
    v_apply_using_tags    varchar2(1);
    
  begin
    v_region := ll_pkg_reservation.region_key(p_reservation_id);
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                                               
    v_name := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                              p_res_step_id   => p_res_step_id, 
                                              p_json_name     => 'name'); 
                                                               
    v_grp_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                      p_param_type     => 'ociGroup' ); 
                                                      
    v_comp_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociCompartment' ); 
    v_dynamic_group_name := ll_pkg_reservation.user_object_name (p_reservation_id  => p_reservation_id,
                                                                 p_param_type      => 'ociDynamicGroup');
    v_tenancy_ocid := ll_pkg_reservation.tenancy_ocid (p_reservation_id => p_reservation_id);
    v_apply_using_tags := ll_pkg_admin.system_parameter('POLICY_TAGS');
                                                       
    v_method := '/20160918/policies'; 
    v_body := '{ "compartmentId" : "'||v_tenancy_ocid||'", "description" : "Policy for LiveLabs reservation '||p_reservation_id||'", "name" : "'||v_name||'", '|| 
              '"statements" : [ ';
    for x in c_ws_policies loop
      if nvl(v_apply_using_tags,'N') = 'N' or nvl(x.apply_using_tags,'N')='N' then
        v_num_lines := v_num_lines + 1;
        v_policy_line := '"' || x.policy_text;
        v_policy_line := replace(v_policy_line, '{groupName}'       , 'id '||v_grp_ocid);
        v_policy_line := replace(v_policy_line, '{compartmentName}' , 'id '||v_comp_ocid);
        v_policy_line := replace(v_policy_line, '{dynamicGroupName}', v_dynamic_group_name);
      
        v_body := v_body || v_policy_line;
    
        if x.restrict_region='Y' then
          v_body := v_body ||' where request.region='||chr(39)||v_region||chr(39);
        end if;
      
        v_body := v_body || '",';
      else
        v_skipped_lines := v_skipped_lines + 1;
      end if;
      
    end loop;
    
    if substr(v_body,length(v_body),1)=',' then
      v_body := substr(v_body,1,length(v_body)-1);
    end if;
    
    v_body := v_body || '] }'; 
    
    if v_num_lines > 0 then
    
      v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                      p_type         => 'POST', 
                                      p_host         => v_host, 
                                      p_method       => v_method, 
                                      p_body         => v_body); 
      if v_clob is json then
        p_ocid := json_value(v_clob, '$.id' );
        ll_pkg_log.log(40,'OCID is '||p_ocid);
      else
        ll_pkg_log.log(40,'No OCID found in result');
      end if;
    
      if p_ocid is null and v_num_lines > 0 then
        p_status := 'N';
        p_result := v_clob;
      else
        p_status := 'Y';
        p_result := case when v_skipped_lines + v_num_lines > 0 and v_apply_using_tags = 'Y' then 'Implemented using tags ('||v_num_lines||' in policy/'||v_skipped_lines||' skipped through tags)' end;
      end if;
    else
      p_status := 'Y';
      p_result := case when v_skipped_lines + v_num_lines > 0 and v_apply_using_tags = 'Y' then 'Implemented using tags ('||v_num_lines||' in policy/'||v_skipped_lines||' skipped through tags)' end;
      p_ocid   := '';
    end if;
    
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
  end;
