  procedure vcn (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_vcn_name          varchar2(200); 
    v_dns_name          varchar2(200);
    v_compartment_ocid  varchar2(200);
    v_dhcp_id           varchar2(200);
    v_seclist_id        varchar2(200);
    v_route_id          varchar2(200);
    v_json_result       varchar2(4000);
    v_body              clob;
    v_clob              clob;
    v_tenancy_id        number;
  begin
    ll_pkg_log.log(20,'Initial call');
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_method := '/20160918/vcns';
    v_vcn_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                   p_res_step_id    => p_res_step_id,
                                                   p_json_name      => 'name');
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
    if v_compartment_ocid is null then
      v_compartment_ocid := ll_pkg_admin.default_compartment_ocid ( p_tenancy_id => ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id));
    end if;
                                                              
    v_body := json_object ('cidrBlock'      VALUE '10.0.0.0/16',
                           'compartmentId'  VALUE v_compartment_ocid,
                           'displayName'    VALUE v_vcn_name,
                           'dnsLabel'       VALUE substr(lower(replace(v_vcn_name,'-','')), 1, 15));
                           
    for x in 1..8 loop
      ll_pkg_log.log(30,'Waiting 80 seconds, '||to_char((x-1)*10)||' seconds passed for previous steps to sync to the region');
      apex_util.pause(10);
    end loop;
    
    ll_pkg_log.log(30,'End of waiting, lets create a VCN !');
   
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'POST',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    p_ocid        := json_value(v_clob,'$.id');
    v_dhcp_id     := json_value(v_clob,'$.defaultDhcpOptionsId');
    v_route_id    := json_value(v_clob,'$.defaultRouteTableId');
    v_seclist_id  := json_value(v_clob,'$.defaultSecurityListId');
    
    v_json_result := json_object( 'ociVcnDhcp'     value v_dhcp_id,
                                  'ociVcnRoute'    value v_route_id,
                                  'ociVcnSeclist'  value v_seclist_id );
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
      p_result := v_json_result;
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
