  procedure internetgw (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_object_name       varchar2(200); 
    v_vcn_id            varchar2(200);
    v_dns_label         varchar2(200);
    v_compartment_ocid  varchar2(200);
    v_body              clob;
    v_clob              clob;
  begin
    ll_pkg_log.log(20,'Initial call');
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_method := '/20160918/internetGateways';
    v_object_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                      p_res_step_id    => p_res_step_id,
                                                      p_json_name      => 'name');
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
    v_vcn_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                    p_param_type     => 'ociVcn'); 
    v_body := json_object ('displayName'   VALUE v_object_name,
                           'vcnId'         VALUE v_vcn_id,
                           'compartmentId' VALUE v_compartment_ocid,
                           'isEnabled'     VALUE 'true');                         
 
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'POST',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    p_ocid        := json_value(v_clob,'$.id');
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
      p_result := '';
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
    procedure service_gw (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_object_name       varchar2(200); 
    v_vcn_id            varchar2(200);
    v_dns_label         varchar2(200);
    v_compartment_ocid  varchar2(200);
    v_body              clob;
    v_clob              clob;
    v_region_key        varchar2(10);
    v_service_ocid      varchar2(200);
    v_service_clob      clob;
  begin
    ll_pkg_log.log(20,'Initial call');
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_method := '/20160918/serviceGateways';
    v_object_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                      p_res_step_id    => p_res_step_id,
                                                      p_json_name      => 'name');
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
    ll_pkg_log.log(40,'Compartment OCID' || v_compartment_ocid);
    v_vcn_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                    p_param_type     => 'ociVcn'); 
    ll_pkg_log.log(40,'VCN OCID: ' || v_vcn_id);
    v_region_key := lower(ll_pkg_admin.region_key(p_region_id =>
                                                    ll_pkg_reservation.region_id (p_reservation_id => p_reservation_id)));
    v_service_clob := ll_pkg_exec.get(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id), 
                            p_host =>ll_pkg_admin.oci_endpoint( p_type => 'iaas', p_region_key => v_region_key), 
                            p_method =>'/20160918/services');
    ll_pkg_log.log(40,'OCI Services clob: ' || v_service_clob);
    
    if v_service_clob is not null then
        begin
            select ocid into v_service_ocid from json_table(v_service_clob,
                                '$[*]' columns (ocid varchar path '$.id',cidrBlock,service_name varchar path '$.name',message varchar path '$.description')) 
                                 where (cidrBlock like '%oracle-services-network%' or
                                lower(message) like '%oracle services network%' or
                                lower(service_name) like '%oracle services network%')
                                and rownum = 1;
            
            ll_pkg_log.log(40,'OCI Services OCID: ' || v_service_ocid);  
        exception
            when no_data_found then
                -- p_result := 'No data found for the service OCID that the service gateway would target.';
                ll_pkg_log.log(40,'No data found: ' || SQLERRM);
        end;
    end if;
    v_body := json_object ('displayName'   VALUE v_object_name,
                           'vcnId'         VALUE v_vcn_id,
                           'compartmentId' VALUE v_compartment_ocid,
                           'services'      VALUE json_array(json_object('serviceId' VALUE v_service_ocid)));      
    
   ll_pkg_log.log(40,'v_body: ' || v_body);                  
 
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'POST',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    p_ocid        := json_value(v_clob,'$.id');
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
      p_result := '';
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
