--
  procedure securitylist (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
  
    cursor c_oracle_cidr (p_region_identifier varchar2, p_reservation_id number) is 
                        select * from (
                         select region, cidr, protocol, region||' for '||listagg(tag,' and ') within group (order by cidr) as remark
                         from ll_oci_service_cidrs_mvw
                         where (tag in ('OBJECT_STORAGE','STUN','GITHUB','GOOGLE','ifconfig.me','Akamai')
                                or  
                               (tag in ('OSN','YUM','OCI') and region = p_region_identifier )  
                                or
                               (tag in ('OSN') and (region = 'us-chicago-1' or (region = ll_pkg_create.genai_endpoint_region(p_region_identifier, p_reservation_id, p_res_step_id) and ll_pkg_create.is_genai_workshop(p_reservation_id) = 'Y')) ))                                      
                         group by region, cidr, protocol                                   
                         order by region, cidr
                        );
    
    v_egress_rules      clob;
    v_ingress_rules     clob;
    v_object_ocid       varchar2(200);
    v_object_name       varchar2(200);
    
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_compartment_ocid  varchar2(200);
    v_body              clob;
    v_clob              clob;
    
    v_region_id         number;
    v_region_identifier varchar2(50);
    v_region_key        varchar2(10);
    v_parameter         varchar2(4000);
    v_continue          varchar2(1);
    v_number            number;
    v_description       varchar2(500);
    v_direction         varchar2(100);
    v_protocol          varchar2(500);
    v_cidr              varchar2(100);
    v_cidr_rule         varchar2(100);
    v_port              varchar2(100);
    v_min_port          varchar2(100);
    v_max_port          varchar2(100);
 
    v_sl_count number;
    v_cidr_clob clob;
    v_vcn_ocid varchar2(4000);
 
    v_port_range varchar2(4000);
 
    function secRuleBlockType(v_destination varchar2) return varchar2 is
        begin
            if (instr(v_destination,'oracle-services-network') > 0 or instr(v_destination,'-objectstorage') > 0) then
                return 'SERVICE_CIDR_BLOCK';
            else
                return 'CIDR_BLOCK'; 
            end if;
        end;
    
  begin
    ll_pkg_log.log(20,'Initial call');
    v_parameter := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                    p_res_step_id    => p_res_step_id,
                                                    p_json_name      => 'param1');
-- Combination of the OSN and OBJECT_STORAGE destinations + any valid values in the ociVCN and ociSecList setup parameter steps    
-- If no additional parameters, only Oracle OSN and OBJECT_STORAGE rules and only access from Internet to environment using port 22, no outgoing activity allowed expect for Oracle Services
-- Source for OSN, OCI and OBJECT_STORAGE is https://docs.cloud.oracle.com/en-us/iaas/Content/General/Concepts/addressranges.htm
  
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id => p_reservation_id);
    v_region_identifier := ll_pkg_admin.region_identifier (p_region_id => v_region_id);
    v_region_key := lower(ll_pkg_admin.region_key(p_region_id => v_region_id));
  
    v_Egress_Rules  := '[';
    v_Ingress_Rules := '[';
-- Additional rules from either the ociVcn or ociSecList (ociSecList preferred, if empty then ociVcn to be sure)
    v_continue := 'Y';
    v_number := 0;
    while v_continue = 'Y' and v_number < 100 loop
      v_description := JSON_VALUE (v_parameter, '$['||v_number||'].description');
      v_direction   := JSON_VALUE (v_parameter, '$['||v_number||'].direction');
      v_protocol    := JSON_VALUE (v_parameter, '$['||v_number||'].protocol');
      v_port        := JSON_VALUE (v_parameter, '$['||v_number||'].port');
      v_cidr        := JSON_VALUE (v_parameter, '$['||v_number||'].cidr');
      if v_direction='I' and v_cidr is null then
        v_cidr := '0.0.0.0/0';
      end if;
      if upper(v_port) = 'ALL' and v_cidr <> '0.0.0.0/0' then
        v_min_port := '0';
        v_max_port := '65536';
      else
        v_min_port := v_port;
        v_max_port := v_port;
      end if;
        
      if v_direction is null then 
        v_continue := 'N';
      elsif v_direction = 'I' then
        v_Ingress_rules := v_Ingress_rules || JSON_OBJECT ('source'           value v_cidr,
                                                          'sourceType'       value 'CIDR_BLOCK',
                                                          'isStateless'      value 'false',
                                                          'protocol'         value case v_protocol when 'ALL' then 'all' when 'UDP' then '17' else '6' end,
                                                          case v_protocol when 'UDP' then 'udpOptions' else 'tcpOptions' end 
                                                                             value JSON_OBJECT ( 'destinationPortRange' value JSON_OBJECT ( 'min' value v_min_port, 'max' value v_max_port ) ),
                                                          'description'      value v_description ) || ',';
      elsif v_direction = 'E' then
        v_Egress_rules := v_Egress_rules || JSON_OBJECT ('destination'      value v_cidr,
                                                         'destinationType'  value 'CIDR_BLOCK',
                                                         'isStateless'      value 'false',
                                                         'protocol'         value case v_protocol when 'ALL' then 'all' when 'UDP' then '17' else '6' end,
                                                         case v_protocol when 'UDP' then 'udpOptions' else 'tcpOptions' end 
                                                                            value JSON_OBJECT ( 'destinationPortRange' value JSON_OBJECT ( 'min' value v_min_port, 'max' value v_max_port ) ),
                                                         'description'      value v_description ) || ',';
      end if;                                                           
      v_number := v_number + 1;
    end loop;
 
    -- add custom SL rules
    for cidr in (select c.protocol, c.direction, c.cidr, c.port_min_or_type, c.port_max_or_code, c.description
                    from ll_workshop_cidrs c, ll_workshop_cidrs_ref r 
                        where r.workshop_id = ll_pkg_reservation.workshop_id(p_reservation_id)
                            and r.cidr_id = c.id) loop
 
        v_cidr_rule := replace(cidr.cidr, '$region', v_region_key);
 
        if cidr.direction = 'I' then
            if cidr.protocol = 1 then
                v_ingress_rules := v_ingress_rules || JSON_OBJECT ('source' value v_cidr_rule,
                                                            'isStateless'   value 'false',
                                                            'sourceType'    value secRuleBlockType(v_cidr_rule),
                                                            'protocol'      value cidr.protocol,
                                                            'description'   value cidr.description,
                                                            'icmpOptions' value JSON_OBJECT ( 'type' value cidr.port_min_or_type, 'code' value cidr.port_max_or_code )
                                                          ) || ',';
            else
                v_ingress_rules := v_ingress_rules || JSON_OBJECT ('source'          value v_cidr_rule,
                                                                  'isStateless'      value 'false',
                                                                  'sourceType'       value secRuleBlockType(v_cidr_rule),
                                                                  'protocol'         value cidr.protocol,
                                                                  'description'      value cidr.description,
                                                                  case cidr.protocol when 17 then 'udpOptions' else 'tcpOptions' end 
                                                                  value JSON_OBJECT ( 'destinationPortRange' value JSON_OBJECT ( 'min' value cidr.port_min_or_type, 'max' value nvl(cidr.port_max_or_code, cidr.port_min_or_type) ) )
                                                                  ) || ',';
            end if;
        end if;
        if cidr.direction = 'E' then
            if cidr.protocol = 1 then
                v_egress_rules := v_egress_rules || JSON_OBJECT ('destination' value v_cidr_rule,
                                                            'isStateless'      value 'false',
                                                            'destinationType'  value secRuleBlockType(v_cidr_rule),
                                                            'protocol'         value cidr.protocol,
                                                            'description'      value cidr.description,
                                                            'icmpOptions'      value JSON_OBJECT ( 'type' value cidr.port_min_or_type, 'code' value cidr.port_max_or_code )
                                                          ) || ',';
            else
                v_egress_rules := v_egress_rules || JSON_OBJECT ('destination' value v_cidr_rule,
                                                                 'isStateless'        value 'false',
                                                                 'destinationType'    value secRuleBlockType(v_cidr_rule),
                                                                 'protocol'           value cidr.protocol,
                                                                 'description'        value cidr.description,
                                                                 case cidr.protocol when 17 then 'udpOptions' else 'tcpOptions' end 
                                                                 value JSON_OBJECT ( 'destinationPortRange' value JSON_OBJECT ( 'min' value cidr.port_min_or_type, 'max' value nvl(cidr.port_max_or_code, cidr.port_min_or_type) ) )
                                                          ) || ',';
            end if;
        end if;
    end loop;
    -- add service CIDRs
    v_egress_rules := v_egress_rules || JSON_OBJECT ('destination' value 'all-' || v_region_key || '-services-in-oracle-services-network',
                                                     'destinationType'    value 'SERVICE_CIDR_BLOCK',
                                                     'protocol'           value '6',
                                                     'description'        value 'Region Services'
                                              );
 
    if substr(v_Egress_rules, length(v_Egress_rules)) = ',' then
      v_Egress_rules := substr(v_Egress_rules, 1, length(v_Egress_rules)-1);
    end if;
    
    v_Egress_rules := v_Egress_rules ||']';
    
-- INGRESS RULES (already filled with any default values)      
  -- Bare minimum ingress rules; only access through port 22. This can change in the future using the flow step parameters
  
    v_Ingress_Rules := v_Ingress_Rules || 
                       '{ "protocol": "6", "source": "0.0.0.0/0", "sourceType": "CIDR_BLOCK", "tcpOptions": { "destinationPortRange": { "max": 22, "min": 22 } } }, '||
                       '{ "protocol": "6", "source": "0.0.0.0/0", "sourceType": "CIDR_BLOCK", "tcpOptions": { "destinationPortRange": { "max": 6080, "min": 6080 } } }, '||
                       '{ "icmpOptions": { "code": 4, "type": 3 }, "protocol": "1", "source": "0.0.0.0/0", "sourceType": "CIDR_BLOCK" }, '||
                       '{ "icmpOptions": { "type": 3 }, "protocol": "1", "source": "10.0.0.0/16", "sourceType": "CIDR_BLOCK" } '||
                       ']';
    ll_pkg_log.log(40,'Egress_rules are: '||v_Egress_rules);
    ll_pkg_log.log(40,'Ingress_rules are: '||v_Ingress_rules);
                       
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_object_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                      p_res_step_id    => p_res_step_id,
                                                      p_json_name      => 'name');
    v_object_ocid := ll_pkg_reservation.flow_step_result (p_reservation_id  => p_reservation_id,
                                                          p_param_type      => 'ociVcn',
                                                          p_result_type     => 'ociVcnSeclist');
    v_method := '/20160918/securityLists/'||v_object_ocid;
    v_body := json_object ('displayName'          VALUE v_object_name,
                             'egressSecurityRules'  VALUE '@1',
                             'ingressSecurityRules' VALUE '@2');
                                                                           
    v_body := replace(v_body,'"@1"',v_egress_rules);
    v_body := replace(v_body,'"@2"',v_ingress_rules);
                                                              
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'PUT',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    ll_pkg_log.log(40,'SL API result: ' || v_clob);
 
    p_ocid        := v_object_ocid;
 
 
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, p_param_type => 'ociCompartment');
    v_vcn_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, p_param_type => 'ociVcn');
 
    -- create SLs for each tag in the CIDRs materialized view
    v_Ingress_rules := '[{ "protocol": "6", "source": "0.0.0.0/0", "sourceType": "CIDR_BLOCK", "tcpOptions": { "destinationPortRange": { "max": 22, "min": 22 } } }]';
    v_Egress_rules := '[';
    v_sl_count := 0;
    v_number := 0;
    for x in c_oracle_cidr(v_region_identifier, p_reservation_id) loop
        v_number := v_number + 1;
        v_Egress_rules := v_Egress_rules || JSON_OBJECT ('destination'      value x.cidr,
                                                    'destinationType'  value 'CIDR_BLOCK',
                                                    'isStateless'      value 'false',
                                                    'protocol'         value case x.protocol when 'TCP' then '6' else '17' end,
                                                    'description'      value x.remark ) || ',';
        -- send an SL in order to ensure that we don't run out of clob space
        if length(v_Egress_rules) > 30000 or v_number >= 198 then 
            v_sl_count := v_sl_count + 1;
            if substr(v_Egress_rules, length(v_Egress_rules)) = ',' then
                v_Egress_rules := substr(v_Egress_rules, 1, length(v_Egress_rules)-1);
            end if;
            v_Egress_rules := v_Egress_rules ||']';
 
            v_body := json_object ('displayName' VALUE 'SL ' || v_sl_count ,
                            'egressSecurityRules'  VALUE '@1',
                            'ingressSecurityRules' value '@2',
                            'compartmentId' value v_compartment_ocid,
                            'vcnId' value v_vcn_ocid);
 
            v_body := replace(v_body,'"@1"',v_Egress_rules);
            v_body := replace(v_body,'"@2"',v_ingress_rules);
 
            ll_pkg_log.log(40,'Misc. egress rules: ' || v_body);
                                                                    
            v_cidr_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                        p_type       => 'POST',
                                        p_host       => v_host,
                                        p_method     => '/20160918/securityLists',
                                        p_body       => v_body);
 
            ll_pkg_log.log(40,'Misc. egress API result: ' || v_cidr_clob);
            -- reset egress rules and the counter
            v_Egress_rules := '[';
            v_number := 0;
        end if;
    end loop;
 
    if length(v_Egress_rules) > 2 then
        v_sl_count := v_sl_count + 1;
        if substr(v_Egress_rules, length(v_Egress_rules)) = ',' then
        v_Egress_rules := substr(v_Egress_rules, 1, length(v_Egress_rules)-1);
        end if;
        
        v_Egress_rules := v_Egress_rules ||']';
 
        v_body := json_object ('displayName' VALUE 'SL ' || v_sl_count ,
                                'egressSecurityRules'  VALUE '@1',
                                'ingressSecurityRules' value '@2',
                                'compartmentId' value v_compartment_ocid,
                                'vcnId' value v_vcn_ocid);
 
        v_body := replace(v_body,'"@1"',v_Egress_rules);
        v_body := replace(v_body,'"@2"',v_ingress_rules);
 
        ll_pkg_log.log(40,'Misc. egress rules: ' || v_body);
 
        v_cidr_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                    p_type       => 'POST',
                                    p_host       => v_host,
                                    p_method     => '/20160918/securityLists',
                                    p_body       => v_body);
 
        ll_pkg_log.log(40,'Misc. egress API result: ' || v_cidr_clob);
    end if;
 
    -- assign newly created SLs to the subnet 
    assign_sls_to_subnet (p_reservation_id => p_reservation_id,
                            p_res_step_id => p_res_step_id, 
                            p_compartment_ocid => v_compartment_ocid, 
                            p_vcn_ocid => v_vcn_ocid);
    
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
      p_result := '';
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;

