  procedure route (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_object_ocid       varchar2(200);
    v_object_name       varchar2(200);
    v_internetgw_id     varchar2(200);
    
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_compartment_ocid  varchar2(200);
    v_body              clob;
    v_clob              clob;
  begin
    ll_pkg_log.log(20,'Initial call');
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_object_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                      p_res_step_id    => p_res_step_id,
                                                      p_json_name      => 'name');
    v_object_ocid := ll_pkg_reservation.flow_step_result (p_reservation_id  => p_reservation_id,
                                                          p_param_type      => 'ociVcn',
                                                          p_result_type     => 'ociVcnRoute');
    v_internetgw_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                           p_param_type     => 'ociVcnIGW' ); 
    v_method := '/20160918/routeTables/'||v_object_ocid;
    v_body := json_object ('displayName'    VALUE v_object_name,
                           'routeRules'     VALUE json_array( json_object('cidrBlock'  VALUE '0.0.0.0/0',
                                                                           'networkEntityId' VALUE v_InternetGW_id)));
                                                              
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'PUT',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    p_ocid        := v_object_ocid;
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    else
      p_status := 'Y';
      p_result := v_clob;
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
procedure priv_route (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_vcn_ocid       varchar2(200);
    v_object_name       varchar2(200);
    v_servicegw_id     varchar2(200);
    v_natgw_id          varchar(200);
    v_compartment_ocid  varchar2(200);
    v_host              varchar2(4000);      
    v_method            varchar2(2000);
    v_body              clob;
    v_clob              clob;
    v_attach_clob       clob;
    v_region_key        varchar2(10);
    v_priv_subnet_ocid  varchar2(200);
  begin
    ll_pkg_log.log(20,'Initial call');
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_object_name := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,
                                                      p_res_step_id    => p_res_step_id,
                                                      p_json_name      => 'name');
    v_vcn_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                      p_param_type     => 'ociVcn');
    v_priv_subnet_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                      p_param_type     => 'ociVcnSubPriv');
    v_servicegw_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                           p_param_type     => 'ociVcnServiceGateway' ); 
    v_natgw_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                           p_param_type     => 'ociVcnNatGW' ); 
    v_method := '/20160918/routeTables/';
    v_region_key := lower(ll_pkg_admin.region_key(p_region_id =>
                                                    ll_pkg_reservation.region_id (p_reservation_id => p_reservation_id)));
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
    v_body := json_object ('vcnId'          VALUE v_vcn_ocid,
                           'displayName'    VALUE v_object_name,
                           'compartmentId'  VALUE v_compartment_ocid,
                           'routeRules'     VALUE json_array( json_object('destination'      VALUE 'all-' || v_region_key || '-services-in-oracle-services-network',
                                                                          'destinationType'  VALUE 'SERVICE_CIDR_BLOCK',
                                                                          'networkEntityId' VALUE v_servicegw_id),
                                                               json_object('cidrBlock'  VALUE '0.0.0.0/0',
                                                                           'networkEntityId' VALUE v_natgw_id)));
                                                              
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'POST',
                                   p_host       => v_host,
                                   p_method     => v_method,
                                   p_body       => v_body);
    p_ocid        := json_value(v_clob,'$.id');
    v_method := '/20160918/subnets/';
    v_body := json_object ('routeTableId' VALUE p_ocid);
    v_attach_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_type       => 'PUT',
                                   p_host       => v_host,
                                   p_method     => v_method || v_priv_subnet_ocid,
                                   p_body       => v_body);
    
    if p_ocid is null then
      p_status := 'N';
      p_result := v_clob;
    elsif json_value(v_attach_clob, '$.routeTableId') <> p_ocid then
      p_status := 'N';
      p_result := v_attach_clob;
    else
      p_status := 'Y';
      p_result := v_clob;
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;
--  
--   #######  ##     ##  #######  ########    ###    
--  ##     ## ##     ## ##     ##    ##      ## ##   
--  ##     ## ##     ## ##     ##    ##     ##   ##  
--  ##     ## ##     ## ##     ##    ##    ##     ## 
--  ##  ## ## ##     ## ##     ##    ##    ######### 
--  ##    ##  ##     ## ##     ##    ##    ##     ## 
--   ##### ##  #######   #######     ##    ##     ## 
--
  procedure quota (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
--    cursor c_res_req is select llrr.id, llrr.tenancy_id, llrr.region_id, llrr.resource_id, llr.quota_family, llr.quota_name, llrr.environments 
--                        from ll_res_reservation_vw LLRR, 
--                             ll_resources          LLR
--                        where llrr.resource_id = llr.id
--                        and llrr.id=p_reservation_id;
      cursor c_res_req is select llres.id, llres.tenancy_id, llres.region_id, llwrr.resource_id, llr.quota_family, llr.quota_name, llwrr.environments
                          from ll_reservations llres, ll_resources llr, ll_ws_resources_required_vw llwrr
                          where llres.workshop_id = llwrr.workshop_id
                          and llr.id = llwrr.resource_id
                          and llres.id = p_reservation_id;                   
	
    cursor c_group_resource (p_res_group_id number, p_tenancy_id number, p_region_id number) is
                        select llr.id, llr.quota_family, llr.quota_name
                        from ll_res_available_vw  LLRA, 
                             ll_resources         LLR
                        where llra.resource_id = llr.id
                        and llra.tenancy_id = p_tenancy_id
                        and llra.region_id = p_region_id
                        and llr.quota_name is not null
                        and llr.quota_family is not null
                        order by num_available desc;
                        
    cursor c_zero is select distinct quota_family
                     from ll_resources
                     where quota_family is not null
                     and quota_family not in ('vcn','compute');
    v_region            varchar2(7000);
    v_host              varchar2(7000);
    v_name              varchar2(7000);
    v_compartment_ocid  varchar2(7000);
    v_statements        clob;
    v_body               clob;
    v_clob               clob;
    v_resource_id        number;
    v_quota_family       varchar2(7000);
    v_quota_name         varchar2(7000);
    v_method             varchar2(7000);
    v_region_identifier  varchar2(7000);
   									
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'limits', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                                               
    v_name := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                              p_res_step_id   => p_res_step_id, 
                                              p_json_name     => 'name'); 
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
                                                                                                                    
    v_method := '/20181025/quotas'; 
    for x in c_zero loop
      if v_statements is not null then
        v_statements := v_statements || ',';
      end if;
      if x.quota_family is not null then
        v_statements := v_statements || '"zero '||x.quota_family||' quotas in compartment id '||v_compartment_ocid||'"'||chr(10);
      end if;
    end loop;
    for x in c_res_req loop
	    v_quota_family := x.quota_family;
	    v_quota_name   := x.quota_name;
      
      if v_quota_family is not null and v_quota_name is not null then
        if v_statements is not null then
          v_statements := v_statements || ',';
        end if;
        v_region_identifier := ll_pkg_admin.region_identifier(x.region_id);   

        if (v_quota_family = 'ai-generative' and (v_quota_name = 'max-on-demand-chat-request-per-minute-count' or v_quota_name = 'max-on-demand-embed-request-per-minute-count')) then
            v_statements := v_statements || '"set '||v_quota_family||' quota '||v_quota_name||' to '||x.environments||' in compartment id '||v_compartment_ocid||' where request.region = '||genai_endpoint_region(v_region_identifier, p_reservation_id, p_res_step_id)||'"'||chr(10);
        else                                                     
            v_statements := v_statements || '"set '||v_quota_family||' quota '||v_quota_name||' to '||x.environments||' in compartment id '||v_compartment_ocid||' where request.region = '||v_region_identifier||'"'||chr(10);
        end if;
      end if;
      
    end loop;
    
    v_statements := '[' || v_statements || ']';
    
    v_body := json_object ('compartmentId'     value ll_pkg_admin.tenancy_ocid(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id) ),
                           'description'       value 'Quota for Livelabs reservation '||p_reservation_id,
                           'name'              value v_name,
                           'statements'        value '{statements}');
                           
    v_body := replace(v_body,'"{statements}"', v_statements);                           
    
    if v_compartment_ocid like 'ocid%compartment%' then
        v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                        p_type         => 'POST', 
                                        p_host         => v_host, 
                                        p_method       => v_method, 
                                        p_body         => v_body); 
        if v_clob is json then
          p_ocid := json_value(v_clob, '$.id' );
          ll_pkg_log.log(40,'OCID is '||p_ocid);
        else
          ll_pkg_log.log(40,'No OCID found in result');
        end if;
    
        if p_ocid is null then
          p_status := 'N';
          p_result := v_clob;
        else
          p_status := 'Y';
        end if;
    else
        p_status := 'Y';
    end if;
    
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
  end;

    function genai_endpoint_region(p_region varchar2, p_res_id number, p_res_step_id number) return varchar2 is
        v_return   VARCHAR2(200);
        v_plsql    VARCHAR2(1000);
        v_result   VARCHAR2(1000); 
        v_status   varchar2(100);
    BEGIN
        -- select value into v_plsql from ll_system_parameters where name = 'GENAI_ENDPOINT_REGION';

        -- EXECUTE IMMEDIATE v_plsql
        --     USING IN p_region, OUT v_return;

        -- return v_return;

        v_return := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_res_id, 
                                                       p_param_type     => 'ociGenAI' );
                                                       

        if v_return like 'Error%' then
            return 'us-chicago-1';
        else 
            return v_return;
        end if;
    END;


    -- Assuming it's a Gen AI workshop if the workshop has the manage Gen AI policy
    function is_genai_workshop(p_res_id number) return varchar2 is
        v_count number;
    begin
        select count(*) into v_count from ll_workshop_policies p 
        join ll_reservations r on r.workshop_id = p.workshop_id
        where r.id = p_res_id and policy_id = 137;

        if (v_count > 0) then
            return 'Y';
        else 
            return 'N';
        end if;

    end; 
--
--  #### ##    ##  ######  ########    ###    ##    ##  ######  ######## 
--   ##  ###   ## ##    ##    ##      ## ##   ###   ## ##    ## ##       
--   ##  ####  ## ##          ##     ##   ##  ####  ## ##       ##       
--   ##  ## ## ##  ######     ##    ##     ## ## ## ## ##       ######   
--   ##  ##  ####       ##    ##    ######### ##  #### ##       ##       
--   ##  ##   ### ##    ##    ##    ##     ## ##   ### ##    ## ##       
--  #### ##    ##  ######     ##    ##     ## ##    ##  ######  ########
--
   procedure instance (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    cursor c_image (p_image_id number, p_tenancy_id number, p_region_id number) is 
                     select image.resource_id, image.image_ocid, image.version, image.instance_prefix, image.ocpu_required, image.seclist_req, listing.app_catalog_ocid, llr.quota_name
                      from ll_images image left join ll_resources llr 
                      on image.resource_id = llr.id 
                      left join omp_listings listing on image.listing_id = listing.id
                      where (image.region_id = p_region_id or image.region_id is null)
                      and (image.tenancy_id = p_tenancy_id or image.tenancy_id is null)
                      and image.active_flg != 'N'
                      and image.id = p_image_id;
    cursor c_ad (p_tenancy_id number, p_region_id number, p_resource_name varchar2) is 
                   select ll_pkg_admin.ad_name( p_tenancy_id => lltp.tenancy_id,
                                                p_region_id  => lltp.region_id,
                                                p_ad         => lltp.ad) as ad_name, 
                                                JSON_VALUE(ll_pkg_exec.get(p_tenancy_id => p_tenancy_id, 
                                                                           p_host => ll_pkg_admin.oci_endpoint( p_type => 'limits', p_region_key => ll_pkg_reservation.region_key(p_reservation_id)), 
                                                                           p_method => '/20190729/services/'||replace(llr.quota_family, 'compute-core', 'compute')||'/limits/'||llr.quota_name||'/resourceAvailability', 
                                                                           p_query_string => 'availabilityDomain='||ll_pkg_admin.ad_name( p_tenancy_id => lltp.tenancy_id, p_region_id  => lltp.region_id, p_ad => lltp.ad)), '$.available') as available
                   from ll_resources llr, ll_tenancy_provides lltp
                   where llr.id = lltp.resource_id                       
                   and llr.quota_name = p_resource_name
                   and lltp.tenancy_id = p_tenancy_id
                   and lltp.region_id= p_region_id
                   order by available desc;
                   
    cursor c_public_key is select public_key
                           from ll_reservations
                           where id = p_reservation_id;
                      
    -- Get Lab and Apps URL's for injection into instance metadata. 
    cursor c_lab_url is 
        SELECT JSON_VALUE(lab_url, '$.DESKTOP_GUIDE_URL'),
               JSON_VALUE(lab_url, '$.DESKTOP_APP1_URL'),
               JSON_VALUE(lab_url, '$.DESKTOP_APP2_URL') 
           from ll_workshops llw
	        where llw.id =(select llr.workshop_id 
                         from ll_reservations llr
                        where llr.id = p_reservation_id);
    
						   
    v_image_ocid           varchar2(100);
    v_image_id             varchar2(100);
    v_resourceversion      varchar2(100);
    v_region_id            number;
    v_tenancy_id           number;
    v_host                 varchar2(200);
    v_name                 varchar2(100);
    v_compartment_ocid     varchar2(200);
    v_availability_domain  varchar2(200);
    v_subnet_id            varchar2(200);
    v_shape                varchar2(200);
    v_method               varchar2(1000);
    v_payload              clob;
    v_clob                 clob;
    v_instance_name        varchar2(100);
    v_available            varchar2(200);
    v_public_key           varchar2(4000);
    v_sqlerrm              varchar2(4000);
    v_netsecgrp_id         varchar2(200);
    v_private_ip           varchar2(200);
    v_inst_auth_grp        varchar2(100);
    v_definedTags          varchar2(200);
    v_param1               varchar2(2000);
    v_resource_name        varchar2(400);
    
    v_continue             varchar2(1) := 'Y';
    v_description          varchar2(500);
    v_direction            varchar2(10);
    v_protocol             varchar2(10);
    v_port                 varchar2(50);
    v_min_port             varchar2(50);
    v_max_port             varchar2(50);
    v_cidr                 varchar2(100);
    v_number               number;
    v_novnc_password       varchar2(10);
    v_desktop_guide_url    varchar2(300);
    v_desktop_app1_url     varchar2(300);
    v_desktop_app2_url     varchar2(300);
  begin
  
    ll_pkg_log.log(10,'Initial call');
  
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id);
                                                                  
    v_name := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                              p_res_step_id   => p_res_step_id, 
                                              p_json_name     => 'name'); 
                                              
    v_param1 := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                                  p_res_step_id   => p_res_step_id, 
                                                  p_json_name     => 'param1'); 
                                               
    v_subnet_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociVcnSubPub'); 
    v_netsecgrp_id := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                       p_param_type     => 'ociNetSecGrp'); 
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
    v_novnc_password :=  ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'NoVncPassword'); 
                                                             
                                                              
    v_image_id   := json_value( v_param1, '$.imageId');
    v_private_ip := json_value ( v_param1, '$.privateIp');
    v_inst_auth_grp := json_value(v_param1, '$.instAuthGrp');
    
    ll_pkg_log.log(40, 'Param1 is: '||v_param1);
    ll_pkg_log.log(40, 'ImageId from res_steps: '|| v_image_id);
    ll_pkg_log.log(40, 'PrivateIP from res_steps: '|| v_private_ip);
    ll_pkg_log.log(40, 'instAuthGrp from res_steps: '|| v_inst_auth_grp);
    
                                                              
    open c_public_key;
    fetch c_public_key into v_public_key;
    close c_public_key;
 -- Lab and App URL's
    open c_lab_url;
    fetch c_lab_url into v_desktop_guide_url,v_desktop_app1_url,v_desktop_app2_url;
    close c_lab_url;
--
    v_method := '/20160918/instances/'; 
    ll_pkg_log.log(30,'Image ID: '||v_image_id);
    if v_image_id is null then
      p_status := 'N';
      p_result := 'ImageID is empty';
      ll_pkg_log.log(1,'ImageID is empty for reservation '||p_reservation_id||', step ID: '||p_res_step_id);
    else
      for x in c_image (v_image_id, v_tenancy_id, v_region_id) loop
        v_instance_name := replace(v_name||'-'||x.instance_prefix,'--','-');
        v_resource_name := x.quota_name;
        if x.version is not null then
          ll_pkg_log.log(30,'Detected Marketplace image');
          v_image_ocid := ll_pkg_admin.get_marketplace_ocid (p_tenancy_id      => v_tenancy_id,
                                                             p_region_id       => v_region_id,
                                                             p_listingid       => x.app_catalog_ocid,
                                                             p_resourceversion => x.version,
                                                             p_compartment_id  => v_compartment_ocid);
          ll_pkg_log.log(40,'Marketplace OCID found: '||v_image_ocid);                                                           
        else
          v_image_ocid := x.image_ocid;
          ll_pkg_log.log(40,'Regular image ID: '||v_image_ocid);                                                           
        end if;
                                                            
        open c_ad (v_tenancy_id, v_region_id, v_resource_name);
        fetch c_ad into v_availability_domain, v_available;
        close c_ad;
        ll_pkg_log.log(40,'Availability domain is: '||v_availability_domain||', '||v_available||' CPUs available here'); 
        if v_resource_name like '%standard-e4-core-count%' then
            v_shape := 'VM.Standard.E4.Flex';
        elsif v_resource_name like '%standard-e5-core-count%' then
            v_shape := 'VM.Standard.E5.Flex';
        -- elsif v_resource_name like '%standard-e6-core-count%' then
        --     v_shape := 'VM.Standard.E6.Flex';
        else
            v_shape := replace('VM.Standard2.'||x.ocpu_required,' ','');
        end if;
        ll_pkg_log.log(40,'Shape determined as: '||v_shape);    
                                                                                                 
       
       -- Generate the payload for the creation
        v_payload := JSON_OBJECT ( 'availabilityDomain'   value v_availability_domain,
                                   'compartmentId'        value v_compartment_ocid,
                                   'displayName'          value v_instance_name,
                                   'shape'                value v_shape,
                                   'shapeConfig'          value JSON_OBJECT ( 'ocpus'                value x.ocpu_required),
                                   'createVnicDetails'    value JSON_OBJECT ( 'nsgIds'               value JSON_ARRAY(v_netsecgrp_id),
                                                                              'privateIp'            VALUE v_private_ip,
                                                                              'skipSourceDestCheck'  VALUE case when v_private_ip is not null then 'true' end,
                                                                              'subnetId'             value v_subnet_id,
                                                                              'hostnameLabel'        value null
                                                                              ABSENT ON NULL),
                                   'metadata'             value JSON_OBJECT ( 'ssh_authorized_keys'  value v_public_key,
                                                                              'vncpwd'               value v_novnc_password,
                                                                              'desktop_guide_url'    value v_desktop_guide_url,
                                                                              'desktop_app1_url'     value v_desktop_app1_url,
                                                                              'desktop_app2_url'     value v_desktop_app2_url ),
                                   'sourceDetails'        value JSON_OBJECT ( 'sourceType'           value 'image',
                                                                              'imageId'              value v_image_ocid),
                                   'definedTags'  value json_object( 'Livelabs'     value JSON_OBJECT( 'Permissions'  value nvl(v_inst_auth_grp,'None'))));
 
        ll_pkg_log.log(40,'Payload for instance creation is '||v_payload);
 
        v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                        p_type         => 'POST', 
                                        p_host         => v_host, 
                                        p_method       => v_method, 
                                        p_body         => v_payload); 
        if v_clob like '%Invalid format for ssh public key%' then
          ll_pkg_reservation.bad_ssh_during_setup (p_reservation_id => p_reservation_id);
        end if;
        p_ocid := ll_pkg_admin.get_id(v_clob);
        if p_ocid is not null then
          p_status := 'Y';
          p_result := v_image_ocid;
          ll_pkg_log.log(40,'Instance has been created; id='||p_ocid);
        else
          p_status:='N';
          p_result := v_clob;
        end if;
      
      -- This is probably only going work work in STAGE but not in MIG or PROD. But I need to test it first..
      ll_pkg_log.log(30,'Stepping into the Network Security Group section');
      v_payload := '';
    
      ll_pkg_log.log(40,'SeclistReq value: '||x.seclist_req);
      if x.seclist_req is not null and p_status='Y' then
    
        ll_pkg_log.log(30,'Adding Network Security List values');
        v_continue := 'Y';
        v_number := 0;
        while v_continue = 'Y' and v_number < 100 loop
          v_description := JSON_VALUE (x.seclist_req, '$['||v_number||'].description');
          v_direction   := JSON_VALUE (x.seclist_req, '$['||v_number||'].direction');
          v_protocol    := JSON_VALUE (x.seclist_req, '$['||v_number||'].protocol');
          v_port        := JSON_VALUE (x.seclist_req, '$['||v_number||'].port');
          v_cidr        := JSON_VALUE (x.seclist_req, '$['||v_number||'].cidr');
          if v_direction='I' and v_cidr is null then
            v_cidr := '0.0.0.0/0';
          end if;
          if upper(v_port) = 'ALL' and v_cidr <> '0.0.0.0/0' then
            v_min_port := '0';
            v_max_port := '65536';
          else
            v_min_port := v_port;
            v_max_port := v_port;
          end if;
        
          if v_direction is null then 
            v_continue := 'N';
          else
            v_payload := JSON_OBJECT( 'securityRules' value JSON_ARRAY ( JSON_OBJECT ( 'description'   value  v_description,
                                                                                       'direction'     value case v_direction when 'I' then 'INGRESS' else 'EGRESS' end,
                                                                                       'protocol'      value case upper(v_protocol) when 'UDP' then '17' when 'ALL' then 'all' else '6' end,
                                                                                       case v_direction when 'I' then 'sourceType' else 'destinationType' end value 'CIDR_BLOCK',
                                                                                       case v_direction when 'I' then 'source' else 'destination' end value v_cidr,
                                                                                       case v_protocol when 'UDP' then 'udpOptions' else 'tcpOptions' end value JSON_OBJECT ( 'destinationPortRange' value JSON_OBJECT ( 'min' value v_min_port, 'max' value v_max_port ) )
                                                                                      ) ) );
                                                                                  
            v_method := '/20160918/networkSecurityGroups/'||v_netsecgrp_id||'/actions/addSecurityRules';                                                                                 
    
            v_clob := ll_pkg_exec.put_post( p_tenancy_id   => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                            p_type         => 'POST', 
                                            p_host         => v_host, 
                                            p_method       => v_method, 
                                            p_body         => v_payload); 
          end if;
    
          v_number := v_number + 1;
        end loop;
      end if;
      end loop;
    end if;
    
    exception
    
      when others then 
        begin
          v_sqlerrm := SQLERRM;
          p_status :='N';
          p_result := v_sqlerrm || ' - ' ||v_clob;
          ll_pkg_log.log(1,sqlerrm || ' - ' || v_clob);
        end;
  
  end;
