  function get_instance_ip (p_reservation_id number, p_res_step_id number) return varchar2 is
                        
    cursor c_reservation is select object_ocid
                            from ll_reservation_steps
                            where reservation_id = p_reservation_id
                            and id = p_res_step_id;
                        
      v_tenancy_id        number;
      v_instance_ocid     varchar2(200);
      v_host              varchar2(200);
      v_compartment_ocid  varchar2(200);
      v_vnicid            varchar2(200);
      v_result            varchar2(2000);
      v_instances         varchar2(2000);
      v_ips               varchar2(2000);
      
      v_instances_clob    clob;
      v_vnics_clob        clob;
      v_vnic_attach_clob  clob;
                       
  begin
  
    ll_pkg_log.log(20,'Initial call');
    
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);
                                                                                                            
    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                              p_param_type     => 'ociCompartment'); 
                                                              
    open c_reservation;
    fetch c_reservation into v_instance_ocid;
    close c_reservation;
    
    ll_pkg_log.log(40,'Checking instance ID '||v_instance_ocid);
    v_vnic_attach_clob := ll_pkg_exec.get (p_tenancy_id     => v_tenancy_id,
                                           p_host           => v_host,
                                           p_method         => '/20160918/vnicAttachments/',
                                           p_compartment_id => v_compartment_ocid,
                                           p_query_string   => 'instanceId='||v_instance_ocid );
    v_vnicid := JSON_VALUE (v_vnic_attach_clob, '$.vnicId');
    
    ll_pkg_log.log(40,'Found vnicAttachment: '||v_vnicid||', clob: '||v_vnic_attach_clob);
    v_vnics_clob :=  ll_pkg_exec.get (p_tenancy_id     => v_tenancy_id,
                                      p_host           => v_host,
                                      p_method         => '/20160918/vnics/'||v_vnicid,
                                      p_compartment_id => v_compartment_ocid);
                                      
    v_ips := JSON_OBJECT ('publicIp'  value JSON_VALUE (v_vnics_clob, '$.publicIp'),
                          'privateIp' value JSON_VALUE (v_vnics_clob, '$.privateIp') );
    ll_pkg_log.log(40,'Found ips: '||v_ips||', clob: '||v_vnics_clob);
    v_instances_clob := ll_pkg_exec.get (p_tenancy_id     => v_tenancy_id,
                                         p_host           => v_host,
                                         p_method         => '/20160918/instances/'||v_instance_ocid,
                                         p_compartment_id => v_compartment_ocid);
    v_instances :=  JSON_OBJECT( 'displayname'     value JSON_VALUE (v_instances_clob, '$.displayName'),
                                 'shape'           value JSON_VALUE (v_instances_clob, '$.shape'), 
                                 'lifecyclestate'  value JSON_VALUE (v_instances_clob, '$.lifecycleState') );
                                 
    ll_pkg_log.log(40,'Found instances: '||v_instances||', clob: '||v_instances_clob);
    
    select json_mergepatch( v_ips, v_instances)
    into v_result
    from dual;
    
    ll_pkg_log.log(20,'End of call');
    
    
    return(v_result);
  end;
