  procedure instance_ips (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    cursor c_instances is select id, flow_step_result
                          from ll_reservation_steps
                          where reservation_id = p_reservation_id
                          and JSON_VALUE ( flow_step_param, '$.type') = 'ociInstance'
                          and object_ocid is not null;
    v_result    varchar2(2000);
    v_sqlerrm   varchar2(2000);
    
  begin
  
    ll_pkg_log.log(20,'Initial call', p_reservation_id);
    
    ll_pkg_log.log(30,'Pausing 15 seconds to wait for instance information');
    apex_util.pause(15);
    ll_pkg_log.log(30,'End of 15 second pause, continuing');
  
    for x in c_instances loop
      v_result := '';
      v_result := get_instance_ip (p_reservation_id => p_reservation_id, 
                                   p_res_step_id    => x.id);
                                   
      if instr(v_result,'null') = 0 then
        update ll_reservation_steps set flow_step_result = v_result where id = x.id;
        commit;
        if nvl(p_status,'X') <> 'N' then
          p_status := 'Y';
        end if;
      else
        p_status := 'N';
        p_result := p_result || 'id '||x.id||' has no IP found - '||chr(10);
      end if;
      
    end loop;
    
    commit;
    ll_pkg_log.log(20,'End of call');
    exception
      when others then begin
                         v_sqlerrm := SQLERRM;
                         p_status := 'N';
                         p_result := v_sqlerrm;
                       end;
  end;
