--
procedure custom_wait (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
   
    v_type              varchar2(100); 
    v_duration          number;
    v_step_date         date;
    v_step_status       varchar2(1);
    v_one_second        number := 1/24/60/60;
  begin 
 
    ll_pkg_log.log(20,'Initial call'); 
    
    v_duration := to_number(ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                                            p_res_step_id   => p_res_step_id, 
                                                            p_json_name     => 'param1')); 
    ll_pkg_reservation.step_status (p_reservation_id   => p_reservation_id,
                                    p_res_step_id      => p_res_step_id,
                                    p_step_date        => v_step_date,
                                    p_step_status      => v_step_status );
                                                 
    if nvl(v_step_date,sysdate) < sysdate and v_step_status = 'W' then
      ll_pkg_log.log(30,'Returning to this function after we have started a new job because we needed to wait (status=W)');
      p_ocid := '';
      p_status := 'Y';
    else
      -- This is a new line, we have not waited before                                                            
      if v_duration > 60 then
      -- If we need to wait longer than 1 minute, then we stop and start a new job
        ll_pkg_log.log(30,'Need to wait longer than 5 minures so stopping and start new job (status=W)');
        p_ocid := '';
        p_status := 'W';
        p_result := v_duration/60;
                         
      else
      -- Less than 1 minute, then simply use the apex_util.pause
        ll_pkg_log.log(30,'Need to wait less than a minute so using apex_util.pause (status=Y)');
        ll_pkg_admin.pause(v_duration);
        p_ocid := '';
        p_status := 'Y'; 
    
      end if;
    end if;
       
    ll_pkg_log.log(20,'End of call'); 
 
  END;
