procedure modifyQuota (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
 
v_user_ocid    varchar2(200);
    v_method       varchar2(2000);
    v_host         varchar2(500);
    v_param1     varchar2(4000);
    v_body         clob;
    v_clob         clob;
    v_param1_fix    varchar2(5000);
    v_compartment_ocid varchar2(500);
    v_quota_ocid varchar2(500);
begin
 
--<compartmentreplace>
v_param1 := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                                 p_res_step_id   => p_res_step_id, 
                                                 p_json_name     => 'param1'); 
 
v_host := ll_pkg_admin.oci_endpoint( p_type => 'limits', 
                                         p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
                                      
 
v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                        p_param_type     => 'ociCompartment');
                                                      
 ll_pkg_log.log(30,'param1_fix: '||v_param1);

-- string replace compartment ocid with compartment ocid 
v_param1_fix := replace(v_param1, '<compartmentReplace>' , v_compartment_ocid);
v_param1_fix := replace(v_param1_fix, '$' , '","');
v_param1_fix := '["' || v_param1_fix || '"]';
 
 
ll_pkg_log.log(30,'param1_fix: '||v_param1_fix);
 
v_quota_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                  p_param_type     => 'ociQuota' );  
 
-- ​PUT /20181025/quotas/{quotaId}
v_method := '/20181025/quotas/' || v_quota_ocid;
 
 
/*
 v_body := json_object ('compartmentId'     value ll_pkg_admin.tenancy_ocid(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id) ),
                           'description'       value 'Quota for Livelabs reservation '||p_reservation_id,
                           'name'              value v_name,
                           'statements'        value '{statements}');
                           
              
*/
v_body := json_object ('statements'      VALUE '{statements}');
 
v_body := replace(v_body,'"{statements}"', v_param1_fix);
 
 
v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                 p_type       => 'PUT',
                                 p_host       => v_host,
                                 p_method     => v_method,
                                 p_body       => v_body);
                      
p_ocid        := json_value(v_clob,'$.id');
 
if p_ocid is null then
  p_status := 'N';
  p_result := v_clob;
else
  p_status := 'Y';
end if;
 
EXCEPTION
WHEN others THEN
p_status := 'N';
p_result := SQLERRM;
ll_pkg_log.log(30,'Issue: '||p_result);
end;
 
 
