  procedure datasafe_alladmin_grant (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    type t_refcurtype IS REF CURSOR;
    cursor c_compartment (p_tenancy_id number) is 
                       select DEFAULT_COMPARTMENT_OCID
                       from ll_tenancies
                       where id = p_tenancy_id;
    c_cursor            t_refcurtype;
    v_cursor            varchar2(4000);
    v_tenancy_id        number;
    v_host              varchar2(4000);
    v_method            varchar2(4000);
    v_resourcegroup_id  number;
    v_privilege_id      number;
    v_clob              clob;
    v_body              clob;
    v_compartment_ocid  varchar2(400);
    v_group_ocid        varchar2(400);
    v_grant_id          varchar2(400);
    
  begin
    ll_pkg_log.log(20,'Initial call');
    -- Get details
    v_tenancy_id := ll_pkg_reservation.tenancy_id(p_reservation_id);
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'datasafe',
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id));
    ll_pkg_log.log(40,'v_host: '||v_host);                                         
    v_group_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id, 
                                                        p_param_type     => 'ociGroup'); 
    -- Get the default compartment OCID
    open c_compartment (v_tenancy_id);
    fetch c_compartment into v_compartment_ocid;
    close c_compartment;
    -- Get DS group ID for group name LiveLabs
    ll_pkg_log.log(30,'Retrieving existing Resource Groups');
    v_clob := ll_pkg_exec.get( p_tenancy_id => v_tenancy_id,
                               p_host       => v_host,
                               p_method     => '/dscs/v1/resourceGroups');
    v_cursor := 'select id '||
                'from JSON_TABLE( '||chr(39)||v_clob||chr(39)||','||q'@ '$[*]' COLUMNS (id, name) ) @'||
                'where name = '||chr(39)||v_compartment_ocid||chr(39); 
    open c_cursor for v_cursor;
    fetch c_cursor into v_resourcegroup_id;
    if c_cursor%found then
      ll_pkg_log.log(30,'Existing DS resource group found: '||v_resourcegroup_id);
    else
      ll_pkg_log.log(30,'No DS resource group found');
    end if;
    close c_cursor;
    -- If group ID not found, create a new one with this name based on Default Livelabs group
    if v_resourcegroup_id is null then
      ll_pkg_log.log(30,'Resourcegroup ID is null, creating new group');
      v_body := JSON_OBJECT ( 'name'           value v_compartment_ocid,
                              'description'    value 'Generic compartment for LiveLabs',
                              'compartmentId'  value v_compartment_ocid );
      v_method := '/dscs/v1/resourceGroups';    
      ll_pkg_log.log(40,'DS request body: '||v_body);
                              
      v_clob := ll_pkg_exec.put_post ( p_tenancy_id   => v_tenancy_id,
                                       p_type         => 'POST',
                                       p_host         => v_host,
                                       p_method       => v_method,
                                       p_body         => v_body );
      
      ll_pkg_log.log(40,'DS POST result: '||v_clob);
      v_resourcegroup_id := ll_pkg_admin.get_id(v_clob);
      ll_pkg_log.log(30,'Retrieved DS group id: '||v_resourcegroup_id);
    end if;
    -- Find privilegeID for the AdministerAll privilege
    v_cursor := q'@select pid
                   from JSON_TABLE( ll_pkg_exec.get( p_tenancy_id => :p_tenancy_id,
                                                     p_host       => :p_host,
                                                     p_method     => '/dscs/v1/privileges'),
                                                     '$[*]' COLUMNS (privilegeName, pid) )
                   where privilegeName = 'AdministerAll'@';
    open c_cursor for v_cursor using v_tenancy_id, v_host;
    fetch c_cursor into v_privilege_id;
    close c_cursor;
    ll_pkg_log.log(40, 'AdministerAll privilege ID: '||v_privilege_id);
    -- Grant AdministerAll privilege to ResourceGroupID and GroupID of the LL user
    -- First we wait 3 minutes to let the GROUP sync to this region, else the Console will fail
    ll_pkg_log.log(30,'Waiting 3 minutes for GROUP information sync with Data Safe');
    apex_util.pause(180);
    ll_pkg_log.log(30,'End of waiting for GROUP sync');
    v_method := '/dscs/v1/grants';
    -- Determine if grant has already been executed
    v_cursor := 'select grantID '||
                q'@from JSON_TABLE( ll_pkg_exec.get( p_tenancy_id => :v_tenancy_id, @'||
                q'@                                  p_host       => :v_host, @'||
                q'@                                  p_method     => '/dscs/v1/grants'), @'||
                q'@'$[*]' COLUMNS ( grantID, privilegeID, userGroupID, resourceGroupID, privilegeName, resourceGroupName)) @'||
                q'@where usergroupid = :v_group_ocid @';
    open c_cursor for v_cursor using v_tenancy_id, v_host, v_group_ocid;
    fetch c_cursor into v_grant_id;
    close c_cursor;
    if v_grant_id is null then
      ll_pkg_log.log(30,'Grant has not been executed; creating new grant');
      v_body := JSON_OBJECT ( 'resourceGroupID'    value v_resourcegroup_id,
                              'userGroupID'        value v_group_ocid,
                              'privilegeID'        value v_privilege_id);
      ll_pkg_log.log(40,'Body for granting DS privilege: '||v_body);                            
      v_clob := ll_pkg_exec.put_post ( p_tenancy_id   => v_tenancy_id,
                                       p_type         => 'POST',
                                       p_host         => v_host,
                                       p_method       => v_method,
                                       p_body         => v_body );                                
      ll_pkg_log.log(40,'Result new grant clob: '||v_clob);
      -- Find the ID of the grant so we can revoke it afterwards
      v_grant_id := JSON_VALUE(v_clob,'$.grantID');
    end if;
    ll_pkg_log.log(30,'Final value for GrantID: '||v_grant_id);       
  -- Checks to see if all went well
    if v_grant_id is not null then
      p_ocid := v_grant_id;
      p_status := 'Y';
    else
      p_ocid := '';
      p_status := 'N';
      p_result := v_clob;
    end if;
    ll_pkg_log.log(20,'End of call');
  -- End of procedure
    
  end;
