  procedure generate_novnc_password (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) is
    v_novnc_password  varchar2(10);
  begin
    v_novnc_password := DBMS_RANDOM.STRING( 'X', 10);
    p_status := 'Y';
    p_ocid := v_novnc_password;
    
  end;
 
 
  procedure assign_sls_to_subnet (p_reservation_id IN number, p_res_step_id IN number, p_compartment_ocid IN varchar2, p_vcn_ocid IN varchar2) is 
    v_subnet_ocid varchar2(4000);
    v_sl_ocids clob;
    v_response clob;
    v_host varchar2(4000);
    v_subnet_response clob;
    v_body clob;
    v_repeat number := 1;
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
 
    -- get list of SLs 
    while v_repeat <= 5 loop
        v_response := ll_pkg_exec.get(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_host       => v_host,
                                   p_method     => '/20160918/securityLists',
                                   p_compartment_id => p_compartment_ocid,
                                   p_query_string       => 'vcnId=' || p_vcn_ocid);
        if apex_web_service.g_status_code > 299  or instr(v_response, 'ocid1.securitylist') = 0 then 
            v_repeat := v_repeat + 1;
            ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', List Security Lists ERROR: ' || v_response);
            apex_util.pause(30*v_repeat);
        else
            exit;
        end if;
    end loop;
    if apex_web_service.g_status_code > 299  or instr(v_response, 'ocid1.securitylist') = 0 then 
        ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', FAILED to get SLs. Exiting...');
        return;
    end if;
    -- build into SL id list 
    v_sl_ocids := '[';
    for sl in (select ocid from json_table(v_response, '$[*]' columns (ocid varchar2 path '$.id'))) loop
        v_sl_ocids := v_sl_ocids || '"' || sl.ocid || '",';
    end loop;
    if substr(v_sl_ocids, length(v_sl_ocids)) = ',' then
        v_sl_ocids := substr(v_sl_ocids, 1, length(v_sl_ocids)-1);
    end if;
    v_sl_ocids := v_sl_ocids || ']';
 
    v_body := '{"securityListIds":' ||v_sl_ocids || '}';
    ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', Security List IDs: ' || v_body);
 
    -- get all subnets in VCN
    v_repeat := 1;
    while v_repeat <= 5 loop
        v_response := ll_pkg_exec.get(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                   p_host       => v_host,
                                   p_method     => '/20160918/subnets',
                                   p_compartment_id => p_compartment_ocid,
                                   p_query_string       => 'vcnId=' || p_vcn_ocid);
        if apex_web_service.g_status_code > 299  or instr(v_response, 'ocid1.subnet') = 0 then 
            v_repeat := v_repeat + 1;
            ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', List Subnets ERROR: ' || v_response);
            apex_util.pause(30*v_repeat);
        else
            exit;
        end if;
    end loop;
    ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', List Subnets response: ' || v_response);
    if apex_web_service.g_status_code > 299  or instr(v_response, 'ocid1.subnet') = 0 then 
        v_response := '[{"id":"' || ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id, p_param_type => 'ociVcnSubPub') || '"}]';
    end if;
    -- add all SLs to each subnet
    for subnet in (select ocid from json_table(v_response, '$[*]' columns (ocid varchar2 path '$.id'))) loop
        v_repeat := 1;
        while v_repeat <= 5 loop
            v_subnet_response := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                        p_type       => 'PUT',
                                        p_host       => v_host,
                                        p_method     => '/20160918/subnets/' || subnet.ocid,
                                        p_body       => v_body);
            if apex_web_service.g_status_code > 299  or instr(v_subnet_response, 'ocid1.subnet') = 0 then 
                v_repeat := v_repeat + 1;
                ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', Update Subnets ERROR: ' || v_subnet_response);
                apex_util.pause(30*v_repeat);
            else
                exit;
            end if;
        end loop;
        ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', Update Subnet response: ' || v_subnet_response);
        if apex_web_service.g_status_code > 299  or instr(v_subnet_response, 'ocid1.subnet') = 0 then 
            ll_pkg_log.log(40, 'Assign SLs to Subnet for Res ' || p_reservation_id || ', FAILED to update Subnet after 5 tries.');
        end if;
    end loop;
  end;
  procedure resetImage (p_reservation_id IN number) is
    v_clob clob;
    v_image_ocid varchar2(4000);
    v_host varchar2(4000);
  begin
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'iaas', 
                                         p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
    v_image_ocid := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,
                                                          p_param_type     => 'ociInstance');
    v_clob := ll_pkg_exec.put_post(p_tenancy_id => ll_pkg_reservation.tenancy_id(p_reservation_id),
                                        p_type       => 'POST',
                                        p_host       => v_host,
                                        p_method     => '/20160918/instances/' || v_image_ocid || '?action=RESET',
                                        p_body       => json_object('actionType' value 'reset'));
    ll_pkg_log.log(40, 'Reset Image response for Reservation '|| p_reservation_id || ': ' || v_clob);
  exception when others then 
    ll_pkg_log.log(40, 'Reset Image EXCEPTION for Reservation '|| p_reservation_id || ': ' || v_clob);
  end;


  function unique_cidr (p_reservation_id number, p_type varchar2 default '') return varchar2 as 
    v_cidr varchar2(100);
    v_hold number;
  begin
    v_cidr := mod(p_reservation_id, 100);
    v_hold := trunc(p_reservation_id/100, 0);
    v_cidr := mod(v_hold, 100) || '.' || v_cidr;
    v_hold := trunc(v_hold/100, 0);
    v_cidr := mod(v_hold, 100) || '.' || v_cidr;
    case  
        when p_type = 'VCN' then v_cidr := v_cidr || '.0/24';
        when p_type = 'PUBLIC' then v_cidr := v_cidr || '.0/25';
        when p_type = 'PRIVATE' then v_cidr := v_cidr || '.128/25';
        else v_cidr := v_cidr || '.0';
    end case;
    return v_cidr;
  end;
 

procedure genairegion (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS 
    v_compartment_ocid  varchar2(200);
    v_resource          varchar2(4000);
    v_tenancy           varchar2(4000);
    v_resource_id       number;
    v_distance          number;
    v_region_key        varchar2(100);
  begin
    ll_pkg_log.log(20,'Initial call');
     v_resource := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                                            p_res_step_id   => p_res_step_id, 
                                                            p_json_name     => 'param1');
    ll_pkg_log.log(40, v_resource);
     v_tenancy := ll_pkg_reservation.tenancy_id(p_reservation_id);
     ll_pkg_log.log(40, v_tenancy);
     v_region_key := ll_pkg_reservation.region_key(p_reservation_id);
     ll_pkg_log.log(40, v_region_key);
     select id into v_resource_id from ll_resources where upper(name) = upper(v_resource);
     ll_pkg_log.log(40, 'Resource ID ' || v_resource_id);
     
     select far_region.region_identifier,        
        sdo_geom.SDO_DISTANCE(
        SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(curr_region.longitude, curr_region.latitude, NULL), NULL, NULL),
        SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(far_region.longitude, far_region.latitude, NULL), NULL, NULL),0.01,
       'unit=KM')
       into p_ocid, v_distance
     from ll_res_available_vw res_av, ll_oci_regions curr_region, ll_oci_regions far_region
     where curr_region.region_key = v_region_key
     and res_av.region_id = far_region.id
     and res_av.tenancy_id = v_tenancy
    and res_av.resource_id = v_resource_id
    and res_av.num_provided > 0
    order by 2
    fetch first 1 row only;

    if p_ocid is null then
      p_status := 'N';
      p_result := 'No Model/Region Found';
    else
      p_status := 'Y';
      p_result := '';
    end if;
    ll_pkg_log.log(20,'End of call');
  EXCEPTION
    WHEN others THEN
      p_status := 'N';
      p_result := SQLERRM;
      ll_pkg_log.log(30,'Issue: '||p_result);
  end;



procedure secure_desktop_user (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) as

    cursor c_desktops (c_reservation_id number) is select sd.id, sd.tenancy_id, sd.region_key, sd.group_ocid
        from ll_secure_desktops sd, ll_oci_regions curr_region, ll_oci_regions far_region
        where curr_region.region_key = ll_pkg_reservation.region_key(c_reservation_id)
            and far_region.region_key = sd.region_key
        order by sdo_geom.SDO_DISTANCE(
            SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(curr_region.longitude, curr_region.latitude, NULL), NULL, NULL),
            SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(far_region.longitude, far_region.latitude, NULL), NULL, NULL),0.01,
            'unit=KM');
    
    v_tenancy_id number;
    v_region_key varchar2(100);
    v_group_ocid varchar2(4000);
    v_tenancy_ocid varchar2(4000);
    v_clob clob;
    v_clob_retry clob;
    v_name varchar2(1000);
    v_body clob;
    v_group_clob clob;
    v_group_body clob;
    v_group_result clob;
    v_password_result clob;
    v_secure_desktop_id number;
begin
    ll_pkg_log.log(20,'Initial call');  

    -- find tenancy/region for secure desktop 
    open c_desktops(p_reservation_id);
    fetch c_desktops into v_secure_desktop_id, v_tenancy_id, v_region_key, v_group_ocid;
    close c_desktops;

    -- -- create user called LLXXXX-SECUREDESKTOP-USER
    v_tenancy_ocid := ll_pkg_admin.tenancy_ocid (v_tenancy_id);                                         
    v_name             := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id, 
                                                            p_res_step_id   => p_res_step_id, 
                                                            p_json_name     => 'name');      
    v_body := JSON_OBJECT ( 'compartmentId'  value   v_tenancy_ocid,
                            'name'           value  v_name, 
                            'description'    value  'LiveLabs automation for reservation '||p_reservation_id); 
     
    v_clob := ll_pkg_exec.put_post(p_tenancy_id  => v_tenancy_id,  
                                   p_type        => 'POST',  
                                   p_host        => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)),  
                                   p_method      => '/20160918/users/',  
                                   p_body        => v_body ); 
    p_ocid := ll_pkg_admin.get_id(v_clob); 
       
    if substr(p_ocid,1,4)='ocid' then 
      p_status := 'Y'; 
    else 
      p_status := 'N'; 
      p_result := substr(v_clob,1,3500); 
      ll_pkg_log.log(40,'Issue with creating secure desktop user - '||v_clob); 
 
      -- check to see if there was a bad gateway error
      if nvl(json_value(v_clob, '$.code'), 'X') like 'InternalError' then
        -- see if there is a user with the right name
        apex_util.pause(5);
        v_clob_retry := ll_pkg_exec.get(p_tenancy_id  => v_tenancy_id,  
                                   p_host        => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)),  
                                   p_method      => '/20160918/users/',  
                                   p_compartment_id => v_tenancy_ocid,
                                   p_query_string        => 'name='||v_name ); 
        ll_pkg_log.log(40, 'InternalError. Checking to see if user was actually created: '|| v_clob_retry);
        for item in (select * from json_table(v_clob_retry, '$[*]' columns (name, id))) loop
            if item.name = v_name then
                p_ocid := item.id;
                p_status := 'Y';
                ll_pkg_log.log(40, 'InternalError. User does exist. Returning ocid: ' || p_ocid);
            end if;
        end loop;
      end if;
 
    end if; 

    if p_status <> 'Y' then
        p_result := 'Error creating user: ' || v_clob || '\n Second Error: ' || v_clob_retry;
        return;
    end if;

    -- assign new user to secure desktop group 
    v_group_body := json_object('groupId' value v_group_ocid,
                                    'userId' value p_ocid);
    v_group_clob := ll_pkg_exec.put_post(p_tenancy_id  => v_tenancy_id,  
                                   p_type        => 'POST',  
                                   p_host        => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)),  
                                   p_method      => '/20160918/userGroupMemberships/',  
                                   p_body        => v_group_body ); 
    v_group_result := ll_pkg_admin.get_id(v_group_clob); 
    if v_group_result like 'ocid%' then 
        p_status := 'Y'; 
    else 
        p_status := 'N'; 
        p_result := 'Error assigning user to group. User: ' || p_ocid || ' \n Group Error: ' || v_group_clob; 
    end if; 

    -- reset user password 
    v_password_result := ll_pkg_exec.put_post( p_tenancy_id   => v_tenancy_id,
                                    p_type         => 'POST', 
                                    p_host         => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)), 
                                    p_method       => '/20160918/users/' || p_ocid || '/uiPassword', 
                                    p_body         => '{}'); 
    if v_password_result like '%ocid%' then
        p_result := json_object('password' value json_value(v_password_result, '$.password' ),
                                'secureDesktopId' value v_secure_desktop_id,
                                'groupMembershipOcid' value v_group_result);
        p_status := 'Y'; 
    else 
        p_status := 'N'; 
        p_result := 'Error reseting user password. User: ' || p_ocid || ' \n Result: ' || v_password_result; 
    end if; 


    ll_pkg_log.log(20,'End of call');
exception
    when others then 
        p_status := 'N';
        p_result := SQLERRM;
        ll_pkg_log.log(30,'Issue: '||p_result);
end;

  
END LL_PKG_CREATE;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_DELETE" AS 
 
-- Generate banners with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE 
 
/* 
  LOG levels 
 
   1 = Serious errors 
  10 = Start and stop of high level packages 
  20 = Start and stop of subroutines 
  30 = Steps inside subroutines 
  40 = Details steps inside subroutes (contains values) 
  50 = Start and stop of REST statements to OCI (exec_get etc) 
  60 = Detailed steps of REST commands 
  70 = Sign steps for REST commands 
  80 = Sign details (contains values) 
*/ 
procedure clean_compartments_used is 
    v_comp_step_id number;
    v_used_comp_wait number;
    begin
        select id into v_comp_step_id from ll_flow_steps where upper(object_name) = 'COMPARTMENT';
        v_used_comp_wait := ll_pkg_admin.minutes_to_days(nvl(ll_pkg_admin.system_parameter('USED_COMPARTMENT_DELETE_WAIT_MINUTES'), 120));
        -- Delete any compartments that are reserved for reservations that have ended
        delete from ll_compartments_used z
          where z.compartment_ocid in (select a.compartment_ocid
          from ll_compartments_used a, ll_reservations_vw b
          where a.reservation_id = b.id
          and cast(stop_gmt + v_used_comp_wait as timestamp) < systimestamp);

        -- Delete any extra compartments reserved for a reservation
        delete from ll_compartments_used z
          where z.compartment_ocid in (  select u.compartment_ocid from ll_compartments_used u
          join ll_reservations_vw r on u.reservation_id = r.id
          join ll_reservation_steps s on s.RESERVATION_ID = r.id
          where s.flow_step_id = v_comp_step_id
          and (
            (s.create_success= 'Y' and s.object_ocid is not null and s.object_ocid <> u.compartment_ocid)
            or
            (s.create_success = 'N' and s.create_retry = 5 and cast(s.create_date + v_used_comp_wait as timestamp) < systimestamp)
          )   
          );
    commit; 
    end;
 
