--
  procedure get_delete_method ( p_type IN varchar2, p_endpoint_type OUT varchar2, p_delete_method OUT varchar2, p_home_region_req OUT varchar2 )is 
   
    cursor c_keys is select delete_method, endpoint_type, nvl(home_region_req,'N') as home_region_req 
                            from ll_delete_objects
                            where step_name=p_type; 
 
    v_method  varchar2(100); 
                             
  begin 
    open c_keys; 
    fetch c_keys into p_delete_method, p_endpoint_type, p_home_region_req; 
    if c_keys%NOTFOUND then 
      v_method := 'Error - Delete method not found'; 
    end if; 
    close c_keys; 
     
  end; 
-- 
--  ########  ######## ##       ######## ######## ########     #######  ########        ## ########  ######  ######## 
--  ##     ## ##       ##       ##          ##    ##          ##     ## ##     ##       ## ##       ##    ##    ##    
--  ##     ## ##       ##       ##          ##    ##          ##     ## ##     ##       ## ##       ##          ##    
--  ##     ## ######   ##       ######      ##    ######      ##     ## ########        ## ######   ##          ##    
--  ##     ## ##       ##       ##          ##    ##          ##     ## ##     ## ##    ## ##       ##          ##    
--  ##     ## ##       ##       ##          ##    ##          ##     ## ##     ## ##    ## ##       ##    ##    ##    
--  ########  ######## ######## ########    ##    ########     #######  ########   ######  ########  ######     ##    
-- 
  procedure delete_object (p_reservation_id IN number, p_res_step_id IN number, p_status OUT varchar2, p_result OUT varchar2) is 
 
    v_host              varchar2(200); 
    v_method            varchar2(200); 
    v_endpoint_type     varchar2(500);
    v_home_region_req   varchar2(10);
    v_clob              clob; 
    v_step_type         varchar2(100); 
    v_status            varchar2(4000);
    v_result            varchar2(4000);
 
  begin 
 
    ll_pkg_log.log(20,'Initial call', p_reservation_id); 
     
    v_step_type := ll_pkg_reservation.step_details( p_reservation_id => p_reservation_id, 
                                                    p_res_step_id    => p_res_step_id, 
                                                    p_json_name      => 'type' ); 
 
    ll_pkg_log.log(40,'Type is '||v_step_type); 
                                                  
    if v_step_type is not null then 
      get_delete_method ( p_type => v_step_type, p_endpoint_type => v_endpoint_type, p_delete_method => v_method, p_home_region_req => v_home_region_req);
    end if; 
     
    if v_method is not null then 
      if v_home_region_req = 'Y' then
        v_host := ll_pkg_admin.oci_endpoint( p_type => v_endpoint_type, 
                                             p_region_key => ll_pkg_reservation.home_region_key(p_reservation_id)); 
      else
        v_host := ll_pkg_admin.oci_endpoint( p_type => v_endpoint_type, 
                                             p_region_key => ll_pkg_reservation.region_key(p_reservation_id)); 
      end if;
    
      v_method := v_method || '/'|| ll_pkg_reservation.step_object_ocid(p_reservation_id => p_reservation_id, p_res_step_id => p_res_step_id); 
      v_method := replace(v_method,'//','/'); 
 
      ll_pkg_log.log(30,'Before delete request'); 
      ll_pkg_log.log(40,'Full delete method is: '||v_method); 
      if v_step_type='ociVcnRoute' then
        ll_pkg_log.log(30,'ociVcnRoute - Cleaning Routing Table'); 
        v_clob := ll_pkg_exec.put_post( p_tenancy_id  => ll_pkg_reservation.tenancy_id(p_reservation_id),  
                                        p_type        => 'PUT',
                                        p_host        => v_host,
                                        p_method      => v_method,
                                        p_body        => '{ "routeRules" : [ ] }');
      elsif v_step_type='ociTerraform' then
        ll_pkg_log.log(30,'Running Destroy job');
        ll_pkg_terraform.destroy_job (p_reservation_id => p_reservation_id,
                                      p_res_step_id    => p_res_step_id,
                                      p_status         => p_status,
                                      p_result         => v_clob);
        ll_pkg_log.log(30,'Destroy job finished, p_status='||p_status);
        if p_status = 'Y' then
          ll_pkg_log.log(30,'Initiating Stack delete');
          ll_pkg_terraform.delete_stack (p_reservation_id    => p_reservation_id,
                                         p_res_step_id       => p_res_step_id,
                                         p_status            => p_status,
                                         p_result            => v_clob);
          ll_pkg_log.log(30,'Stack delete initiated, p_status='||p_status);                                         
        end if;
        if p_status='Y' then
          v_clob := '';
        end if;
      else
        ll_pkg_log.log(30,'Deleting '||v_step_type||' using regular delete call'); 
        v_clob := ll_pkg_exec.delete (p_tenancy_id  => ll_pkg_reservation.tenancy_id(p_reservation_id),  
                                      p_host        => v_host,  
                                      p_method      => v_method); 
      end if;
 
      ll_pkg_log.log(40,'Result after Delete - p_status='||p_status||', v_clob='||v_clob); 
      
      if v_clob is null then
        ll_pkg_log.log(40,'v_clob is null and p_status is null, so all seems to be correct.');
        p_status := 'Y';
      elsif v_clob is not null and v_step_type = 'ociVcnRoute' and instr(v_clob,'compartmentId') > 0  then
        ll_pkg_log.log(40,'v_clob is not null and step_type=ociVcnRoute and we have a compartment.. So all seems to be correct.');
        p_status := 'Y';
      else
        ll_pkg_log.log(40,'In else section of if. Apparently something is wrong.');
        p_status := 'N';
        p_result := nvl(p_result,v_clob);
      end if;
    elsif v_step_type='ociSecureDesktopUser' then 
      ll_pkg_log.log(30,'Secure Desktop user delete started');
      ll_pkg_delete.secure_desktop_user (p_reservation_id    => p_reservation_id,
                                         p_res_step_id       => p_res_step_id,
                                         p_status            => p_status,
                                         p_result            => p_result);
    else
      p_status := 'N';
      p_result := 'Method not found';
    end if; 
       
    ll_pkg_log.log(20,'End of call'); 
 
  END delete_object; 
