  procedure del_fs_exports (p_tenancy_id number, p_region_key varchar2, p_comp_ocid varchar2, p_filesystem_id varchar2) is
                      
    v_clob     clob;
    v_method   varchar2(1000);
  begin
  
    v_method := '/20171215/exports/';
  
    for y in (select id, lifecyclestate
                        from json_table(ll_pkg_exec.get (p_tenancy_id    => p_tenancy_id,
                                                         p_host          => ll_pkg_admin.oci_endpoint (p_type => 'FILESTORAGE', p_region_key => p_region_key),
                                                         p_compartment_id => p_comp_ocid,
                                                         p_method => '/20171215/exports'), '$[*]' COLUMNS (id, lifecycleState )) 
                        where nvl(upper(lifecyclestate),'X') not in ('TERMINATED','DELETED')) loop
      v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                    p_host       => ll_pkg_admin.oci_endpoint (p_type => 'FILESTORAGE', p_region_key => p_region_key),
                                    p_method => v_method ||y.id );
                                    
      ll_pkg_log.log(40,'Filesystem Export delete: '||v_clob);
    end loop;
  end;
