  function artifact_exists (p_tenancy_id number, p_region_id number, p_containerimage_id varchar2 default null, p_containerrepo_id varchar2 default null) return varchar2 is
    v_clob    clob;
    v_method  varchar2(4000);
    v_host    varchar2(4000);
    v_exists  varchar2(1) := 'Y';
  begin
    if p_containerimage_id is not null then
      v_method := '/20160918/container/images/'||p_containerimage_id;
    elsif p_containerrepo_id is not null then
      v_method := '/20160918/container/repositories/'||p_containerrepo_id;
    end if;
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'artifacts',
                                         p_region_key => ll_pkg_admin.region_key (p_region_id) );
    v_clob := ll_pkg_exec.get(  p_tenancy_id   => p_tenancy_id,
                                p_host         => v_host,
                                p_method       => v_method );
    if JSON_VALUE(v_clob,'$.code') = 'REPO_ID_UNKNOWN' then
      v_exists := 'N';
    else
      v_exists := 'Y';
    end if;                                
    return(v_exists);
  end;
  
