--  ########   #######  ######## ##    ##    ########  ######## ######## ########    ##    ########
--
  function bulk_delete (p_tenancy_id number, p_comp_ocid varchar2 ) return number is
    cursor c_regions is select region_key 
                        from ll_oci_regions;
    cursor c_bulk_items (p_name in varchar2) is select name
                                                from ll_bulk_delete_items
                                                where name = p_name
                                                and nvl(global,'N') <> 'Y';
                        
    v_clob              clob;
    v_json_bulk         clob;
    v_json_next         varchar2(1);
    v_json_item         number;
    v_json_search_type  varchar2(500);
    v_json_search_ocid  varchar2(500);
    v_json_search_state varchar2(500);
    v_json_type         varchar2(500);
    v_json_ocid         varchar2(500);
    v_json_state        varchar2(500);
    v_dummy             varchar2(500);
    v_num_found         number                := 0;
    v_resources_again   varchar2(1);
    v_resources_retry   number;
  begin
    for x in c_regions loop
      -- Do multiple retries to get the resource list because I suspect we get an empty list once in a while resulting in resources still active
      v_resources_again := 'Y';
      v_resources_retry := 0;
      while v_resources_again = 'Y' and v_resources_retry <= 10 loop
        v_clob := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                       p_host       => ll_pkg_admin.oci_endpoint (p_type => 'query', p_region_key => x.region_key),
                                       p_type       => 'POST', 
                                       p_method     => '/20180409/resources',
                                       p_body       => '{ "type": "Structured", "query": "query all resources where compartmentId = '|| chr(39)||p_comp_ocid||chr(39)||'" }');
        if JSON_VALUE(v_clob, '$.items[0].resourceType') is not null then
          v_resources_again := 'N';
        else
          v_resources_retry := v_resources_retry + 1;
        end if;  
      end loop;                                     
      v_json_item := 0;
      v_json_next := 'Y';
      while v_json_next = 'Y' and v_json_item < 99 loop
        v_json_search_type   := '$.items['||v_json_item||'].resourceType';
        v_json_search_ocid   := '$.items['||v_json_item||'].identifier';
        v_json_search_state  := '$.items['||v_json_item||'].lifecycleState';
        v_json_type  := JSON_VALUE ( v_clob, v_json_search_type);
        v_json_ocid  := JSON_VALUE ( v_clob, v_json_search_ocid);
        v_json_state := JSON_VALUE ( v_clob, v_json_search_state);
        if v_json_state is null then
          v_json_next := 'N';
        elsif upper(v_json_state) not in ('TERMINATED', 'DELETED') then
          v_num_found := v_num_found + 1;
          dbms_output.put('Found type '||v_json_type||' - ');
          open c_bulk_items(v_json_type);
          fetch c_bulk_items into v_dummy;
          if c_bulk_items%FOUND then
            dbms_output.put_line('Matched !');
            ----Anoosha fix for datasafe (until they add datasafe to the bulk delete resources)
            -- if v_json_type = 'DataSafeUserAssessment' then 
            --   ll_pkg_log.log(40,' Started Data Safe User Assessment deletion: '||v_clob);      
            --   v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
            --                         p_host       => 'datasafe.us-phoenix-1.oci.oraclecloud.com',
            --                         p_method => '/20181201/userAssessments/'||v_json_ocid );
            --   ll_pkg_log.log(40,'Data Safe User Assessment delete: '||v_clob);
            -- else
            --Anoosha datasafe end fix--
            if v_json_bulk is not null then
            v_json_bulk := v_json_bulk || ',';
            end if;
        
            v_json_bulk := v_json_bulk || JSON_OBJECT ( 'entityType'   value  v_json_type,
                                                        'identifier'   value  v_json_ocid);
            if v_json_type = 'RouteTable' then
            clear_routetable (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_ocid => v_json_ocid );
            end if;
            --end if;    
          else
            dbms_output.put_line('-');
  
          end if;
          close c_bulk_items;
        end if;
        v_json_item := v_json_item + 1;
        if length(v_json_bulk) > 3500 then 
          v_json_bulk := ' { "resources" : ['||v_json_bulk||'] }';
          v_clob := ll_pkg_exec.put_post ( p_tenancy_id  => p_tenancy_id,
                                           p_type        => 'POST',
                                           p_host        => 'identity.us-ashburn-1.oraclecloud.com',
                                           p_method      => '/20160918/compartments/'||p_comp_ocid||'/actions/bulkDeleteResources',
                                           p_body        => v_json_bulk);
          dbms_output.put_line(v_json_bulk);                                           
          v_json_bulk := '';
        end if;                                           
      end loop;
    end loop;
    if v_json_bulk is not null then
      v_json_bulk := ' { "resources" : ['||v_json_bulk||'] }';
      v_clob := ll_pkg_exec.put_post ( p_tenancy_id  => p_tenancy_id,
                                       p_type        => 'POST',
                                       p_host        => 'identity.us-ashburn-1.oraclecloud.com',
                                       p_method      => '/20160918/compartments/'||p_comp_ocid||'/actions/bulkDeleteResources',
                                       p_body        => v_json_bulk);
      dbms_output.put_line(v_json_bulk);
    end if;
    return(v_num_found);
  end;
