  procedure clean_compartment (p_tenancy_id number, p_comp_ocid varchar2, p_delete varchar2 default 'N', p_move varchar2 default 'Y', p_region_key varchar2 default null, p_available_ocid varchar2 default null) is
    type t_resource is record ( region_key     varchar2(1000),
                                region_id      number, 
                                resourcetype   varchar2(1000),
                                identifier     varchar2(1000),
                                displayname    varchar2(1000),
                                lifecyclestate varchar2(1000),
                                api_type       varchar2(1000),
                                del_method     varchar2(1000) );  
   
    type t_resources IS TABLE OF t_resource;
    cursor c_regions is select region_key, id as region_id from LL_OCI_REGIONS;
    cursor c_del_method (p_search_name varchar2) is select delete_method||'/{ID}' as delete_method, endpoint_type
                                                    from LL_DELETE_OBJECTS
                                                    where search_name = p_search_name;
    v_clob            clob;
    v_dummy           clob;
    v_resources       t_resources;
    v_deleted_comp    number := 0;
    v_region_last     varchar2(100);
    v_num_objects     number;
    v_load_resources  varchar2(1) := 'Y';
    v_load_count      number := 0;
    v_false_positive  number := 0;
    v_search_result   clob;
    v_delete_method   varchar2(400);
    v_endpoint_type   varchar2(400);
  begin
-- TODO: Public IP check and delete
-- TODO: Backup policies in Block Storage
-- TODO: Zone management DNS
    ll_pkg_log.log(20,'Initial call');
    delete ll_compartments_used where compartment_ocid = p_comp_ocid;
    commit;
    v_num_objects := 0;
--    for c_del in (select IAAS.region_key, IAAS.id region_id,JTAB.resourcetype, JTAB.identifier, JTAB.displayname, JTAB.lifecyclestate, endpoint_type as api_type, delete_method||'/{ID}' as del_method
--                  from ( select region_key, id, 
--                                ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
--                                                     p_host       => ll_pkg_admin.oci_endpoint (p_type => 'query', p_region_key => region_key),
--                                                     p_type       => 'POST', 
--                                                     p_method     => '/20180409/resources',
--                                                     p_body       => '{ "type": "Structured", "query": "query all resources where compartmentId = '|| chr(39)||p_comp_ocid||chr(39)||'" }') MyJSON
--                   from ll_oci_regions ar ) IAAS,
--                   JSON_TABLE(MyJSON, '$' COLUMNS (NESTED PATH '$.items[*]' COLUMNS (resourceType, identifier, compartmentId, timeCreated, displayName, availabilityDomain, lifecycleState ))) JTAB,
--                   (select search_name, delete_method, endpoint_type from LL_DELETE_OBJECTS ) LLDO
--                    where nvl(upper(lifecyclestate),'X') not in ('TERMINATED','DELETED') -- Optionally PENDING_DELETION for Keys and Vaults. David will discuss
--                    and JTAB.resourcetype = LLDO.search_name(+)
--                    and JTAB.RESOURCETYPE is not null) loop
--                    where nvl(upper(lifecyclestate),'X') not in ('TERMINATED','DELETED') -- Optionally PENDING_DELETION for Keys and Vaults. David will discuss
--                    and JTAB.resourcetype = LLDO.search_name(+)
--                    and JTAB.RESOURCETYPE is not null) loop
    for x in c_regions loop
      ll_pkg_log.log(30,'Querying region '||x.region_key||' for resources.');
      v_search_result := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                              p_host       => ll_pkg_admin.oci_endpoint (p_type => 'query', p_region_key => x.region_key),
                                              p_type       => 'POST', 
                                              p_method     => '/20180409/resources',
                                              p_body       => '{ "type": "Structured", "query": "query all resources where compartmentId = '|| chr(39)||p_comp_ocid||chr(39)||'" }');
      ll_pkg_log.log(40,'Search result is '||v_search_result);
      if instr(v_search_result,'ocid') > 0 then
        ll_pkg_log.log(30,'Delete any OKE clusters for region '||x.region_key);
        del_OkeCluster (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_comp_ocid => p_comp_ocid );
      end if;
      for c_del in (select resourcetype, identifier, displayname, lifecyclestate
                    from JSON_TABLE (v_search_result, 
                                     '$' COLUMNS (NESTED PATH '$.items[*]' 
                                                  COLUMNS (resourceType, identifier, compartmentId, timeCreated, displayName, availabilityDomain, lifecycleState )))
                    where nvl(upper(lifecyclestate),'X') not in ('TERMINATED','DELETED') ) loop
        if c_del.identifier is not null then
          open c_del_method(c_del.resourcetype);
          fetch c_del_method into v_delete_method, v_endpoint_type;
          close c_del_method;                                                  
          v_clob := '';
          v_num_objects := v_num_objects + 1;
          ll_pkg_log.log(30,'Detected '||c_del.resourcetype||' in '||x.region_key||', delete using method: '||v_delete_method||' and endpoint '||v_endpoint_type);
-- Clean routetable in case we cannot delete it (because it is the default for the VCN)
          if c_del.resourcetype='RouteTable' then
      -- Remove all lines in the route table so we can delete the Gateways. Also, just to be sure, delete the route table
            clear_routetable (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_ocid => c_del.identifier);      
            ll_pkg_log.log(40,'Routetable empty: '||substr(v_clob,1,2000));
          end if;
-- VCN delete  
          if c_del.resourcetype='Vcn' then
            del_igw (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_comp_ocid => p_comp_ocid, p_api_type => v_endpoint_type, p_vcn_id => c_del.identifier);
            del_drg (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_comp_ocid => p_comp_ocid, p_api_type => v_endpoint_type );
            del_NetSecGrp (p_tenancy_id => p_tenancy_id, p_region_key => x.region_key, p_comp_ocid => p_comp_ocid, p_api_type => v_endpoint_type , p_vcn_id => c_del.identifier);
          -- All should be deleted now so we can delete the VCN in the generic step
          end if;
-- Logs in LogGroups
          if c_del.resourcetype='LogGroup' then
            del_logs(p_tenancy_id => p_tenancy_id, 
                     p_region_key => x.region_key, 
                     p_loggroup_id => c_del.identifier);
          end if;           
-- Buckets      
          if c_del.resourcetype='Bucket' then
            delete_objectstorage (p_tenancy_id       => p_tenancy_id,
                                  p_region           => x.region_key,
                                  p_compartment_ocid => p_comp_ocid,
                                  p_tenancy_name     => ll_pkg_admin.tenancy_name(p_tenancy_id));
            ll_pkg_log.log(40,'Region Key: '||x.region_key||', Compartment: '||p_comp_ocid||', Object Storage deleted');                                            
        end if;
-- @RFONTCHA - For example, check the code for the routing table delete (is actuall a post to clean stuff)
-- https://docs.oracle.com/en-us/iaas/api/#/en/key/release/Key/ScheduleKeyDeletion
-- If you need sysdate -> special OCI date, please user LL_PKG_ADMIN.date_to_datetime (p_date in date) return varchar2; 
-- If resource is Key then do xxxx
-- If resource is BigDataService then do xxx
      -- ContainerImages and ContainerRepo
          if c_del.resourcetype = 'ContainerRepo' and 
            ll_pkg_delete.artifact_exists( p_tenancy_id => p_tenancy_id, p_region_id => x.region_id, p_containerrepo_id => c_del.identifier ) = 'N' then     
            v_false_positive := v_false_positive + 1;
          end if;
          if c_del.resourcetype = 'ContainerImage' and 
            ll_pkg_delete.artifact_exists( p_tenancy_id => p_tenancy_id, p_region_id => x.region_id, p_containerimage_id => c_del.identifier ) = 'N' then
            v_false_positive := v_false_positive + 1;
          end if;
          if c_del.resourcetype = 'OrmJob' then
            v_false_positive := v_false_positive + 1;
          end if;
          if c_del.resourcetype not in ('Bucket') and v_endpoint_type is not null then  
            ll_pkg_log.log(30,'Attempt to delete resource '||c_del.resourcetype||' with id '||c_del.identifier);
            v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                          p_host       => ll_pkg_admin.oci_endpoint (p_type => v_endpoint_type, 
                                                                                     p_region_key => x.region_key),
                                          p_method => replace(v_delete_method,'{ID}',c_del.identifier) );
            ll_pkg_log.log(30,'Result of delete: '||v_clob);
          else
            ll_pkg_log.log(30,'Skipping delete for resourcetype '||c_del.resourcetype||' with id '||c_del.identifier);
          end if;
        end if;
    
      end loop; 
    end loop;
    ll_pkg_log.log(40,'Number of objects BEFORE false positives: '||v_num_objects||' number of false positives: '||v_false_positive);                                 
    v_num_objects := v_num_objects - v_false_positive;
    ll_pkg_log.log(40,'Number of objects AFTER false positives: '||v_num_objects||' number of false positives: '||v_false_positive);                                 
    -- Now do a bulk delete of the environments
--    v_num_objects := v_num_objects + bulk_delete (p_tenancy_id => p_tenancy_id, p_comp_ocid => p_comp_ocid );
    ll_pkg_log.log(40,'Number of objects AFTER bulk delete: '||v_num_objects||' p_delete flag is set to ' || p_delete||' for compartment: '||p_comp_ocid||' in tenancy: '||p_tenancy_id);                                 
-- Delete if flag has been set
    if v_num_objects = 0 and p_delete='Y' then
      ll_pkg_log.log(30,'Deleting');                                 
      v_deleted_comp := v_deleted_comp + 1;
      delete LL_COMPARTMENTS_USED where compartment_ocid = p_comp_ocid;
      ll_pkg_log.log(40,'v_deleted_comp: '||v_deleted_comp);                                     
      if v_deleted_comp <= 8 then
          v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                        p_host       => ll_pkg_admin.oci_endpoint (p_type => 'IDENTITY', 
                                                                                   p_region_key => 'IAD'),
                                        p_method => '/20160918/compartments/'||p_comp_ocid);
        ll_pkg_log.log(30,'Deleted compartment '||p_comp_ocid);                                 
      end if;
    end if;
-- Move if flag has been set
    ll_pkg_log.log(40,'Number of objects: '||v_num_objects||' p_move flag set to '||p_move||' for compartment: '||p_comp_ocid||' in tenancy: '||p_tenancy_id);                                 
    if v_num_objects = 0 and p_move='Y' then
     ll_pkg_log.log(40,'Move flag has been set for '||p_comp_ocid);
      delete LL_COMPARTMENTS_USED where compartment_ocid = p_comp_ocid;
      ll_pkg_log.log(30,'Attempted to delete from LL_COMPARTMENT_USED - compartment '||p_comp_ocid);
      ll_pkg_admin.update_compartment (p_tenancy_id   => p_tenancy_id,
                                       p_compartment  => p_comp_ocid,
                                       p_name         => 'ZZ-EMPTY-'||to_char(sysdate,'YYYYMMDD-HH24MISS')||'-'||dbms_random.string('U',4),
                                       p_description  => 'Ready for reuse');
      ll_pkg_admin.move_compartment(p_tenancy_id  => p_tenancy_id,
                       p_compartment => p_comp_ocid,
                       p_dest        => nvl(p_available_ocid,'AVAILABLE') );
      delete LL_COMPARTMENTS_USED where compartment_ocid = p_comp_ocid;                      
      ll_pkg_log.log(30,'Moved compartment to Available: '||p_comp_ocid);                                 
    end if;
    
    ll_pkg_log.log(20,'End of call');
  end;
--
-- =============================================================================================================================
--
  procedure clean_compartment_job (p_tenancy_id number, p_comp_ocid varchar2, p_delete varchar2 default 'N', p_move varchar2 default 'Y', p_region_key varchar2 default null) is
    v_statement   varchar2(4000);
    v_jobname     varchar2(2000);
  begin
      v_jobname := dbms_scheduler.generate_job_name('CLEANCOMP_');
      v_statement := 'LL_PKG_DELETE.CLEAN_COMPARTMENT( '||p_tenancy_id||', @'||p_comp_ocid||'@, @'||p_delete||'@, @'||p_move||'@, @'||p_region_key||'@);';
      v_statement := replace(v_statement, '@', chr(39));
      DBMS_SCHEDULER.create_job (
        job_name        => v_jobname,
        job_type        => 'PLSQL_BLOCK',
        job_action      => 'BEGIN '||v_statement||' END;',
        start_date      => CAST(sysdate AS TIMESTAMP),
        repeat_interval => null,
        enabled         => TRUE );       
  end;
