  procedure delete_objectstorage (p_tenancy_id number, p_tenancy_name varchar2, p_region varchar2, p_compartment_ocid varchar2) is 
                                                                
    v_clob clob; 
   
  begin 
   
    ll_pkg_log.log (20, 'Start delete buckets/files function.'); 
   
    for buckets in (select name 
                    from json_table(ll_pkg_exec.get (p_tenancy_id     => p_tenancy_id,
                                                     p_host           => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE', p_region_key => p_region),
                                                     p_method         => '/n/'||p_tenancy_name||'/b/',
                                                     p_compartment_id => p_compartment_ocid )
                                    , '$[*]' COLUMNS ( name varchar2 PATH '$.name'))) loop 
      ll_pkg_log.log (40,'Found bucket '||buckets.name); 
      -- Check PARs and delete
      for preauth in (select id from json_table(ll_pkg_exec.get(p_tenancy_id    => p_tenancy_id,
                                                                p_host          => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE', p_region_key => p_region),
                                                                p_method        => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/p/'),
                                                            '$[*]' COLUMNS (id))) loop
        v_clob := ll_pkg_exec.delete(p_tenancy_id    => p_tenancy_id, 
                                     p_host          => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE', p_region_key => p_region),
                                     p_method        => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/p/'||utl_url.escape(preauth.id, false, 'utf8'));   
      end loop;
      -- Check MultiPart Uploads pending
 
      for files in (select uploadId as id, object  
                    from json_table(ll_pkg_exec.get (p_tenancy_id    => p_tenancy_id,
                                                     p_host          => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE', p_region_key => p_region),
                                                     p_method        => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/u'),
                                    '$[*]' COLUMNS ( object, uploadId))) loop 
        ll_pkg_log.log (40,'Found MultipartUpload id '||files.id); 
        v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                      p_host       => ll_pkg_admin.oci_endpoint (p_type       => 'OBJECTSTORAGE', 
                                                                                 p_region_key => p_region), 
                                      p_method     => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/u/'||files.object||'?uploadId='||files.id); 
        ll_pkg_log.log (40,'Deleted Multipart upload for id '||files.id); 
      end loop; 
      --Delete the actual file
 
      for files in (select replace(name,' ','%20') as name  
                    from json_table(ll_pkg_exec.get (p_tenancy_id    => p_tenancy_id,
                                                     p_host          => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE', p_region_key => p_region),
                                                     p_method  => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/o'), 
                                    '$.objects[*]' COLUMNS ( name varchar2 PATH '$.name'))) loop 
        ll_pkg_log.log (40,'Found file /'||buckets.name||'/'||files.name); 
        v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                      p_host       => ll_pkg_admin.oci_endpoint (p_type       => 'OBJECTSTORAGE', 
                                                                                 p_region_key => p_region), 
                                      p_method     => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/o/'||files.name); 
        ll_pkg_log.log (40,'Deleted file /'||buckets.name||'/'||files.name); 
      end loop; 
       
      for reqs in (select id 
                   from json_table(ll_pkg_exec.get (p_tenancy_id    => p_tenancy_id,
                                                    p_host          => ll_pkg_admin.oci_endpoint (p_type => 'OBJECTSTORAGE',  p_region_key => p_region),
                                                    p_method        => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/p'),
                                   '$[*]' COLUMNS ( id varchar2 PATH '$.id'))) loop
        ll_pkg_log.log (40,'Found pre-authenticated request /'||buckets.name||'/'||reqs.id); 
        v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                      p_host       => ll_pkg_admin.oci_endpoint (p_type       => 'OBJECTSTORAGE', 
                                                                                 p_region_key => p_region), 
                                      p_method     => '/n/'||p_tenancy_name||'/b/'||buckets.name||'/p/'||reqs.id); 
        ll_pkg_log.log (40,'Deleted pre-authenticated request /'||buckets.name||'/'||reqs.id); 
      end loop;       
 
      v_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                    p_host       => ll_pkg_admin.oci_endpoint (p_type       => 'OBJECTSTORAGE', 
                                                                               p_region_key => p_region), 
                                    p_method     => '/n/'||p_tenancy_name||'/b/'||buckets.name); 
      ll_pkg_log.log (40,'Deleted bucket '||buckets.name||' - '||v_clob); 
    end loop; 
 
    ll_pkg_log.log (20,'End delete buckets/files function.'); 
 
  end; 
