  procedure delete_reservation_objects (p_reservation_id in number) is
  
    cursor c_steps is select id, object_ocid, region_id, nvl(delete_retry,0) delete_retry
                      from ll_reservation_steps
                      where reservation_id = p_reservation_id
                      and delete_order is not null
                      and nvl(delete_retry,0) < 5
                      and nvl(delete_success,'N') <> 'Y'
                      order by case substr(object_ocid,1,17) when 'ocid1.compartment' then 0 else 1 end, delete_order;
--                      for update of delete_success, delete_date, delete_result, delete_retry;
    v_status    varchar2(1);
    v_result    varchar2(4000);
    v_run_again varchar2(1);
    
    v_step_id      number;
    v_object_ocid  varchar2(200);
    v_region_id    number;
    v_delete_retry number;
    
    v_compartment_ocid  varchar2(200);
  begin
  
    ll_pkg_log.log(20,'Initial call', p_reservation_id);
    
    v_run_again := 'Y';
  
    while v_run_again = 'Y' loop
      open c_steps;
      fetch c_steps into v_step_id, v_object_ocid, v_region_id, v_delete_retry;
      if c_steps%NOTFOUND then
        v_run_again := 'N';
      end if;
      
      v_result := '';
      
      if v_run_again = 'Y' then
        if substr(v_object_ocid,1,17)='ocid1.compartment' and v_run_again ='Y' then
          ll_pkg_log.log(30,'Moving compartment');
          v_compartment_ocid := v_object_ocid;
          delete ll_compartments_used where compartment_ocid = v_object_ocid;
          commit;
          begin
              if nvl(v_delete_retry, 0) > 0 then 
                  apex_util.pause(120 + dbms_random.value(1, 30));  
              end if;  
              ll_pkg_admin.move_compartment (p_tenancy_id   => 	ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id),
                                             p_compartment  => v_object_ocid,
                                             p_dest         => 'RECYCLEBIN');
              v_status:='Y';
              v_result:='';
           exception when others then
              v_status := 'N';
              v_result := 'unable to move compartment to recyclebin';
           end;
        else
          ll_pkg_log.log(30,'Deleting object');
          
          if v_object_ocid is not null then
          
            delete_object (p_reservation_id => p_reservation_id,
                           p_res_step_id    => v_step_id,
                           p_status         => v_status,
                           p_result         => v_result );
  --We need to write extra stuff to make sure the object is actually deleted and we did not get a false positive.                         
                       
            v_status := nvl(v_status,'Y');                       
            ll_pkg_log.log(40,'Deleting object with id '||v_step_id||' status is '||v_status||' with result '||v_result);
          else
            v_status := 'Y';
            v_result := 'No delete executed because ocid is empty';
          end if;
        end if;
       
        update ll_reservation_steps 
           set delete_success = v_status, delete_date = sysdate, delete_result = v_result, delete_retry = case v_status when 'Y' then null else v_delete_retry+1 end
         where id = v_step_id;
       
        commit;
      end if;
      close c_steps;
    end loop;
    -- if v_compartment_ocid is not null then
    --   ll_pkg_delete.clean_compartment( p_tenancy_id => ll_pkg_reservation.tenancy_id (p_reservation_id => p_reservation_id), 
    --                                    p_comp_ocid  => v_compartment_ocid);
    -- end if;
  end;
  procedure deleteCompartments (p_tenancy_id IN number, p_compartment IN varchar2, p_dest IN varchar2, p_delete_only IN varchar2, p_permissions IN varchar2 default null, p_owner IN varchar2 default null, p_workshop_id IN varchar2 default null, p_region IN varchar2 default null, p_event_id IN varchar2 default null) is 
  -- if p_delete_only is N then procedure to move selected most recent two compartments from livelabs-available compartment to livelabs-delete compartment, update and delete them. 
  -- if p_delete_only is Y then procedure to delete the selected most recent six compartments from livelabs-delete compartment. 
    cursor c_tenancy is select nvl(default_compartment_ocid, tenancy_ocid), ll_pkg_admin.region_key (p_region_id => home_region ) as region_key
                    from ll_tenancies
                    where id = p_tenancy_id;
    v_default_ocid    varchar2(2000);
    v_region_key      varchar2(10);
    v_new_ocid        varchar2(2000);
    v_host            varchar2(2000);
    v_method_tag      varchar2(2000); 
    v_m_payload       varchar2(2000); 
    v_m_payload_tag   varchar2(4000);
    v_m_clob          clob; 
    v_m_clob_tag      clob;
    v_m_method        varchar2(2000);
    v_m_retry         varchar2(1);
    v_m_counter       number  := 0; 
    v_u_payload_tag   varchar2(4000);
    v_u_clob_tag      clob;
    v_update_status   varchar2(4000);
    v_u_retry         varchar2(1);
    v_u_attempts      number  := 0;
    
    v_d_clob          varchar2(4000);
    v_delete_status   varchar2(4000);
    v_d_attempts      number  := 0;
    delete_counter    number  := 0;
    
    v_max_retry       number;
    v_sqlerrm         varchar2(4000);
  begin 
    
    ll_pkg_log.log(20, 'Begin of delete compartments call');
    
    ll_pkg_security.set_security_group;
    
    open c_tenancy;
    fetch c_tenancy into v_default_ocid, v_region_key;
    close c_tenancy;
    if p_dest is null then
            select delete_ocid into v_new_ocid from ll_tenancies where id = p_tenancy_id;
    else 
            v_new_ocid := p_dest;
    end if; 
    
    v_host := ll_pkg_admin.oci_endpoint (p_type       => 'identity', 
                                         p_region_key => v_region_key); 
    v_method_tag := '/20160918/compartments/'||p_compartment; 
    v_max_retry  := nvl(ll_pkg_admin.is_number(ll_pkg_admin.system_parameter ('MAX_COMPARTMENT_RETRY')),30);  
    if p_delete_only = 'N' then  
        v_m_payload     := json_object( 'targetCompartmentId' value v_new_ocid);
        
        v_m_payload_tag := json_object( 'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS')));
        v_u_payload_tag := json_object( 'name'         value 'ZZ-DELETE-'||to_char(sysdate,'YYYYMMDD-HH24MISS')||'-'||dbms_random.string('U',4),
                                    'description'  value 'Ready for delete',
                                    'freeformTags' value json_object( 'LastMoveDate' value to_char(sysdate,'YYYYMMDD-HH24:MI:SS')),
                                    'definedTags'  value json_object( 'Livelabs'     value JSON_OBJECT( 'Owner'  value nvl(p_owner,'Empty'),
                                                                                                        'Region'            value nvl(p_region,'Empty'),
                                                                                                        'Permissions'       value nvl(p_permissions,'Empty'),
                                                                                                        'WorkshopID'  value nvl(p_workshop_id, 'Empty'),
                                                                                                        'EventID'     value nvl(p_event_id, 'Empty')
                                                                                                    )
                                                                    )
                                    );
        v_m_method     := '/20160918/compartments/'||p_compartment||'/actions/moveCompartment'; 
        
        ll_pkg_log.log(30, 'Begin of move call');
        v_m_retry := 'Y';
        v_m_counter := 0;
        while v_m_retry = 'Y' and v_m_counter <= v_max_retry loop
        
            v_m_clob_tag := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                                p_type       => 'PUT',
                                                p_host       => v_host,
                                                p_method     => v_method_tag,
                                                p_body       => v_m_payload_tag );
            v_m_clob := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                            p_type       => 'POST',
                                            p_host       => v_host,
                                            p_method     => v_m_method,
                                            p_body       => v_m_payload );
                                            
            v_m_counter := v_m_counter + 1;                                     
                                        
            ll_pkg_log.log(40, 'Result of attempt '||v_m_counter||' for MOVE COMPARTMENT: '|| v_m_clob);
            
            if v_m_clob is not null and nvl(JSON_VALUE(v_m_clob,'$.message'),'X') not like 'Destination compartment is already the parent of current compartment%' then
                v_m_retry := 'Y';
                apex_util.pause(10);
            else
                v_m_retry := 'N';
            end if;
            if v_m_clob is not null and nvl(JSON_VALUE(v_m_clob,'$.message'),'X') like 'Compartment rename or move in progress' then
                v_m_retry := 'Y';
                apex_util.pause(10);
            else
                v_m_retry := 'N';
            end if;
            
        end loop;
        
        if v_m_clob is not null then
        
            ll_pkg_log.log(40,'Issue Move Compartment: v_m_attempts='||v_m_counter||', result is '||v_m_clob);      
            -- ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR', 
            --                                     p_event      => 'Compartment Move Error', 
            --                                     p_message    => substr('OCID: '||p_compartment||chr(10)||'Result: '||v_m_clob,1,1000), 
            --                                     p_priority   => 1);
        end if;
        ll_pkg_log.log(30, 'End of move call');
        
        ll_pkg_log.log(30, 'Begin of update call');
        v_u_retry := 'Y';
        v_u_attempts := 0;
        
        while v_u_retry = 'Y' and v_u_attempts <= v_max_retry and nvl(v_update_status,'X') <> 'ACTIVE' loop
            v_u_attempts := v_u_attempts + 1;
            v_u_clob_tag := ll_pkg_exec.put_post(p_tenancy_id => p_tenancy_id,
                                                p_type       => 'PUT',
                                                p_host       => v_host,
                                                p_method     => v_method_tag,
                                                p_body       => v_u_payload_tag );
                                        
            ll_pkg_log.log(40, 'Result of attempt ' || v_u_attempts || ' for update COMPARTMENT ('||p_compartment||'): '||v_u_clob_tag);
            v_update_status := JSON_VALUE( v_u_clob_tag, '$.lifecycleState');
            if v_update_status <> 'ACTIVE' then
                ll_pkg_log.log(30, 'Compartment not renamed, try again. Attempt# '||v_u_attempts);
                apex_util.pause(10);
            end if;
            if v_u_clob_tag is not null and nvl(JSON_VALUE(v_u_clob_tag,'$.message'),'X') like 'Compartment rename in progress' then
                v_u_retry := 'Y';
                apex_util.pause(10);
            else
                v_u_retry := 'N';
            end if;
        end loop;
        if v_update_status <> 'ACTIVE' then
            ll_pkg_log.log(40,'Issue Update Compartment: v_u_attempts='||v_u_attempts||', result is '||v_u_clob_tag);
            ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR', 
                                    p_event      => 'Compartment Update Error', 
                                    p_message    => substr('OCID: '||p_compartment||chr(10)||'Result: '||v_u_clob_tag,1,1000), 
                                    p_priority   => 1);
        end if;
        ll_pkg_log.log(30, 'End of update call');
    end if;
    if p_delete_only = 'N' or p_delete_only = 'Y' then    
        ll_pkg_log.log(30, 'Begin of delete call');
        v_d_attempts := 0;
        while v_d_attempts < v_max_retry and nvl(v_delete_status,'X') <> 'ACTIVE' loop
            v_d_attempts := v_d_attempts + 1;
            v_d_clob := ll_pkg_exec.delete (p_tenancy_id => p_tenancy_id,
                                            p_host       => v_host,
                                            p_method => v_method_tag);
            apex_util.pause(5);                                   
            v_delete_status := JSON_VALUE( v_d_clob, '$.lifecycleState');
                                
            if v_d_clob is null and v_delete_status is null and v_d_attempts > 1 then
                ll_pkg_log.log(40, 'Compartment not deleted, result of attempt '||v_d_attempts||' to delete COMPARTMENT ('||p_compartment||'): '|| '"' || v_d_clob || '"');
                exit;
            end if;                                
            ll_pkg_log.log(40, 'Result of attempt ' || v_d_attempts || ' to delete COMPARTMENT ('||p_compartment||'): '||v_d_clob);
            
            if v_delete_status is not null and v_delete_status = 'DELETING' then
                delete_counter := delete_counter + 1;
                dbms_output.put_line('Number of compartments deleted - ' || delete_counter);
            end if;
            if v_delete_status is not null and v_delete_status <> 'DELETING' then
                ll_pkg_log.log(40, 'Compartment not deleted, try again. Attempt# '||v_d_attempts);
                apex_util.pause(10);
            end if;
        
        end loop;
        if v_delete_status is not null and v_delete_status <> 'DELETING' then
            ll_pkg_log.log(40,'Issue Deleting Compartment: v_attempts='||v_d_attempts||', result is '||v_d_clob);
            ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR', 
                                    p_event      => 'Compartment Update Error', 
                                    p_message    => substr('OCID: '||p_compartment||chr(10)||'Result: '||v_d_clob,1,1000), 
                                    p_priority   => 1);
        end if;
        ll_pkg_log.log(30, 'End of delete call');
    end if;
    ll_pkg_log.log(20, 'End of delete compartments call');
    exception
            when others then begin
                                v_sqlerrm := SQLERRM;
                                ll_pkg_log.log(30, 'Error during delete compartments executinon: '||v_sqlerrm);
                             end;
                        
  end;
  procedure deleteAvailableCompartments (p_tenancy_id IN number, p_available_ocid IN varchar2 default null, p_delete_ocid IN varchar2 default null) as
  -- procedure to fetch 2 most recent compartments in LiveLabs-Available compartment and call the deleteCompartments procedure to move, update and delete them  
    v_delete_ocid       varchar2(200);
    v_available_ocid    varchar2(200);
    v_region_key        varchar(200);
    v_host              varchar2(2000);
    v_compartments_clob clob;
    c_compartment       varchar2(200);
    v_sqlerrm           varchar2(4000);
    p_delete_only       varchar2(1):='N';
    
    c_compartment_counter number :=0;
    c_count_compartment varchar2(200);
    
    type t_refcurtype IS REF CURSOR;
    c_compartments t_refcurtype;
    c_count_compartments t_refcurtype;
    
  begin
    ll_pkg_log.log(20, 'Begin of delete available compartments call');
    select ll_pkg_admin.region_key (p_region_id => home_region ) as region_key into v_region_key
            from ll_tenancies
            where id = p_tenancy_id;
    if p_delete_ocid is null then
            select delete_ocid into v_delete_ocid from ll_tenancies where id = p_tenancy_id;
    else 
            v_delete_ocid := p_delete_ocid;
    end if;   
    if p_available_ocid is null then
            select available_ocid into v_available_ocid from ll_tenancies where id = p_tenancy_id;
    else 
            v_available_ocid := p_available_ocid;
    end if;       
    v_host := ll_pkg_admin.oci_endpoint (p_type       => 'identity', 
                                         p_region_key => v_region_key);                
    v_compartments_clob := ll_pkg_exec.get (p_tenancy_id     => p_tenancy_id,
                                              p_host           => v_host,
                                              p_method         => '/20160918/compartments/',
                                              p_query_string   => 'compartmentIdInSubtree=TRUE');
    open c_count_compartments for q'@select id 
                           from json_table( :v, '$[*]' COLUMNS (id, compartmentId, lifecycleState))
                           where compartmentId = :x and lifecycleState = 'ACTIVE'@' using v_compartments_clob, v_available_ocid;
    loop    
        
        fetch c_count_compartments into c_count_compartment;
        exit when c_count_compartments%notfound;
        c_compartment_counter := c_compartment_counter + 1;
    
    end loop;
    ll_pkg_log.log(30, 'Number of Available compartments - ' || c_compartment_counter);
    open c_compartments for q'@select id 
                        from json_table( :v, '$[*]' COLUMNS (id, name, compartmentId, lifecycleState, NESTED freeformTags[*] COLUMNS (LastMoveDate)))
                        where compartmentId = :x and lifecycleState = 'ACTIVE'
                        order by LastMoveDate desc fetch first 2 rows only@' using v_compartments_clob, v_available_ocid;                                          
    ll_pkg_log.log(30, 'Selected compartments. Start of loop.');
    while c_compartment_counter > ll_pkg_admin.system_parameter('MAX_AVAILABLE_COMPARTMENTS') loop
        fetch c_compartments into c_compartment;
        exit when c_compartments%notfound;
        
        ll_pkg_log.log(40, 'Started process for : ' || c_compartments%rowcount || ' - compartment : ' || c_compartment);
        deleteCompartments (p_tenancy_id => p_tenancy_id, p_compartment => c_compartment, p_dest => v_delete_ocid, p_delete_only => p_delete_only);
        ll_pkg_log.log(40, 'Ended process for : ' || c_compartments%rowcount || ' - compartment : ' || c_compartment);
        c_compartment_counter := c_compartment_counter - 1;
        ll_pkg_log.log(30, 'Number of Available compatments - ' || c_compartment_counter);    
    end loop;    
    ll_pkg_log.log(30, 'Ended of loop');
    ll_pkg_log.log(20, 'End of delete available compartments call');
    exception
            when others then begin
                                v_sqlerrm := SQLERRM;
                                ll_pkg_log.log(20, 'Error during delete available compartments execution: '||v_sqlerrm);
                            end;
  end;   
  procedure bulkDeleteCompartments (p_tenancy_id IN number, p_delete_ocid IN varchar2 default null) is
    -- procedure to fetch 6 most recent compartments in LiveLabs-Delete compartment and call deleteCompartments procedure to delete them   
    v_delete_ocid       varchar2(200);
    v_region_key        varchar(200);
    v_host              varchar2(2000);
    v_compartments_clob clob;
    c_compartment       varchar2(200);
    v_sqlerrm           varchar2(4000);
    p_delete_only       varchar2(1):='Y';
    
    type t_refcurtype IS REF CURSOR;
    c_compartments t_refcurtype;
    begin
    
        ll_pkg_log.log(20, 'Begin of bulk delete compartments call');
        ll_pkg_security.set_security_group;
        select ll_pkg_admin.region_key (p_region_id => home_region ) as region_key into v_region_key
            from ll_tenancies
            where id = p_tenancy_id;
        if p_delete_ocid is null then
            select delete_ocid into v_delete_ocid from ll_tenancies where id = p_tenancy_id;
        else 
            v_delete_ocid := p_delete_ocid;
        end if;       
        v_host := ll_pkg_admin.oci_endpoint (p_type       => 'identity', 
                                         p_region_key => v_region_key);                
        v_compartments_clob := ll_pkg_exec.get (p_tenancy_id     => p_tenancy_id,
                                              p_host           => v_host,
                                              p_method         => '/20160918/compartments/',
                                              p_query_string   => 'compartmentIdInSubtree=TRUE');
        open c_compartments for q'@select id 
                           from json_table( :v, '$[*]' COLUMNS (id, name, compartmentId, lifecycleState, NESTED freeformTags[*] COLUMNS (LastMoveDate)))
                           where compartmentId = :x and lifecycleState = 'ACTIVE'
                           order by LastMoveDate desc fetch first 6 rows only@' using v_compartments_clob, v_delete_ocid; 
        ll_pkg_log.log(20, 'Selected compartments. Start of loop.');
        loop
            
            fetch c_compartments into c_compartment;
            exit when c_compartments%notfound;
            
            ll_pkg_log.log(30, 'Started process for : ' || c_compartments%rowcount || ' - compartment : ' || c_compartment);
            deleteCompartments (p_tenancy_id => p_tenancy_id, p_compartment => c_compartment, p_dest => v_delete_ocid, p_delete_only => p_delete_only);
            ll_pkg_log.log(30, 'Ended process for : ' || c_compartments%rowcount || ' - compartment : ' || c_compartment);
        end loop;    
        ll_pkg_log.log(20, 'Ended of loop');
        ll_pkg_log.log(20, 'End of bulk delete compartments call');
        exception
            when others then begin
                                v_sqlerrm := SQLERRM;
                                ll_pkg_log.log(20, 'Error during bulk delete compartments execution: '||v_sqlerrm);
                             end;
  end;

    procedure secure_desktop_user (p_reservation_id IN number, p_res_step_id IN number, p_status OUT varchar2, p_result OUT varchar2) as
        cursor c_desktops(c_desktop_id number) is select tenancy_id, region_key, group_ocid
                        from ll_secure_desktops
                        where id = c_desktop_id;
        v_clob clob;
        v_tenancy_id number;
        v_secure_desktop_id number;
        v_region_key varchar2(1000);
        v_group_ocid varchar2(1000);
        v_membership_ocid varchar2(4000);
        v_clob2 clob;
    begin
        ll_pkg_log.log(20, 'Starting delete secure desktop user');
        -- get secure desktop info
        v_secure_desktop_id := ll_pkg_reservation.flow_step_result (p_reservation_id => p_reservation_id, p_param_type => 'ociSecureDesktopUser', p_result_type => 'secureDesktopId'); 
        v_membership_ocid := ll_pkg_reservation.flow_step_result (p_reservation_id => p_reservation_id, p_param_type => 'ociSecureDesktopUser', p_result_type => 'groupMembershipOcid'); 
        open c_desktops(v_secure_desktop_id);
        fetch c_desktops into v_tenancy_id, v_region_key, v_group_ocid;
        close c_desktops;

        -- remove user from group
        v_clob := ll_pkg_exec.delete (p_tenancy_id  => v_tenancy_id,  
                                      p_host        => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)),  
                                      p_method      => '/20160918/userGroupMemberships/' || v_membership_ocid);  
        ll_pkg_log.log(30, 'remove desktop user from group response: ' || v_clob);
        if v_clob is null then 
            p_status := 'Y';
            p_result := '';
        else
            p_status := 'N';
            p_result := v_clob;
        end if;
        -- delete user
        v_clob2 := ll_pkg_exec.delete (p_tenancy_id  => v_tenancy_id,  
                                      p_host        => ll_pkg_admin.oci_endpoint( p_type => 'identity', p_region_key => ll_pkg_admin.home_region_key(v_tenancy_id)),  
                                      p_method      => '/20160918/users/' || ll_pkg_reservation.step_object_ocid(p_reservation_id, p_res_step_id));  
        ll_pkg_log.log(30, 'delete desktop user response: ' || v_clob2);
        if v_clob2 is null and p_status = 'Y' then 
            p_status := 'Y';
            p_result := '';
        else
            p_status := 'N';
            p_result := 'remove user from group: ' || v_clob || '\n delete user: ' || v_clob2;
        end if;
    exception when others then 
        p_status := 'N';
        p_result := 'Exception: ' || SQLERRM;
    end;

END LL_PKG_DELETE;
