--  ##     ##  ##  ##    ##  ##       ##    ##    ##    ##    ## ##     ## ##     ## ##        ##    ## ##     ##  
--  ########  ####  ######   ########  ######     ##     ######  ##     ## ##     ## #########  ######   #######   
 
  function digestSHA256 (p_string in varchar2) return varchar2 is 
    v_return  varchar2(8000); 
  begin 
    ll_pkg_log.log(80,'Begin Digest SHA256');
    v_return := utl_raw.cast_to_varchar2(utl_encode.base64_encode(java_digest_sha256(p_string))); 
    ll_pkg_log.log(80,'End Digest SHA256');
    return(v_return); 
  end; 
 
