  function tenancy_private_key (p_tenancy_id number) return varchar2 is 
   
    cursor c_tenancy is select ll_pkg_security.decrypt(PEM_KEY_PRIV) from ll_tenancies where id = p_tenancy_id; 
    v_tenancy_key   varchar2(2000); 
     
  begin 
    open c_tenancy; 
    fetch c_tenancy into v_tenancy_key; 
    if c_tenancy%NOTFOUND then 
      v_tenancy_key := 'Error: Tenancy not found'; 
    end if; 
    close c_tenancy; 
     
    return(v_tenancy_key); 
  end; 
     
     
 
--   ######  ####  ######   ##    ##   
--  ##    ##  ##  ##    ##  ###   ##   
--  ##        ##  ##        ####  ##   
--   ######   ##  ##   #### ## ## ##   
--        ##  ##  ##    ##  ##  ####   
--  ##    ##  ##  ##    ##  ##   ###   
--   ######  ####  ######   ##    ##   
 
  function sign (p_tenancy_id number, p_string varchar2) return char is  
    v_PK       varchar2(2000);  
    v_PK_raw   raw(32000);  
    v_sign_raw raw(32000);  
    v_sign     varchar2(4000);  
  begin  
 
    LL_PKG_LOG.LOG(70,'Start Signing'); 
 
    v_PK := tenancy_private_key(p_tenancy_id); 
    
    v_PK := replace(v_PK,'-----END PRIVATE KEY-----','');  
    v_PK := replace(v_PK,'-----BEGIN PRIVATE KEY-----','');  
    v_PK := replace(v_PK,'\n','');  
    v_PK := replace(v_PK,chr(13),'');  
    v_PK := replace(v_PK,chr(10),'');
    v_PK := replace(v_PK,' ','');
    LL_PKG_LOG.LOG(80,'String to sign is: '||p_string);
    v_PK_raw := utl_encode.base64_decode(utl_raw.cast_to_raw(v_PK));  
    v_sign_raw := java_sign_raw(p_string, v_PK_raw);  
    v_sign := utl_raw.cast_to_varchar2(utl_encode.base64_encode(v_sign_raw));  
 
    v_sign := replace(v_sign,chr(13),'');  
    v_sign := replace(v_sign,chr(10),'');  
    LL_PKG_LOG.LOG(80,'Signed return value is: '||v_sign);
    LL_PKG_LOG.LOG(70,'End of call'); 
    return(v_sign);  
  end;  
 
--  ######## ##     ## ########  ######      ######   ######## ########   
--  ##        ##   ##  ##       ##    ##    ##    ##  ##          ##      
--  ##         ## ##   ##       ##          ##        ##          ##      
--  ######      ###    ######   ##          ##   #### ######      ##      
--  ##         ## ##   ##       ##          ##    ##  ##          ##      
--  ##        ##   ##  ##       ##    ##    ##    ##  ##          ##      
--  ######## ##     ## ########  ######      ######   ########    ##      
 
  function get (p_tenancy_id number, p_host varchar2, p_method varchar2, p_compartment_id varchar2 default null, p_last_string varchar2 default null, p_query_string varchar2 default null, p_multiple_page varchar2 default 'Y', p_add_compartment varchar2 default 'Y' ) return clob is
    v_timestamp        varchar2(100); 
    v_next_page        varchar2(1) := 'Y'; 
    v_next_page_id     varchar2(4000); 
    v_clob             clob; 
    v_clob_result      clob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_url              varchar2(4000); 
    v_url_spec         varchar2(4000); 
    v_auth_head        varchar2(4000); 
 
    v_header_name  varchar2(4000); 
    v_header_value varchar2(4000); 
    v_attempts          number := 0;
 
  begin 
  
    set_proxy;
 
    LL_PKG_LOG.LOG( 50,'Initial call to GET (tenancy: '||p_tenancy_id||', p_host: '||p_host||', p_method: '||p_method||', p_compartment_id: '||p_compartment_id||')'); 
    LL_PKG_LOG.LOG( 60,'p_host='||p_host||', p_method='||p_method||', p_compartment_id='||p_compartment_id||', p_last_string='||p_last_string||', p_query_string='||p_query_string); 
 
    while v_next_page='Y' and v_attempts <= 10 loop 
      if p_add_compartment = 'Y' then
        v_url_spec := p_method||nvl(p_last_string, '?compartmentId='||nvl(p_compartment_id,LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id))); 
      else
        v_url_spec := p_method;
      end if;
      if p_query_string is not null then 
        if p_add_compartment = 'Y' then
          v_url_spec := v_url_spec || '&' || p_query_string; 
        else
          v_url_spec := v_url_spec || '?' || p_query_string;
        end if;
      end if; 
 
      if v_next_page = 'Y' and v_next_page_id is not null then 
        v_url_spec := v_url_spec || '&page=' || v_next_page_id; 
      end if; 
 
      v_timestamp := to_char(systimestamp AT TIME ZONE 'GMT','Dy, DD Mon YYYY HH24:MI:SS')|| ' GMT'; 
      v_sigstring := replace('(request-target): get '||v_url_spec||'\ndate: '||v_timestamp||'\nhost: '||p_host,'\n',ltrim(rtrim(chr(10)))); 
      v_signature := sign(p_tenancy_id, v_sigstring); 
      v_auth_head := 'Signature version="1",keyId="'||LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_FINGERPRINT(p_tenancy_id)||'",algorithm="rsa-sha256",headers="(request-target) date host",signature="'||v_signature||'"'; 
      v_url := 'https://'||p_host||v_url_spec; 
 
      LL_PKG_LOG.LOG(60,'Initiating headers and execution'); 
     
      apex_web_service.g_request_headers.delete(); 
      apex_web_service.g_request_headers(1).name := 'date'; 
      apex_web_service.g_request_headers(1).value := v_timestamp; 
      apex_web_service.g_request_headers(2).name := 'Authorization'; 
      apex_web_service.g_request_headers(2).value := v_auth_head; 
 
      LL_PKG_LOG.LOG(60,'Before execute REST request'); 
      LL_PKG_LOG.LOG(70,'URL: '||v_url);
 
      begin 
        v_clob := apex_web_service.make_rest_request( p_url => v_url,  
                                                      p_http_method => 'GET', 
                                                      p_proxy_override => g_override_proxy );   
      exception 
        when others then LL_PKG_LOG.LOG(60,'Error in EXEC_GET - '||SQLERRM); 
      end; 
                                                     
      LL_PKG_LOG.LOG(60,'Result = '||v_clob);                                                     
 
      if instr(v_clob,'TooManyRequests') > 0 then 
        v_next_page := 'Y'; 
        LL_PKG_LOG.LOG(60,'Wait initiated due to too many requests'); 
        v_attempts := v_attempts + 1;
        pause; 
      else 
        LL_PKG_LOG.LOG(70,'Building result clob'); 
        v_clob_result := v_clob_result || v_clob; 
        v_next_page := 'N'; 
        v_next_page_id := ''; 
         
        for i in 1.. apex_web_service.g_headers.count loop 
          v_header_name := apex_web_service.g_headers(i).name; 
          v_header_value := apex_web_service.g_headers(i).value; 
          if v_header_name='opc-next-page' and p_multiple_page = 'Y' then 
            v_next_page_id := v_header_value; 
            v_next_page    := 'Y'; 
            LL_PKG_LOG.LOG(70,'Next page detected; fetching next page'); 
          end if; 
        end loop; 
      end if; 
    end loop; 
 
    v_clob_result := replace(v_clob_result,'][',','); 
 
    LL_PKG_LOG.LOG(60,'GET result is: '||v_clob_result); 
    LL_PKG_LOG.LOG(50,'End of GET request'); 
 
    return(v_clob_result); 
  end; 
 
--  ######## ##     ## ########  ######      ######   ######## ########    ########  ##        #######  ########   
--  ##        ##   ##  ##       ##    ##    ##    ##  ##          ##       ##     ## ##       ##     ## ##     ##  
--  ##         ## ##   ##       ##          ##        ##          ##       ##     ## ##       ##     ## ##     ##  
--  ######      ###    ######   ##          ##   #### ######      ##       ########  ##       ##     ## ########   
--  ##         ## ##   ##       ##          ##    ##  ##          ##       ##     ## ##       ##     ## ##     ##  
--  ##        ##   ##  ##       ##    ##    ##    ##  ##          ##       ##     ## ##       ##     ## ##     ##  
--  ######## ##     ## ########  ######      ######   ########    ##       ########  ########  #######  ########   
 
  function get_blob (p_tenancy_id number, p_host varchar2, p_method varchar2, p_compartment_id varchar2 default null, p_last_string varchar2 default null, p_query_string varchar2 default null) return blob is 
    v_timestamp        varchar2(100); 
    v_blob             blob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_url              varchar2(4000); 
    v_url_spec         varchar2(4000); 
    v_auth_head        varchar2(4000); 
 
    v_header_name  varchar2(4000); 
    v_header_value varchar2(4000); 
 
  begin 
  
    set_proxy;
   
    LL_PKG_LOG.LOG( 50,'Initial call to GET BLOB (tenancy: '||p_tenancy_id||', p_host: '||p_host||', p_method: '||p_method||', p_compartment_id: '||p_compartment_id||')'); 
 
    v_url_spec := p_method||nvl(p_last_string, '?compartmentId='||p_compartment_id); 
    if p_query_string is not null then 
      v_url_spec := v_url_spec || '&' || p_query_string; 
    end if; 
 
    LL_PKG_LOG.LOG(60,'URL is '||v_url_spec); 
 
    v_timestamp := to_char(systimestamp AT TIME ZONE 'GMT','Dy, DD Mon YYYY HH24:MI:SS')|| ' GMT'; 
    v_sigstring := replace('(request-target): get '||v_url_spec||'\ndate: '||v_timestamp||'\nhost: '||p_host,'\n',ltrim(rtrim(chr(10)))); 
    v_signature := sign(p_tenancy_id, v_sigstring); 
    v_auth_head := 'Signature version="1",keyId="'||LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_FINGERPRINT(p_tenancy_id)||'",algorithm="rsa-sha256",headers="(request-target) date host",signature="'||v_signature||'"'; 
    v_url := 'https://'||p_host||v_url_spec; 
     
    apex_web_service.g_request_headers.delete(); 
    apex_web_service.g_request_headers(1).name := 'date'; 
    apex_web_service.g_request_headers(1).value := v_timestamp; 
    apex_web_service.g_request_headers(2).name := 'Authorization'; 
    apex_web_service.g_request_headers(2).value := v_auth_head; 
 
    begin 
     
      v_blob := apex_web_service.make_rest_request_b( p_url => v_url,  
                                                      p_http_method => 'GET', 
                                                      p_proxy_override => g_override_proxy );                                              
 
    exception 
      when others then LL_PKG_LOG.LOG(60,'Error in EXEC_GET - '||SQLERRM); 
    end; 
     
    LL_PKG_LOG.LOG(50,'End of request'); 
    return(v_blob); 
  end; 
--
