  function get_docker (p_tenancy_id number, p_region_key varchar2, p_method varchar2 ) return clob is 
    v_auth_key         varchar2(200);
    v_region_key       varchar2(200);
    v_username         varchar2(200);
    v_password         varchar2(200);
    v_swift_name       varchar2(200);
    v_url              varchar2(4000); 
    v_auth_url         varchar2(2000);
    v_clob             clob; 
    v_clob_result      clob; 
    v_header_name      varchar2(4000); 
    v_header_value     varchar2(4000); 
    v_token            varchar2(500);
    v_next_page        varchar2(1) := 'Y'; 
    v_next_page_id     varchar2(4000); 
    v_auth_payload     varchar2(2000);
/*  
  
    v_timestamp        varchar2(100); 
    v_clob             clob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_url              varchar2(4000); 
    v_url_spec         varchar2(4000); 
    v_auth_head        varchar2(4000); 
 
    v_header_name  varchar2(4000); 
    v_header_value varchar2(4000); 
    */
 
  begin 
  
    set_proxy;
    
    v_username   := ll_pkg_admin.user_name(p_tenancy_id => p_tenancy_id);
    v_password   := ll_pkg_admin.user_auth_token(p_tenancy_id => p_tenancy_id);
    v_swift_name := ll_pkg_admin.user_swift_name(p_tenancy_id => p_tenancy_id);
    
    v_url := 'https://'||p_region_key||'.ocir.io'||p_method; 
    
 
--    LL_PKG_LOG.LOG( 50,'Initial call to GET (tenancy: '||p_tenancy_id||', p_host: '||p_host||', p_method: '||p_method||', p_compartment_id: '||p_compartment_id||')'); 
--    LL_PKG_LOG.LOG( 60,'p_host='||p_host||', p_method='||p_method||', p_compartment_id='||p_compartment_id||', p_last_string='||p_last_string||', p_query_string='||p_query_string); 
-- Authentication
    v_auth_url := 'https://'||p_region_key||'.ocir.io/20180419/docker/token?service='||lower(p_region_key)||'.ocir.io&client_id='||v_username; 
    apex_web_service.g_request_headers.delete(); 
    v_clob := apex_web_service.make_rest_request( p_url            => v_auth_url,  
                                                  p_http_method    => 'GET',
                                                  p_username       => v_swift_name||'/'||v_username,
                                                  p_password       => v_password,
                                                  p_proxy_override => g_override_proxy );   
    v_token := JSON_VALUE(v_clob, '$.token');
    
    ll_pkg_log.log(40,'Token found is '||v_token);
    
-- Retrieve of information
    apex_web_service.g_request_headers.delete(); 
    apex_web_service.g_request_headers(1).name := 'Authorization'; 
    apex_web_service.g_request_headers(1).value := 'Bearer '||v_token;
    v_clob := apex_web_service.make_rest_request( p_url            => v_url,  
                                                  p_http_method    => 'GET', 
                                                  p_proxy_override => g_override_proxy );   
    LL_PKG_LOG.LOG(60,'Result = '||v_clob);                                                     
    
      for i in 1.. apex_web_service.g_headers.count loop 
        v_header_name := apex_web_service.g_headers(i).name; 
        v_header_value := apex_web_service.g_headers(i).value; 
        ll_pkg_log.log(40,'Header Name: '||v_header_name);
        ll_pkg_log.log(40,'Header Value: '||v_header_value);
        if v_header_name='opc-next-page' then 
          v_next_page_id := v_header_value; 
          v_next_page    := 'Y'; 
          LL_PKG_LOG.LOG(70,'Pagination flag enabled !!'); 
        end if; 
      end loop; 
    LL_PKG_LOG.LOG(50,'End of GET request'); 
 
    return(v_clob); 
  end; 
--  ######## ##     ## ########  ######     ########  ##     ## ########    ########   #######   ######  ########  
--  ##        ##   ##  ##       ##    ##    ##     ## ##     ##    ##       ##     ## ##     ## ##    ##    ##     
--  ##         ## ##   ##       ##          ##     ## ##     ##    ##       ##     ## ##     ## ##          ##     
--  ######      ###    ######   ##          ########  ##     ##    ##       ########  ##     ##  ######     ##     
--  ##         ## ##   ##       ##          ##        ##     ##    ##       ##        ##     ##       ##    ##     
--  ##        ##   ##  ##       ##    ##    ##        ##     ##    ##       ##        ##     ## ##    ##    ##     
--  ######## ##     ## ########  ######     ##         #######     ##       ##         #######   ######     ##   
 
  function put_post (p_tenancy_id number, p_type varchar2, p_host varchar2, p_method varchar2, p_body clob, p_content_type varchar2 default 'application/json' ) return clob is 
    v_timestamp        varchar2(100); 
    v_clob             clob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_body_signature   varchar2(4000); 
    v_url              varchar2(4000); 
    v_auth_head        varchar2(4000); 
    v_curl             clob; 
    v_body             clob; 
    v_again            varchar2(1) := 'Y'; 
    v_header_name      varchar2(1000);
    v_header_value     varchar2(1000);
    v_attempts         number := 0;
 
  begin 
 
    LL_PKG_LOG.LOG( 50,'Initial call to PUT POST (tenancy: '||p_tenancy_id||', p_typ: '||p_type||', p_host: '||p_host||', p_method: '||p_method||')'); 
 
    set_proxy;
 
    v_body := p_body || chr(10); 
 
    while v_again = 'Y' and v_attempts <= 10 loop 
      v_timestamp := to_char(systimestamp AT TIME ZONE 'GMT','Dy, DD Mon YYYY HH24:MI:SS')|| ' GMT'; 
      LL_PKG_LOG.LOG(80,'Before signature, size is '||length(digestsha256(v_body)));     
      v_body_signature := digestsha256(v_body); 
      v_sigstring := replace('(request-target): '||lower(p_type)||' '||p_method||'\ndate: '||v_timestamp||'\nhost: '||p_host||'\nx-content-sha256: '||v_body_signature||'\ncontent-type: '||p_content_type||'\ncontent-length: '||length(v_body),'\n',ltrim(rtrim(chr(10)))); 
      LL_PKG_LOG.LOG(80,'sigstring = '||v_sigstring); 
      v_signature := sign(p_tenancy_id, v_sigstring); 
      v_auth_head := 'Signature version="1",keyId="'||LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_OCID(p_tenancy_id)|| 
                     '/'||LL_PKG_ADMIN.USER_FINGERPRINT(p_tenancy_id)|| 
                     '",algorithm="rsa-sha256",headers="(request-target) date host x-content-sha256 content-type content-length", signature="'||v_signature||'"'; 
      v_url := 'https://'||p_host||p_method; 
 
      apex_web_service.g_request_headers.delete(); 
      apex_web_service.g_request_headers(1).name := 'date'; 
      apex_web_service.g_request_headers(1).value := v_timestamp; 
      apex_web_service.g_request_headers(2).name := 'x-content-sha256'; 
      apex_web_service.g_request_headers(2).value := v_body_signature; 
      apex_web_service.g_request_headers(3).name := 'content-type'; 
      apex_web_service.g_request_headers(3).value := p_content_type; 
      apex_web_service.g_request_headers(4).name := 'Authorization'; 
      apex_web_service.g_request_headers(4).value := v_auth_head; 
     
      LL_PKG_LOG.LOG(60,'URL = '||v_url); 
      LL_PKG_LOG.LOG(70,'http_method = '||upper(p_type)); 
      LL_PKG_LOG.LOG(60,'BODY = '||v_body); 
 
      begin 
 
        v_clob := apex_web_service.make_rest_request( p_url => v_url,  
                                                      p_http_method => upper(p_type), 
                                                      p_body => v_body, 
                                                      p_proxy_override => g_override_proxy );   
                                                       
      exception 
        when others then 
        LL_PKG_LOG.LOG(60,'Error in EXEC_PUT_POST - '||SQLERRM); 
        LL_PKG_LOG.LOG(60,'Backtrace - ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
      end; 
                                                    
      LL_PKG_LOG.LOG(60,'CLOB = '||v_clob); 
       
      if instr(v_clob,'TooManyRequests') > 0 then 
        v_again := 'Y'; 
        v_attempts := v_attempts + 1;
        pause; 
      else 
        v_again := 'N'; 
      end if; 
       
    end loop; 
      for i in 1.. apex_web_service.g_headers.count loop 
        v_header_name := apex_web_service.g_headers(i).name; 
        v_header_value := apex_web_service.g_headers(i).value; 
      end loop; 
 
    LL_PKG_LOG.LOG(50,'End of request'); 
 
    return(v_clob); 
  end; 
--
-- ====================================================================================================================================
--
  procedure put_post_in_pages (p_tenancy_id IN number, p_type IN varchar2, p_host IN varchar2, p_method IN varchar2, p_body IN clob, p_result OUT clob, p_pagination IN OUT varchar2, p_content_type IN varchar2 default 'application/json' ) is
    v_timestamp        varchar2(100); 
    v_clob             clob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_body_signature   varchar2(4000); 
    v_url              varchar2(4000); 
    v_url_spec         varchar2(4000);
    v_auth_head        varchar2(4000); 
    v_curl             clob; 
    v_body             clob; 
    v_again            varchar2(1) := 'Y'; 
    v_header_name      varchar2(2000);
    v_header_value     varchar2(2000);
 
  begin 
 
    LL_PKG_LOG.LOG( 50,'Initial call to PUT POST (tenancy: '||p_tenancy_id||', p_typ: '||p_type||', p_host: '||p_host||', p_method: '||p_method||')'); 
 
    set_proxy;
 
    v_body := p_body || chr(10); 
 
    while v_again = 'Y' loop 
      v_url_spec := p_method; 
      if p_pagination is not null then 
        v_url_spec := v_url_spec || '?page=' || p_pagination; 
      end if; 
 
      v_timestamp := to_char(systimestamp AT TIME ZONE 'GMT','Dy, DD Mon YYYY HH24:MI:SS')|| ' GMT'; 
      LL_PKG_LOG.LOG(80,'Before signature, size is '||length(digestsha256(v_body)));     
      v_body_signature := digestsha256(v_body); 
      v_sigstring := replace('(request-target): '||lower(p_type)||' '||v_url_spec||'\ndate: '||v_timestamp||'\nhost: '||p_host||'\nx-content-sha256: '||v_body_signature||'\ncontent-type: '||p_content_type||'\ncontent-length: '||length(v_body),'\n',ltrim(rtrim(chr(10)))); 
      LL_PKG_LOG.LOG(80,'sigstring = '||v_sigstring); 
      v_signature := sign(p_tenancy_id, v_sigstring); 
      v_auth_head := 'Signature version="1",keyId="'||LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_OCID(p_tenancy_id)|| 
                     '/'||LL_PKG_ADMIN.USER_FINGERPRINT(p_tenancy_id)|| 
                     '",algorithm="rsa-sha256",headers="(request-target) date host x-content-sha256 content-type content-length", signature="'||v_signature||'"'; 
      v_url := 'https://'||p_host||v_url_spec; 
 
      apex_web_service.g_request_headers.delete(); 
      apex_web_service.g_request_headers(1).name := 'date'; 
      apex_web_service.g_request_headers(1).value := v_timestamp; 
      apex_web_service.g_request_headers(2).name := 'x-content-sha256'; 
      apex_web_service.g_request_headers(2).value := v_body_signature; 
      apex_web_service.g_request_headers(3).name := 'content-type'; 
      apex_web_service.g_request_headers(3).value := p_content_type; 
      apex_web_service.g_request_headers(4).name := 'Authorization'; 
      apex_web_service.g_request_headers(4).value := v_auth_head; 
     
      LL_PKG_LOG.LOG(60,'URL = '||v_url); 
      LL_PKG_LOG.LOG(70,'http_method = '||upper(p_type)); 
      LL_PKG_LOG.LOG(60,'BODY = '||v_body); 
 
      begin 
 
        v_clob := apex_web_service.make_rest_request( p_url => v_url,  
                                                      p_http_method => upper(p_type), 
                                                      p_body => v_body, 
                                                      p_proxy_override => g_override_proxy );   
                                                       
      exception 
        when others then LL_PKG_LOG.LOG(60,'Error in EXEC_PUT_POST_PAGES - '||SQLERRM); 
      end; 
                                                    
      LL_PKG_LOG.LOG(60,'CLOB = '||v_clob); 
       
      if instr(v_clob,'TooManyRequests') > 0 then 
        v_again := 'Y'; 
        LL_PKG_LOG.LOG(60,'Wait initiated due to too many requests'); 
        pause; 
      else 
        LL_PKG_LOG.LOG(70,'In ELSE for pagination check'); 
        p_result := v_clob; 
        v_again := 'N'; 
        p_pagination := ''; 
         
        for i in 1.. apex_web_service.g_headers.count loop 
          v_header_name := apex_web_service.g_headers(i).name; 
          v_header_value := apex_web_service.g_headers(i).value; 
          if v_header_name='opc-next-page' then 
            p_pagination := v_header_value; 
          end if; 
        end loop; 
      end if; 
       
    end loop; 
 
    LL_PKG_LOG.LOG(50,'End of request'); 
 
  end; 
 
--  ######## ##     ## ########  ######     ########  ######## ##       ######## ######## ########  
--  ##        ##   ##  ##       ##    ##    ##     ## ##       ##       ##          ##    ##        
--  ##         ## ##   ##       ##          ##     ## ##       ##       ##          ##    ##        
--  ######      ###    ######   ##          ##     ## ######   ##       ######      ##    ######    
--  ##         ## ##   ##       ##          ##     ## ##       ##       ##          ##    ##        
--  ##        ##   ##  ##       ##    ##    ##     ## ##       ##       ##          ##    ##        
--  ######## ##     ## ########  ######     ########  ######## ######## ########    ##    ########  
 
  function delete (p_tenancy_id number, p_host varchar2, p_method varchar2) return clob is 
    v_timestamp        varchar2(100); 
    v_get_again        varchar2(1)     := 'Y'; 
    v_clob             clob; 
    v_sigstring        varchar2(4000); 
    v_signature        varchar2(4000); 
    v_url              varchar2(4000); 
    v_auth_head        varchar2(4000); 
    v_attempts         number := 0; 
 
    -- test with 
    -- declare 
    -- t clob; 
    --  begin 
    --    t := res_bm.rp_exec_get ('database.eu-frankfurt-1.oraclecloud.com','/20160918/databases', 'ocid1.compartment.oc1..aaaaaaaaja5hmjbi6wxhyfsbk4ysztgzig5uvx7zljgwnenywjex4xmkcolq'); 
    --    dbms_output.put_line(t); 
    --  end; 
 
  begin 
   
    LL_PKG_LOG.LOG( 50,'Initial call to DELETE (tenancy: '||p_tenancy_id||', p_host: '||p_host||', p_method: '||p_method||')'); 
    set_proxy;
    while v_get_again='Y' and v_attempts < 10 loop 
 
      v_timestamp := to_char(systimestamp AT TIME ZONE 'GMT','Dy, DD Mon YYYY HH24:MI:SS')|| ' GMT'; 
      v_sigstring := replace('(request-target): delete '||p_method||'\ndate: '||v_timestamp||'\nhost: '||p_host,'\n',ltrim(rtrim(chr(10)))); 
      v_signature := sign(p_tenancy_id, v_sigstring); 
      v_auth_head := 'Signature version="1",keyId="'||LL_PKG_ADMIN.TENANCY_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_OCID(p_tenancy_id)||'/'||LL_PKG_ADMIN.USER_FINGERPRINT(p_tenancy_id)||'",algorithm="rsa-sha256",headers="(request-target) date host",signature="'||v_signature||'"'; 
      v_url := 'https://'||p_host||p_method; 
     
      apex_web_service.g_request_headers.delete(); 
      apex_web_service.g_request_headers(1).name := 'date'; 
      apex_web_service.g_request_headers(1).value := v_timestamp; 
      apex_web_service.g_request_headers(2).name := 'Authorization'; 
      apex_web_service.g_request_headers(2).value := v_auth_head; 
 
      LL_PKG_LOG.LOG(60,'Before execute REST DELETE request, URL: @'||v_url||'@'); 
       
      begin 
       
        v_clob := apex_web_service.make_rest_request( p_url => v_url,  
                                                      p_http_method => 'DELETE', 
                                                      p_proxy_override => g_override_proxy );                                              
                                                       
      exception 
        when others then LL_PKG_LOG.LOG(60,'Error in EXEC_DELETE - '||v_url||' - '||g_override_proxy||' - '||SQLERRM); 
      end; 
                                                       
 
      LL_PKG_LOG.LOG(60,'After execute REST request, request is '||v_url); 
      LL_PKG_LOG.LOG(60,'After execute REST request, result is: '||v_clob); 
 
      if instr(v_clob,'TooManyRequests') > 0 then 
        v_get_again := 'Y'; 
        v_attempts := v_attempts + 1; 
        pause; 
        LL_PKG_LOG.LOG(60,'Wait initiated due to too many requests'); 
        v_clob := ''; 
      else 
        v_get_again := 'N'; 
        LL_PKG_LOG.LOG(70,'No Many Requests message received'); 
      end if; 
       
      LL_PKG_LOG.LOG(70,'After TooManyRequets check.'); 
    end loop; 
 
    LL_PKG_LOG.LOG(60,'exec_delete finished, result = '||v_clob); 
 
    apex_web_service.g_request_headers.delete(); 
 
    LL_PKG_LOG.LOG(50,'End of call'); 
 
    return(v_clob); 
  end; 
--
-- =========================================================================================
--
  procedure send_prowl (p_error_type varchar2, p_message varchar2, p_event varchar2, p_priority number default 5) is
  
    cursor c_keys is select key_value
                     from ll_keys
                     where key_type='PROWL-KEY'
                     and key_name in (select key_name
                                      from ll_keys
                                      where key_type='PROWL-'||p_error_type
                                      and active_flg='Y')
                     and active_flg='Y';
                     
    v_param_name    apex_application_global.vc_arr2;
    v_param_value   apex_application_global.vc_arr2;
    v_clob          clob;
                     
  begin
    if nvl(g_prowl_message,'Empty') <> p_message then
      ll_pkg_log.log(1,'Prowl message: '||p_message);
      set_proxy;
      apex_web_service.g_request_headers.delete(); 
      apex_web_service.g_request_headers(1).name := 'Content-Type';  
      apex_web_service.g_request_headers(1).value := 'application/x-www-form-urlencoded';  
      for x in c_keys loop
        v_param_name(1) := 'apikey';          v_param_value(1) := x.key_value;
        v_param_name(2) := 'priority';        v_param_value(2) := p_priority;
        v_param_name(3) := 'application';     v_param_value(3) := ll_pkg_admin.system_parameter ('EMAIL_SENDER');
        v_param_name(4) := 'event';           v_param_value(4) := p_event;
        v_param_name(5) := 'description';     v_param_value(5) := p_message;
      
        v_clob := apex_web_service.make_rest_request( p_url            => 'https://api.prowlapp.com/publicapi/add',
                                                      p_http_method    => 'POST',  
                                                      p_parm_name      => v_param_name,  
                                                      p_parm_value     => v_param_value,
                                                      p_proxy_override => g_override_proxy );                                              
                                                      
      end loop;
      g_prowl_message := p_message;
    end if;  
    
  exception
    when others then null;
  end;
  
END;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_ISSUES" as 
     
    g_override_proxy varchar2(200); 
 
    procedure set_proxy 
    as 
 
    begin 
        if g_override_proxy is null then 
            g_override_proxy := ll_pkg_admin.system_parameter ('PROXY'); 
        end if; 
 
        if g_override_proxy is null then 
            g_override_proxy := 'appoci-proxy01-vip.oraclevcn.com'; 
        end if; 
    end set_proxy; 
 
 
    function get_issue_type_id( p_code in varchar2 ) return number 
    as 
        l_issue_type_id number; 
 
        cursor cur_issue_types( p_code in varchar2 ) is 
            select issue_type_id 
              from ll_issue_types 
             where code = upper(p_code); 
    begin 
        for rec_issue_type in cur_issue_types(p_code) 
        loop 
            l_issue_type_id := rec_issue_type.issue_type_id; 
        end loop; 
 
        return l_issue_type_id; 
    end get_issue_type_id; 
 
 
    function get_issue_status_id( p_code in varchar2 ) return number 
    as 
        l_issue_status_id number; 
 
        cursor cur_issue_types( p_code in varchar2 ) is 
            select issue_status_id 
              from ll_issue_statuses 
             where code = upper(p_code); 
    begin 
        for rec_issue_type in cur_issue_types(p_code) 
        loop 
            l_issue_status_id := rec_issue_type.issue_status_id; 
        end loop; 
 
        return l_issue_status_id; 
    end get_issue_status_id; 
 
 
    function get_open_issue(p_workshop_id   in number, 
                            p_voucher_id    in number default null, 
                            p_issue_type_id in number, 
                            p_issue_value   in varchar2) return number 
    as 
        l_issue_id number; 
 
        cursor cur_issues is 
            select i.issue_id 
              from ll_workshop_issues i, 
                   ll_issue_statuses s 
             where 1 = 1 
               and i.issue_status_id    = s.issue_status_id 
               and i.workshop_id        = p_workshop_id 
               and i.voucher_id         = p_voucher_id 
               and i.issue_type_id      = p_issue_type_id 
               and s.code               in (c_issue_status_error) 
               and i.issue_value        = p_issue_value; 
    begin 
        for rec_issue in cur_issues 
        loop 
            l_issue_id := rec_issue.issue_id; 
        end loop; 
 
        return l_issue_id; 
    end get_open_issue; 
     
         
    procedure add_workshop_issue(p_workshop_id        in number, 
                                 p_voucher_id         in number default null, 
                                 p_issue_type_id      in number, 
                                 p_issue_status_id    in number, 
                                 p_issue_value        in varchar2, 
                                 p_issue_return_value in varchar2) 
    as 
        l_issue_id number; 
    begin 
        l_issue_id := get_open_issue(p_workshop_id   => p_workshop_id, 
                                     p_voucher_id    => p_voucher_id, 
                                     p_issue_type_id => p_issue_type_id, 
                                     p_issue_value   => p_issue_value); 
 
        if l_issue_id is null then 
            insert into ll_workshop_issues(workshop_id, 
                                           voucher_id, 
                                           issue_type_id, 
                                           issue_status_id, 
                                           issue_value, 
                                           issue_return_value) 
            values (p_workshop_id, 
                    p_voucher_id, 
                    p_issue_type_id, 
                    p_issue_status_id, 
                    p_issue_value, 
                    p_issue_return_value); 
        else 
            update ll_workshop_issues 
               set issue_count = issue_count + 1 
             where issue_id = l_issue_id; 
        end if; 
         
    end add_workshop_issue; 
 
 
    procedure validate_link(p_url              in  varchar2, 
                            p_proxy_override   in  varchar2 default null, 
                            p_https_host       in  varchar2 default null, 
                            p_link_valid       out boolean, 
                            p_resp_status_code out varchar2) 
    as 
        l_response clob; 
    begin 
        -- new env: set proxy to null 
        l_response := apex_web_service.make_rest_request(p_url              => p_url, 
                                                         p_proxy_override   => '', 
                                                         p_https_host       => p_https_host, 
                                                         p_transfer_timeout => 15, 
                                                         p_http_method      => 'GET'); 
         
        if apex_web_service.g_status_code like '2%' then  
            p_link_valid := true; 
        else 
            p_link_valid := false; 
        end if; 
 
        p_resp_status_code := apex_web_service.g_status_code; 
 
    exception when others then 
        p_link_valid := false; 
        p_resp_status_code := 408; 
    end validate_link; 
 
 
    procedure validate_workshop_links 
    as 
        l_link_valid       boolean; 
        l_resp_status_code varchar2(10); 
 
        l_issue_type_id    number; 
        l_status_id        number; 
 
        cursor cur_workshops is 
            select workshop_id, 
                   github_url, 
                   livelab_url 
              from ( 
                    select id workshop_id, 
                           json_value(lab_url,'$.GITHUB_URL') github_url, 
                           json_value(lab_url,'$.LIVELABS_URL') livelab_url 
                    from ll_workshops 
                    ) 
              where 1= 1 
                and (github_url is not null 
                        or livelab_url is not null 
                        ); 
    begin 
        l_issue_type_id := get_issue_type_id(c_issue_type_broken_link); 
        l_status_id     := get_issue_status_id(c_issue_status_error); 
 
        set_proxy(); 
 
        for rec_workshop in cur_workshops 
        loop 
            if rec_workshop.github_url is not null then 
                 
                validate_link(p_url              => rec_workshop.github_url, 
                              p_proxy_override   => g_override_proxy, 
                              p_link_valid       => l_link_valid, 
                              p_resp_status_code => l_resp_status_code); 
 
                if not l_link_valid then  
                    add_workshop_issue(p_workshop_id        => rec_workshop.workshop_id, 
                                       p_issue_type_id      => l_issue_type_id, 
                                       p_issue_status_id    => l_status_id, 
                                       p_issue_value        => rec_workshop.github_url, 
                                       p_issue_return_value => l_resp_status_code); 
                end if; 
            end if; 
 
            if rec_workshop.livelab_url is not null then 
                 
                validate_link(p_url              => rec_workshop.livelab_url, 
                              p_proxy_override   => g_override_proxy, 
                              p_link_valid       => l_link_valid, 
                              p_resp_status_code => l_resp_status_code); 
 
                if not l_link_valid then  
                    add_workshop_issue(p_workshop_id        => rec_workshop.workshop_id, 
                                       p_issue_type_id      => l_issue_type_id, 
                                       p_issue_status_id    => l_status_id, 
                                       p_issue_value        => rec_workshop.livelab_url, 
                                       p_issue_return_value => l_resp_status_code); 
                end if; 
            end if; 
        end loop; 
    end validate_workshop_links; 
 
 
    procedure validate_event_links 
    as 
        l_link_valid       boolean; 
        l_resp_status_code varchar2(10); 
 
        l_issue_type_id    number; 
        l_status_id        number; 
 
        cursor cur_events is 
            select voucher_id, 
                   workshop_id, 
                   github_url, 
                   livelab_url 
              from ( 
                    select id voucher_id, 
                           workshop_id, 
                           json_value(alt_url,'$.GITHUB_URL') github_url, 
                           json_value(alt_url,'$.LIVELABS_URL') livelab_url 
                    from ll_vouchers 
                    ) 
              where 1= 1 
                and (github_url is not null 
                        or livelab_url is not null 
                        ); 
    begin 
        l_issue_type_id := get_issue_type_id(c_issue_type_broken_link); 
        l_status_id     := get_issue_status_id(c_issue_status_error); 
 
        set_proxy(); 
 
        for rec_event in cur_events 
        loop 
            if rec_event.github_url is not null then 
                 
                validate_link(p_url              => rec_event.github_url, 
                              p_proxy_override   => g_override_proxy, 
                              p_link_valid       => l_link_valid, 
                              p_resp_status_code => l_resp_status_code); 
 
                if not l_link_valid then  
                    add_workshop_issue(p_workshop_id        => rec_event.workshop_id, 
                                       p_voucher_id         => rec_event.voucher_id, 
                                       p_issue_type_id      => l_issue_type_id, 
                                       p_issue_status_id    => l_status_id, 
                                       p_issue_value        => rec_event.github_url, 
                                       p_issue_return_value => l_resp_status_code); 
                end if; 
            end if; 
 
            if rec_event.livelab_url is not null then 
                 
                validate_link(p_url              => rec_event.livelab_url, 
                              p_proxy_override   => g_override_proxy, 
                              p_link_valid       => l_link_valid, 
                              p_resp_status_code => l_resp_status_code); 
 
                if not l_link_valid then  
                    add_workshop_issue(p_workshop_id        => rec_event.workshop_id, 
                                       p_voucher_id         => rec_event.voucher_id, 
                                       p_issue_type_id      => l_issue_type_id, 
                                       p_issue_status_id    => l_status_id, 
                                       p_issue_value        => rec_event.livelab_url, 
                                       p_issue_return_value => l_resp_status_code); 
                end if; 
            end if; 
        end loop; 
    end validate_event_links; 
 
 
    procedure validate_all_links 
    as 
    begin 
        ll_pkg_log.log(10,'Initiate link validations'); 
         
        ll_pkg_log.log(20,'Start Workshop Links Validation'); 
        validate_workshop_links(); 
         
        ll_pkg_log.log(20,'Start Event Links Validation'); 
        validate_event_links(); 
         
        ll_pkg_log.log(10,'End of call');   
    end validate_all_links; 
 
end ll_pkg_issues;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_LOG" AS 
 
/*  Logging levels 
 
    1  = serious error 
    10 = start and stop of high level package 
    20 = start and stop of subroutine 
    30 = steps inside subroutine 
    40 = detailed steps inside subroutine (contains values) 
    50 = exec of commands start/stop 
    60 = detailed steps of exec commands 
    70 = signing of URLs 
    80 = details on signing of URLs */ 
     
-- Generate headers with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE 
    g_reservation_id   number;
 
 
--  ##        #######   ######    
--  ##       ##     ## ##    ##   
--  ##       ##     ## ##         
--  ##       ##     ## ##   ####  
--  ##       ##     ## ##    ##   
--  ##       ##     ## ##    ##   
--  ########  #######   ######   
 
  procedure log (p_loglevel number, p_value clob, p_reservation_id number default null) AS
    PRAGMA AUTONOMOUS_TRANSACTION; 
 
    cursor c_params1 is select /*+ RESULT_CACHE */ value from ll_system_parameters where name='LOGLEVEL'; 
    cursor c_params2 is select /*+ RESULT_CACHE */ value from ll_system_parameters where name='LOGVALUE'; 
    cursor c_dummy is select /*+ RESULT_CACHE */ * from LL_PANIC_DO_NOT_DELETE;
 
      v_loglevel         varchar2(50); 
      v_logvalue         varchar2(200);
      v_owner            varchar2(200); 
      v_name             varchar2(200);  
      v_lineno           number; 
      v_caller           varchar2(200); 
      v_would_have       varchar2(1);
      v_dummy            ll_panic_do_not_delete%rowtype;
      v_sid              varchar2(100);
      v_sessionid        varchar2(100);
      v_sqlerrm          varchar2(4000);
      v_apex_user        varchar2(100);
 
      v_entry_loglevel   number; 
      v_disp_loglevel    number; 
      
      v_log_add          varchar2(4000);
      v_do_log           varchar2(1);
      
    begin 
        
      open c_params1; 
      fetch c_params1 into v_loglevel; 
      close c_params1; 
      if instr(v_loglevel,p_loglevel) > 0 or p_loglevel = 1 then
        v_do_log := 'Y';
        open c_params2; 
        fetch c_params2 into v_logvalue; 
        close c_params2; 
        v_apex_user := SYS_CONTEXT('APEX$SESSION','APP_USER'); 
        OWA_UTIL.WHO_CALLED_ME(owner => v_owner, name => v_name, lineno => v_lineno, caller_t => v_caller); 
      else
        v_do_log := 'N';
      end if;
      
      if v_do_log = 'Y' and instr(v_loglevel, 'BJ') = 0 and SYS_CONTEXT ('USERENV', 'BG_JOB_ID') is not null and p_loglevel <> 1 then
        v_do_log := 'N';
      end if;
      
      g_reservation_id := nvl(p_reservation_id,g_reservation_id);
      
      if v_do_log = 'Y' and ( upper(p_value) like '%'||upper(v_logvalue)||'%' or 
                              upper(v_apex_user) like '%'||upper(v_logvalue)||'%' or 
                              upper(v_name) like '%'||upper(v_logvalue)||'%' or 
                              g_reservation_id like '%'||v_logvalue||'%' or
                              p_loglevel = 1 ) then
        insert into ll_logging (log_date, log_level, module, log_value, session_id, reservation_id, apex_user) 
          values (sysdate, p_loglevel, v_name||' ('||v_lineno||')', substr(p_value,1,32000) , SYS_CONTEXT ('USERENV', 'SESSIONID'), g_reservation_id, v_apex_user  ); 
        commit; 
      end if; 
      
      exception when others then
        begin
          v_sqlerrm := SQLERRM;
          ll_pkg_exec.send_prowl (p_error_type => 'LOG-ERROR', p_message => 'Error during logwrite', p_event => 'Logerror', p_priority => 1);
        end;
  END log; 
   
--   ######  ##     ##    ###    ##    ##  ######   ########    ##        #######   ######   ##       ######## ##     ## ######## ##        
--  ##    ## ##     ##   ## ##   ###   ## ##    ##  ##          ##       ##     ## ##    ##  ##       ##       ##     ## ##       ##        
--  ##       ##     ##  ##   ##  ####  ## ##        ##          ##       ##     ## ##        ##       ##       ##     ## ##       ##        
--  ##       ######### ##     ## ## ## ## ##   #### ######      ##       ##     ## ##   #### ##       ######   ##     ## ######   ##        
--  ##       ##     ## ######### ##  #### ##    ##  ##          ##       ##     ## ##    ##  ##       ##        ##   ##  ##       ##        
--  ##    ## ##     ## ##     ## ##   ### ##    ##  ##          ##       ##     ## ##    ##  ##       ##         ## ##   ##       ##        
--   ######  ##     ## ##     ## ##    ##  ######   ########    ########  #######   ######   ######## ########    ###    ######## ########    
 
  procedure change_loglevel (p_level number) AS 
  BEGIN 
    update ll_system_parameters set value=p_level where name='LOGLEVEL'; 
    commit; 
  END change_loglevel; 
  
  procedure reset_loglevel as
  begin
    -- if the loglevel is already normal, do nothing and reset the clock
    if ll_pkg_admin.system_parameter('LOGLEVEL') = '01:BJ' then 
        update ll_system_parameters set value=null where name='LAST_LOGLEVEL_RESET';
    else 
        -- if the last_loglevel_reset is null, set it
        if ll_pkg_admin.system_parameter('LAST_LOGLEVEL_RESET') is null then
            update ll_system_parameters set value=to_char(systimestamp, 'DD-MON-YY HH24.MI.SS') where name = 'LAST_LOGLEVEL_RESET';
        -- if it is not null, then check to see if its been too long and we need to reset
        elsif systimestamp > (to_timestamp(ll_pkg_admin.system_parameter('LAST_LOGLEVEL_RESET'), 'DD-MON-YY HH24.MI.SS') + cast(ll_pkg_admin.system_parameter('LOGLEVEL_RESET_PERIOD') as number)/24) then
            -- if it has been longer than allowed, reset time and logelevel
            update ll_system_parameters set value='01:BJ' where name='LOGLEVEL';
            update ll_system_parameters set value=null where name='LAST_LOGLEVEL_RESET';
        end if;
    end if;
  end;
  
END LL_PKG_LOG; 
-- (to_timestamp(ll_pkg_admin.system_parameter('LAST_LOGLEVEL_RESET'), 'DD-MON-YY HH24.MI.SS') + 0.25/24) < systimestamp;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_ORDS" as

    procedure authorizeORDS(p_content_type varchar2 default 'application/json') as
        v_ords_id varchar2(4000);
        v_ords_secret varchar2(4000);
        v_ords_auth varchar2(4000);
    begin
        select value into v_ords_id from ll_system_parameters where name = 'ORDS_ID';
        select value into v_ords_secret from ll_system_parameters where name = 'ORDS_SECRET';
        select value into v_ords_auth from ll_system_parameters where name = 'ORDS_AUTH';
        apex_web_service.oauth_authenticate(
                p_token_url     => v_ords_auth,
                p_client_id     => v_ords_id,
                p_client_secret => v_ords_secret);
                --, p_proxy_override => 'appoci-proxy01-vip.oraclevcn.com');
        apex_web_service.g_request_headers(1).name  := 'Authorization';
        apex_web_service.g_request_headers(1).value := 'Bearer ' || apex_web_service.oauth_get_last_token;
        if p_content_type is not null then
            apex_web_service.g_request_headers(2).name  := 'Content-Type';
            apex_web_service.g_request_headers(2).value := p_content_type;
        end if;
    end;
    
    procedure syncImageConnections as
        cursor c_connections is 
            select
                t.*,
                json_object(
                    'row_id'      value t.id,
                    'livelabs_id' value t.workshop_id,
                    'image_id'    value t.image_id,
                    'active_flg'  value t.active_flg
                    returning clob) as body_clob
            from ll_workshop_images t
            where t.updated_flg > 0;
        v_ords_url varchar2(4000);
        v_response clob;
    begin
        authorizeORDS;
        select value into v_ords_url from ll_system_parameters where name = 'ORDS_URL';

        for connection in c_connections loop
            v_response := apex_web_service.make_rest_request(p_url => v_ords_url || 'computeImages/connectImage/',  
                                            p_http_method => 'PUT', 
                                            p_body => connection.body_clob); -- p_proxy_override => 'appoci-proxy01-vip.oraclevcn.com'

            update ll_workshop_images set updated_flg = 0 where id = connection.id;
            
            ll_pkg_log.log(60, 'Successfully connected image #' || connection.image_id || ' to LiveLab #' || connection.workshop_id);
        end loop;
    end;

    procedure createImage(p_image_id number) as
        v_body clob;
        v_ords_url varchar2(1000);
        response clob;
        v_errm clob;
    begin
        authorizeORDS;
        select value into v_ords_url from ll_system_parameters where name = 'ORDS_URL';
        select json_object(
             'image_id'        value p_image_id,
             'listing_id'      value listing_id,
             'remarks'         value remarks,
             'seclist_req'     value seclist_req,
             'ocpu_req'        value ocpu_required,
             'image_req'       value image_req,
             'pubkey_req'      value pubkey_req,
             'novnc_enabled'   value novnc_enabled,
             'database_version' value database_version,
             'version'         value version,
             'instance_prefix' value instance_prefix,
             'image_ocid'      value image_ocid,
             'active_flg'      value 'Y',
             'added_on'        value added_on,
             'added_by'        value added_by
             null on null
             returning clob
           )
        into   v_body
        from   ll_images
        where  id = p_image_id;
        ll_pkg_log.log(60, 'JSON Payload: ' || v_body);
    -- https://apex.oraclecorp.com/pls/apex/wmsdevelop/wms/
        response := apex_web_service.make_rest_request(p_url => v_ords_url || 'compute-images/createImage',  
                                            p_http_method => 'POST',
                                            p_body => v_body);
        if apex_web_service.g_status_code != 200 then
            raise_application_error(
                -20001,
                'Sync REST call failed with status ' || apex_web_service.g_status_code
                || ': ' || substr(response, 1, 4000)
            );
        end if;
    
        dbms_output.put_line(response);
        ll_pkg_log.log(60, 'Created image #' || p_image_id || ' in LiveLabs.');

    exception when others then
        v_errm := SQLERRM;
        ll_pkg_log.log(60, 'Error creating image #' || p_image_id || ' in LiveLabs: ' || v_errm);
        raise;  
    end;


    procedure updateImage(p_image_id number) as
        v_body clob;
        v_ords_url varchar2(1000);
        response clob;
        errm varchar2(4000);
    begin
        authorizeORDS;
        select value into v_ords_url from ll_system_parameters where name = 'ORDS_URL';
        select json_object(
             'image_id'        value p_image_id,
             'listing_id'      value listing_id,
             'remarks'         value remarks,
             'seclist_req'     value seclist_req,
             'ocpu_req'        value ocpu_required,
             'image_req'       value image_req,
             'pubkey_req'      value pubkey_req,
             'novnc_enabled'   value novnc_enabled,
             'database_version' value database_version,
             'version'         value version,
             'instance_prefix' value instance_prefix,
             'image_ocid'      value image_ocid,
             'active_flg'      value 'Y'
             null on null 
             returning clob
           )
        into   v_body
        from   ll_images
        where  id = p_image_id;
        ll_pkg_log.log(60, 'JSON Payload: ' || v_body);

        response := apex_web_service.make_rest_request(p_url => v_ords_url || 'compute-images/updateImage/' || p_image_id,  
                                                p_http_method => 'PUT', 
                                                p_body => v_body);
        if apex_web_service.g_status_code != 200 then
        raise_application_error(
            -20001, 
            'Sync REST call failed with status ' || apex_web_service.g_status_code
            || ': ' || substr(response, 1, 4000)
        );
        end if;
        dbms_output.put_line(response);

        -- update ll_images set updated_flg = 0 where id = p_image_id;
        ll_pkg_log.log(60, 'Updated image #' || p_image_id || ' in LiveLabs.');

    exception when others then
            errm := SQLERRM;
            ll_pkg_log.log(60, 'Error updating image #' || p_image_id || ' in LiveLabs: ' || errm);
            raise;
    end;   

