        'Sync REST call failed with status ' || apex_web_service.g_status_code
        || ': ' || substr(response, 1, 4000)
    );
    end if;

    ll_pkg_log.log(60, 'Connected image #' || v_image_id || ' with LL ID #' || v_ll_id); 

exception when others then
        errm := SQLERRM;
        ll_pkg_log.log(60, 'Error connecting image #' || v_image_id || ' with LL ID #' || v_ll_id || ': ' || errm);
