/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_OVERVIEW" as
  procedure compartments (p_tenancy_id number default null) is
    cursor c_tenancies is select llt.id, llor.id as region_id, ll_pkg_admin.oci_endpoint ( 'identity', llor.region_key) as host
                          from ll_tenancies llt, ll_oci_regions llor
                          where llt.home_region = llor.id
                          and (llt.id = p_tenancy_id or p_tenancy_id is null)
                          and llt.active_flg='Y';
    v_json_result  clob;                          
  begin
    delete ll_ovw_compartments where tenancy_id in (select id from ll_tenancies where active_flg='N');
    commit;
    for x in c_tenancies loop
      v_json_result := ll_pkg_exec.get ( p_tenancy_id   =>  x.id,
                                         p_host         =>  x.host,
                                         p_method       => '/20160918/compartments/',
                                         p_query_string => 'compartmentIdInSubtree=TRUE');
      if v_json_result is not null then
        delete ll_ovw_compartments where tenancy_id = x.id;
        for z in (select x.id tid, jtab.id id, 
                                 jtab.compartmentId, 
                                 jtab.name, 
                                 jtab.description, 
                                 jtab.timeCreated, 
                                 jtab.lifecycleState,
                                 case substr(creator,1,4) when 'ocid' then substr(creator,instr(creator,'/')+1) 
                                      when 'orac' then substr(creator,instr(creator,'/')+1) 
                                      else creator end as creator
                          from JSON_TABLE ( v_json_result, '$[*]' COLUMNS (id, compartmentId, name, description, timeCreated, lifecycleState, 
                                                                           NESTED PATH definedTags COLUMNS ( Creator    VARCHAR2 PATH '$.Administration.Creator'))
                                          ) JTAB
                          where jtab.id is not null
                          and lifecycleState<>'DELETED'                                                                           
                          union all
                          select id, tenancy_ocid, null, 'Tenancy', 'Tenancy Root Level', null, 'ACTIVE', null
                          from ll_tenancies 
                          where id = x.id) loop
        insert into ll_ovw_compartments (TENANCY_ID, ID, COMPARTMENTID, NAME, DESCRIPTION, TIMECREATED, LIFECYCLESTATE, CREATOR) values(z.tid, z.id, z.compartmentId, z.name, z.description, z.timeCreated, z.lifecycleState, z.creator);
        end loop;
                --                 select x.id, 
                  ---               jtab.id, 
                     --            jtab.compartmentId, 
                       --          jtab.name, 
                         --        jtab.description, 
                           --      jtab.timeCreated, 
                 --                jtab.lifecycleState,
                   --              case substr(creator,1,4) when 'ocid' then substr(creator,instr(creator,'/')+1) 
                     --                 when 'orac' then substr(creator,instr(creator,'/')+1) 
                       --               else creator end as creator
                         -- from JSON_TABLE ( v_json_result, '$[*]' COLUMNS (id, compartmentId, name, description, timeCreated, lifecycleState, 
                 --                                                          NESTED PATH definedTags COLUMNS ( Creator    VARCHAR2 PATH '$.Administration.Creator'))
                   --                       ) JTAB
                     --     where jtab.id is not null
                       --   and lifecycleState<>'DELETED'                                                                           
                         -- union all
               --           select id, tenancy_ocid, null, 'Tenancy', 'Tenancy Root Level', null, 'ACTIVE', null
               --           from ll_tenancies 
                 --         where id = x.id;
        -- delete duplicate compartment OCID entries. This can happen if a compartment was moved when the GET request was issued. Both the source and target parent would
        -- return a record. Easiest way is to just delete the duplicate and keep the latest version
        delete ll_ovw_compartments a where rowid <> (select max(rowid)
                                                     from ll_ovw_compartments b
                                                     where a.id = b.id );                          
        -- Update table and build the nested patch for compartments. This Nested Path is easy to identify the location of the compartment if it has been nested 
        update ll_ovw_compartments a set nested_path = ( select nested_path
                                                      from (select id, SYS_CONNECT_BY_PATH(name, '/') AS Nested_Path
                                                            FROM   ll_ovw_compartments b
                                                            where lifecyclestate='ACTIVE'
                                                            START WITH compartmentid IS NULL
                                                            CONNECT BY compartmentid = PRIOR id
                                                            ORDER SIBLINGS BY id) b 
                                                      where a.id = b.id )
                                  where nested_path is null;                          
      end if;
      commit;
    end loop;
    commit;
  end;
--
-- ===================================================================================
--
  procedure search_all_compartments (p_tenancy_id number default null) is
    cursor c_tenancies is select llt.id, llt.tenancy_name, llor.id as region_id, llor.region_name, ll_pkg_admin.oci_endpoint ( 'query', llor.region_key) as host
                          from ll_tenancies llt, ll_oci_regions llor
                          where (llt.id = p_tenancy_id or p_tenancy_id is null)
                          and PEM_KEY_PRIV is not null
                          and PEM_KEY_PUB	is not null
                          and PEM_KEY_RSA is not null;
                          --and llt.active_flg = 'Y';
    v_json_result  clob;
    v_pagination   varchar2(4000);                          
    v_next_page    varchar2(1);
  begin
    ll_pkg_log.log(20,'Initial call, p_tenancy_id: '||nvl(to_char(p_tenancy_id),'null'));
    delete ll_ovw_search_results where tenancy_id in (select id from ll_tenancies where active_flg='N');
    commit;
    for x in c_tenancies loop
      ll_pkg_log.log(30,'Searching for items in tenancy '||x.tenancy_name||', region '||x.region_name);
      v_next_page := 'Y';
      delete ll_ovw_search_results where tenancy_id = x.id and region_id = x.region_id;
      while v_next_page = 'Y' loop     
        ll_pkg_log.log(40,'Requesting next page in search resources');
        ll_pkg_exec.put_post_in_pages (p_tenancy_id => x.id,
                                       p_host       => x.host,
                                       p_type       => 'POST', 
                                       p_method     => '/20180409/resources',
                                       p_body       => '{ "type": "Structured", "query": "query all resources" }',
                                       p_result     => v_json_result,
                                       p_pagination => v_pagination ); 
        for z in (select resourcetype, identifier, compartmentid, timecreated,
                           displayname, lifecyclestate, freeformtags, definedtags, systemtags, searchcontext, identitycontext
                    from JSON_TABLE(v_json_result, '$.items[*]' COLUMNS (
                                     resourcetype     varchar2 PATH '$.resourceType',
                                     identifier       varchar2 PATH '$.identifier',
                                     compartmentid    varchar2 PATH '$.compartmentId',
                                     timecreated      varchar2 PATH '$.timeCreated',
                                     displayname      varchar2 PATH '$.displayName',
                                     lifecyclestate   varchar2 PATH '$.lifecycleState',
                                     freeformtags     format JSON PATH '$.freeformTags',
                                     definedtags      format JSON PATH '$.definedTags',
                                     systemtags       format JSON PATH '$.systemTags',
                                     searchcontext    varchar2 PATH '$.searchContext', 
                                     identitycontext varchar2 PATH '$.identitycontext'))
                    where upper(lifecyclestate) not in ('TERMINATED','DELETED')
                    and resourcetype not in ('Compartment','Key','OrmJob','GoldenGateDeploymentBackup','ContainerImage')) loop
        insert into LL_OVW_SEARCH_RESULTS ( tenancy_id, region_id, resourcetype, identifier, compartmentid, timecreated,
                                            displayname, lifecyclestate, freeformtags, definedtags, systemtags, searchcontext, identitycontext)
                    values (x.id, x.region_id, z.resourcetype, z.identifier, z.compartmentid, z.timecreated,
                           z.displayname, z.lifecyclestate, z.freeformtags, z.definedtags, z.systemtags, z.searchcontext, z.identitycontext);
                    --from JSON_TABLE(v_json_result, '$.items[*]' COLUMNS (
                      --               resourcetype     varchar2 PATH '$.resourceType',
                        --             identifier       varchar2 PATH '$.identifier',
                          --           compartmentid    varchar2 PATH '$.compartmentId',
                            --         timecreated      varchar2 PATH '$.timeCreated',
                              --       displayname      varchar2 PATH '$.displayName',
                                --     lifecyclestate   varchar2 PATH '$.lifecycleState',
                      --               freeformtags     format JSON PATH '$.freeformTags',
                        --             definedtags      format JSON PATH '$.definedTags',
                          --           systemtags       format JSON PATH '$.systemTags',
                            --         searchcontext    varchar2 PATH '$.searchContext', 
                              --       identitycontext varchar2 PATH '$.identitycontext'))
                    --where upper(lifecyclestate) not in ('TERMINATED','DELETED')
                    --and resourcetype not in ('Compartment','Key','OrmJob','GoldenGateDeploymentBackup','ContainerImage'); 
        end loop;
        commit;                                     
        
        if v_pagination is not null then 
          v_next_page := 'Y';
        else
          v_next_page := 'N';
        end if;    
      end loop;
    end loop;   
    -- Delete ContainerRepo and ContainerImages that have already been deleted;
    ll_pkg_log.log(30,'Deleting ContainerRepo and ContainerImages that have already been deleted');
    delete ll_ovw_search_results where ll_pkg_delete.artifact_exists( p_tenancy_id => tenancy_id, p_region_id => region_id, p_containerimage_id => identifier ) = 'N' 
                                   and resourcetype='ContainerImage'
                                   and (p_tenancy_id = tenancy_id or p_tenancy_id is null);
    delete ll_ovw_search_results where ll_pkg_delete.artifact_exists( p_tenancy_id => tenancy_id, p_region_id => region_id, p_containerrepo_id => identifier ) = 'N' 
                                   and resourcetype='ContainerRepo'
                                   and (p_tenancy_id = tenancy_id or p_tenancy_id is null);
    commit;
    ll_pkg_log.log(30,'End of delete for ContainerRepo and ContainerImages');
    ll_pkg_log.log(20,'End of call');
  end;                                         
--
-- ======================================================================================
--
  procedure refresh_all (p_tenancy_id number default null) is
    v_jobname     varchar2(500);
    v_statement   varchar2(4000);
  begin
    begin
      compartments;
    exception
      when OTHERS then null;
    end;
    for x in ( select id from ll_tenancies where PEM_KEY_PRIV is not null and PEM_KEY_PUB	is not null and PEM_KEY_RSA is not null and (id = p_tenancy_id or p_tenancy_id is null)) loop
      v_statement := 'LL_PKG_OVERVIEW.SEARCH_ALL_COMPARTMENTS('||x.id||');';
      v_jobname := dbms_scheduler.generate_job_name('OVW_REFRESH_');
      DBMS_SCHEDULER.create_job (
        job_name        => v_jobname,
        job_type        => 'PLSQL_BLOCK',
        job_action      => 'BEGIN '||v_statement||' END;',
        start_date      => CAST(sysdate AS TIMESTAMP),
        repeat_interval => null,
        enabled         => TRUE );
    end loop;
  end;
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_QR" AS 
 
    --C O N S T A N T S 
 
    --data mode 
    cNumericMode CONSTANT pls_integer := 1;  
    cAlphanumericMode CONSTANT pls_integer := 2;  
    cByteMode CONSTANT pls_integer := 3;  
    cKanjiMode CONSTANT pls_integer := 4;  
 
 
    --V A R I A B L E S 
     
    --debug 
    gpbDebug boolean := false; 
    gpnDebugLevel pls_integer := 1; 
     
    --mode and version 
    gpnMode pls_integer; 
    gpnVersion pls_integer; 
 
    --Error Correction Code Words and Block Information 
    TYPE r_err_cor IS RECORD( 
        total_no_of_data_cw pls_integer, 
        ec_cw_per_block pls_integer, 
        blocks_in_g1 pls_integer, 
        cw_in_g1 pls_integer, 
        blocks_in_g2 pls_integer, 
        cw_in_g2 pls_integer); 
     
    TYPE t_err_cor IS TABLE OF r_err_cor INDEX BY varchar2(10); 
     
    gprErrCorInfo t_err_cor; 
 
    --logs and antilogs 
    TYPE t_log_anti IS TABLE OF pls_integer INDEX BY pls_integer; 
    gprLog t_log_anti; 
    gprAntiLog t_log_anti; 
 
    --matrix 
    TYPE t_row IS TABLE OF varchar2(1); 
    TYPE t_column IS TABLE OF t_row; 
    TYPE t_masking IS TABLE OF t_column INDEX BY pls_integer; 
     
    gprMatrix t_column := t_column(); 
    gprMasking t_masking;  
 
 
 
--DEBUG FUNCS AND PROCS 
PROCEDURE p_debug( 
    p_text varchar2, 
    p_level pls_integer default 1, 
    p_new_line boolean default true) IS 
BEGIN 
    if gpbDebug and p_level <= gpnDebugLevel then 
        if p_new_line then 
            DBMS_OUTPUT.put_line(p_text); 
        else 
            DBMS_OUTPUT.put(p_text); 
        end if; 
    end if; 
END; 
 
 
PROCEDURE p_dbms_output_matrix( 
    p_matrix t_column, 
    p_level pls_integer default 1) IS 
     
    lcQR varchar2(200); 
     
BEGIN 
    FOR t IN 1 .. p_matrix.count LOOP 
        lcQR := null; 
        FOR p IN 1 .. p_matrix.count LOOP 
            lcQR := lcQR || nvl(p_matrix(t)(p), 'X'); 
        END LOOP; 
        p_debug(lcQR, p_level); 
    END LOOP; 
END; 
 
 
--UTILITY FUNCS AND PROCS 
FUNCTION bitor(p1 number, p2 number) RETURN number IS 
BEGIN 
  RETURN p1 - bitand(p1, p2) + p2; 
END; 
 
FUNCTION bitxor(p1 number, p2 number) RETURN number IS 
BEGIN 
  RETURN bitor(p1, p2) - bitand(p1, p2); 
END; 
 
FUNCTION bin2dec(binval varchar2) RETURN pls_integer IS 
  result            NUMBER := 0; 
BEGIN 
  FOR t IN 1 .. length(binval) LOOP 
     result := (result * 2) + to_number(substr(binval, t, 1)); 
  END LOOP; 
   
  RETURN result; 
END bin2dec; 
 
FUNCTION f_integer_2_binary(p_integer pls_integer) RETURN varchar2 IS 
    lcBinary varchar2(100); 
BEGIN 
    SELECT LISTAGG(SIGN(BITAND(p_integer, POWER(2, LEVEL-1))),'') WITHIN GROUP(ORDER BY LEVEL DESC) 
    INTO lcBinary 
    FROM dual 
    CONNECT BY POWER(2, LEVEL-1) <= p_integer; 
 
    RETURN lcBinary; 
END; 
 
 
 
 
--INIT FUNCS AND PROCS 
PROCEDURE p_fill_log_antilog IS 
    lnVal pls_integer; 
    lnPrevVal pls_integer; 
BEGIN 
    FOR t IN 0 .. 255 LOOP 
        if t = 0 then 
            lnVal := 1; 
        else 
            lnVal := lnPrevVal * 2; 
            if lnVal > 255 then 
                lnVal := bitxor(lnVal, 285); 
            end if; 
        end if; 
         
        gprLog(t) := lnVal; 
        gprAntiLog(lnVal) := t; 
         
        lnPrevVal := lnVal; 
         
        p_debug('Log for ' || t || ': ' || gprLog(t), 4); 
         
    END LOOP; 
END; 
 
FUNCTION f_matrix_size RETURN pls_integer IS 
BEGIN 
    --minimal matrix size is 21x21 module; every next version is 4 modules larger 
    RETURN ((gpnVersion - 1) * 4) + 21; 
END; 
 
 
 
PROCEDURE p_init_matrix IS 
 
    TYPE t_col IS TABLE OF pls_integer; 
    TYPE t_alignment_pos IS TABLE OF t_col; 
    lrAlignPos t_alignment_pos := t_alignment_pos(); 
     
    lcModule varchar2(1); 
 
    PROCEDURE p_add_finder(p_column pls_integer, p_row pls_integer) IS 
    BEGIN 
        --outer black square  
        FOR t IN 0 .. 6 LOOP 
            gprMatrix(p_column + t)(p_row) := '3'; 
            gprMatrix(p_column + t)(p_row + 6) := '3'; 
            gprMatrix(p_column)(p_row + t) := '3'; 
            gprMatrix(p_column + 6)(p_row + t) := '3'; 
        END LOOP; 
 
        --inner white square 
        FOR t IN 0 .. 4 LOOP 
            gprMatrix(p_column + 1 + t)(p_row + 1) := '2'; 
            gprMatrix(p_column + 1 + t)(p_row + 1 + 4) := '2'; 
            gprMatrix(p_column + 1)(p_row + 1 + t) := '2'; 
            gprMatrix(p_column + 1 + 4)(p_row + 1 + t) := '2'; 
        END LOOP; 
 
        --inner black square 
        FOR t IN 0 .. 2 LOOP 
            FOR p IN 0 .. 2 LOOP 
                gprMatrix(p_column + 2 + t)(p_row + 2 + p) := '3'; 
            END LOOP; 
        END LOOP; 
 
    END; 
 
    PROCEDURE p_init_alignment IS 
    BEGIN 
        lrAlignPos.delete; 
        lrAlignPos.extend(40); 
         
        lrAlignPos(1) := t_col(0); 
        lrAlignPos(2) := t_col(6, 18); 
        lrAlignPos(3) := t_col(6, 22); 
        lrAlignPos(4) := t_col(6, 26); 
        lrAlignPos(5) := t_col(6, 30); 
        lrAlignPos(6) := t_col(6, 34); 
        lrAlignPos(7) := t_col(6, 22, 38); 
        lrAlignPos(8) := t_col(6, 24, 42); 
        lrAlignPos(9) := t_col(6, 26, 46); 
        lrAlignPos(10) := t_col(6, 28, 50); 
        lrAlignPos(11) := t_col(6, 30, 54); 
        lrAlignPos(12) := t_col(6, 32, 58); 
        lrAlignPos(13) := t_col(6, 34, 62); 
        lrAlignPos(14) := t_col(6, 26, 46, 66); 
        lrAlignPos(15) := t_col(6, 26, 48, 70); 
        lrAlignPos(16) := t_col(6, 26, 50, 74); 
        lrAlignPos(17) := t_col(6, 30, 54, 78); 
        lrAlignPos(18) := t_col(6, 30, 56, 82); 
        lrAlignPos(19) := t_col(6, 30, 58, 86); 
        lrAlignPos(20) := t_col(6, 34, 62, 90); 
        lrAlignPos(21) := t_col(6, 28, 50, 72, 94); 
        lrAlignPos(22) := t_col(6, 26, 50, 74, 98); 
        lrAlignPos(23) := t_col(6, 30, 54, 78, 102); 
        lrAlignPos(24) := t_col(6, 28, 54, 80, 106); 
        lrAlignPos(25) := t_col(6, 32, 58, 84, 110); 
        lrAlignPos(26) := t_col(6, 30, 58, 86, 114); 
        lrAlignPos(27) := t_col(6, 34, 62, 90, 118); 
        lrAlignPos(28) := t_col(6, 26, 50, 74, 98, 122 ); 
        lrAlignPos(29) := t_col(6, 30, 54, 78, 102, 126); 
        lrAlignPos(30) := t_col(6, 26, 52, 78, 104, 130 ); 
        lrAlignPos(31) := t_col(6, 30, 56, 82, 108, 134 ); 
        lrAlignPos(32) := t_col(6, 34, 60, 86, 112, 138 ); 
        lrAlignPos(33) := t_col(6, 30, 58, 86, 114, 142 ); 
        lrAlignPos(34) := t_col(6, 34, 62, 90, 118, 146 ); 
        lrAlignPos(35) := t_col(6, 30, 54, 78, 102, 126, 150); 
        lrAlignPos(36) := t_col(6, 24, 50, 76, 102, 128, 154); 
        lrAlignPos(37) := t_col(6, 28, 54, 80, 106, 132, 158); 
        lrAlignPos(38) := t_col(6, 32, 58, 84, 110, 136, 162); 
        lrAlignPos(39) := t_col(6, 26, 54, 82, 110, 138, 166); 
        lrAlignPos(40) := t_col(6, 30, 58, 86, 114, 142, 170); 
         
    END; 
 
    PROCEDURE p_add_alignment(p_column pls_integer, p_row pls_integer) IS 
    BEGIN 
        --check if coordinates are OK and alignment is on matrix 
        if p_column - 2 < 1 or p_column + 2 > f_matrix_size or p_row - 2 < 1 or p_row + 2 > f_matrix_size then 
            p_debug('Alignment on ' || p_column || ', ' || p_row || ' is outside of matrix! Skipping...', 2); 
            RETURN; 
        end if; 
     
        --first check if overlap with existing finders; if overlaps then do not draw finder 
        FOR t IN p_column - 2 .. p_column + 2 LOOP 
            FOR p IN p_row - 2 .. p_row + 2 LOOP 
                if gprMatrix(p)(t) is not null then 
                    p_debug('Alignment on ' || p_column || ', ' || p_row || ' overlaps with finder! Skipping...', 2); 
                    RETURN; 
                end if; 
            END LOOP; 
        END LOOP; 
 
        --draw alignment 
        --outer black square  
        FOR t IN 0 .. 4 LOOP 
            gprMatrix(p_row - 2)(p_column - 2 + t) := '3'; 
            gprMatrix(p_row - 2 + t)(p_column - 2) := '3'; 
            gprMatrix(p_row + 2)(p_column - 2 + t) := '3'; 
            gprMatrix(p_row - 2 + t)(p_column + 2) := '3'; 
        END LOOP; 
 
        --inner white square and center module 
        FOR t IN 0 .. 2 LOOP 
            FOR p IN 0 .. 2 LOOP 
                gprMatrix(p_row - 1 + t)(p_column - 1 + p) := '2'; 
            END LOOP; 
        END LOOP; 
        gprMatrix(p_row)(p_column) := '3'; 
         
         
    END; 
 
BEGIN 
    p_debug('Matrix size: ' || f_matrix_size || 'x' || f_matrix_size || ' modules', 2); 
 
    --collection initialization 
    gprMatrix.delete; 
     
    gprMatrix.extend(f_matrix_size); 
    FOR t IN 1 .. f_matrix_size LOOP 
        gprMatrix(t) := t_row(); 
        gprMatrix(t).extend(f_matrix_size); 
    END LOOP; 
     
     
    --add Finder Patterns (3x) 
    p_add_finder(1, 1); 
    p_add_finder(f_matrix_size - 6, 1); 
    p_add_finder(1, f_matrix_size - 6); 
 
 
    --add Separators 
    FOR t IN 0 .. 7 LOOP 
        --upper left 
        gprMatrix(1 + t)(1 + 7) := '2'; 
        gprMatrix(1 + 7)(1 + t) := '2'; 
         
        --lower left 
        gprMatrix(f_matrix_size - 7 + t)(1 + 7) := '2'; 
        gprMatrix(f_matrix_size - 7)(1 + t) := '2'; 
         
        --upper right 
        gprMatrix(1 + t)(f_matrix_size - 7) := '2'; 
        gprMatrix(1 + 7)(f_matrix_size - 7 + t) := '2'; 
    END LOOP; 
     
 
    --add Alignment Patterns (for versions larger then 1) 
    p_init_alignment; 
     
    if gpnVersion > 1 then 
        FOR t IN 1 .. lrAlignPos(gpnVersion).count LOOP 
            FOR p IN 1 .. lrAlignPos(gpnVersion).count LOOP 
                p_add_alignment(lrAlignPos(gpnVersion)(t) + 1, lrAlignPos(gpnVersion)(p) + 1); 
            END LOOP; 
        END LOOP; 
    end if; 
     
     
    --Timing Patterns 
    FOR t IN 9 .. f_matrix_size - 8 LOOP 
        if t mod 2 <> 0 then 
            lcModule := '3';  --first module is black, then white, then black... 
        else 
            lcModule := '2'; 
        end if; 
 
        gprMatrix(7)(t) := lcModule; 
        gprMatrix(t)(7) := lcModule; 
    END LOOP; 
     
     
    --Dark Module 
    gprMatrix(f_matrix_size - 7)(9) := '3'; 
     
    --Reserved Areas (Format Information Area, Version Information Area) 
    --will be filled with actual values later 
     
    --Format Information Area, placeholder values are dots 
    FOR t IN 1 .. 9 LOOP 
        if gprMatrix(9)(t) is null then  
            gprMatrix(9)(t) := '.'; 
        end if; 
 
        if gprMatrix(t)(9) is null then  
            gprMatrix(t)(9) := '.'; 
        end if; 
    END LOOP; 
 
    FOR t IN 1 .. 8 LOOP 
        if gprMatrix(f_matrix_size - t + 1)(9) is null then  
            gprMatrix(f_matrix_size - t + 1)(9) := '.'; 
        end if; 
 
        if gprMatrix(9)(f_matrix_size - t + 1) is null then  
            gprMatrix(9)(f_matrix_size - t + 1) := '.'; 
        end if; 
    END LOOP; 
 
    --Version Information Area, placeholder values are * 
    --it aplies only to versions 7 and larger 
    if gpnVersion >= 7 then 
        FOR t IN 1 .. 6 LOOP 
            gprMatrix(f_matrix_size - 8)(t) := '*'; 
            gprMatrix(f_matrix_size - 9)(t) := '*'; 
            gprMatrix(f_matrix_size - 10)(t) := '*'; 
 
            gprMatrix(t)(f_matrix_size - 8) := '*'; 
            gprMatrix(t)(f_matrix_size - 9) := '*'; 
            gprMatrix(t)(f_matrix_size - 10) := '*'; 
             
        END LOOP; 
    end if; 
END; 
 
 
