    lrValues(12) := '883,535,367,226,691,419,287,177,489,296,203,125,374,227,155,96'; 
    lrValues(13) := '1022,619,425,262,796,483,331,204,580,352,241,149,427,259,177,109'; 
    lrValues(14) := '1101,667,458,282,871,528,362,223,621,376,258,159,468,283,194,120'; 
    lrValues(15) := '1250,758,520,320,991,600,412,254,703,426,292,180,530,321,220,136'; 
    lrValues(16) := '1408,854,586,361,1082,656,450,277,775,470,322,198,602,365,250,154'; 
    lrValues(17) := '1548,938,644,397,1212,734,504,310,876,531,364,224,674,408,280,173'; 
    lrValues(18) := '1725,1046,718,442,1346,816,560,345,948,574,394,243,746,452,310,191'; 
    lrValues(19) := '1903,1153,792,488,1500,909,624,384,1063,644,442,272,813,493,338,208'; 
    lrValues(20) := '2061,1249,858,528,1600,970,666,410,1159,702,482,297,919,557,382,235'; 
    lrValues(21) := '2232,1352,929,572,1708,1035,711,438,1224,742,509,314,969,587,403,248'; 
    lrValues(22) := '2409,1460,1003,618,1872,1134,779,480,1358,823,565,348,1056,640,439,270'; 
    lrValues(23) := '2620,1588,1091,672,2059,1248,857,528,1468,890,611,376,1108,672,461,284'; 
    lrValues(24) := '2812,1704,1171,721,2188,1326,911,561,1588,963,661,407,1228,744,511,315'; 
    lrValues(25) := '3057,1853,1273,784,2395,1451,997,614,1718,1041,715,440,1286,779,535,330'; 
    lrValues(26) := '3283,1990,1367,842,2544,1542,1059,652,1804,1094,751,462,1425,864,593,365'; 
    lrValues(27) := '3517,2132,1465,902,2701,1637,1125,692,1933,1172,805,496,1501,910,625,385'; 
    lrValues(28) := '3669,2223,1528,940,2857,1732,1190,732,2085,1263,868,534,1581,958,658,405'; 
    lrValues(29) := '3909,2369,1628,1002,3035,1839,1264,778,2181,1322,908,559,1677,1016,698,430'; 
    lrValues(30) := '4158,2520,1732,1066,3289,1994,1370,843,2358,1429,982,604,1782,1080,742,457'; 
    lrValues(31) := '4417,2677,1840,1132,3486,2113,1452,894,2473,1499,1030,634,1897,1150,790,486'; 
    lrValues(32) := '4686,2840,1952,1201,3693,2238,1538,947,2670,1618,1112,684,2022,1226,842,518'; 
    lrValues(33) := '4965,3009,2068,1273,3909,2369,1628,1002,2805,1700,1168,719,2157,1307,898,553'; 
    lrValues(34) := '5253,3183,2188,1347,4134,2506,1722,1060,2949,1787,1228,756,2301,1394,958,590'; 
    lrValues(35) := '5529,3351,2303,1417,4343,2632,1809,1113,3081,1867,1283,790,2361,1431,983,605'; 
    lrValues(36) := '5836,3537,2431,1496,4588,2780,1911,1176,3244,1966,1351,832,2524,1530,1051,647'; 
    lrValues(37) := '6153,3729,2563,1577,4775,2894,1989,1224,3417,2071,1423,876,2625,1591,1093,673'; 
    lrValues(38) := '6479,3927,2699,1661,5039,3054,2099,1292,3599,2181,1499,923,2735,1658,1139,701'; 
    lrValues(39) := '6743,4087,2809,1729,5313,3220,2213,1362,3791,2298,1579,972,2927,1774,1219,750'; 
    lrValues(40) := '7089,4296,2953,1817,5596,3391,2331,1435,3993,2420,1663,1024,3057,1852,1273,784'; 
 
 
    --a version depending of error correction method, mode and data length 
    lnPosition := (f_err_cor_2_number(p_error_correction) - 1) * 4 + gpnMode; 
     
    p_debug('length: ' || lnLength, 2); 
 
    FOR t IN 1 .. 40 LOOP 
        p_debug(lrValues(t), 4); 
         
        SELECT to_number(column_value) a 
        BULK COLLECT INTO lrData 
        FROM XMLTABLE(lrValues(t)); 
 
        p_debug('Value on position ' || lnPosition || ': ' || lrData(lnPosition), 2); 
         
        if lrData(lnPosition) >= lnLength then 
            lnVersion := t; 
            EXIT; 
        end if; 
         
    END LOOP; 
     
    --if version can not be determined then throw error 
    if lnVersion = 0 then 
        RAISE_APPLICATION_ERROR(-20000, 'Data length is too big to be encoded in one QR code.');     
    end if; 
 
    --debug  
    p_debug('version: ' || lnVersion); 
 
    RETURN lnVersion; 
     
END f_get_version; 
 
 
FUNCTION f_encode_data( 
    p_data varchar2, 
    p_error_correction varchar2) RETURN varchar2 IS 
     
    lcData varchar2(32000); 
    lnCounter pls_integer := 1; 
    lcSub varchar2(3); 
    lnReqNumOfBits pls_integer; 
    lcChar varchar2(1 char); 
 
    --function returns value of character in alphanumeric mode 
    FUNCTION f_get_code(p_char varchar2) RETURN pls_integer IS 
        lnCode pls_integer; 
    BEGIN 
        --0 - 9 
        if instr('0123456789', p_char) > 0 then 
            lnCode := to_number(p_char); 
        elsif instr('ABCDEFGHIJKLMNOPQRSTUVWXYZ', p_char) > 0 then 
            lnCode := ascii(p_char) - 55; 
        elsif p_char = ' ' then  
            lnCode := 36; 
        elsif p_char = '$' then  
            lnCode := 37; 
        elsif p_char = '%' then  
            lnCode := 38; 
        elsif p_char = '*' then  
            lnCode := 39; 
        elsif p_char = '+' then  
            lnCode := 40; 
        elsif p_char = '-' then  
            lnCode := 41; 
        elsif p_char = '.' then  
            lnCode := 42; 
        elsif p_char = '/' then  
            lnCode := 43; 
        elsif p_char = ':' then  
            lnCode := 44; 
        end if;  
         
        RETURN lnCode; 
    END f_get_code; 
 
     
BEGIN 
    --encoded data regardless of mode always start with mode indicator and character count indicator 
    lcData := f_mode_indicator || f_char_count_indicator(p_data); 
 
    --data encoding - different for different modes  
    if gpnMode = cNumericMode then 
        LOOP 
            lcSub := ltrim(substr(p_data, lnCounter, 3), '0'); 
             
            p_debug(lcSub, 2); 
             
            if length(lcSub) = 3 then 
                lcData := lcData || lpad(f_integer_2_binary( to_number(lcSub) ), 10, '0'); 
            elsif length(lcSub) = 2 then 
                lcData := lcData || lpad(f_integer_2_binary( to_number(lcSub) ), 7, '0'); 
            elsif length(lcSub) = 1 then 
                lcData := lcData || lpad(f_integer_2_binary( to_number(lcSub) ), 4, '0'); 
            end if; 
             
            EXIT WHEN lnCounter >= length(p_data);  
             
            lnCounter := lnCounter + 3; 
        END LOOP; 
         
    elsif gpnMode = cAlphanumericMode then 
         
        LOOP 
            lcSub := substr(p_data, lnCounter, 2); 
             
            p_debug(lcSub, 2); 
             
            if length(lcSub) = 2 then 
                lcData := lcData || lpad(f_integer_2_binary( f_get_code(substr(lcSub, 1, 1)) * 45 + f_get_code(substr(lcSub, 2, 1)) ), 11, '0'); 
            elsif length(lcSub) = 1 then 
                lcData := lcData || lpad(f_integer_2_binary( f_get_code(lcSub) ), 6, '0'); 
            end if; 
 
            EXIT WHEN lnCounter >= length(p_data);  
             
            lnCounter := lnCounter + 2; 
        END LOOP; 
         
    elsif gpnMode = cByteMode then 
        FOR t IN 1 .. length(p_data) LOOP 
            lcChar := substr(p_data, t, 1); 
            lcData := lcData || lpad(f_integer_2_binary( ascii(lcChar) ), 8 * lengthb(lcChar), '0'); 
             
        END LOOP; 
         
    elsif gpnMode = cKanjiMode then 
        --TODO for Kanji mode 
        null; 
    end if; 
 
    p_debug('Data without right padding (number of bits ' || length(lcData) || '): ' || lcData, 2); 
 
    --terminator zeros 
    lnReqNumOfBits := gprErrCorInfo(gpnVersion || '-' || p_error_correction).total_no_of_data_cw * 8; 
    p_debug('Required number of bits: ' || lnReqNumOfBits, 2); 
     
    if lnReqNumOfBits - lengthb(p_data) >= 4 then 
        lcData := lcData || '0000'; 
        p_debug('Terminator zeros: 0000', 2); 
    else 
        lcData := rpad(lcData, lnReqNumOfBits - lengthb(p_data), '0'); 
        p_debug('Terminator zeros: ' || rpad(null, lnReqNumOfBits - lengthb(p_data), '0'), 2); 
    end if; 
 
    --additional right padding with 0 to reach a string length multiple of 8 
     LOOP 
        EXIT WHEN length(lcData) mod 8 = 0; 
        lcData := lcData || '0'; 
        p_debug('Additional right padding zeros: 0', 2); 
    END LOOP; 
 
    --final filling of data with 11101100 and 00010001 alternatively until full length is reached 
     LOOP 
        EXIT WHEN length(lcData) = lnReqNumOfBits; 
        lcData := lcData || '11101100'; 
        p_debug('Additional padding with: 11101100', 2); 
        EXIT WHEN length(lcData) = lnReqNumOfBits; 
        lcData := lcData || '00010001'; 
        p_debug('Additional padding with: 00010001', 2); 
    END LOOP; 
 
 
    --debug 
    p_debug('Data (number of bits ' || length(lcData) || '): ' || lcData); 
     
    RETURN lcData; 
     
END f_encode_data; 
 
 
 
FUNCTION f_final_data_with_ec( 
    p_encoded_data varchar2, 
    p_error_correction varchar2) RETURN varchar2 IS 
     
    TYPE t_cw IS TABLE OF pls_integer; 
    TYPE r_block IS RECORD (cw t_cw); 
    TYPE t_block IS TABLE OF r_block INDEX BY varchar2(10); 
     
    lrBlock t_block; 
     
    lcVersionEC varchar2(10); 
    lcBlock varchar2(10); 
    lnCounter pls_integer := 1; 
    lcCW varchar2(8); 
    lnCW pls_integer; 
    lnGroups pls_integer; 
    lcDebug varchar2(10000); 
    lnReminderBits pls_integer := 0; 
     
    lcResult varchar2(32000); 
     
    FUNCTION f_blocks_in_group(p_group pls_integer) RETURN pls_integer IS 
    BEGIN 
        RETURN 
            CASE  
                WHEN p_group = 1 THEN gprErrCorInfo(lcVersionEC).blocks_in_g1  
                ELSE nvl(gprErrCorInfo(lcVersionEC).blocks_in_g2, 0)  
            END; 
    END; 
 
    FUNCTION f_cw_in_group(p_group pls_integer) RETURN pls_integer IS 
    BEGIN 
        RETURN 
            CASE  
                WHEN p_group = 1 THEN gprErrCorInfo(lcVersionEC).cw_in_g1  
                ELSE nvl(gprErrCorInfo(lcVersionEC).cw_in_g2, 0) 
            END; 
    END; 
 
    PROCEDURE p_add_cw_to_block(p_gb varchar2, p_cw pls_integer) IS 
    BEGIN 
        lrBlock(p_gb).cw.extend; 
        lrBlock(p_gb).cw(lrBlock(p_gb).cw.count) := p_cw; 
    END; 
     
    PROCEDURE p_debug_collection( 
        p_description varchar2, 
        p_collection t_cw, 
        p_level pls_integer default 1) IS 
         
    BEGIN 
        lcDebug := p_description; 
        FOR t IN p_collection.first .. p_collection.last LOOP  
            lcDebug := lcDebug || p_collection(t) || ', '; 
        END LOOP; 
        p_debug(rtrim(lcDebug, ', '), p_level); 
    END; 
     
    FUNCTION f_poly_divide(p_mess_poly t_cw, p_gen_poly t_cw) RETURN t_cw IS 
        lrEC t_cw := t_cw(); 
        lrDivider t_cw := t_cw(); 
        lrResult t_cw := t_cw(); 
         
        lnAnti pls_integer; 
    BEGIN 
        --copy message polynomial to lrEC 
        lrEC := lrEc MULTISET UNION ALL p_mess_poly; 
         
        --To make sure that the exponent of the lead term doesn't become too small during the division 
        --multiply the message polynomial by xn where n is the number of error correction codewords that are needed 
        --so, we extend the collection and fill those elements with 0 
        lrEC.extend(p_gen_poly.count - 1); 
        FOR t IN REVERSE lrEC.first .. lrEC.last LOOP 
            EXIT WHEN lrEC(t) is not null; 
            lrEC(t) := 0; 
        END LOOP; 
     
        FOR t IN 1 .. p_mess_poly.count LOOP 
            p_debug('Step ' || t || ':', 2); 
             
            if lrEC(t) > 0 then 
                --Lead Term of the Message Polynomial (in first cycle) or result from previous cycle  
                --antilog is needed for multipilcation with generator polynomial (next step) 
                lnAnti := gprAntiLog( lrEC(t) ); 
                p_debug('Lead Term of the Message Polynomial: ' || lrEC(t) || ' (antiLog ' || lnAnti || ')', 2); 
                 
                --copy generator polynomial to lrDivider 
                lrDivider.delete; 
                lrDivider := lrDivider MULTISET UNION ALL p_gen_poly; 
                 
                --Multiply the Generator Polynomial by the Lead Term of the Message Polynomial  
                --everything is happening in antilog - generator polynomial is already in antilog 
                --basicly we add two antilogs 
                FOR p IN 1 .. lrDivider.count LOOP 
                    lrDivider(p) := lrDivider(p) + lnAnti; 
                    if lrDivider(p) >= 255 then  
                        lrDivider(p) := lrDivider(p) - 255; 
                    end if; 
                END LOOP; 
                 
                p_debug_collection( 
                    'Generator polynomial multiplied with Lead Term antiLog (in antiLog): ', 
                    lrDivider, 
                    2); 
                 
                --XOR the result with the message polynomial (first cycle) or result from previous cycle 
                --Message or result from previous cycle is already in log, so we convert generated polynomial from previous step into log 
                --leading terms, which are already 0 are discarded (index is "p + t - 1") 
                FOR p IN 1 .. lrDivider.count LOOP 
                    lrEC(p + t - 1) := bitxor( lrEC(p + t - 1), gprLog(lrDivider(p)) ); 
                END LOOP; 
 
                p_debug_collection( 
                    'XOR the result with the message polynomial or result from previous cycle (in Log): ', 
                    lrEC, 
                    2); 
            else  
                p_debug('skipping this step and discarding next lead term 0...', 2); 
            end if; 
 
        END LOOP; 
     
        --last remaining elements are error correction codewords 
        FOR t IN lrEC.count - (p_gen_poly.count - 2) .. lrEC.count LOOP 
            lrResult.extend; 
            lrResult(lrResult.count) := lrEC(t); 
        END LOOP; 
 
        RETURN lrResult; 
    END; 
     
     
BEGIN 
    --Version and EC Level 
    lcVersionEC := gpnVersion || '-' || p_error_correction; 
    p_debug('Version and EC Level: ' || lcVersionEC, 2); 
 
    --generator polynomial - init for all 13 possible options 
    --generator polynomial has the same structure as message polynomial (block) and so the same type is used 
    lrBlock('7').cw := t_cw(0, 87, 229, 146, 149, 238, 102, 21); 
    lrBlock('10').cw := t_cw(0, 251, 67, 46, 61, 118, 70, 64, 94, 32, 45); 
    lrBlock('13').cw := t_cw(0, 74, 152, 176, 100, 86, 100, 106, 104, 130, 218, 206, 140, 78); 
    lrBlock('15').cw := t_cw(0, 8, 183, 61, 91, 202, 37, 51, 58, 58, 237, 140, 124, 5, 99, 105); 
    lrBlock('16').cw := t_cw(0, 120, 104, 107, 109, 102, 161, 76, 3, 91, 191, 147, 169, 182, 194, 225, 120); 
    lrBlock('17').cw := t_cw(0, 43, 139, 206, 78, 43, 239, 123, 206, 214, 147, 24, 99, 150, 39, 243, 163, 136); 
    lrBlock('18').cw := t_cw(0, 215, 234, 158, 94, 184, 97, 118, 170, 79, 187, 152, 148, 252, 179, 5, 98, 96, 153); 
    lrBlock('20').cw := t_cw(0, 17, 60, 79, 50, 61, 163, 26, 187, 202, 180, 221, 225, 83, 239, 156, 164, 212, 212, 188, 190); 
    lrBlock('22').cw := t_cw(0, 210, 171, 247, 242, 93, 230, 14, 109, 221, 53, 200, 74, 8, 172, 98, 80, 219, 134, 160, 105, 165, 231); 
    lrBlock('24').cw := t_cw(0, 229, 121, 135, 48, 211, 117, 251, 126, 159, 180, 169, 152, 192, 226, 228, 218, 111, 0, 117, 232, 87, 96, 227, 21); 
    lrBlock('26').cw := t_cw(0, 173, 125, 158, 2, 103, 182, 118, 17, 145, 201, 111, 28, 165, 53, 161, 21, 245, 142, 13, 102, 48, 227, 153, 145, 218, 70); 
    lrBlock('28').cw := t_cw(0, 168, 223, 200, 104, 224, 234, 108, 180, 110, 190, 195, 147, 205, 27, 232, 201, 21, 43, 245, 87, 42, 195, 212, 119, 242, 37, 9, 123); 
    lrBlock('30').cw := t_cw(0, 41, 173, 145, 152, 216, 31, 179, 182, 50, 48, 110, 86, 239, 96, 222, 125, 42, 173, 226, 193, 224, 130, 156, 37, 251, 216, 238, 40, 192, 180); 
 
    --debug - Generator Polynomial used 
    p_debug_collection( 
        'Generator Polynomial (' || gprErrCorInfo(lcVersionEC).ec_cw_per_block || '): ', 
        lrBlock(gprErrCorInfo(lcVersionEC).ec_cw_per_block).cw, 
        2); 
     
    --how many groups 
    lnGroups := (CASE WHEN gprErrCorInfo(lcVersionEC).blocks_in_g2 is null THEN 1 ELSE 2 END); 
     
    --debug - number of groups and blocks in each group, number of codewords for each block in group 
    p_debug('Number of groups: ' || lnGroups, 2); 
    FOR gr IN 1 .. lnGroups LOOP 
        p_debug('Group ' || gr || ' - number of blocks in group: ' || f_blocks_in_group(gr), 2); 
        p_debug('Group ' || gr || ' - number of codewords in each block: ' || f_cw_in_group(gr), 2); 
    END LOOP; 
     
    --prepare message polynomial for each group and block (G1B1, G1B2 ... G2B1, G2B2...) 
    FOR gr IN 1 .. lnGroups LOOP 
        FOR blk IN 1 .. f_blocks_in_group(gr) LOOP 
            --init block 
            lcBlock := 'G' || gr || 'B' || blk; 
            lrBlock(lcBlock).cw := t_cw(); 
             
            p_debug('Group ' || gr || ', block ' || blk || ' - message polynomial:', 2);  
             
            --fill block with data codewords (codewords are converted to decimal) 
            FOR cw IN 1 .. f_cw_in_group(gr) LOOP 
                lcCW := substr(p_encoded_data, lnCounter, 8); 
                lnCW := bin2dec(lcCW); 
                 
                p_add_cw_to_block(lcBlock, lnCW); 
                p_debug('Codeword ' || cw || ': ' || lcCW || ' (' || lnCW || ')', 2); 
                 
                lnCounter := lnCounter + 8; 
            END LOOP; 
             
        END LOOP; 
    END LOOP; 
 
 
    --calculate error correction data for each group and block (G1B1EC, G1B2EC... G2B1EC, G2B2EC...) 
    FOR gr IN 1 .. lnGroups LOOP 
        FOR blk IN 1 .. f_blocks_in_group(gr) LOOP 
            lrBlock('G' || gr || 'B' || blk || 'EC').cw := f_poly_divide( 
                lrBlock('G' || gr || 'B' || blk).cw, --message polynomial 
                lrBlock(gprErrCorInfo(lcVersionEC).ec_cw_per_block).cw  --generator polynomial 
                ); 
             
            p_debug_collection( 
                'Final error correction codewords for group ' || gr || ' and block ' || blk || ': ', 
                lrBlock('G' || gr || 'B' || blk || 'EC').cw, 
                2); 
             
        END LOOP; 
    END LOOP; 
     
     
    --structure final message (interleaving) - data codewords 
    lcDebug := 'Interleaved data codewords: '; 
    FOR cnt IN 1 .. greatest( f_cw_in_group(1), f_cw_in_group(2) ) LOOP 
        FOR gr IN 1 .. lnGroups LOOP 
            FOR blk IN 1 .. f_blocks_in_group(gr) LOOP 
                 
                if lrBlock('G' || gr || 'B' || blk).cw.count >= cnt then 
                    lcResult := lcResult || lpad(f_integer_2_binary( lrBlock('G' || gr || 'B' || blk).cw(cnt) ), 8, '0'); 
                    lcDebug := lcDebug || lrBlock('G' || gr || 'B' || blk).cw(cnt) || ', '; 
                end if; 
             
            END LOOP; 
        END LOOP; 
    END LOOP; 
    p_debug(rtrim(lcDebug, ', '), 2); 
 
 
    --structure final message (interleaving) - error correction codewords 
    lcDebug := 'Interleaved error correction codewords: '; 
    FOR cnt IN 1 .. gprErrCorInfo(lcVersionEC).ec_cw_per_block LOOP 
        FOR gr IN 1 .. lnGroups LOOP 
            FOR blk IN 1 .. f_blocks_in_group(gr) LOOP 
                lcResult := lcResult || lpad(f_integer_2_binary( lrBlock('G' || gr || 'B' || blk || 'EC').cw(cnt) ), 8, '0'); 
                    lcDebug := lcDebug || lrBlock('G' || gr || 'B' || blk || 'EC').cw(cnt) || ', '; 
            END LOOP; 
        END LOOP; 
    END LOOP; 
    p_debug(rtrim(lcDebug, ', '), 2); 
     
     
    --Add Remainder Bits for some QR versions, if necessary 
    lnReminderBits :=  
        CASE 
            WHEN gpnVersion between 2 and 6 THEN 7 
            WHEN gpnVersion between 21 and 27 THEN 4 
            WHEN gpnVersion between 14 and 20 or gpnVersion between 28 and 34 THEN 3 
            ELSE 0 
            END; 
    p_debug('Reminder bits: ' || lnReminderBits, 2); 
     
    if lnReminderBits > 0 then 
        lcResult := rpad(lcResult, length(lcResult) + lnReminderBits, '0'); 
    end if; 
 
    p_debug('Final message (length ' || length(lcResult) || '): ' || lcResult); 
 
 
    RETURN lcResult; 
END f_final_data_with_ec; 
 
 
 
PROCEDURE p_place_fm_in_matrix(lcData varchar2) IS 
     
    lnColumn pls_integer; 
    lnRow pls_integer; 
    lnDirection pls_integer; 
     
    lnCounter pls_integer; 
     
 
    PROCEDURE p_set_module(p_column pls_integer, p_row pls_integer) IS 
    BEGIN 
        if gprMatrix(p_row)(p_column) is null then 
            gprMatrix(p_row)(p_column) := substr(lcData, lnCounter, 1); 
            lnCounter := lnCounter + 1; 
        end if; 
    END; 
     
BEGIN 
    --staring values 
    lnColumn := f_matrix_size; 
     
    lnRow := f_matrix_size; 
    lnDirection := -1; 
     
    lnCounter := 1; 
 
    LOOP 
        EXIT WHEN lnColumn < 1; 
     
        --fill data in column 
        FOR t IN 1 .. f_matrix_size LOOP 
            p_set_module(lnColumn, lnRow); 
            p_set_module(lnColumn - 1, lnRow); 
             
            lnRow := lnRow + lnDirection; 
        END LOOP; 
 
        --change of direction 
        lnDirection := lnDirection * -1; 
         
        --first position for next column (because the last iteration of loop breached through matrix margine) 
        lnRow := lnRow + lnDirection;  
         
        --next column 
        lnColumn := lnColumn - 2; 
        --exception is vertical time pattern - if pattern is reached then column shifts to the first column on the left  
        if lnColumn = 7 then  
            lnColumn := 6; 
        end if; 
 
    END LOOP; 
 
    --debug filled matrix 
    p_debug('Matrix filled with final message (modules marked with dots are for format data; marked with stars are for version - those data will be filled in masking step):', 2); 
    p_dbms_output_matrix(gprMatrix, 2); 
END; 
 
 
PROCEDURE p_masking_format_version(p_error_correction varchar2) IS 
 
    TYPE t_format_version IS TABLE OF varchar2(20) INDEX BY varchar2(2); 
     
    lrFormat t_format_version; 
    lrVersion t_format_version; 
     
    lnR pls_integer; 
    lnC pls_integer; 
 
    PROCEDURE p_init_format_version IS 
    BEGIN 
        --init format 
        lrFormat('L0') := '111011111000100'; 
        lrFormat('L1') := '111001011110011'; 
        lrFormat('L2') := '111110110101010'; 
        lrFormat('L3') := '111100010011101'; 
        lrFormat('L4') := '110011000101111'; 
        lrFormat('L5') := '110001100011000'; 
        lrFormat('L6') := '110110001000001'; 
        lrFormat('L7') := '110100101110110'; 
        lrFormat('M0') := '101010000010010'; 
        lrFormat('M1') := '101000100100101'; 
        lrFormat('M2') := '101111001111100'; 
        lrFormat('M3') := '101101101001011'; 
        lrFormat('M4') := '100010111111001'; 
        lrFormat('M5') := '100000011001110'; 
        lrFormat('M6') := '100111110010111'; 
        lrFormat('M7') := '100101010100000'; 
        lrFormat('Q0') := '011010101011111'; 
        lrFormat('Q1') := '011000001101000'; 
        lrFormat('Q2') := '011111100110001'; 
        lrFormat('Q3') := '011101000000110'; 
        lrFormat('Q4') := '010010010110100'; 
        lrFormat('Q5') := '010000110000011'; 
        lrFormat('Q6') := '010111011011010'; 
        lrFormat('Q7') := '010101111101101'; 
        lrFormat('H0') := '001011010001001'; 
        lrFormat('H1') := '001001110111110'; 
        lrFormat('H2') := '001110011100111'; 
        lrFormat('H3') := '001100111010000'; 
        lrFormat('H4') := '000011101100010'; 
        lrFormat('H5') := '000001001010101'; 
        lrFormat('H6') := '000110100001100'; 
        lrFormat('H7') := '000100000111011'; 
         
        --init version 
        lrVersion('7') := '000111110010010100'; 
        lrVersion('8') := '001000010110111100'; 
        lrVersion('9') := '001001101010011001'; 
        lrVersion('10') := '001010010011010011'; 
        lrVersion('11') := '001011101111110110'; 
        lrVersion('12') := '001100011101100010'; 
        lrVersion('13') := '001101100001000111'; 
        lrVersion('14') := '001110011000001101'; 
        lrVersion('15') := '001111100100101000'; 
        lrVersion('16') := '010000101101111000'; 
        lrVersion('17') := '010001010001011101'; 
        lrVersion('18') := '010010101000010111'; 
        lrVersion('19') := '010011010100110010'; 
        lrVersion('20') := '010100100110100110'; 
        lrVersion('21') := '010101011010000011'; 
        lrVersion('22') := '010110100011001001'; 
        lrVersion('23') := '010111011111101100'; 
        lrVersion('24') := '011000111011000100'; 
        lrVersion('25') := '011001000111100001'; 
        lrVersion('26') := '011010111110101011'; 
        lrVersion('27') := '011011000010001110'; 
        lrVersion('28') := '011100110000011010'; 
        lrVersion('29') := '011101001100111111'; 
        lrVersion('30') := '011110110101110101'; 
        lrVersion('31') := '011111001001010000'; 
        lrVersion('32') := '100000100111010101'; 
        lrVersion('33') := '100001011011110000'; 
        lrVersion('34') := '100010100010111010'; 
        lrVersion('35') := '100011011110011111'; 
        lrVersion('36') := '100100101100001011'; 
        lrVersion('37') := '100101010000101110'; 
        lrVersion('38') := '100110101001100100'; 
        lrVersion('39') := '100111010101000001'; 
        lrVersion('40') := '101000110001101001'; 
    END p_init_format_version; 
 
 
    PROCEDURE p_format_version(p_mask pls_integer) IS 
        lcFormat varchar2(20); 
        lcVersion varchar2(20); 
        lnCounter pls_integer; 
 
        PROCEDURE p_set_module( 
            p_row pls_integer,  
            p_column pls_integer,  
            p_pos pls_integer,  
            p_format_version varchar2  --F for format and V for version 
            ) IS 
        BEGIN 
            --modules are reserved and values 2 and 3 are set (not 0 and 1) 
            gprMasking(p_mask)(p_row)(p_column) :=  
                (CASE WHEN substr( (CASE WHEN p_format_version = 'F' THEN lcFormat ELSE lcVersion END), p_pos, 1) = '1' THEN '3' ELSE '2' END); 
        END; 
 
    BEGIN 
        --put format in matrix (for all 8 maskings) 
        lcFormat := lrFormat(p_error_correction || p_mask); 
        p_debug('Format for error correction ' || p_error_correction || ' and masking ' || p_mask || ': ' || lcFormat, 3); 
         
        --top left finder 
        p_set_module(9, 1, 1, 'F'); 
        p_set_module(9, 2, 2, 'F'); 
        p_set_module(9, 3, 3, 'F'); 
        p_set_module(9, 4, 4, 'F'); 
        p_set_module(9, 5, 5, 'F'); 
        p_set_module(9, 6, 6, 'F'); 
        p_set_module(9, 8, 7, 'F'); 
        p_set_module(9, 9, 8, 'F'); 
        p_set_module(8, 9, 9, 'F'); 
        p_set_module(6, 9, 10, 'F'); 
        p_set_module(5, 9, 11, 'F'); 
        p_set_module(4, 9, 12, 'F'); 
        p_set_module(3, 9, 13, 'F'); 
        p_set_module(2, 9, 14, 'F'); 
        p_set_module(1, 9, 15, 'F'); 
 
        --lower left and top right finder 
        p_set_module(f_matrix_size, 9, 1, 'F'); 
        p_set_module(f_matrix_size - 1, 9, 2, 'F'); 
        p_set_module(f_matrix_size - 2, 9, 3, 'F'); 
        p_set_module(f_matrix_size - 3, 9, 4, 'F'); 
        p_set_module(f_matrix_size - 4, 9, 5, 'F'); 
        p_set_module(f_matrix_size - 5, 9, 6, 'F'); 
        p_set_module(f_matrix_size - 6, 9, 7, 'F'); 
         
        p_set_module(9, f_matrix_size - 7, 8, 'F'); 
        p_set_module(9, f_matrix_size - 6, 9, 'F'); 
        p_set_module(9, f_matrix_size - 5, 10, 'F'); 
        p_set_module(9, f_matrix_size - 4, 11, 'F'); 
        p_set_module(9, f_matrix_size - 3, 12, 'F'); 
        p_set_module(9, f_matrix_size - 2, 13, 'F'); 
        p_set_module(9, f_matrix_size - 1, 14, 'F'); 
        p_set_module(9, f_matrix_size, 15, 'F'); 
         
         
        --put version in matrix (for 7 and higher) 
        if gpnVersion >= 7 then 
            lcVersion := lrVersion(gpnVersion); 
            p_debug('Version (' || gpnVersion || ') for matrix: ' || lcVersion, 3); 
 
             
            lnCounter := 1; 
            FOR c IN REVERSE 1 .. 6 LOOP 
                FOR r IN 8 .. 10 LOOP 
                    --bottom left  
                    p_set_module(f_matrix_size - r, c, lnCounter, 'V'); 
                     
                    --top right 
                    p_set_module(c, f_matrix_size - r, lnCounter, 'V'); 
 
                    lnCounter := lnCounter + 1; 
                END LOOP; 
            END LOOP;  
 
        else 
            p_debug('Version (' || gpnVersion || ') is not needed for matrix', 3); 
        end if; 
         
         
    END p_format_version; 
     
BEGIN 
    --init format and version collection 
    p_init_format_version; 
 
    --copy matrix for 8 different maskings 
    FOR t IN 0 .. 7 LOOP 
        gprMasking(t) := t_column(); 
        gprMasking(t) := gprMasking(t) MULTISET UNION ALL gprMatrix; 
    END LOOP; 
 
    --mask every copy with different masking 
    FOR t IN 0 .. 7 LOOP 
         
        FOR r IN 1 .. f_matrix_size LOOP 
            FOR c IN 1 .. f_matrix_size LOOP 
                 
                --matrix (collection) in Oracle begins with 1 
                lnR := r - 1; 
                lnC := c - 1; 
             
                --masking is done only on data and error correction modules (matrix values 0 or 1 - other values are fixed) 
                if gprMasking(t)(r)(c) in ('1', '0') then 
                 
                    --mask patterns 
                    if  
                        (t=0 and (lnR + lnC) mod 2 = 0) or 
                        (t=1 and lnR mod 2 = 0) or 
                        (t=2 and lnC mod 3 = 0) or 
                        (t=3 and (lnR + lnC) mod 3 = 0) or 
                        (t=4 and (floor(lnR / 2) + floor(lnC / 3)) mod 2 = 0) or 
                        (t=5 and ((lnR * lnC) mod 2) + ((lnR * lnC) mod 3) = 0) or 
                        (t=6 and (((lnR * lnC) mod 2) + ((lnR * lnC) mod 3)) mod 2 = 0) or 
                        (t=7 and (((lnR + lnC) mod 2) + ((lnR * lnC) mod 3)) mod 2 = 0) then 
 
                        --switch black and white module 
                        if gprMasking(t)(r)(c) = '1' then 
                            gprMasking(t)(r)(c) := '0'; 
                        else 
                            gprMasking(t)(r)(c) := '1'; 
                        end if; 
                         
                    end if; 
 
                end if; 
                 
            END LOOP; 
        END LOOP; 
 
        p_format_version(t); 
         
        p_debug('Mask pattern ' || t || ':', 3); 
        p_dbms_output_matrix(gprMasking(t), 3); 
        p_debug('------------------------------------------------------------------------------------------', 3); 
     
    END LOOP; 
 
    --reserved fields marked with 2 and 3 are not necessary any more - change them to 0 and 1 
    FOR t IN 0 .. 7 LOOP 
        FOR r IN 1 .. f_matrix_size LOOP 
            FOR c IN 1 .. f_matrix_size LOOP 
                gprMasking(t)(r)(c) := CASE gprMasking(t)(r)(c) WHEN '3' THEN '1' WHEN '2' THEN '0' ELSE gprMasking(t)(r)(c) END; 
            END LOOP; 
        END LOOP; 
    END LOOP; 
 
END p_masking_format_version; 
 
 
PROCEDURE p_penalty_rules(p_masking_out pls_integer default null) IS 
    lnRule1 pls_integer; 
    lnRule2 pls_integer; 
    lnRule3 pls_integer; 
    lnRule4 pls_integer; 
     
    lnCounter pls_integer; 
    lcPattern varchar2(11); 
    lnPercent pls_integer; 
     
    lnLowestPenalty pls_integer; 
    lnChosenMasking pls_integer; 
     
    lnDebugTemp pls_integer; 
     
BEGIN 
    --large initial values to be sure that first masking (0) is lower than those values 
    lnLowestPenalty := 100000000; 
    lnChosenMasking := 8; 
     
 
    --iterate through all 8 maskings, calculate penalty and find lowest penalty score 
    FOR t IN 0 .. 7 LOOP 
     
        --rule 1 - five or more same-colored modules in a row (or column) 
        lnRule1 := 0; 
         
        FOR r IN 1 .. f_matrix_size LOOP  --horizontal direction 
            lnCounter := 1; 
            FOR c IN 2 .. f_matrix_size LOOP 
                if gprMasking(t)(r)(c) = gprMasking(t)(r)(c - 1) then 
                    lnCounter := lnCounter + 1; 
                end if; 
                if gprMasking(t)(r)(c) <> gprMasking(t)(r)(c - 1) or c = f_matrix_size then 
                    if lnCounter >= 5 then 
                        lnRule1 := lnRule1 + 3 + (lnCounter - 5);  --if 5 modules are the same color then penalty is 3 plus 1 for every additional module (4 for 6 modules...) 
                    end if; 
                    lnCounter := 1; 
                end if; 
            END LOOP; 
        END LOOP; 
         
        lnDebugTemp := lnRule1; 
        p_debug('Masking ' || t || ', rule 1 - horizontal direction: ' || lnRule1, 2); 
 
        FOR c IN 1 .. f_matrix_size LOOP  --vertical direction 
            lnCounter := 1; 
            FOR r IN 2 .. f_matrix_size LOOP 
                if gprMasking(t)(r)(c) = gprMasking(t)(r - 1)(c) then 
                    lnCounter := lnCounter + 1; 
                end if; 
                if gprMasking(t)(r)(c) <> gprMasking(t)(r - 1)(c) or r = f_matrix_size then 
                    if lnCounter >= 5 then 
                        lnRule1 := lnRule1 + 3 + (lnCounter - 5);  --if 5 modules are the same color then penalty is 3 plus 1 for every additional module (4 for 6 modules...) 
                    end if; 
                    lnCounter := 1; 
                end if; 
            END LOOP; 
        END LOOP; 
         
        p_debug('Masking ' || t || ', rule 1 - vertical direction: ' || (lnRule1 - lnDebugTemp), 2); 
        p_debug('Masking ' || t || ', rule 1 - sum: ' || lnRule1, 2); 
        p_debug(' ', 2); 
 
         
        --rule 2 - areas of the same color that are 2x2 modules 
        lnRule2 := 0; 
         
        FOR r IN 1 .. f_matrix_size - 1 LOOP 
            FOR c IN 1 .. f_matrix_size - 1 LOOP 
                if  
                    gprMasking(t)(r)(c) = gprMasking(t)(r + 1)(c) and  
                    gprMasking(t)(r)(c) = gprMasking(t)(r)(c + 1) and  
                    gprMasking(t)(r)(c) = gprMasking(t)(r + 1)(c + 1)  
                    then 
                    lnRule2 := lnRule2 + 3; 
                end if; 
            END LOOP; 
        END LOOP; 
 
        p_debug('Masking ' || t || ', rule 2 - sum: ' || lnRule2, 2); 
        p_debug(' ', 2); 
 
 
        --rule 3 - patterns of dark-light-dark-dark-dark-light-dark that have four light modules on either side (10111010000 or 00001011101) 
        lnRule3 := 0; 
         
        FOR r IN 1 .. f_matrix_size LOOP  --horizontal direction 
            FOR c IN 1 .. f_matrix_size - 10 LOOP 
                lcPattern := null; 
                FOR p IN 0 .. 10 LOOP 
                    lcPattern := lcPattern || gprMasking(t)(r)(c + p); 
                END LOOP; 
                 
                if lcPattern in ('10111010000', '00001011101') then 
                    p_debug(lcPattern || ' (horizontal) found in row ' || r || ' and column ' || c, 3); 
                    lnRule3 := lnRule3 + 40; 
                end if; 
            END LOOP; 
        END LOOP; 
         
        lnDebugTemp := lnRule3; 
        p_debug('Masking ' || t || ', rule 3 - horizontal direction: ' || lnRule3, 2); 
 
        FOR c IN 1 .. f_matrix_size LOOP  --horizontal direction 
            FOR r IN 1 .. f_matrix_size - 10 LOOP 
                lcPattern := null; 
                FOR p IN 0 .. 10 LOOP 
                    lcPattern := lcPattern || gprMasking(t)(r + p)(c); 
                END LOOP; 
                 
                if lcPattern in ('10111010000', '00001011101') then 
                    p_debug(lcPattern || ' (vertical) found in row ' || r || ' and column ' || c, 3); 
                    lnRule3 := lnRule3 + 40; 
                end if; 
            END LOOP; 
        END LOOP; 
 
        p_debug('Masking ' || t || ', rule 3 - vertical direction: ' || (lnRule3 - lnDebugTemp), 2); 
        p_debug('Masking ' || t || ', rule 3 - sum: ' || lnRule3, 2); 
        p_debug(' ', 2); 
 
 
        --rule 4 -  ratio of light modules to dark modules 
        lnCounter := 0;  --count dark modules 
        FOR r IN 1 .. f_matrix_size LOOP 
            FOR c IN 1 .. f_matrix_size LOOP 
                if gprMasking(t)(r)(c) = '1' then 
                    lnCounter := lnCounter + 1; 
                end if; 
            END LOOP; 
        END LOOP; 
 
        lnPercent := trim(lnCounter * 100 / (f_matrix_size * f_matrix_size));  --calculate percent of dark modules 
 
        p_debug('Masking ' || t || ', rule 4 - total number of modules: ' || (f_matrix_size * f_matrix_size), 2); 
        p_debug('Masking ' || t || ', rule 4 - dark modules: ' || lnCounter, 2); 
        p_debug('Masking ' || t || ', rule 4 - % of dark modules: ' || lnPercent, 2); 
         
        LOOP  --find lower multiple of 5 
            EXIT WHEN lnPercent mod 5 = 0; 
            lnPercent := lnPercent - 1; 
        END LOOP; 
         
        lnRule4 := least(  --subtract 50 from lower and upper multiple of 5; take absolute value; use smallest value; multiply with 10 
            abs(lnPercent - 50) / 5, 
            abs(lnPercent + 5 - 50) / 5) * 10; 
         
        p_debug('Masking ' || t || ', rule 4 - value: ' || lnRule4, 2); 
        p_debug(' ', 2); 
 
 
        p_debug('Masking ' || t || ', final penalty value: ' || (lnRule1 + lnRule2 + lnRule3 + lnRule4), 2); 
        p_debug('-----------------------------------------', 2); 
         
        --check if penalty for current masking is lowest 
        if (lnRule1 + lnRule2 + lnRule3 + lnRule4) < lnLowestPenalty then 
            lnLowestPenalty := (lnRule1 + lnRule2 + lnRule3 + lnRule4); 
            lnChosenMasking := t; 
        end if; 
         
    END LOOP; 
 
    p_debug('Masking ' || lnChosenMasking || ' has lowest penalty of ' || lnLowestPenalty || ' and will be used for QR code matrix.', 2); 
 
    --copy the best masking into original matrix and use it as result of QR code calculation 
    --in case of debugging and selected masking output - use this value instead calculated and make an output 
    gprMatrix.delete; 
    gprMatrix := gprMatrix MULTISET UNION ALL gprMasking( nvl(p_masking_out, lnChosenMasking) ); 
 
END p_penalty_rules; 
 
 
 
PROCEDURE p_generate_qr( 
    p_data varchar2, 
    p_error_correction varchar2, 
    p_debug boolean default false, 
    p_debug_level pls_integer default 1, 
    p_masking_out pls_integer default null 
    ) IS 
     
    lcData varchar2(32000); 
    lcFinal varchar2(32000); 
     
BEGIN 
    --global variables and tables, which has the same values during QR code generation 
    gpbDebug := p_debug; 
    gpnDebugLevel := p_debug_level; 
 
    gpnMode := f_get_mode(p_data); 
    gpnVersion := f_get_version(p_data, p_error_correction); 
  
    p_fill_err_cor; 
    p_fill_log_antilog; 
     
    --init matrix collection and fill static elements 
    --gpnVersion := 14;  --only for debugging 
    p_init_matrix; 
     
    --OPERATIONAL PART 
     
    --encoded data with all parts (terminal zeros, padding bytes...) 
    lcData := f_encode_data(p_data, p_error_correction); 
     
    --final structured message (data plus error correction) 
    lcFinal := f_final_data_with_ec(lcData, p_error_correction); 
     
    --place final message in matrix 
    p_place_fm_in_matrix(lcFinal); 
     
    --masking; format and version info 
    p_masking_format_version(p_error_correction); 
     
    --Four Penalty Rules - choose which masking is the easiest to read and copy that masking in matrix variable 
    p_penalty_rules(p_masking_out); 
     
     
END p_generate_qr; 
 
 
FUNCTION f_matrix_2_vc2 RETURN varchar2 IS 
    lcQR varchar2(32727); 
BEGIN 
    FOR t IN 1 .. gprMatrix.count LOOP 
        FOR p IN 1 .. gprMatrix.count LOOP 
            lcQR := lcQR || nvl(gprMatrix(t)(p), 'X'); 
        END LOOP; 
        lcQR := lcQR || chr(10); 
    END LOOP; 
     
    RETURN lcQR; 
END; 
 
   
 
 
 
 
PROCEDURE p_generate_qr_data( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H (see bellow) 
    p_qr OUT varchar2, --generated QR code data in format row || newline (chr 10) || row || newline...; 1 for black module, 0 for white 
    p_matrix_size OUT pls_integer --matrix size in modules (21, 25, 29...) 
    ) IS 
     
BEGIN 
    --generate matrix 
    p_generate_qr( 
        p_data => p_data,  
        p_error_correction => p_error_correction,  
        p_debug => false,  
        p_debug_level => 1); 
     
    --convert matrix to vc2 (output) 
    p_qr := f_matrix_2_vc2; 
 
    --matrix size 
    p_matrix_size := f_matrix_size; 
     
END p_generate_qr_data; 
 
 
PROCEDURE p_qr_debug( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H (see bellow) 
    p_debug boolean default true,  --should DBMS OUTPUT be printed 
    p_debug_level pls_integer default 1,  --debug level (1, 2, 3...) - details to be printed in debug output 
    p_masking_out pls_integer default null, 
    p_qr OUT varchar2, 
    p_matrix_size OUT pls_integer 
    ) IS 
     
BEGIN 
    --generate matrix 
    p_generate_qr( 
        p_data => p_data,  
        p_error_correction => p_error_correction,  
        p_debug => p_debug,  
        p_debug_level => p_debug_level, 
        p_masking_out => p_masking_out); 
 
    --convert matrix to debug form 
    p_qr := f_matrix_2_vc2; 
 
    --matrix size 
    p_matrix_size := f_matrix_size; 
     
END p_qr_debug; 
 
 
 
FUNCTION f_qr_as_html_table( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H 
    p_module_size_in_px pls_integer default 8, --module size in pixels 
    p_margines boolean default false --margines around QR code (4 modules) 
    ) RETURN clob IS 
     
    lcQR varchar2(32727); 
    lnMatrixSize pls_integer; 
    lcClob clob; 
 
    PROCEDURE p_add_clob(lcText varchar2) IS 
    BEGIN 
        lcClob := lcClob || lcText || chr(10); 
    END; 
     
BEGIN 
    if p_data is null then 
        lcClob := 'no data to display.'; 
        RETURN lcClob; 
    end if; 
 
 
    p_generate_qr_data( 
        p_data => p_data, 
        p_error_correction => p_error_correction,  
        p_qr => lcQR, 
        p_matrix_size => lnMatrixSize 
        ); 
 
    p_add_clob('<table style="border-collapse: collapse;">'); 
     
    --columns (for column width defined in style - inline on page) 
    FOR t IN 1 .. lnMatrixSize + (CASE WHEN p_margines THEN 8 ELSE 0 END) LOOP 
        p_add_clob('<col style="width: ' || p_module_size_in_px || 'px;">'); 
    END LOOP; 
     
    --top margine - 4 module rows 
    if p_margines then 
        FOR t in 1 .. 4 LOOP 
            p_add_clob('<tr style="height: ' || p_module_size_in_px || 'px;"><td style="background-color: #FFFFFF; padding: 0px 0px;"></td></tr>'); 
        END LOOP; 
    end if; 
 
 
    FOR t IN 1 .. lnMatrixSize LOOP 
     
        --new row 
        p_add_clob('<tr style="height: ' || p_module_size_in_px || 'px;">'); 
         
        --left margine - 4 modules 
        if p_margines then 
            FOR z in 1 .. 4 LOOP 
                p_add_clob('<td style="background-color: #FFFFFF; padding: 0px 0px;"></td>'); 
            END LOOP; 
        end if; 
         
        --modules in row 
        FOR p IN 1 .. lnMatrixSize LOOP 
     
            p_add_clob('<td style="background-color: #' || 
                  (CASE  
                       substr(lcQR, (t - 1) * (lnMatrixSize + 1) + p, 1)  
                   WHEN '0' THEN 'FFFFFF'  
                   ELSE '000000' END) ||  
                  '; padding: 0px 0px;"></td>'); 
             
        END LOOP; 
 
        --right margine - 4 modules 
        if p_margines then 
            FOR z in 1 .. 4 LOOP 
                p_add_clob('<td style="background-color: #FFFFFF; padding: 0px 0px;"></td>'); 
            END LOOP; 
        end if; 
 
        p_add_clob('</tr>'); 
         
    END LOOP; 
     
    --bottom margine - 4 module rows 
    if p_margines then 
        FOR t in 1 .. 4 LOOP 
            p_add_clob('<tr style="height: ' || p_module_size_in_px || 'px;"><td style="background-color: #FFFFFF; padding: 0px 0px;"></td></tr>'); 
        END LOOP; 
    end if; 
     
    p_add_clob('</table>'); 
 
    RETURN lcClob; 
     
END f_qr_as_html_table; 
 
 
 
 
PROCEDURE p_qr_as_html_table( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H 
    p_module_size_in_px pls_integer default 8, --module size in pixels 
    p_margines boolean default false --margines around QR code (4 modules) 
    ) IS 
     
    lcClob clob; 
    lnFrom pls_integer := 1; 
    lnTo pls_integer; 
     
BEGIN 
    if p_data is null then 
        htp.p('no data to display.'); 
        RETURN; 
    end if; 
 
    lcClob := f_qr_as_html_table(p_data, p_error_correction, p_module_size_in_px, p_margines); 
     
    LOOP 
        lnTo := instr(lcClob, chr(10), lnFrom); 
        if lnTo = 0 then 
            lnTo := length(lcClob); 
        end if; 
     
        htp.p(substr(lcClob, lnFrom, lnTo - lnFrom)); 
         
        lnFrom := lnTo + 1; 
         
        EXIT WHEN lnTo = length(lcClob); 
    END LOOP; 
     
END p_qr_as_html_table; 
 
 
 
 
FUNCTION unsigned_short(s in pls_integer) RETURN raw IS 
    lrRet raw(4); 
BEGIN 
    lrRet := UTL_RAW.reverse( UTL_RAW.cast_from_binary_integer(s) ); 
    RETURN UTL_RAW.substr(lrRet, 1, 2); 
END unsigned_short; 
 
 
FUNCTION unsigned_int(i in pls_integer) RETURN raw IS  
    lrRet raw(4); 
BEGIN 
    lrRet := UTL_RAW.reverse( UTL_RAW.cast_from_binary_integer(i) ); 
    RETURN lrRet; 
END unsigned_int; 
 
 
 
FUNCTION f_qr_as_bmp( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H 
    p_margines varchar2 default 'N' --margines around QR code (4 modules) - values Y or N 
    ) RETURN blob IS 
     
    lcQR varchar2(32727); 
    lnMatrixSize pls_integer; 
    lnZeros pls_integer; 
    lnImageBytes pls_integer; 
    lnWidthHeight pls_integer; 
 
    lbBlob blob; 
    lrLine raw(500); 
     
BEGIN 
    if p_data is null then 
        return null; 
        RAISE_APPLICATION_ERROR(-20000, 'no data to display.'); 
    end if; 
 
    p_generate_qr_data( 
        p_data => p_data, 
        p_error_correction => p_error_correction,  
        p_qr => lcQR, 
        p_matrix_size => lnMatrixSize 
        ); 
 
 
    DBMS_LOB.createTemporary(lbBlob, true); 
 
    --Header 
    lnWidthHeight := lnMatrixSize + (CASE WHEN p_margines = 'Y' THEN 8 ELSE 0 END); 
    lnImageBytes := lnWidthHeight * lnWidthHeight * 8; 
     
    dbms_lob.append(lbBlob, utl_raw.cast_to_raw('BM')); -- Pos  0 - fixed 
    dbms_lob.append(lbBlob, unsigned_int(14 + 40 + 8 + lnImageBytes));    -- Pos  2 - file size (62 as header size + data size + color pallete) 
    dbms_lob.append(lbBlob, unsigned_int(0));      -- Pos 6, unused / reserved, value 0 
    dbms_lob.append(lbBlob, unsigned_int(14 + 40 + 8));      -- Pos 10, offset to image data - header size + information size + color pallete 
 
    -- Information 
    dbms_lob.append(lbBlob, unsigned_int(40));    -- Pos 14 - size of information header (always 40) 
    dbms_lob.append(lbBlob, unsigned_int(lnWidthHeight * 8));    -- Pos 18 - width 
    dbms_lob.append(lbBlob, unsigned_int(lnWidthHeight * 8));   -- Pos 22 - height 
    dbms_lob.append(lbBlob, unsigned_short(1));        -- Pos 26, planes 
    dbms_lob.append(lbBlob, unsigned_short(1));        -- Pos 28, bits per pixel 
    dbms_lob.append(lbBlob, unsigned_int(0));        -- Pos 30, no compression 
    dbms_lob.append(lbBlob, unsigned_int(lnImageBytes)); -- Pos 34 - image data size 
    dbms_lob.append(lbBlob, unsigned_int(0));      -- Pos 38, x pixels/meter 
    dbms_lob.append(lbBlob, unsigned_int(0));      -- Pos 42, y pixels/meter 
    dbms_lob.append(lbBlob, unsigned_int(0));         -- Pos 46, Number of colors 
    dbms_lob.append(lbBlob, unsigned_int(0));         -- Pos 50, Important colors 
 
    --Colors 
    dbms_lob.append(lbBlob, unsigned_int(16777215));  -- White (FF FF FF 00) 
    dbms_lob.append(lbBlob, unsigned_int(0));         -- Black (00 00 00 00) 
     
     
     
    --Data 
     
    --zeros at the end of the scan line (scan line in bytes must be mod 4) 
    lnZeros := 0; 
    LOOP 
        EXIT WHEN (lnWidthHeight + lnZeros) mod 4 = 0; 
        lnZeros := lnZeros + 1; 
    END LOOP; 
     
    --bottom margine 
    if p_margines = 'Y' then 
        lrLine := utl_raw.copies( utl_raw.cast_to_raw(chr(0)), lnWidthHeight + lnZeros); 
         
        FOR t IN 1 .. 32 LOOP 
            dbms_lob.append(lbBlob, utl_raw.substr(lrLine, 1, lnWidthHeight + lnZeros)); 
        END LOOP; 
    end if; 
     
    --data for scan lines 
    FOR r IN REVERSE 1 .. lnMatrixSize LOOP 
        --first prepare scan line as raw data 
        if p_margines = 'Y' then 
            --left margine 
            lrLine := utl_raw.copies( utl_raw.cast_to_raw(chr(0)), 4); 
        else 
            --no margines 
            lrLine := null; 
        end if; 
         
        --data from matrix 
        FOR c IN 1 .. lnMatrixSize LOOP 
            lrLine := lrLine || utl_raw.cast_to_raw(chr( 
                CASE WHEN substr(lcQR, (r - 1) * (lnMatrixSize + 1) + c, 1) = '1' THEN 255 ELSE 0 END 
                )); 
        END LOOP; 
 
        --right margine 
        if p_margines = 'Y' then 
            lrLine := lrLine || utl_raw.copies( utl_raw.cast_to_raw(chr(0)), 4); 
        end if; 
 
        --trailing zeroes (mod 4) 
        FOR c IN 1 .. lnZeros LOOP 
            lrLine := lrLine || utl_raw.cast_to_raw(chr(0)); 
        END LOOP; 
         
        --8 scan lines in file because module is 8x8 pixels 
        FOR t IN 1 .. 8 LOOP 
            dbms_lob.append(lbBlob, utl_raw.substr(lrLine, 1, lnWidthHeight + lnZeros)); 
        END LOOP; 
    END LOOP; 
 
    --top margine (4 modules) 
    if p_margines = 'Y' then 
        lrLine := utl_raw.copies( utl_raw.cast_to_raw(chr(0)), lnWidthHeight + lnZeros); 
         
        FOR t IN 1 .. 32 LOOP 
            dbms_lob.append(lbBlob, utl_raw.substr(lrLine, 1, lnWidthHeight + lnZeros)); 
        END LOOP; 
    end if; 
 
    RETURN lbBlob; 
END f_qr_as_bmp; 
 
 
 
 
PROCEDURE p_qr_as_img_tag_base64( 
    p_data varchar2,  --data going to be encoded into QR code 
    p_error_correction varchar2, --L, M, Q or H 
    p_image_size_px pls_integer, 
    p_margines varchar2 default 'N' --margines around QR code (4 modules) - values Y or N 
    ) IS 
     
    lbBlob blob; 
    l_step PLS_INTEGER := 12000; -- make sure you set a multiple of 3 not higher than 24573 
     
BEGIN 
    lbBlob := f_qr_as_bmp(p_data, p_error_correction, p_margines); 
     
    htp.prn('<img src="data:image/bmp;base64, '); 
     
    FOR i IN 0 .. TRUNC((DBMS_LOB.getlength(lbBlob) - 1 )/l_step) LOOP 
        htp.prn( UTL_RAW.cast_to_varchar2(UTL_ENCODE.base64_encode(DBMS_LOB.substr(lbBlob, l_step, i * l_step + 1))) ); 
    END LOOP; 
 
    htp.prn('" alt="qr code" width="' || p_image_size_px || 'px" height = "' || p_image_size_px || 'px" />'); 
     
END; 
 
PROCEDURE p_save_file( 
    p_document blob, 
    p_file_name varchar2, 
    p_folder varchar2 
    ) IS 
 
    lfFile utl_file.file_type; 
    lnLen pls_integer := 32767; 
     
BEGIN 
    lfFile := utl_file.fopen(p_folder, p_file_name, 'wb'); 
    FOR i in 0 .. trunc( (dbms_lob.getlength(p_document) - 1 ) / lnLen ) LOOP 
        utl_file.put_raw(lfFile, dbms_lob.substr(p_document, lnLen, i * lnLen + 1)); 
    END LOOP; 
    utl_file.fclose(lfFile); 
END; 
 
 
 
END LL_PKG_QR;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_RESERVATION" AS                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                         
-- Generate banners with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE                                                                                                                                                                                                                                     

/*                                                                                                                                                                                                                                                                                                                                       
  LOG levels                                                                                                                                                                                                                                                                                                                             

   1 = Serious errors                                                                                                                                                                                                                                                                                                                    
  10 = Start and stop of high level packages                                                                                                                                                                                                                                                                                             
  20 = Start and stop of subroutines                                                                                                                                                                                                                                                                                                     
  30 = Steps inside subroutines                                                                                                                                                                                                                                                                                                          
  40 = Details steps inside subroutes (contains values)                                                                                                                                                                                                                                                                                  
  50 = Start and stop of REST statements to OCI (exec_get etc)                                                                                                                                                                                                                                                                           
  60 = Detailed steps of REST commands                                                                                                                                                                                                                                                                                                   
  70 = Sign steps for REST commands                                                                                                                                                                                                                                                                                                      
  80 = Sign details (contains values)                                                                                                                                                                                                                                                                                                    
*/                                                                                                                                                                                                                                                                                                                                       

--                                                                                                                                                                                                                                                                                                                                       
-- ======================================================================================================================================================                                                                                                                                                                                
--                                                                                                                                                                                                                                                                                                                                       
  function lock_reservation_setup (p_reservation_id number) return varchar2 is                                                                                                                                                                                                                                                           
    v_return_value  varchar2(1);                                                                                                                                                                                                                                                                                                         
    v_sqlerrm       varchar2(4000);                                                                                                                                                                                                                                                                                                      
  begin                                                                                                                                                                                                                                                                                                                                  
    v_return_value := 'N';                                                                                                                                                                                                                                                                                                               
    begin                                                                                                                                                                                                                                                                                                                                
      delete ll_lock where date_lock_expires < sysdate;                                                                                                                                                                                                                                                                                  
      insert into ll_lock (reservation_id) values (p_reservation_id);                                                                                                                                                                                                                                                                    
      commit;                                                                                                                                                                                                                                                                                                                            
      v_return_value := 'Y';                                                                                                                                                                                                                                                                                                             
    EXCEPTION                                                                                                                                                                                                                                                                                                                            
      when OTHERS then begin                                                                                                                                                                                                                                                                                                             
                         v_sqlerrm := SQLERRM;                                                                                                                                                                                                                                                                                           
                         ll_pkg_log.log(1,'Duplicate setup prevented for reservation '||p_reservation_id||' - '||v_sqlerrm);                                                                                                                                                                                                             
                       end;                                                                                                                                                                                                                                                                                                              
    end;                                                                                                                                                                                                                                                                                                                                 
    return(v_return_value);                                                                                                                                                                                                                                                                                                              
  end;                                                                                                                                                                                                                                                                                                                                   

--   ######  ######## ######## ##     ## ########     ########  ########  ######  ######## ########  ##     ##    ###    ######## ####  #######  ##    ##                                                                                                                                                                                
--  ##    ## ##          ##    ##     ## ##     ##    ##     ## ##       ##    ## ##       ##     ## ##     ##   ## ##      ##     ##  ##     ## ###   ##                                                                                                                                                                                
--  ##       ##          ##    ##     ## ##     ##    ##     ## ##       ##       ##       ##     ## ##     ##  ##   ##     ##     ##  ##     ## ####  ##                                                                                                                                                                                
--   ######  ######      ##    ##     ## ########     ########  ######    ######  ######   ########  ##     ## ##     ##    ##     ##  ##     ## ## ## ##                                                                                                                                                                                
--        ## ##          ##    ##     ## ##           ##   ##   ##             ## ##       ##   ##    ##   ##  #########    ##     ##  ##     ## ##  ####                                                                                                                                                                                
--  ##    ## ##          ##    ##     ## ##           ##    ##  ##       ##    ## ##       ##    ##    ## ##   ##     ##    ##     ##  ##     ## ##   ###                                                                                                                                                                                
--   ######  ########    ##     #######  ##           ##     ## ########  ######  ######## ##     ##    ###    ##     ##    ##    ####  #######  ##    ##                                                                                                                                                                                
-- This procedure will take the existing flow steps per reservation (which have been generated by 'create_reservation_steps') and execute them one by one                                                                                                                                                                                
-- The procedure will execute the steps (ll_reservation_steps) in order of the 'create_order' column from low to high.                                                                                                                                                                                                                   
-- All steps with the same create_order will be executed in a random order                                                                                                                                                                                                                                                               
-- The procedure will halt if one of the steps in a 'create_order' has failed (create_success='N') and retried 5 times (create_retry)                                                                                                                                                                                                    

  procedure setup_reservation (p_reservation_id number) is                                                                                                                                                                                                                                                                               

    cursor c_res_steps (p_create_order number)                                                                                                                                                                                                                                                                                           
                       is select llrs.id, llws.step_code, create_retry                                                                                                                                                                                                                                                                   
                          from ll_reservation_steps llrs, ll_flow_steps llws                                                                                                                                                                                                                                                             
                          where llrs.flow_step_id = llws.id                                                                                                                                                                                                                                                                              
                          and reservation_id = p_reservation_id                                                                                                                                                                                                                                                                          
                          and ( create_success is null or                                                                                                                                                                                                                                                                                
                                ( create_success = 'W' and nvl(create_date,sysdate- (1/24/6)) < sysdate ) or                                                                                                                                                                                                                             
                                create_success = 'N'                                                                                                                                                                                                                                                                                     
                              )                                                                                                                                                                                                                                                                                                          
                          and nvl(create_retry,0) < 5                                                                                                                                                                                                                                                                                    
                          and llrs.create_order = p_create_order;                                                                                                                                                                                                                                                                        
--                          for update of create_date, create_success, create_result, flow_step_result, create_retry;                                                                                                                                                                                                                    

    cursor c_find_step_order is select create_order, count(create_order), sum(case when create_retry >= 5 then 1 else 0 end)                                                                                                                                                                                                             
                                from ll_reservation_steps llrs                                                                                                                                                                                                                                                                           
                                where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                  
                                and nvl(create_success,'N')<>'Y'                                                                                                                                                                                                                                                                         
                                and create_order = (select min(create_order)                                                                                                                                                                                                                                                             
                                                    from ll_reservation_steps llrs                                                                                                                                                                                                                                                       
                                                    where reservation_id = p_reservation_id                                                                                                                                                                                                                                              
                                                    and nvl(create_success,'N')<>'Y')                                                                                                                                                                                                                                                    
                                group by create_order;                                                                                                                                                                                                                                                                                   

    v_ocid            varchar2(500);                                                                                                                                                                                                                                                                                                     
    v_status          varchar2(10000);                                                                                                                                                                                                                                                                                                   
    v_result          varchar2(10000);                                                                                                                                                                                                                                                                                                   
    v_step_id         number;                                                                                                                                                                                                                                                                                                            
    v_step_code       varchar2(50);                                                                                                                                                                                                                                                                                                      
    v_create_order    number;                                                                                                                                                                                                                                                                                                            
    v_create_items    number;                                                                                                                                                                                                                                                                                                            
    v_create_error    number;                                                                                                                                                                                                                                                                                                            
    v_command         varchar2(4000);                                                                                                                                                                                                                                                                                                    
    v_dummy_status    varchar2(1000);                                                                                                                                                                                                                                                                                                    
    v_dummy_result    varchar2(1000);                                                                                                                                                                                                                                                                                                    
    v_tf_log          CLOB;                                                                                                                                                                                                                                                                                                              

    v_run_again       varchar2(1);                                                                                                                                                                                                                                                                                                       
    v_do_update       varchar2(1);                                                                                                                                                                                                                                                                                                       
    v_create_retry    number;                                                                                                                                                                                                                                                                                                            
    v_sqlerrm         varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call', p_reservation_id);                                                                                                                                                                                                                                                                                 
    v_run_again := lock_reservation_setup (p_reservation_id => p_reservation_id);                                                                                                                                                                                                                                                        
    ll_pkg_security.set_security_group;                                                                                                                                                                                                                                                                                                  

    while v_run_again = 'Y' loop                                                                                                                                                                                                                                                                                                         

      ll_pkg_log.log(30,'RUN_AGAIN = Y');                                                                                                                                                                                                                                                                                                

      v_ocid         := '';                                                                                                                                                                                                                                                                                                              
      v_status       := '';                                                                                                                                                                                                                                                                                                              
      v_result       := '';                                                                                                                                                                                                                                                                                                              
      v_create_order := '';                                                                                                                                                                                                                                                                                                              
      v_create_items := '';                                                                                                                                                                                                                                                                                                              
      v_create_error := '';                                                                                                                                                                                                                                                                                                              

      open c_find_step_order;                                                                                                                                                                                                                                                                                                            
      fetch c_find_step_order into v_create_order, v_create_items, v_create_error;                                                                                                                                                                                                                                                       
      if c_find_step_order%NOTFOUND then                                                                                                                                                                                                                                                                                                 
        v_run_again := 'N';                                                                                                                                                                                                                                                                                                              
        v_do_update := 'N';                                                                                                                                                                                                                                                                                                              
      else                                                                                                                                                                                                                                                                                                                               
        ll_pkg_log.log(40,'Step found for create_order '||v_create_order ||', create_items='||v_create_items||', create_error='||v_create_error);                                                                                                                                                                                        
      end if;                                                                                                                                                                                                                                                                                                                            
      close c_find_step_order;                                                                                                                                                                                                                                                                                                           

      if v_create_order is null or v_create_items = v_create_error then                                                                                                                                                                                                                                                                  
        v_run_again := 'N';                                                                                                                                                                                                                                                                                                              
        ll_pkg_log.log(40,'No open orders, RUN_AGAIN=N, fatal errors = '||v_create_error);                                                                                                                                                                                                                                               
      else                                                                                                                                                                                                                                                                                                                               
        ll_pkg_log.log(40,'Step order '||v_create_order||' has '||v_create_items||' open items of which '||v_create_error||' have terminally errored out');                                                                                                                                                                              
        open c_res_steps(v_create_order);                                                                                                                                                                                                                                                                                                
        fetch c_res_steps into v_step_id, v_step_code, v_create_retry;                                                                                                                                                                                                                                                                   
        if c_res_steps%FOUND then                                                                                                                                                                                                                                                                                                        
          v_run_again := 'Y';                                                                                                                                                                                                                                                                                                            
          v_do_update := 'Y';                                                                                                                                                                                                                                                                                                            
          ll_pkg_log.log(40,'We will be updating this item id '||v_step_id||' with code '||v_step_code);                                                                                                                                                                                                                                 
        else                                                                                                                                                                                                                                                                                                                             
          v_do_update := 'N';                                                                                                                                                                                                                                                                                                            
          v_run_again := 'N';                                                                                                                                                                                                                                                                                                            
          v_create_retry := 999;                                                                                                                                                                                                                                                                                                         
        end if;                                                                                                                                                                                                                                                                                                                          

        ll_pkg_log.log(40,'Found id '||v_step_id||' code '||v_step_code||' create_retry '||v_create_retry);                                                                                                                                                                                                                              

        if nvl(v_create_retry,0) < 6 then                                                                                                                                                                                                                                                                                                
          if v_step_code = 'sendEmailProvisioning'  then                                                                                                                                                                                                                                                                                 
              ll_pkg_log.log(30,'Sending provisioning email');                                                                                                                                                                                                                                                                           
              ll_pkg_apex.send_template_email                                                                                                                                                                                                                                                                                            
                                           ( p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                                   
                                             p_phase              => 'SETUP_STARTED',                                                                                                                                                                                                                                                    
                                             p_status             => v_status,                                                                                                                                                                                                                                                           
                                             p_result             => v_result);                                                                                                                                                                                                                                                          
          elsif v_step_code = 'sendEmailProvisioned'  then                                                                                                                                                                                                                                                                               
              ll_pkg_log.log(30,'Sending email all is well');                                                                                                                                                                                                                                                                            
              ll_pkg_apex.send_template_email                                                                                                                                                                                                                                                                                            
                                           ( p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                                   
                                             p_phase              => 'SETUP_FINISHED',                                                                                                                                                                                                                                                   
                                             p_status             => v_status,                                                                                                                                                                                                                                                           
                                             p_result             => v_result);                                                                                                                                                                                                                                                          
          else                                                                                                                                                                                                                                                                                                                           
            begin                                                                                                                                                                                                                                                                                                                        
              v_command :=  'begin '||                                                                                                                                                                                                                                                                                                   
                              ll_pkg_admin.get_flow_step_source_code( v_step_code)||                                                                                                                                                                                                                                                     
                                             '( p_reservation_id => :1,'||                                                                                                                                                                                                                                                               
                                             '  p_res_step_id    => :2,'||                                                                                                                                                                                                                                                               
                                             '  p_ocid           => :3,'||                                                                                                                                                                                                                                                               
                                             '  p_status         => :4,'||                                                                                                                                                                                                                                                               
                                             '  p_result         => :5); '||                                                                                                                                                                                                                                                             
                            'end;';                                                                                                                                                                                                                                                                                                      
            ll_pkg_log.log(40,'Begin execute immediate for '||v_command);                                                                                                                                                                                                                                                                
            execute immediate ( v_command )                                                                                                                                                                                                                                                                                              
                                          using IN p_reservation_id,                                                                                                                                                                                                                                                                     
                                                IN v_step_id,                                                                                                                                                                                                                                                                            
                                                OUT v_ocid,                                                                                                                                                                                                                                                                              
                                                OUT v_status,                                                                                                                                                                                                                                                                            
                                                OUT v_result;                                                                                                                                                                                                                                                                            
            exception                                                                                                                                                                                                                                                                                                                    
              when OTHERS then  begin                                                                                                                                                                                                                                                                                                    
                                  v_sqlerrm := SQLERRM;                                                                                                                                                                                                                                                                                  
                                  v_status := 'N';                                                                                                                                                                                                                                                                                       
                                  v_result := v_sqlerrm;                                                                                                                                                                                                                                                                                 
                              end;                                                                                                                                                                                                                                                                                                       
            end;                                                                                                                                                                                                                                                                                                                         
          end if;                                                                                                                                                                                                                                                                                                                        

          ll_pkg_log.log(30,'Create result is '||v_result);                                                                                                                                                                                                                                                                              

          if v_do_update = 'Y' then                                                                                                                                                                                                                                                                                                      
            if v_step_code in ('ociTfApplyJob', 'ociTfCheckStatus') and nvl(v_status,'Y') = 'N'  and NOT REGEXP_LIKE(v_result, '"code"\s*:\s*"Conflict"') then                                                                                                                                                                           
              v_create_retry := 5;                                                                                                                                                                                                                                                                                                       
            elsif nvl(v_status,'Y') = 'N' then                                                                                                                                                                                                                                                                                           
              v_create_retry := nvl(v_create_retry,0)+1;                                                                                                                                                                                                                                                                                 
            else                                                                                                                                                                                                                                                                                                                         
              v_status := nvl(v_status,'Y');                                                                                                                                                                                                                                                                                             
              v_create_retry := '';                                                                                                                                                                                                                                                                                                      
            end if;                                                                                                                                                                                                                                                                                                                      

            begin                                                                                                                                                                                                                                                                                                                        
              ll_pkg_log.log(40,'Current status is '||v_status||', current result is '||v_result);                                                                                                                                                                                                                                       
              update ll_reservation_steps set create_date=sysdate,                                                                                                                                                                                                                                                                       
                                              create_success=v_status,                                                                                                                                                                                                                                                                   
                                              flow_step_result = case                                                                                                                                                                                                                                                                    
                                                when nvl(v_status,'N') = 'Y' then v_result                                                                                                                                                                                                                                                
                                                when v_step_code in ('ociTfApplyJob', 'ociTfCheckStatus') then v_result
                                                else ''                                                                                                                                                                                                                                                                                 
                                              end,                                                                                                                                                                                                                                                                                      
                                              create_result= case when nvl(v_status,'N') <> 'Y' then v_result else '' end,                                                                                                                                                                                                               
                                              object_ocid=v_ocid,                                                                                                                                                                                                                                                                        
                                              create_retry=v_create_retry where id = v_step_id;                                                                                                                                                                                                                                          
              commit;                                                                                                                                                                                                                                                                                                                    
              ll_pkg_log.log(40,'End of update, status is still '||v_status||', current result is still '||v_result);                                                                                                                                                                                                                    
            exception                                                                                                                                                                                                                                                                                                                    
              when others then begin                                                                                                                                                                                                                                                                                                     
                                 v_sqlerrm := SQLERRM;                                                                                                                                                                                                                                                                                   
                                 ll_pkg_log.log(1,'Issue during update: '||v_sqlerrm);                                                                                                                                                                                                                                                   
                               end;                                                                                                                                                                                                                                                                                                      
            end;                                                                                                                                                                                                                                                                                                                         

            if nvl(v_status,'N') = 'N' then                                                                                                                                                                                                                                                                                              
                if v_create_retry != 5 then                                                                                                                                                                                                                                                                                              
                    ll_pkg_log.log(30,'Error detected. Logging now.');                                                                                                                                                                                                                                                                   
                else                                                                                                                                                                                                                                                                                                                     
                    if v_step_code in ('ociTfApplyJob') then                                                                                                                                                                                                                                                                             
                        ll_pkg_log.log(1,'Terraform failure detected, grabbing logs now.');                                                                                                                                                                                                                                               
                        v_tf_log := ' ' || ll_pkg_terraform.fetch_terraform_logs(p_reservation_id);                                                                                                                                                                                                                                      
                    end if;                                                                                                                                                                                                                                                                                                               
                    if v_step_code in ('ociTfApplyJob', 'ociTfCheckStatus') then
                      ll_pkg_terraform.send_terraform_failure_email(
                        p_reservation_id => p_reservation_id,
                        p_log_result     => v_result
                      );
                    end if;
                    declare                                                                                                                                                                                                                                                                                                               
                        v_failures_workshop varchar2(100);                                                                                                                                                                                                                                                                               
                        v_failures_total varchar2(100);                                                                                                                                                                                                                                                                                  
                    begin                                                                                                                                                                                                                                                                                                                
                        -- get failure counts                                                                                                                                                                                                                                                                                            
                        begin                                                                                                                                                                                                                                                                                                            
                            -- Count for specific workshop                                                                                                                                                                                                                                                                               
                            SELECT to_char(COUNT(*)) INTO v_failures_workshop                                                                                                                                                                                                                                                            
                            FROM ll_reservations r                                                                                                                                                                                                                                                                                       
                                INNER JOIN ll_reservation_steps rs ON r.id = rs.reservation_id                                                                                                                                                                                                                                           
                            WHERE rs.create_success = 'N'                                                                                                                                                                                                                                                                                
                                AND rs.create_retry = 5                                                                                                                                                                                                                                                                                  
                                AND rs.create_date >= sysdate - (1/24)                                                                                                                                                                                                                                                                   
                                AND r.workshop_id = workshop_id(p_reservation_id);                                                                                                                                                                                                                                                       

                            -- Count for all workshops                                                                                                                                                                                                                                                                                   
                            SELECT to_char(COUNT(*)) INTO v_failures_total                                                                                                                                                                                                                                                               
                            FROM ll_reservations r                                                                                                                                                                                                                                                                                       
                                INNER JOIN ll_reservation_steps rs ON r.id = rs.reservation_id                                                                                                                                                                                                                                           
                            WHERE rs.create_success = 'N'                                                                                                                                                                                                                                                                                
                                AND rs.create_retry = 5                                                                                                                                                                                                                                                                                  
                                AND rs.create_date >= sysdate - (1/24);                                                                                                                                                                                                                                                                  
                        exception when others then                                                                                                                                                                                                                                                                                       
                            v_failures_workshop := 'Error';                                                                                                                                                                                                                                                                              
                            v_failures_total := 'Error';                                                                                                                                                                                                                                                                                 
                        end;                                                                                                                                                                                                                                                                                                             
                        ll_pkg_log.log(30,'Reservation failure detected. Sending alerts!');                                                                                                                                                                                                                                              
                        ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR',                                                                                                                                                                                                                                                          
                                                p_event      => 'Create step error',                                                                                                                                                                                                                                                     
                                                p_message    => substr('Reservation: '||p_reservation_id ||chr(10)||                                                                                                                                                                                                                     
                                                                       'Step code: '||v_step_code||chr(10)||                                                                                                                                                                                                                             
                                                                       'Workshop ID: '|| ll_pkg_reservation.workshop_id(p_reservation_id) ||chr(10)||                                                                                                                                                                                    
                                                                       'Event ID: '|| nvl(TO_CHAR(ll_pkg_reservation.event_id(p_reservation_id)), 'None')  ||chr(10)||                                                                                                                                                                   
                                                                       'Tenancy: ' || ll_pkg_reservation.tenancy_name(ll_pkg_reservation.tenancy_id(p_reservation_id)) ||chr(10)||                                                                                                                                                       
                                                                       'Region: ' || ll_pkg_admin.region_name(ll_pkg_reservation.region_id(p_reservation_id)) ||chr(10)||                                                                                                                                                                
                                                                       'Workshop Failures (past hour): ' || v_failures_workshop || chr(10) ||                                                                                                                                                                                            
                                                                       'Total Failures (past hour): ' || v_failures_total || chr(10) ||                                                                                                                                                                                                  
                                                                       'Result: '||v_result || chr(10) || v_tf_log,1,10000),                                                                                                                                                                                                             
                                                p_priority   => 1);                                                                                                                                                                                                                                                                      
                                              -- Added by Madhu ---                                                                                                                                                                                                                                                                      
                        ll_pkg_log.log(30,'Error detected, sending mail to livelabs-support_us');                                                                                                                                                                                                                                        
                            APEX_MAIL.SEND(                                                                                                                                                                                                                                                                                              
                                    p_to        => 'livelabs-support_us@oracle.com',                                                                                                                                                                                                                                                     
                                    p_from      => 'noreply@oracle.com', -- email change                                                                                                                                                                                                                                                 
                                    p_subj      => 'Error detected in Reservation ',                                                                                                                                                                                                                                                     
                                    p_body      => substr('Reservation: '||p_reservation_id||chr(13)||chr(10)||                                                                                                                                                                                                                          
                                                                       'Step code: '||v_step_code||chr(13)||chr(10)||                                                                                                                                                                                                                    
                                                                       'Step id: '||v_step_id||chr(13)||chr(10)||                                                                                                                                                                                                                        
                                                                       'Create Retry: '||v_create_retry||chr(13)||chr(10)||                                                                                                                                                                                                              
                                                                                           'Result: '||v_result,1,10000));                                                                                                                                                                                                               
                    end;                                                                                                                                                                                                                                                                                                                 
                end if;                                                                                                                                                                                                                                                                                                                  

                  -- Added by Madhu ---                                                                                                                                                                                                                                                                                                  
            end if;                                                                                                                                                                                                                                                                                                                      
            ll_pkg_log.log(40,'Checking for build error on Terraform');                                                                                                                                                                                                                                                                  
            if nvl(v_status,'N') = 'N' and v_create_retry = 5 then                                                                                                                                                                                                                                                                       
              if ll_pkg_admin.system_parameter('BUILD_ERROR_SEND_EMAIL') = 'Y' then                                                                                                                                                                                                                                                      
                -- Send an email to attendee and livelabs(-admin)_us@oracle.com                                                                                                                                                                                                                                                          
                ll_pkg_apex.send_template_email (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                   
                                                 p_phase          => 'BUILD_ERROR',                                                                                                                                                                                                                                                      
                                                 p_status         => v_dummy_status,                                                                                                                                                                                                                                                     
                                                 p_result         => v_dummy_result);                                                                                                                                                                                                                                                    
                ll_pkg_log.log(1,'Error during reservation build - Email send for reservation '||p_reservation_id);                                                                                                                                                                                                                      
              end if;                                                                                                                                                                                                                                                                                                                    
              if ll_pkg_admin.system_parameter('BUILD_ERROR_CHANGE_OWNER') = 'Y' then                                                                                                                                                                                                                                                    
                -- Change the owner1 email address so that it does not add to his/her account                                                                                                                                                                                                                                            
                update ll_reservations set owner1= case when substr(owner1,1,5)='ERROR' then null else 'ERROR-'||owner1 end where id = p_reservation_id;                                                                                                                                                                                 
                commit;                                                                                                                                                                                                                                                                                                                  
                ll_pkg_log.log(1,'Error during reservation build - Owner renamed for reservation '||p_reservation_id);                                                                                                                                                                                                                   
              end if;                                                                                                                                                                                                                                                                                                                    
            end if;                                                                                                                                                                                                                                                                                                                      
            ll_pkg_log.log(40,'Checking for status W (Wait)');                                                                                                                                                                                                                                                                           
            if v_status = 'W' then                                                                                                                                                                                                                                                                                                       
              ll_pkg_log.log(40,'Status W detected');                                                                                                                                                                                                                                                                                    
              v_run_again := 'N';                                                                                                                                                                                                                                                                                                        
              ll_pkg_admin.create_job (p_type        => 'RESTART_RESERVATION',                                                                                                                                                                                                                                                           
                                       p_parameters  => json_object( 'P1' value p_reservation_id),                                                                                                                                                                                                                                       
                                       p_jobname     => 'RESWAIT_'||p_reservation_id,                                                                                                                                                                                                                                                    
                                       p_start_date  => sysdate + ( to_number(v_result) / 60 / 24) );                                                                                                                                                                                                                                    
              ll_pkg_log.log(40,'Status is W (Waiting), run_again to N, new job created');                                                                                                                                                                                                                                               
            end if;                                                                                                                                                                                                                                                                                                                      

            ll_pkg_log.log(30,'After update of ll_reservation');                                                                                                                                                                                                                                                                         
          end if;                                                                                                                                                                                                                                                                                                                        

          close c_res_steps;                                                                                                                                                                                                                                                                                                             
          ll_pkg_log.log(40,'Before Commit');                                                                                                                                                                                                                                                                                            
          commit;                                                                                                                                                                                                                                                                                                                        
          ll_pkg_log.log(40,'End of commit');                                                                                                                                                                                                                                                                                            

          if v_status='N' then                                                                                                                                                                                                                                                                                                           
            apex_util.pause(2);                                                                                                                                                                                                                                                                                                          
          end if;                                                                                                                                                                                                                                                                                                                        
          ll_pkg_log.log(30,'Information committed.');                                                                                                                                                                                                                                                                                   
        else                                                                                                                                                                                                                                                                                                                             
          close c_res_steps;                                                                                                                                                                                                                                                                                                             
        end if;                                                                                                                                                                                                                                                                                                                          
      end if;                                                                                                                                                                                                                                                                                                                            
      ll_pkg_log.log(40,'RUN_AGAIN = '||v_run_again);                                                                                                                                                                                                                                                                                    

    end loop;                                                                                                                                                                                                                                                                                                                            

    ll_pkg_log.log(30,'End of loop.');                                                                                                                                                                                                                                                                                                   
    ll_pkg_log.log(20,'End of call.');                                                                                                                                                                                                                                                                                                   

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ######## #### ##    ## ########        ###    ##     ##    ###    #### ##          ######## ######## ##    ##    ###     ######  ##    ##                                                                                                                                                                                            
--  ##        ##  ###   ## ##     ##      ## ##   ##     ##   ## ##    ##  ##             ##    ##       ###   ##   ## ##   ##    ##  ##  ##                                                                                                                                                                                             
--  ##        ##  ####  ## ##     ##     ##   ##  ##     ##  ##   ##   ##  ##             ##    ##       ####  ##  ##   ##  ##         ####                                                                                                                                                                                              
--  ######    ##  ## ## ## ##     ##    ##     ## ##     ## ##     ##  ##  ##             ##    ######   ## ## ## ##     ## ##          ##                                                                                                                                                                                               
--  ##        ##  ##  #### ##     ##    #########  ##   ##  #########  ##  ##             ##    ##       ##  #### ######### ##          ##                                                                                                                                                                                               
--  ##        ##  ##   ### ##     ##    ##     ##   ## ##   ##     ##  ##  ##             ##    ##       ##   ### ##     ## ##    ##    ##                                                                                                                                                                                               
--  ##       #### ##    ## ########     ##     ##    ###    ##     ## #### ########       ##    ######## ##    ## ##     ##  ######     ##                                                                                                                                                                                               
--                                                                                                                                                                                                                                                                                                                                       
   procedure find_available_tenancy (p_tenancy_id OUT number, p_region_id OUT number, p_available_json OUT CLOB, p_workshop_id IN number default null, p_event_id IN number default null, p_res_id IN number default null) is                                                                                                            
     PRAGMA AUTONOMOUS_TRANSACTION;                                                                                                                                                                                                                                                                                                      
     v_status               varchar2(100);                                                                                                                                                                                                                                                                                               
     v_status_desc          varchar2(4000);                                                                                                                                                                                                                                                                                              
     v_param_filled         number;                                                                                                                                                                                                                                                                                                      
     v_res_busy             varchar2(1);                                                                                                                                                                                                                                                                                                 
     v_res_busy_count       number;                                                                                                                                                                                                                                                                                                      

     v_tr_json              clob;                                                                                                                                                                                                                                                                                                        

     v_workshop_id          number;                                                                                                                                                                                                                                                                                                      
     v_event_id             number;                                                                                                                                                                                                                                                                                                      
     v_tenancy_id           number;                                                                                                                                                                                                                                                                                                      
     v_region_id            number;                                                                                                                                                                                                                                                                                                      
     v_rank_info            number;                                                                                                                                                                                                                                                                                                      
     v_extra_required       number;                                                                                                                                                                                                                                                                                                      

     v_tenancies_allowed    varchar2(1000);                                                                                                                                                                                                                                                                                              
     v_regions_allowed      varchar2(1000);                                                                                                                                                                                                                                                                                              
     v_workshop_regions_set varchar2(1) := 'N';                                                                                                                                                                                                                                                                                          

     v_username             varchar2(200);                                                                                                                                                                                                                                                                                               
     v_country_code         varchar2(20);                                                                                                                                                                                                                                                                                                

     v_clob_available       clob;                                                                                                                                                                                                                                                                                                        
     v_clob                 clob;                                                                                                                                                                                                                                                                                                        

     procedure do_log (p_location varchar2 default null) is                                                                                                                                                                                                                                                                              

       v_clob    clob;                                                                                                                                                                                                                                                                                                                   
       v_num_ws  number;                                                                                                                                                                                                                                                                                                                 

     begin                                                                                                                                                                                                                                                                                                                               

       ll_pkg_log.log(20,'Initial request, p_workshop_id: '||p_workshop_id||', p_event_id: '||p_event_id||', p_res_id: '||p_res_id);                                                                                                                                                                                                     

       for x in (select p_location || ' - ' ||tenancy_id || ' ('||environments||')' as environments                                                                                                                                                                                                                                      
                 from ( select tenancy_id, LISTAGG(region_id, ', ') WITHIN GROUP (ORDER BY region_id) as environments                                                                                                                                                                                                                    
                        from (select distinct tenancy_id, region_id from ll_find_tenancy_temp)                                                                                                                                                                                                                                           
                        group by tenancy_id) ) loop                                                                                                                                                                                                                                                                                      
         v_clob := v_clob || x.environments || chr(10);                                                                                                                                                                                                                                                                                  
       end loop;                                                                                                                                                                                                                                                                                                                         

       ll_pkg_log.log(40,v_clob);                                                                                                                                                                                                                                                                                                        
     end;                                                                                                                                                                                                                                                                                                                                

   begin                                                                                                                                                                                                                                                                                                                                 

     ll_pkg_log.log(20,'Initial request, p_workshop_id: '||p_workshop_id||', p_event_id: '||p_event_id||', p_res_id: '||p_res_id);                                                                                                                                                                                                       
   -- Check if any IN parameter has been filled or more than 1                                                                                                                                                                                                                                                                           

     v_param_filled := case when length(p_workshop_id) > 0 then 1 else 0 end +                                                                                                                                                                                                                                                           
                       case when length(p_event_id)    > 0 then 1 else 0 end +                                                                                                                                                                                                                                                           
                       case when length(p_res_id)      > 0 then 1 else 0 end;                                                                                                                                                                                                                                                            

     if v_param_filled = 0 then                                                                                                                                                                                                                                                                                                          
       v_status      := 'ERROR';                                                                                                                                                                                                                                                                                                         
       v_status_desc := 'No value entered for workshop, event code or reservation ID';                                                                                                                                                                                                                                                   
     elsif v_param_filled > 1 then                                                                                                                                                                                                                                                                                                       
       v_status      := 'ERROR';                                                                                                                                                                                                                                                                                                         
       v_status_desc := 'Can only use 1 IN parameter (workshop_id, event_code or res_id)';                                                                                                                                                                                                                                               
     end if;                                                                                                                                                                                                                                                                                                                             

    /* Based on the parameters passed in figure out if there is a specific tenancy/region based on workshop, event, or reservation */                                                                                                                                                                                                    
     if p_res_id is not null then                                                                                                                                                                                                                                                                                                        
       ll_pkg_log.log(40,'p_res_id: '||p_res_id);                                                                                                                                                                                                                                                                                        
       select workshop_id, voucher_id, tenancy_id, region_id into v_workshop_id, v_event_id, v_tenancy_id, v_region_id from ll_reservations where id = p_res_id;                                                                                                                                                                         
       ll_pkg_log.log(40,'Check 1: v_workshop_id: '||v_workshop_id||' v_event_id: '||v_event_id||' v_tenancy_id: '||v_tenancy_id||' v_region_id: '||v_region_id);                                                                                                                                                                        
     end if;                                                                                                                                                                                                                                                                                                                             
     if v_event_id is null and p_event_id is not null then                                                                                                                                                                                                                                                                               
       v_event_id := p_event_id;                                                                                                                                                                                                                                                                                                         
     end if;                                                                                                                                                                                                                                                                                                                             

     if v_event_id is not null and (v_workshop_id is null or v_tenancy_id is null) then                                                                                                                                                                                                                                                  
       ll_pkg_log.log(40,'v_event_id: '||v_event_id);                                                                                                                                                                                                                                                                                    
       select workshop_id, id, tenancy_id, region_id into v_workshop_id, v_event_id, v_tenancy_id, v_region_id from ll_vouchers where id = v_event_id;                                                                                                                                                                                   
       ll_pkg_log.log(40,'Check 2: v_workshop_id: '||v_workshop_id||' v_event_id: '||v_event_id||' v_tenancy_id: '||v_tenancy_id||' v_region_id: '||v_region_id);                                                                                                                                                                        
     end if;                                                                                                                                                                                                                                                                                                                             
     if v_workshop_id is null and p_workshop_id is not null then                                                                                                                                                                                                                                                                         
       v_workshop_id := p_workshop_id;                                                                                                                                                                                                                                                                                                   
       ll_pkg_log.log(40,'v_workshop_id based on p_workshop_id');                                                                                                                                                                                                                                                                        
     end if;                                                                                                                                                                                                                                                                                                                             

   -- WORKSHOP_ID is not null: find tenancy list for this workshop                                                                                                                                                                                                                                                                       
        if p_workshop_id is not null or (v_tenancy_id is null and v_workshop_id is not null) then                                                                                                                                                                                                                                        
       ll_pkg_log.log(40,'p_workshop_id: '||p_workshop_id||', v_workshop_id: '||v_workshop_id);                                                                                                                                                                                                                                          
       select tenancies_allowed into v_tenancies_allowed from ll_workshops where id = v_workshop_id;                                                                                                                                                                                                                                     
       ll_pkg_log.log(40,'Check 3: v_tenancies_allowed: '||v_tenancies_allowed);                                                                                                                                                                                                                                                         
     end if;                                                                                                                                                                                                                                                                                                                             
    /* Fill in table with tenancy, region, resource combos required by the workshop and their quantities */                                                                                                                                                                                                                              
    insert into ll_find_tenancy_temp (tenancy_id, region_id, resource_id, resource_required, PREFERENCE_POINTS, resource_used, resource_available, resource_tenancy)                                                                                                                                                                     
    select lt.id, lor.id, llwr.resource_id, llwr.environments, 100, llra.num_reserved, llra.num_available, llra.num_provided                                                                                                                                                                                                             
    from ll_tenancies lt, ll_oci_regions lor, LL_WS_RESOURCES_REQUIRED_VW llwr, ll_res_available_vw llra                                                                                                                                                                                                                                 
    where llwr.workshop_id = v_workshop_id                                                                                                                                                                                                                                                                                               
    and nvl(lt.active_flg,'Y') = 'Y'                                                                                                                                                                                                                                                                                                     
    and nvl(lor.active_flg,'Y') = 'Y'                                                                                                                                                                                                                                                                                                    
    and llra.tenancy_id = lt.id                                                                                                                                                                                                                                                                                                          
    and llra.region_id = lor.id                                                                                                                                                                                                                                                                                                          
    and llra.resource_id = llwr.resource_id                                                                                                                                                                                                                                                                                              
    and llra.num_available > 0;                                                                                                                                                                                                                                                                                                          
  /* Remove all of the tenancies and regions that do not have enough resources */                                                                                                                                                                                                                                                        
  delete from ll_find_tenancy_temp where resource_required > nvl(resource_available, 0);                                                                                                                                                                                                                                                 

  /* Remove all of the tenancies and regions that do not satisfy all of the resources */                                                                                                                                                                                                                                                 
--   for y in (select distinct resource_id from ll_find_tenancy_temp) loop                                                                                                                                                                                                                                                               
    for y in (select distinct resource_id from LL_WS_RESOURCES_REQUIRED_VW where workshop_id = v_workshop_id) loop                                                                                                                                                                                                                       
  delete from ll_find_tenancy_temp a where (a.tenancy_id, a.region_id) not in                                                                                                                                                                                                                                                            
     (select distinct b.tenancy_id, b.region_id                                                                                                                                                                                                                                                                                          
     from ll_find_tenancy_temp b                                                                                                                                                                                                                                                                                                         
     where b.resource_id = y.resource_id);                                                                                                                                                                                                                                                                                               
  end loop;                                                                                                                                                                                                                                                                                                                              
/* If a workshop can only run on specific tenancies */                                                                                                                                                                                                                                                                                   
if v_tenancy_id is null and v_tenancies_allowed is not null then                                                                                                                                                                                                                                                                         
  ll_pkg_log.log(40,'Multiplying preference points by 2 because v_tenancies_allowed was set to '||v_tenancies_allowed);                                                                                                                                                                                                                  
     update ll_find_tenancy_temp set preference_points = preference_points*3 where ':'||v_tenancies_allowed||':' like '%:'||tenancy_id||':%';                                                                                                                                                                                            
  end if;                                                                                                                                                                                                                                                                                                                                
/* If a workshop can only run in specific regions */                                                                                                                                                                                                                                                                                     
/*                                                                                                                                                                                                                                                                                                                                       
  select count(*) into v_workshop_regions_set from ll_workshop_regions where workshop_id = v_workshop_id;                                                                                                                                                                                                                                

     if v_workshop_regions_set > 0 then                                                                                                                                                                                                                                                                                                  
       update ll_find_tenancy_temp a set preference_points = preference_points*2 where exists (select null from ll_workshop_regions b where a.tenancy_id = b.tenancy_id and a.region_id = b.region_id and b.workshop_id = v_workshop_id);                                                                                                
     end if;                                                                                                                                                                                                                                                                                                                             
*/                                                                                                                                                                                                                                                                                                                                       
/* Update if we have a tenancy based on the parameters passed in */                                                                                                                                                                                                                                                                      
if(v_tenancy_id is not null) then                                                                                                                                                                                                                                                                                                        
  ll_pkg_log.log(40,'Mulitplying preference points by 5 because v_tenancy_id was set to'||v_tenancy_id);                                                                                                                                                                                                                                 
  update ll_find_tenancy_temp set preference_points = preference_points*5 where tenancy_id = v_tenancy_id;                                                                                                                                                                                                                               
end if;                                                                                                                                                                                                                                                                                                                                  
/* Update if we have a region based on the logic above */                                                                                                                                                                                                                                                                                
if(v_region_id is not null and v_tenancy_id is not null) then                                                                                                                                                                                                                                                                            
ll_pkg_log.log(40,'Mulitplying preference points by 1.2 because v_tenancy_id was set to '||v_tenancy_id||' and v_region_id was set to'||v_region_id);                                                                                                                                                                                    
update ll_find_tenancy_temp set preference_points = preference_points*1.20 where region_id = v_region_id and tenancy_id = v_tenancy_id;                                                                                                                                                                                                  
end if;                                                                                                                                                                                                                                                                                                                                  

/* Find out how many reservations in the past 2.4 hours and in the next 2.4 hours to see if the system is busy */                                                                                                                                                                                                                        
select count(*) into v_res_busy_count                                                                                                                                                                                                                                                                                                    
from ll_reservations_vw                                                                                                                                                                                                                                                                                                                  
where start_gmt > sysdate -.1                                                                                                                                                                                                                                                                                                            
and start_gmt < sysdate +.1;                                                                                                                                                                                                                                                                                                             

v_res_busy := 'N';                                                                                                                                                                                                                                                                                                                       

if (v_res_busy_count > nvl(ll_pkg_admin.system_parameter('RESERVATION_BUSY_COUNT'),100) )                                                                                                                                                                                                                                                
then v_res_busy := 'Y';                                                                                                                                                                                                                                                                                                                  
end if;                                                                                                                                                                                                                                                                                                                                  

/* Update if for the weight score from ll_tenancies minus the active reservations */                                                                                                                                                                                                                                                     
for x in (select llt.id tenancy_id, decode(v_res_busy, 'Y',80,llt.preference_weight)-nvl(llra.res_count,0) pref_weight                                                                                                                                                                                                                   
from ll_tenancies llt, (select tenancy_id, count(*) res_count from ll_reservations_vw llr where active_flg = 'Y' and start_date > sysdate - 1 group by tenancy_id) llra                                                                                                                                                                  
where llt.id = llra.tenancy_id (+)                                                                                                                                                                                                                                                                                                       
and llt.is_public='Y') loop                                                                                                                                                                                                                                                                                                              
if(x.pref_weight > 0) then                                                                                                                                                                                                                                                                                                               
ll_pkg_log.log(40,'Adding '||x.pref_weight||' to '||x.tenancy_id||' to weight it from ll_tenancies');                                                                                                                                                                                                                                    
update ll_find_tenancy_temp a set a.preference_points = a.preference_points+x.pref_weight where a.tenancy_id = x.tenancy_id;                                                                                                                                                                                                             
end if;                                                                                                                                                                                                                                                                                                                                  
end loop;                                                                                                                                                                                                                                                                                                                                

/* Update preference points if tenancy is public */                                                                                                                                                                                                                                                                                      
update ll_find_tenancy_temp lftt set preference_points = preference_points*1.60 where exists                                                                                                                                                                                                                                             
(select 'x'                                                                                                                                                                                                                                                                                                                              
from ll_tenancies lt                                                                                                                                                                                                                                                                                                                     
where lftt.tenancy_id = lt.id                                                                                                                                                                                                                                                                                                            
and lt.is_public = 'Y');                                                                                                                                                                                                                                                                                                                 

   -- Determine best tenancy/region for the workshop                                                                                                                                                                                                                                                                                     



     if p_res_id is not null then                                                                                                                                                                                                                                                                                                        

       select owner1 into v_username from ll_reservations where id = p_res_id;                                                                                                                                                                                                                                                           

       ll_pkg_log.log(40,'v_username: '||v_username || ' p_res_id: ' || p_res_id);                                                                                                                                                                                                                                                       

       begin                                                                                                                                                                                                                                                                                                                             
         v_country_code := ll_pkg_admin.get_country (v_username);                                                                                                                                                                                                                                                                        
       exception                                                                                                                                                                                                                                                                                                                         
         when OTHERS then begin                                                                                                                                                                                                                                                                                                          
                            ll_pkg_log.log(40,'No valid country found for user '||v_username);                                                                                                                                                                                                                                           
                            v_country_code := '';                                                                                                                                                                                                                                                                                        
                          end;                                                                                                                                                                                                                                                                                                           
       end;                                                                                                                                                                                                                                                                                                                              
       ll_pkg_log.log(40,'v_username: '||v_username || ' v_country_code: ' || v_country_code);                                                                                                                                                                                                                                           
       if v_country_code is not null then                                                                                                                                                                                                                                                                                                


       ll_pkg_log.log(40,'v_username: '||v_username || ' v_country_code: ' || v_country_code);                                                                                                                                                                                                                                           

       for x in (select myrank myrank, id                                                                                                                                                                                                                                                                                                
                                                                                        from ( select id, distance, DENSE_RANK() over (ORDER BY distance desc) as myrank                                                                                                                                                                 
                                                                                               from ( select id, ceil(ll_pkg_admin.distance_country_dc (p_country_code => v_country_code, p_region_id => id)) as distance                                                                                                                
                                                                                                      from ll_oci_regions)                                                                                                                                                                                                               
                                                                                             )  )                                                                                                                                                                                                                                        
       loop                                                                                                                                                                                                                                                                                                                              
          ll_pkg_log.log(40,'region: '||x.id || ' v_country_code: ' || v_country_code||' myrank '||x.myrank);                                                                                                                                                                                                                            
          update ll_find_tenancy_temp a set a.preference_points = a.preference_points + x.myrank where a.region_id = x.id;                                                                                                                                                                                                               
        end loop;                                                                                                                                                                                                                                                                                                                        

       end if;                                                                                                                                                                                                                                                                                                                           

     end if;                                                                                                                                                                                                                                                                                                                             


     do_log('After preference points');                                                                                                                                                                                                                                                                                                  

   -- Build a list of how many environments we can run for this setup (this makes live easier when scheduling things)                                                                                                                                                                                                                    

     ll_pkg_log.log(40,'Build a list of how many environments we can run for this WS');                                                                                                                                                                                                                                                  

     for x in (select tenancy_id,                                                                                                                                                                                                                                                                                                        
                            region_id,                                                                                                                                                                                                                                                                                                   
                            case when sum(preference_points) <= 0 then 0 else sum(case when resource_available/resource_required <= 0 then 0 else floor(resource_available/resource_required) end) end environments,                                                                                                                     
                            sum(preference_points) as preference_points                                                                                                                                                                                                                                                                  
                     from ll_find_tenancy_temp group by tenancy_id, region_id) loop                                                                                                                                                                                                                                                      

       ll_pkg_log.log(40,'Tenancy: '||x.tenancy_id||', region: '||x.region_id||', environments: '||x.environments||', preference points: '||x.preference_points);                                                                                                                                                                        
     end loop;                                                                                                                                                                                                                                                                                                                           


     p_available_json := '[';                                                                                                                                                                                                                                                                                                            

     for x in (select tenancy_id, region_id, environments, preference_points                                                                                                                                                                                                                                                             
               from (select tenancy_id,                                                                                                                                                                                                                                                                                                  
                            region_id,                                                                                                                                                                                                                                                                                                   
                            case when sum(preference_points) <= 0 then 0 else sum(case when resource_available/resource_required <= 0 then 0 else floor(resource_available/resource_required) end) end environments,                                                                                                                     
                            sum(preference_points) as preference_points                                                                                                                                                                                                                                                                  
                     from ll_find_tenancy_temp group by tenancy_id, region_id)                                                                                                                                                                                                                                                           
               where environments > 0                                                                                                                                                                                                                                                                                                    
               order by preference_points desc) loop                                                                                                                                                                                                                                                                                     

       if substr(p_available_json,length(p_available_json),1) = '}' then                                                                                                                                                                                                                                                                 
         p_available_json := p_available_json || ',';                                                                                                                                                                                                                                                                                    
       end if;                                                                                                                                                                                                                                                                                                                           

       p_available_json := p_available_json || JSON_OBJECT ('tenancy_id'        value x.tenancy_id,                                                                                                                                                                                                                                      
                                                            'region_id'         value x.region_id,                                                                                                                                                                                                                                       
                                                            'environments'      value x.environments,                                                                                                                                                                                                                                    
                                                            'preference_points' value x.preference_points );                                                                                                                                                                                                                             

     -- The values are ordered in preference points so the first tenancy that comes out should be the best tenancy.                                                                                                                                                                                                                      
       if p_tenancy_id is null then                                                                                                                                                                                                                                                                                                      
         ll_pkg_log.log(40,'Finding initial tenancy for the request');                                                                                                                                                                                                                                                                   

         p_tenancy_id := x.tenancy_id;                                                                                                                                                                                                                                                                                                   
         p_region_id := x.region_id;                                                                                                                                                                                                                                                                                                     
       end if;                                                                                                                                                                                                                                                                                                                           

     end loop;                                                                                                                                                                                                                                                                                                                           

     p_available_json := p_available_json || ']';                                                                                                                                                                                                                                                                                        

     commit;                                                                                                                                                                                                                                                                                                                             

     ll_pkg_log.log(40, 'p_tenancy_id: '||p_tenancy_id||', p_region_id: '||p_region_id||', p_available_json: '||p_available_json);                                                                                                                                                                                                       

     ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                   

   end;                                                                                                                                                                                                                                                                                                                                  
  procedure find_available_tenancy_bkp (p_tenancy_id OUT number, p_region_id OUT number, p_available_json OUT CLOB, p_workshop_id IN number default null, p_event_id IN number default null, p_res_id IN number default null) is                                                                                                         
    PRAGMA AUTONOMOUS_TRANSACTION;                                                                                                                                                                                                                                                                                                       
    v_status               varchar2(100);                                                                                                                                                                                                                                                                                                
    v_status_desc          varchar2(4000);                                                                                                                                                                                                                                                                                               
    v_param_filled         number;                                                                                                                                                                                                                                                                                                       

    v_tr_json              clob;                                                                                                                                                                                                                                                                                                         
    v_workshop_id          number;                                                                                                                                                                                                                                                                                                       
    v_event_id             number;                                                                                                                                                                                                                                                                                                       
    v_tenancy_id           number;                                                                                                                                                                                                                                                                                                       
    v_region_id            number;                                                                                                                                                                                                                                                                                                       
    v_rank_info            number;                                                                                                                                                                                                                                                                                                       

    v_tenancies_allowed    varchar2(1000);                                                                                                                                                                                                                                                                                               
    v_regions_allowed      varchar2(1000);                                                                                                                                                                                                                                                                                               
    v_workshop_regions_set varchar2(1) := 'N';                                                                                                                                                                                                                                                                                           
    v_username             varchar2(200);                                                                                                                                                                                                                                                                                                
    v_country_code         varchar2(20);                                                                                                                                                                                                                                                                                                 
    v_clob_available       clob;                                                                                                                                                                                                                                                                                                         
    v_clob                 clob;                                                                                                                                                                                                                                                                                                         
    procedure do_log (p_location varchar2 default null) is                                                                                                                                                                                                                                                                               
      v_clob    clob;                                                                                                                                                                                                                                                                                                                    
      v_num_ws  number;                                                                                                                                                                                                                                                                                                                  
    begin                                                                                                                                                                                                                                                                                                                                
      ll_pkg_log.log(20,'Initial request, p_workshop_id: '||p_workshop_id||', p_event_id: '||p_event_id||', p_res_id: '||p_res_id);                                                                                                                                                                                                      
      for x in (select p_location || ' - ' ||tenancy_id || ' ('||environments||')' as environments                                                                                                                                                                                                                                       
                from ( select tenancy_id, LISTAGG(region_id, ', ') WITHIN GROUP (ORDER BY region_id) as environments                                                                                                                                                                                                                     
                       from (select distinct tenancy_id, region_id from ll_find_tenancy_temp)                                                                                                                                                                                                                                            
                       group by tenancy_id) ) loop                                                                                                                                                                                                                                                                                       
        v_clob := v_clob || x.environments || chr(10);                                                                                                                                                                                                                                                                                   
      end loop;                                                                                                                                                                                                                                                                                                                          
      ll_pkg_log.log(40,v_clob);                                                                                                                                                                                                                                                                                                         
    end;                                                                                                                                                                                                                                                                                                                                 
  begin                                                                                                                                                                                                                                                                                                                                  
    ll_pkg_log.log(20,'Initial request, p_workshop_id: '||p_workshop_id||', p_event_id: '||p_event_id||', p_res_id: '||p_res_id);                                                                                                                                                                                                        
  -- Check if any IN parameter has been filled or more than 1                                                                                                                                                                                                                                                                            

    v_param_filled := case when length(p_workshop_id) > 0 then 1 else 0 end +                                                                                                                                                                                                                                                            
                      case when length(p_event_id)    > 0 then 1 else 0 end +                                                                                                                                                                                                                                                            
                      case when length(p_res_id)      > 0 then 1 else 0 end;                                                                                                                                                                                                                                                             

    if v_param_filled = 0 then                                                                                                                                                                                                                                                                                                           
      v_status      := 'ERROR';                                                                                                                                                                                                                                                                                                          
      v_status_desc := 'No value entered for workshop, event code or reservation ID';                                                                                                                                                                                                                                                    
    elsif v_param_filled > 1 then                                                                                                                                                                                                                                                                                                        
      v_status      := 'ERROR';                                                                                                                                                                                                                                                                                                          
      v_status_desc := 'Can only use 1 IN parameter (workshop_id, event_code or res_id)';                                                                                                                                                                                                                                                
    end if;                                                                                                                                                                                                                                                                                                                              
  -- Start finding out the mandatory or restricting values for tenancy_id and region_id.                                                                                                                                                                                                                                                 
  -- RES_ID is not null: find workshop_id, event_code and if present the pre-stated tenancy_id and region_id when resid has been filled                                                                                                                                                                                                  
    if p_res_id is not null then                                                                                                                                                                                                                                                                                                         
      ll_pkg_log.log(40,'p_res_id: '||p_res_id);                                                                                                                                                                                                                                                                                         
      select workshop_id, voucher_id, tenancy_id, region_id into v_workshop_id, v_event_id, v_tenancy_id, v_region_id from ll_reservations where id = p_res_id;                                                                                                                                                                          
      ll_pkg_log.log(40,'Check 1: v_workshop_id: '||v_workshop_id||' v_event_id: '||v_event_id||' v_tenancy_id: '||v_tenancy_id||' v_region_id: '||v_region_id);                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
  -- EVENT_CODE is not null: find the tenancy, the workshop_id, any tenancy_id and region_id for this event                                                                                                                                                                                                                              
    if v_event_id is null and p_event_id is not null then                                                                                                                                                                                                                                                                                
      v_event_id := p_event_id;                                                                                                                                                                                                                                                                                                          
    end if;                                                                                                                                                                                                                                                                                                                              
    if v_event_id is not null and (v_workshop_id is null or v_tenancy_id is null) then                                                                                                                                                                                                                                                   
      ll_pkg_log.log(40,'v_event_id: '||v_event_id);                                                                                                                                                                                                                                                                                     
      select workshop_id, id, tenancy_id, region_id into v_workshop_id, v_event_id, v_tenancy_id, v_region_id from ll_vouchers where id = v_event_id;                                                                                                                                                                                    
      ll_pkg_log.log(40,'Check 2: v_workshop_id: '||v_workshop_id||' v_event_id: '||v_event_id||' v_tenancy_id: '||v_tenancy_id||' v_region_id: '||v_region_id);                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
  -- If v_workshop_id is null but p_workshop_id is filled, sync values                                                                                                                                                                                                                                                                   
    if v_workshop_id is null and p_workshop_id is not null then                                                                                                                                                                                                                                                                          
      v_workshop_id := p_workshop_id;                                                                                                                                                                                                                                                                                                    
      ll_pkg_log.log(40,'v_workshop_id based on p_workshop_id');                                                                                                                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
  -- WORKSHOP_ID is not null: find tenancy list for this workshop                                                                                                                                                                                                                                                                        
  -- This situation will happen (a) if we call the system with p_workshop_id or (b) if the RES_ID and EVENT_ID did not yield any limiting tenancy ids (and we do have a workshop id)                                                                                                                                                     
    if p_workshop_id is not null or (v_tenancy_id is null and v_workshop_id is not null) then                                                                                                                                                                                                                                            
      ll_pkg_log.log(40,'p_workshop_id: '||p_workshop_id||', v_workshop_id: '||v_workshop_id);                                                                                                                                                                                                                                           
      select tenancies_allowed into v_tenancies_allowed from ll_workshops where id = v_workshop_id;                                                                                                                                                                                                                                      
      ll_pkg_log.log(40,'Check 3: v_tenancies_allowed: '||v_tenancies_allowed);                                                                                                                                                                                                                                                          
    end if;                                                                                                                                                                                                                                                                                                                              
  -- Here gather all tenancy/region combinations with the resources needed. This will be a big table                                                                                                                                                                                                                                     
    ll_pkg_log.log(40,'Running insert with v_workshop_id: '||v_workshop_id);                                                                                                                                                                                                                                                             
    insert into ll_find_tenancy_temp (tenancy_id, region_id, resource_id, resource_required)                                                                                                                                                                                                                                             
      select lt.id, lor.id, llwr.resource_id, llwr.environments                                                                                                                                                                                                                                                                          
      from ll_tenancies lt, ll_oci_regions lor, LL_WS_RESOURCES_REQUIRED_VW llwr                                                                                                                                                                                                                                                         
      where llwr.workshop_id = v_workshop_id                                                                                                                                                                                                                                                                                             
      and nvl(lt.active_flg,'Y') = 'Y'                                                                                                                                                                                                                                                                                                   
      and nvl(lor.active_flg,'Y') = 'Y';                                                                                                                                                                                                                                                                                                 
  do_log('Insert resources required');                                                                                                                                                                                                                                                                                                   

  -- Restrict tenancies when reservation or event code already has a setting.                                                                                                                                                                                                                                                            
    if v_tenancy_id is not null then                                                                                                                                                                                                                                                                                                     
      delete ll_find_tenancy_temp where tenancy_id <> v_tenancy_id;                                                                                                                                                                                                                                                                      
    end if;                                                                                                                                                                                                                                                                                                                              
  do_log('Tenancy deleted reservation level');                                                                                                                                                                                                                                                                                           
  -- Restrict region(s) when reservation or event code already has a setting.                                                                                                                                                                                                                                                            
    if v_region_id is not null then                                                                                                                                                                                                                                                                                                      
      delete ll_find_tenancy_temp where region_id <> v_region_id;                                                                                                                                                                                                                                                                        
    end if;                                                                                                                                                                                                                                                                                                                              
  do_log('Region deleted reservation level');                                                                                                                                                                                                                                                                                            
  -- Restrict tenancies when it was set on workshop level (but only if v_tenancy_id is null)                                                                                                                                                                                                                                             
  -- This doesn't work if there is more than one because the string would be 6:5 and nothing matches that. Need to cycle through the array of tenancies allowed deleting the ones not in it                                                                                                                                              
    if v_tenancy_id is null and v_tenancies_allowed is not null then                                                                                                                                                                                                                                                                     
      delete ll_find_tenancy_temp where ':'||v_tenancies_allowed||':' not like '%:'||tenancy_id||':%';                                                                                                                                                                                                                                   
    end if;                                                                                                                                                                                                                                                                                                                              
  do_log('Tenancy deleted workshop level');                                                                                                                                                                                                                                                                                              
  -- Restrict values based on the LL_WORKSHOP_REGIONS table                                                                                                                                                                                                                                                                              
    select count(*) into v_workshop_regions_set from ll_workshop_regions where workshop_id = v_workshop_id;                                                                                                                                                                                                                              
    if v_workshop_regions_set > 0 then                                                                                                                                                                                                                                                                                                   
      delete ll_find_tenancy_temp a where not exists (select null from ll_workshop_regions b where a.tenancy_id = b.tenancy_id and a.region_id = b.region_id and b.workshop_id = v_workshop_id);                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
  do_log('Tenancy and Region WORKSHOP_REGIONS level');                                                                                                                                                                                                                                                                                   
  -- If no v_tenancies_allowed filled and no default tenancy/region filled, only use public tenancies                                                                                                                                                                                                                                    
    if v_tenancy_id is null and v_tenancies_allowed is null and v_workshop_regions_set = 0 then                                                                                                                                                                                                                                          
      delete ll_find_tenancy_temp where tenancy_id not in (select id from ll_tenancies where is_public='Y');                                                                                                                                                                                                                             
    end if;                                                                                                                                                                                                                                                                                                                              
  do_log('Only use public templates');                                                                                                                                                                                                                                                                                                   
 -- Determine current usage of the tenancies based on running reservations                                                                                                                                                                                                                                                               
    update ll_find_tenancy_temp lftt set (resource_tenancy, resource_used, resource_available) = (select num_provided, num_reserved, num_available                                                                                                                                                                                       
                                                                                                  from ll_res_available_vw lra                                                                                                                                                                                                           
                                                                                                  where lra.tenancy_id = lftt.tenancy_id                                                                                                                                                                                                 
                                                                                                  and lra.region_id = lftt.region_id                                                                                                                                                                                                     
                                                                                                  and lra.resource_id = lftt.resource_id);                                                                                                                                                                                               
  do_log('Current usage');                                                                                                                                                                                                                                                                                                               
  -- Remove predicted usage of event codes active at the moment that have specific tenancy and region                                                                                                                                                                                                                                    
    for x in (select  llwrr.resource_id, nvl(llv.users_concurrent, llv.users_maximum) * llwrr.environments as extra_required, llv.tenancy_id, llv.region_id                                                                                                                                                                              
              from ll_vouchers llv, ll_ws_resources_required_vw llwrr                                                                                                                                                                                                                                                                    
              where llv.workshop_id = llwrr.workshop_id                                                                                                                                                                                                                                                                                  
              and sysdate between llv.valid_from and llv.valid_to                                                                                                                                                                                                                                                                        
              and llv.tenancy_id is not null and llv.region_id is not null                                                                                                                                                                                                                                                               
              and llv.workshop_id = v_workshop_id                                                                                                                                                                                                                                                                                        
              and (llv.id <> p_event_id or p_event_id is null)) loop                                                                                                                                                                                                                                                                     
      update ll_find_tenancy_temp set resource_required = resource_required + x.extra_required,                                                                                                                                                                                                                                          
                                      resource_available = resource_tenancy - resource_used - x.extra_required                                                                                                                                                                                                                           
                                  where tenancy_id = x.tenancy_id and region_id = x.region_id and resource_id = x.resource_id;                                                                                                                                                                                                           
    end loop;                                                                                                                                                                                                                                                                                                                            
  do_log('Remove based on current usage');                                                                                                                                                                                                                                                                                               
  --Give points to the tenancies                                                                                                                                                                                                                                                                                                         
    update ll_find_tenancy_temp lftt1 set preference_points = ( select myrank                                                                                                                                                                                                                                                            
                                                                from ( select lftt2.tenancy_id,                                                                                                                                                                                                                                          
                                                                              lftt2.region_id,                                                                                                                                                                                                                                           
                                                                              case when nvl(lftt2.resource_available,0) < lftt2.resource_required                                                                                                                                                                                        
                                                                              then -100000 else (DENSE_RANK() OVER (ORDER BY lftt2.resource_available desc) * 100) end myrank                                                                                                                                                            
                                                                       from ll_find_tenancy_temp lftt2                                                                                                                                                                                                                                   
                                                                       where lftt2.resource_id = lftt1.resource_id ) b                                                                                                                                                                                                                   
                                                                where b.tenancy_id = lftt1.tenancy_id                                                                                                                                                                                                                                    
                                                                and b.region_id = lftt1.region_id );                                                                                                                                                                                                                                     
    do_log('Points for tenancies');                                                                                                                                                                                                                                                                                                      
  -- Determine best tenancy/region for the workshop                                                                                                                                                                                                                                                                                      
    ll_pkg_log.log(40,'Determine best tenancy/region for the workshop. The p_res_id is: ' || p_res_id);                                                                                                                                                                                                                                  
    if p_res_id is not null then                                                                                                                                                                                                                                                                                                         

      select owner1 into v_username from ll_reservations where id = p_res_id;                                                                                                                                                                                                                                                            

      ll_pkg_log.log(40,'v_username: '||v_username || ' p_res_id: ' || p_res_id);                                                                                                                                                                                                                                                        
      begin                                                                                                                                                                                                                                                                                                                              
        v_country_code := ll_pkg_admin.get_country (v_username);                                                                                                                                                                                                                                                                         
      exception                                                                                                                                                                                                                                                                                                                          
        when OTHERS then begin                                                                                                                                                                                                                                                                                                           
                           ll_pkg_log.log(40,'No valid country found for user '||v_username);                                                                                                                                                                                                                                            
                           v_country_code := '';                                                                                                                                                                                                                                                                                         
                         end;                                                                                                                                                                                                                                                                                                            
      end;                                                                                                                                                                                                                                                                                                                               
      ll_pkg_log.log(40,'v_username: '||v_username || ' v_country_code: ' || v_country_code);                                                                                                                                                                                                                                            
      if v_country_code is not null then                                                                                                                                                                                                                                                                                                 

      ll_pkg_log.log(40,'v_username: '||v_username || ' v_country_code: ' || v_country_code);                                                                                                                                                                                                                                            
      for x in (select myrank*100 myrank100, id                                                                                                                                                                                                                                                                                          
                                                                                       from ( select id, distance, DENSE_RANK() over (ORDER BY distance desc) as myrank                                                                                                                                                                  
                                                                                              from ( select id, ceil(ll_pkg_admin.distance_country_dc (p_country_code => v_country_code, p_region_id => id)) as distance                                                                                                                 
                                                                                                     from ll_oci_regions)                                                                                                                                                                                                                
                                                                                            ) b, ll_find_tenancy_temp lftt                                                                                                                                                                                                               
                                                                                       where b.id = lftt.region_id )                                                                                                                                                                                                                     
      loop                                                                                                                                                                                                                                                                                                                               
         update ll_find_tenancy_temp a set a.preference_points = a.preference_points + x.myrank100 where a.region_id = x.id;                                                                                                                                                                                                             
       end loop;                                                                                                                                                                                                                                                                                                                         

      end if;                                                                                                                                                                                                                                                                                                                            

    end if;                                                                                                                                                                                                                                                                                                                              

    do_log('After preference points');                                                                                                                                                                                                                                                                                                   
  -- Build a list of how many environments we can run for this setup (this makes live easier when scheduling things)                                                                                                                                                                                                                     
    ll_pkg_log.log(40,'Build a list of how many environments we can run for this WS');                                                                                                                                                                                                                                                   
    for x in (select tenancy_id,                                                                                                                                                                                                                                                                                                         
                           region_id,                                                                                                                                                                                                                                                                                                    
                           case when sum(preference_points) <= 0 then 0 else sum(case when resource_available/resource_required <= 0 then 0 else floor(resource_available/resource_required) end) end environments,                                                                                                                      
                           sum(preference_points) as preference_points                                                                                                                                                                                                                                                                   
                    from ll_find_tenancy_temp group by tenancy_id, region_id) loop                                                                                                                                                                                                                                                       
      ll_pkg_log.log(40,'Tenancy: '||x.tenancy_id||', region: '||x.region_id||', environments: '||x.environments||', preference points: '||x.preference_points);                                                                                                                                                                         
    end loop;                                                                                                                                                                                                                                                                                                                            
    p_available_json := '[';                                                                                                                                                                                                                                                                                                             
    for x in (select tenancy_id, region_id, environments, preference_points                                                                                                                                                                                                                                                              
              from (select tenancy_id,                                                                                                                                                                                                                                                                                                   
                           region_id,                                                                                                                                                                                                                                                                                                    
                           case when sum(preference_points) <= 0 then 0 else sum(case when resource_available/resource_required <= 0 then 0 else floor(resource_available/resource_required) end) end environments,                                                                                                                      
                           sum(preference_points) as preference_points                                                                                                                                                                                                                                                                   
                    from ll_find_tenancy_temp group by tenancy_id, region_id)                                                                                                                                                                                                                                                            
              where environments > 0                                                                                                                                                                                                                                                                                                     
              order by preference_points desc) loop                                                                                                                                                                                                                                                                                      
      if substr(p_available_json,length(p_available_json),1) = '}' then                                                                                                                                                                                                                                                                  
        p_available_json := p_available_json || ',';                                                                                                                                                                                                                                                                                     
      end if;                                                                                                                                                                                                                                                                                                                            
      p_available_json := p_available_json || JSON_OBJECT ('tenancy_id'        value x.tenancy_id,                                                                                                                                                                                                                                       
                                                           'region_id'         value x.region_id,                                                                                                                                                                                                                                        
                                                           'environments'      value x.environments,                                                                                                                                                                                                                                     
                                                           'preference_points' value x.preference_points );                                                                                                                                                                                                                              
    -- The values are ordered in preference points so the first tenancy that comes out should be the best tenancy.                                                                                                                                                                                                                       
      if p_tenancy_id is null then                                                                                                                                                                                                                                                                                                       
        ll_pkg_log.log(40,'Finding initial tenancy for the request');                                                                                                                                                                                                                                                                    
        p_tenancy_id := x.tenancy_id;                                                                                                                                                                                                                                                                                                    
        p_region_id := x.region_id;                                                                                                                                                                                                                                                                                                      
      end if;                                                                                                                                                                                                                                                                                                                            
    end loop;                                                                                                                                                                                                                                                                                                                            
    p_available_json := p_available_json || ']';                                                                                                                                                                                                                                                                                         
    commit;                                                                                                                                                                                                                                                                                                                              
    ll_pkg_log.log(40, 'p_tenancy_id: '||p_tenancy_id||', p_region_id: '||p_region_id||', p_available_json: '||p_available_json);                                                                                                                                                                                                        
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                    
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--   ######  ########      ######  #### ##    ##  ######   ##       ########     ######  ######## ######## ########                                                                                                                                                                                                                      
--  ##    ## ##     ##    ##    ##  ##  ###   ## ##    ##  ##       ##          ##    ##    ##    ##       ##     ##                                                                                                                                                                                                                     
--  ##       ##     ##    ##        ##  ####  ## ##        ##       ##          ##          ##    ##       ##     ##                                                                                                                                                                                                                     
--  ##       ########      ######   ##  ## ## ## ##   #### ##       ######       ######     ##    ######   ########                                                                                                                                                                                                                      
--  ##       ##   ##            ##  ##  ##  #### ##    ##  ##       ##                ##    ##    ##       ##                                                                                                                                                                                                                            
--  ##    ## ##    ##     ##    ##  ##  ##   ### ##    ##  ##       ##          ##    ##    ##    ##       ##                                                                                                                                                                                                                            
--   ######  ##     ##     ######  #### ##    ##  ######   ######## ########     ######     ##    ######## ##                                                                                                                                                                                                                            
--                                                                                                                                                                                                                                                                                                                                       
  procedure create_single_reservation_step (p_reservation_id number, p_tenancy_id number, p_region_id number, p_flow_step_id number, p_instantiate_level varchar2 default 'U', p_environments number default 1, p_param1 varchar2 default null ) AS                                                                                      
    cursor c_flow_steps is                                                                                                                                                                                                                                                                                                               
                      select llfs.step_code, llfs.create_order, llfs.delete_order, replace('LL'||to_char(p_reservation_id,'9999000')||'-',' ','')||llfs.object_name                                                                                                                                                                      
                      from ll_flow_steps llfs                                                                                                                                                                                                                                                                                            
                      where llfs.id = p_flow_step_id                                                                                                                                                                                                                                                                                     
                      and nvl(llfs.active_flg,'Y')='Y'                                                                                                                                                                                                                                                                                   
                      order by create_order;                                                                                                                                                                                                                                                                                             

    cursor c_check ( p_reservation_id number, p_flow_step_id number, p_flow_step_param varchar2) is                                                                                                                                                                                                                                      
                     select 1                                                                                                                                                                                                                                                                                                            
                     from ll_reservation_steps                                                                                                                                                                                                                                                                                           
                     where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                             
                     and   flow_step_id = p_flow_step_id                                                                                                                                                                                                                                                                                 
                     and   flow_step_param = p_flow_step_param;                                                                                                                                                                                                                                                                          

--    v_prefix           varchar2(50) := replace('LL'||to_char(p_reservation_id,'99000')||'-',' ','');                                                                                                                                                                                                                                   
    v_object_name      varchar2(100);                                                                                                                                                                                                                                                                                                    
    v_flow_step_param  varchar2(4000);                                                                                                                                                                                                                                                                                                   
    v_repository_url   varchar2(4000);                                                                                                                                                                                                                                                                                                   

    v_region_id        number;                                                                                                                                                                                                                                                                                                           
    v_workshop_id      number;                                                                                                                                                                                                                                                                                                           
    v_environments     number;                                                                                                                                                                                                                                                                                                           
    v_tenancy_id       number;                                                                                                                                                                                                                                                                                                           
    v_check            number;                                                                                                                                                                                                                                                                                                           

    v_step_code        varchar2(50);                                                                                                                                                                                                                                                                                                     
    v_create_order     number;                                                                                                                                                                                                                                                                                                           
    v_delete_order     number;                                                                                                                                                                                                                                                                                                           

  BEGIN                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call', p_reservation_id);                                                                                                                                                                                                                                                                                 
    open c_flow_steps;                                                                                                                                                                                                                                                                                                                   
    fetch c_flow_steps into v_step_code, v_create_order, v_delete_order, v_object_name;                                                                                                                                                                                                                                                  
    if c_flow_steps%FOUND then                                                                                                                                                                                                                                                                                                           
      ll_pkg_log.log(40,'For step code: '||v_step_code||', object name will be: '||v_object_name||' - param1 is '||p_param1);                                                                                                                                                                                                            

      ll_pkg_log.log(30,'Step level Reservation or only single environment');                                                                                                                                                                                                                                                            
      v_flow_step_param := JSON_OBJECT( 'type'    value v_step_code,                                                                                                                                                                                                                                                                     
                                        'name'    value v_object_name,                                                                                                                                                                                                                                                                   
                                        'param1'  value '@p@',                                                                                                                                                                                                                                                                           
                                        'order'   value 1);                                                                                                                                                                                                                                                                              
      v_flow_step_param := replace (v_flow_step_param, '"@p@"', nvl(p_param1,'null'));                                                                                                                                                                                                                                                   
      if v_step_code = 'ociTerraform' then                                                                                                                                                                                                                                                                                               
        begin                                                                                                                                                                                                                                                                                                                            
          select repository_url                                                                                                                                                                                                                                                                                                          
            into v_repository_url                                                                                                                                                                                                                                                                                                        
            from ll_tf_scripts                                                                                                                                                                                                                                                                                                           
           where id = to_number(p_param1);                                                                                                                                                                                                                                                                                               
        exception                                                                                                                                                                                                                                                                                                                        
          when no_data_found then                                                                                                                                                                                                                                                                                                        
            v_repository_url := null;                                                                                                                                                                                                                                                                                                    
        end;                                                                                                                                                                                                                                                                                                                             

        select json_mergepatch(                                                                                                                                                                                                                                                                                                          
                 v_flow_step_param,                                                                                                                                                                                                                                                                                                      
                 json_object(                                                                                                                                                                                                                                                                                                            
                   'repositoryUrl' value nvl(                                                                                                                                                                                                                                                                                            
                     v_repository_url,                                                                                                                                                                                                                                                                                                   
                     'https://github.com/oracle-livelabs/terraform.git'                                                                                                                                                                                                                                                                  
                   )                                                                                                                                                                                                                                                                                                                     
                 )                                                                                                                                                                                                                                                                                                                       
               )                                                                                                                                                                                                                                                                                                                         
          into v_flow_step_param                                                                                                                                                                                                                                                                                                         
          from dual;                                                                                                                                                                                                                                                                                                                     
      end if;                                                                                                                                                                                                                                                                                                                            

      open c_check(p_reservation_id  => p_reservation_id,                                                                                                                                                                                                                                                                                
                   p_flow_step_id    => p_flow_step_id,                                                                                                                                                                                                                                                                                  
                   p_flow_step_param => v_flow_step_param);                                                                                                                                                                                                                                                                              
      fetch c_check into v_check;                                                                                                                                                                                                                                                                                                        
      if c_check%NOTFOUND then                                                                                                                                                                                                                                                                                                           
        insert into ll_reservation_steps                                                                                                                                                                                                                                                                                                 
           (reservation_id, flow_step_id, region_id, create_order, delete_order, flow_step_param)                                                                                                                                                                                                                                        
          values                                                                                                                                                                                                                                                                                                                         
           (p_reservation_id, p_flow_step_id, p_region_id, v_create_order, v_delete_order, v_flow_step_param );                                                                                                                                                                                                                          
      end if;                                                                                                                                                                                                                                                                                                                            
      close c_check;                                                                                                                                                                                                                                                                                                                     
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_flow_steps;                                                                                                                                                                                                                                                                                                                  

    commit;                                                                                                                                                                                                                                                                                                                              

    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                    

  END create_single_reservation_step;                                                                                                                                                                                                                                                                                                    
--                                                                                                                                                                                                                                                                                                                                       
--   ######  ########  ########    ###    ######## ########    ########  ########  ######      ######  ######## ######## ########   ######                                                                                                                                                                                               
--  ##    ## ##     ## ##         ## ##      ##    ##          ##     ## ##       ##    ##    ##    ##    ##    ##       ##     ## ##    ##                                                                                                                                                                                              
--  ##       ##     ## ##        ##   ##     ##    ##          ##     ## ##       ##          ##          ##    ##       ##     ## ##                                                                                                                                                                                                    
--  ##       ########  ######   ##     ##    ##    ######      ########  ######    ######      ######     ##    ######   ########   ######                                                                                                                                                                                               
--  ##       ##   ##   ##       #########    ##    ##          ##   ##   ##             ##          ##    ##    ##       ##              ##                                                                                                                                                                                              
--  ##    ## ##    ##  ##       ##     ##    ##    ##          ##    ##  ##       ##    ##    ##    ##    ##    ##       ##        ##    ##                                                                                                                                                                                              
--   ######  ##     ## ######## ##     ##    ##    ########    ##     ## ########  ######      ######     ##    ######## ##         ######                                                                                                                                                                                               

  procedure create_reservation_steps (p_reservation_id number) AS                                                                                                                                                                                                                                                                        

    cursor c_reservation is select workshop_id, tenancy_id, region_id, (select voucher_code from ll_vouchers llv where llv.id = llr.voucher_id) as voucher_code                                                                                                                                                                          
                            from ll_reservations llr                                                                                                                                                                                                                                                                                     
                            where id = p_reservation_id;                                                                                                                                                                                                                                                                                 
--                            for update of region_id, tenancy_id, active_flg;                                                                                                                                                                                                                                                           

    cursor c_steps (p_workshop_id number) is                                                                                                                                                                                                                                                                                             
                      select llfs.step_code, llfs.id as step_id, llfs.create_order, llfs.delete_order, llwf.parameters, llfs.is_group                                                                                                                                                                                                    
                      from ll_flow_steps llfs, ll_workshop_flow llwf                                                                                                                                                                                                                                                                     
                      where llfs.id = llwf.step_id                                                                                                                                                                                                                                                                                       
                      and llwf.workshop_id = p_workshop_id                                                                                                                                                                                                                                                                               
                      and nvl(llfs.active_flg,'Y')='Y'                                                                                                                                                                                                                                                                                   
                      order by create_order;                                                                                                                                                                                                                                                                                             

    cursor c_check ( p_reservation_id number, p_flow_step_id number, p_flow_step_param varchar2) is                                                                                                                                                                                                                                      
                     select 1                                                                                                                                                                                                                                                                                                            
                     from ll_reservation_steps                                                                                                                                                                                                                                                                                           
                     where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                             
                     and   flow_step_id = p_flow_step_id                                                                                                                                                                                                                                                                                 
                     and   flow_step_param = p_flow_step_param;                                                                                                                                                                                                                                                                          

    cursor c_step_id (p_step_code in varchar2) is select id                                                                                                                                                                                                                                                                              
                                                  from ll_flow_steps                                                                                                                                                                                                                                                                     
                                                  where step_code = p_step_code;                                                                                                                                                                                                                                                         


    v_prefix                varchar2(50) := replace('LL'||to_char(p_reservation_id,'9999000')||'-',' ','');                                                                                                                                                                                                                              
    --v_prefix                varchar2(50) := replace('LL'||to_char(p_reservation_id,'000')||'-',' ','');                                                                                                                                                                                                                                
    v_object_name           varchar2(100);                                                                                                                                                                                                                                                                                               
    v_flow_step_param       varchar2(4000);                                                                                                                                                                                                                                                                                              

    v_region_id             number;                                                                                                                                                                                                                                                                                                      
    v_workshop_id           number;                                                                                                                                                                                                                                                                                                      
    v_environments          number;                                                                                                                                                                                                                                                                                                      
    v_tenancy_id            number;                                                                                                                                                                                                                                                                                                      
    v_voucher_code          varchar2(100);                                                                                                                                                                                                                                                                                               
    v_active_flg            varchar2(1);                                                                                                                                                                                                                                                                                                 
    v_status_out            varchar2(1);                                                                                                                                                                                                                                                                                                 
    v_result_out            varchar2(4000);                                                                                                                                                                                                                                                                                              
    v_tenancy_error_reason  varchar2(4000);                                                                                                                                                                                                                                                                                              
    v_check                 number;                                                                                                                                                                                                                                                                                                      
    v_sqlerr                varchar2(2000);                                                                                                                                                                                                                                                                                              
    v_step_id               number;                                                                                                                                                                                                                                                                                                      
    v_parameter1            varchar2(4000);                                                                                                                                                                                                                                                                                              
    v_dummy_clob            clob;                                                                                                                                                                                                                                                                                                        
    v_secure_desktop        varchar2(1);                                                                                                                                                                                                                                                                                                 
    --                                                                                                                                                                                                                                                                                                                                   
    procedure add_child_step (p_child_step varchar2, p_param1 varchar2 default null) is                                                                                                                                                                                                                                                  
      cursor c_flow_steps is select id                                                                                                                                                                                                                                                                                                   
                             from ll_flow_steps                                                                                                                                                                                                                                                                                          
                             where step_code=p_child_step                                                                                                                                                                                                                                                                                
                             and nvl(active_flg,'Y')='Y';                                                                                                                                                                                                                                                                                
      v_child_id_step  number;                                                                                                                                                                                                                                                                                                           
    begin                                                                                                                                                                                                                                                                                                                                
      open c_flow_steps;                                                                                                                                                                                                                                                                                                                 
      fetch c_flow_steps into v_child_id_step;                                                                                                                                                                                                                                                                                           
      if c_flow_steps%FOUND then                                                                                                                                                                                                                                                                                                         
        create_single_reservation_step (p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                                        
                                        p_tenancy_id         => v_tenancy_id,                                                                                                                                                                                                                                                            
                                        p_region_id          => v_region_id,                                                                                                                                                                                                                                                             
                                        p_flow_step_id       => v_child_id_step,                                                                                                                                                                                                                                                         
                                        p_param1             => p_param1);                                                                                                                                                                                                                                                               
       end if;                                                                                                                                                                                                                                                                                                                           
       close c_flow_steps;                                                                                                                                                                                                                                                                                                               
     end;                                                                                                                                                                                                                                                                                                                                
     --                                                                                                                                                                                                                                                                                                                                  
  BEGIN                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call', p_reservation_id);                                                                                                                                                                                                                                                                                 

    v_environments := 1;                                                                                                                                                                                                                                                                                                                 
    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_workshop_id, v_tenancy_id, v_region_id, v_voucher_code;                                                                                                                                                                                                                                                   
    if v_region_id is null or v_tenancy_id is null then                                                                                                                                                                                                                                                                                  
      ll_pkg_log.log(30,'No tenancy or region in reservation, finding one for reservation: '||p_reservation_id);                                                                                                                                                                                                                         
      find_available_tenancy ( p_res_id         => p_reservation_id,                                                                                                                                                                                                                                                                     
                               p_tenancy_id     => v_tenancy_id,                                                                                                                                                                                                                                                                         
                               p_region_id      => v_region_id ,                                                                                                                                                                                                                                                                         
                               p_available_json => v_dummy_clob);                                                                                                                                                                                                                                                                        

      ll_pkg_log.log(40,'New tenancy: '||v_tenancy_id||', new region id: '||v_region_id);                                                                                                                                                                                                                                                
      if v_tenancy_id is not null and v_region_id is not null then                                                                                                                                                                                                                                                                       
        update ll_reservations set tenancy_id = v_tenancy_id, region_id = v_region_id where id = p_reservation_id;                                                                                                                                                                                                                       
        commit;                                                                                                                                                                                                                                                                                                                          
      else                                                                                                                                                                                                                                                                                                                               
        v_active_flg:='N';                                                                                                                                                                                                                                                                                                               
        update ll_reservations set active_flg='N' where id = p_reservation_id;                                                                                                                                                                                                                                                           
        commit;                                                                                                                                                                                                                                                                                                                          
        ll_pkg_apex.send_template_email (p_reservation_id => p_reservation_id, p_phase => 'RESOURCE_CANCELLED', p_status => v_status_out, p_result => v_result_out);                                                                                                                                                                     
      end if;                                                                                                                                                                                                                                                                                                                            
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 
    if nvl(v_active_flg,'Y') = 'Y' then                                                                                                                                                                                                                                                                                                  
      ll_pkg_log.log(30,'Reservation found');                                                                                                                                                                                                                                                                                            
      ll_pkg_log.log(40,'Reservation found, region_id: '||v_region_id||', workshop_id: '||v_workshop_id||', environments: '||v_environments||', tenancy: '||v_tenancy_id);                                                                                                                                                               
      add_child_step (p_child_step => 'ociPolicy');                                                                                                                                                                                                                                                                                      
      add_child_step (p_child_step => 'ociQuota');                                                                                                                                                                                                                                                                                       
      add_child_step (p_child_step => 'sendEmailProvisioning');                                                                                                                                                                                                                                                                          
      add_child_step (p_child_step => 'sendEmailProvisioned');                                                                                                                                                                                                                                                                           

      -- check for secure desktop to add to steps                                                                                                                                                                                                                                                                                        
      begin                                                                                                                                                                                                                                                                                                                              
        select nvl(json_value(v.event_config_json, '$.SecureDesktop'), 'N') into v_secure_desktop                                                                                                                                                                                                                                        
            from ll_reservations r, ll_vouchers v                                                                                                                                                                                                                                                                                        
            where r.voucher_id = v.id                                                                                                                                                                                                                                                                                                    
            and r.id = p_reservation_id;                                                                                                                                                                                                                                                                                                 
        if v_secure_desktop = 'Y' then                                                                                                                                                                                                                                                                                                   
            add_child_step (p_child_step => 'ociSecureDesktopUser');                                                                                                                                                                                                                                                                     
        end if;                                                                                                                                                                                                                                                                                                                          
      exception when others then                                                                                                                                                                                                                                                                                                         
        null;                                                                                                                                                                                                                                                                                                                            
      end;                                                                                                                                                                                                                                                                                                                               


      for l_step in c_steps(v_workshop_id) loop                                                                                                                                                                                                                                                                                          
        ll_pkg_log.log(40,l_step.step_code);                                                                                                                                                                                                                                                                                             
        if nvl(l_step.is_group,'N')='Y' then                                                                                                                                                                                                                                                                                             
          for l_group_steps in (select step_code from ll_flow_group_steps where group_step_id = l_step.step_id and active_flg='Y' ) loop                                                                                                                                                                                                 
            add_child_step (p_child_step => l_group_steps.step_code, p_param1     => l_step.parameters);                                                                                                                                                                                                                                 
          end loop;                                                                                                                                                                                                                                                                                                                      
        else                                                                                                                                                                                                                                                                                                                             
          case l_step.step_code                                                                                                                                                                                                                                                                                                          
            when 'ociInstance' then begin                                                                                                                                                                                                                                                                                                
                                      for NewImage in (select llwi.image_id, lli.seclist_req, json_value(lli.image_req, '$.privateIp') as private_ip, json_value(lli.image_req, '$.instAuthGrp') as inst_auth_grp, novnc_enabled                                                                                                         
                                                       from ll_workshop_images llwi, ll_images lli                                                                                                                                                                                                                                       
                                                       where llwi.image_id = lli.id                                                                                                                                                                                                                                                      
                                                       and llwi.workshop_id in (select workshop_id                                                                                                                                                                                                                                       
                                                                                from ll_reservations                                                                                                                                                                                                                                     
                                                                                where id=p_reservation_id)) loop                                                                                                                                                                                                                         
                                        create_single_reservation_step (                                                                                                                                                                                                                                                                 
                                                    p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                            
                                                    p_tenancy_id         => v_tenancy_id,                                                                                                                                                                                                                                                
                                                    p_region_id          => v_region_id,                                                                                                                                                                                                                                                 
                                                    p_flow_step_id       => l_step.step_id,                                                                                                                                                                                                                                              
                                                    p_param1             => json_object('imageId' value NewImage.image_id, 'privateIp' value NewImage.private_ip, 'instAuthGrp' value NewImage.inst_auth_grp, 'novnc_enabled' value NewImage.novnc_enabled) );                                                                           

                                      end loop;                                                                                                                                                                                                                                                                                          
                                      add_child_step (p_child_step => 'ociNetSecGrp');                                                                                                                                                                                                                                                   
                                      add_child_step( p_child_step => 'ociGetIPs');                                                                                                                                                                                                                                                      
                                      add_child_step( p_child_step => 'NoVncPassword');                                                                                                                                                                                                                                                  
                                    end;                                                                                                                                                                                                                                                                                                 
            when 'ociTerraform' then begin                                                                                                                                                                                                                                                                                               
                                       create_single_reservation_step (                                                                                                                                                                                                                                                                  
                                                    p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                            
                                                    p_tenancy_id         => v_tenancy_id,                                                                                                                                                                                                                                                
                                                    p_region_id          => v_region_id,                                                                                                                                                                                                                                                 
                                                    p_flow_step_id       => l_step.step_id,                                                                                                                                                                                                                                              
                                                    p_param1             => l_step.parameters);                                                                                                                                                                                                                                          

                                       add_child_step (p_child_step => 'ociTfApplyJob', p_param1 => l_step.parameters);                                                                                                                                                                                                                  
                                       add_child_step (p_child_step => 'ociTfCheckStatus', p_param1 => l_step.parameters);                                                                                                                                                                                                               
                                     end;                                                                                                                                                                                                                                                                                                
           else                                                                                                                                                                                                                                                                                                                          
             create_single_reservation_step (                                                                                                                                                                                                                                                                                            
                                      p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                                          
                                      p_tenancy_id         => v_tenancy_id,                                                                                                                                                                                                                                                              
                                      p_region_id          => v_region_id,                                                                                                                                                                                                                                                               
                                      p_flow_step_id       => l_step.step_id,                                                                                                                                                                                                                                                            
                                      p_param1             => l_step.parameters );                                                                                                                                                                                                                                                       
           end case;                                                                                                                                                                                                                                                                                                                     
        end if;                                                                                                                                                                                                                                                                                                                          

      end loop;                                                                                                                                                                                                                                                                                                                          

      commit;                                                                                                                                                                                                                                                                                                                            
    end if;                                                                                                                                                                                                                                                                                                                              

    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                    

    exception                                                                                                                                                                                                                                                                                                                            

      when others then begin                                                                                                                                                                                                                                                                                                             
                         v_sqlerr := sqlerrm;                                                                                                                                                                                                                                                                                            
                         ll_pkg_log.log(1,'Issue with RESID: '||p_reservation_id||', error is: '||v_sqlerr);                                                                                                                                                                                                                             
                         ll_pkg_exec.send_prowl (p_error_type => 'CREATE-ERROR',                                                                                                                                                                                                                                                         
                                                 p_message    => 'Issue generating steps: '||v_sqlerr,                                                                                                                                                                                                                                   
                                                 p_event      => 'Error creating RES ID: '||p_reservation_id,                                                                                                                                                                                                                            
                                                 p_priority   => 1);                                                                                                                                                                                                                                                                     
                        -- Added by Madhu ---                                                                                                                                                                                                                                                                                            
                        ll_pkg_log.log(30,'Issue with RESID '||p_reservation_id||', sending mail to livelabs-support_us');                                                                                                                                                                                                               
                        APEX_MAIL.SEND(                                                                                                                                                                                                                                                                                                  
                                p_to        => 'livelabs-support_us@oracle.com',                                                                                                                                                                                                                                                         
                                p_from      => 'noreply@oracle.com', -- email change                                                                                                                                                                                                                                                     
                                p_subj      => 'Error creating RES ID: '||p_reservation_id ,                                                                                                                                                                                                                                             
                                p_body      =>  'Issue generating steps: '||v_sqlerr );                                                                                                                                                                                                                                                  
                        -- Added by Madhu ---                                                                                                                                                                                                                                                                                            
                       end;                                                                                                                                                                                                                                                                                                              

  END create_reservation_steps;                                                                                                                                                                                                                                                                                                          
--                                                                                                                                                                                                                                                                                                                                       
--   ######  ##       ########    ###    ##    ##    ########  ########  ######     ######## ##    ## ########  ######## ########                                                                                                                                                                                                        
--  ##    ## ##       ##         ## ##   ###   ##    ##     ## ##       ##    ##    ##       ###   ## ##     ## ##       ##     ##                                                                                                                                                                                                       
--  ##       ##       ##        ##   ##  ####  ##    ##     ## ##       ##          ##       ####  ## ##     ## ##       ##     ##                                                                                                                                                                                                       
