--  ##       ##       ##       ######### ##  ####    ##   ##   ##             ##    ##       ##  #### ##     ## ##       ##     ##                                                                                                                                                                                                       
--  ##    ## ##       ##       ##     ## ##   ###    ##    ##  ##       ##    ##    ##       ##   ### ##     ## ##       ##     ##                                                                                                                                                                                                       
--   ######  ######## ######## ##     ## ##    ##    ##     ## ########  ######     ######## ##    ## ########  ######## ########                                                                                                                                                                                                        
--                                                                                                                                                                                                                                                                                                                                       
  procedure clean_reservations_ended is                                                                                                                                                                                                                                                                                                  
    cursor c_reservations is select id                                                                                                                                                                                                                                                                                                   
                             from ll_reservations_vw llr                                                                                                                                                                                                                                                                                 
                             where stop_gmt < sysdate                                                                                                                                                                                                                                                                                    
                             and exists (select null                                                                                                                                                                                                                                                                                     
                                         from ll_reservation_steps llrs                                                                                                                                                                                                                                                                  
                                         where llrs.reservation_id = llr.id                                                                                                                                                                                                                                                              
                                         and delete_order is not null                                                                                                                                                                                                                                                                    
                                         and (delete_success is null or (delete_success = 'N' and delete_retry < 5)));                                                                                                                                                                                                                   


    -- cursor c_reservations(c_failure_wait number) is select id                                                                                                                                                                                                                                                                         
    --                          from ll_reservations_vw llr                                                                                                                                                                                                                                                                              
    --                          -- start deleting reservations that were successful, only after they ended                                                                                                                                                                                                                               
    --                          where ((stop_gmt < sysdate and not exists (                                                                                                                                                                                                                                                              
    --                                                         select 'x'                                                                                                                                                                                                                                                                
    --                                                         from ll_reservation_steps llrs                                                                                                                                                                                                                                            
    --                                                         where llrs.reservation_id = llr.id                                                                                                                                                                                                                                        
    --                                                         and llrs.create_success = 'N')                                                                                                                                                                                                                                            
    --                                                     )                                                                                                                                                                                                                                                                             
    --                             -- or start deleting failed reservations after c_failure_wait amount of time from last action on reservation                                                                                                                                                                                          
    --                             or ((select max(llrs.create_date)                                                                                                                                                                                                                                                                     
    --                                     from ll_reservation_steps llrs                                                                                                                                                                                                                                                                
    --                                     where llrs.reservation_id = llr.id                                                                                                                                                                                                                                                            
    --                                         and llrs.create_date is not null) + c_failure_wait < sysdate                                                                                                                                                                                                                              
    --                                 and exists (                                                                                                                                                                                                                                                                                      
    --                                         select 'x'                                                                                                                                                                                                                                                                                
    --                                         from ll_reservation_steps llrs2                                                                                                                                                                                                                                                           
    --                                         where llrs2.reservation_id = llr.id                                                                                                                                                                                                                                                       
    --                                         and llrs2.create_success = 'N'                                                                                                                                                                                                                                                            
    --                                         and llrs2.create_retry = 5                                                                                                                                                                                                                                                                
    --                                 ))                                                                                                                                                                                                                                                                                                
    --                             )                                                                                                                                                                                                                                                                                                     
    --                          -- only delete those that have not begun deletion                                                                                                                                                                                                                                                        
    --                          and exists (select 'x'                                                                                                                                                                                                                                                                                   
    --                                      from ll_reservation_steps llrs                                                                                                                                                                                                                                                               
    --                                      where llrs.reservation_id = llr.id                                                                                                                                                                                                                                                           
    --                                      and delete_order is not null                                                                                                                                                                                                                                                                 
    --                                      and (delete_success is null or (delete_success = 'N' and delete_retry < 5)));                                                                                                                                                                                                                

    v_status varchar2(1);                                                                                                                                                                                                                                                                                                                
    v_result varchar2(400);                                                                                                                                                                                                                                                                                                              
    -- v_clean_failure_wait number;                                                                                                                                                                                                                                                                                                      
  begin                                                                                                                                                                                                                                                                                                                                  
    -- v_clean_failure_wait := ll_pkg_admin.minutes_to_days(nvl(ll_pkg_admin.system_parameter('CLEAN_FAILURE_WAIT_MINUTES'), 30));                                                                                                                                                                                                       
    -- for x in c_reservations(v_clean_failure_wait) loop                                                                                                                                                                                                                                                                                
    for x in c_reservations loop                                                                                                                                                                                                                                                                                                         
      ll_pkg_log.log(20,'Create job for object clean reservation '||x.id, x.id);                                                                                                                                                                                                                                                         
      ll_pkg_apex.send_template_email (p_reservation_id => x.id,                                                                                                                                                                                                                                                                         
                                       p_phase          => 'TO_BE_DELETED',                                                                                                                                                                                                                                                              
                                       p_status         => v_status,                                                                                                                                                                                                                                                                     
                                       p_result         => v_result);                                                                                                                                                                                                                                                                    
      ll_pkg_admin.create_job (p_type        => 'CLEAN_RES_OBJECTS',                                                                                                                                                                                                                                                                     
                               p_parameters  => json_object('P1' value x.id),                                                                                                                                                                                                                                                            
                               p_jobname     => replace('CLEANOBJ_'||x.id,' ',''));                                                                                                                                                                                                                                                      

    end loop;                                                                                                                                                                                                                                                                                                                            
  end;                                                                                                                                                                                                                                                                                                                                   

    function check_preprovisioned(p_reservation_id number, p_start_gmt date) return boolean is                                                                                                                                                                                                                                           
        v_event_id number;                                                                                                                                                                                                                                                                                                               
        v_event_code varchar2(50);                                                                                                                                                                                                                                                                                                       
        v_new_res_id number;                                                                                                                                                                                                                                                                                                             
        v_res_email varchar2(100);                                                                                                                                                                                                                                                                                                       
    begin                                                                                                                                                                                                                                                                                                                                
        select voucher_id, owner1 into v_event_id, v_res_email from ll_reservations where id = p_reservation_id;                                                                                                                                                                                                                         
        if v_event_id is null or p_start_gmt > sysdate then                                                                                                                                                                                                                                                                              
            commit;                                                                                                                                                                                                                                                                                                                      
            return false;                                                                                                                                                                                                                                                                                                                
        end if;                                                                                                                                                                                                                                                                                                                          
        select voucher_code into v_event_code from ll_vouchers where id = v_event_id for update;                                                                                                                                                                                                                                         
        select r.id into v_new_res_id from ll_reservations_vw r                                                                                                                                                                                                                                                                          
            where r.voucher_id = v_event_id                                                                                                                                                                                                                                                                                              
            and r.owner1 = v_event_code||'@LIVELABS.COM'                                                                                                                                                                                                                                                                                 
            and p_start_gmt < sysdate                                                                                                                                                                                                                                                                                                    
            and r.stop_gmt > sysdate                                                                                                                                                                                                                                                                                                     
            and r.active_flg = 'Y'                                                                                                                                                                                                                                                                                                       
            and (select count(*) from ll_reservation_steps where reservation_id = r.id) > 0                                                                                                                                                                                                                                              
            and (select count(*) from ll_reservation_steps where reservation_id = r.id and create_order is not null and create_success='N') = 0 fetch first 1 rows only;                                                                                                                                                                 
        update ll_reservations set owner1 = v_res_email where id = v_new_res_id;                                                                                                                                                                                                                                                         
        update ll_reservations set owner1 = v_new_res_id||'-DONE@LIVELABS.COM', active_flg = 'N' where id = p_reservation_id;                                                                                                                                                                                                            
        commit;                                                                                                                                                                                                                                                                                                                          
        return true;                                                                                                                                                                                                                                                                                                                     
    exception when others then                                                                                                                                                                                                                                                                                                           
        commit;                                                                                                                                                                                                                                                                                                                          
        return false;                                                                                                                                                                                                                                                                                                                    
    end;                                                                                                                                                                                                                                                                                                                                 



--                                                                                                                                                                                                                                                                                                                                       
--  ########  ########   #######   ######  ########  ######   ######     ########  ########  ######     #### ##    ## #### ######## ####    ###    ##                                                                                                                                                                                    
--  ##     ## ##     ## ##     ## ##    ## ##       ##    ## ##    ##    ##     ## ##       ##    ##     ##  ###   ##  ##     ##     ##    ## ##   ##                                                                                                                                                                                    
--  ##     ## ##     ## ##     ## ##       ##       ##       ##          ##     ## ##       ##           ##  ####  ##  ##     ##     ##   ##   ##  ##                                                                                                                                                                                    
--  ########  ########  ##     ## ##       ######    ######   ######     ########  ######    ######      ##  ## ## ##  ##     ##     ##  ##     ## ##                                                                                                                                                                                    
--  ##        ##   ##   ##     ## ##       ##             ##       ##    ##   ##   ##             ##     ##  ##  ####  ##     ##     ##  ######### ##                                                                                                                                                                                    
--  ##        ##    ##  ##     ## ##    ## ##       ##    ## ##    ##    ##    ##  ##       ##    ##     ##  ##   ###  ##     ##     ##  ##     ## ##                                                                                                                                                                                    
--  ##        ##     ##  #######   ######  ########  ######   ######     ##     ## ########  ######     #### ##    ## ####    ##    #### ##     ## ########                                                                                                                                                                              
--                                                                                                                                                                                                                                                                                                                                       
  procedure process_reservation_initial (p_reservation_id number, p_start_gmt date) is                                                                                                                                                                                                                                                   

    v_status    varchar2(1);                                                                                                                                                                                                                                                                                                             
    v_result    varchar2(4000);                                                                                                                                                                                                                                                                                                          
    v_template  varchar2(50);                                                                                                                                                                                                                                                                                                            
    v_preprovisioned boolean;                                                                                                                                                                                                                                                                                                            

  begin                                                                                                                                                                                                                                                                                                                                  
    ll_pkg_log.log(10,'Initial call', p_reservation_id);                                                                                                                                                                                                                                                                                 
    ll_pkg_security.set_security_group;                                                                                                                                                                                                                                                                                                  
    ll_pkg_log.log(30,'Waiting 5 seconds for reservation to be committed');                                                                                                                                                                                                                                                              
    apex_util.pause(5);                                                                                                                                                                                                                                                                                                                  
    ll_pkg_log.log(30,'Sending email to attendee');                                                                                                                                                                                                                                                                                      

    if p_start_gmt < sysdate then                                                                                                                                                                                                                                                                                                        
      v_template := 'RESERVATION_IMMEDIATE';                                                                                                                                                                                                                                                                                             
    else                                                                                                                                                                                                                                                                                                                                 
      v_template := 'RESERVATION_REGISTERED';                                                                                                                                                                                                                                                                                            
    end if;                                                                                                                                                                                                                                                                                                                              


    ll_pkg_apex.send_template_email ( p_reservation_id     => p_reservation_id,                                                                                                                                                                                                                                                          
                                             p_phase              => v_template,                                                                                                                                                                                                                                                         
                                             p_status             => v_status,                                                                                                                                                                                                                                                           
                                             p_result             => v_result);                                                                                                                                                                                                                                                          
    v_preprovisioned := check_preprovisioned(p_reservation_id, p_start_gmt);                                                                                                                                                                                                                                                             
    if p_start_gmt < sysdate and v_preprovisioned = false then                                                                                                                                                                                                                                                                           
      ll_pkg_log.log(30,'Starting immediate reservation process');                                                                                                                                                                                                                                                                       
      ll_pkg_admin.create_job (p_type        => 'CREATE_AND_PROCESS_RES',                                                                                                                                                                                                                                                                
                               p_parameters  => json_object( 'P1' value p_reservation_id),                                                                                                                                                                                                                                               
				               p_jobname     => 'IMMRES'||p_reservation_id);                                                                                                                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
    ll_pkg_log.log(10,'End of call');                                                                                                                                                                                                                                                                                                    
    exception                                                                                                                                                                                                                                                                                                                            
      when OTHERS then begin                                                                                                                                                                                                                                                                                                             
                         v_result := v_result || '-' || SQLERRM;                                                                                                                                                                                                                                                                         
                         ll_pkg_log.log(10,'Issue during send: '||v_result);                                                                                                                                                                                                                                                             
                       end;                                                                                                                                                                                                                                                                                                              

  end;                                                                                                                                                                                                                                                                                                                                   

--  ########  ########  ######   ####  #######  ##    ##    ##    ## ######## ##    ##                                                                                                                                                                                                                                                   
--  ##     ## ##       ##    ##   ##  ##     ## ###   ##    ##   ##  ##        ##  ##                                                                                                                                                                                                                                                    
--  ##     ## ##       ##         ##  ##     ## ####  ##    ##  ##   ##         ####                                                                                                                                                                                                                                                     
--  ########  ######   ##   ####  ##  ##     ## ## ## ##    #####    ######      ##                                                                                                                                                                                                                                                      
--  ##   ##   ##       ##    ##   ##  ##     ## ##  ####    ##  ##   ##          ##                                                                                                                                                                                                                                                      
--  ##    ##  ##       ##    ##   ##  ##     ## ##   ###    ##   ##  ##          ##                                                                                                                                                                                                                                                      
--  ##     ## ########  ######   ####  #######  ##    ##    ##    ## ########    ##                                                                                                                                                                                                                                                      

  function region_key (p_reservation_id number) return varchar2 is                                                                                                                                                                                                                                                                       
    cursor c_reservation is select region_key                                                                                                                                                                                                                                                                                            
                            from ll_oci_regions                                                                                                                                                                                                                                                                                          
                            where id = (select region_id                                                                                                                                                                                                                                                                                 
                                        from ll_reservations                                                                                                                                                                                                                                                                             
                                        where id = p_reservation_id);                                                                                                                                                                                                                                                                    

    v_return_value    varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  
    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
