                            from ll_tenancies                                                                                                                                                                                                                                                                                            
                            where default_compartment_ocid is not null                                                                                                                                                                                                                                                                   
                            and id = (select tenancy_id                                                                                                                                                                                                                                                                                  
                                      from ll_reservations                                                                                                                                                                                                                                                                               
                                      where id = p_reservation_id);                                                                                                                                                                                                                                                                      

    v_return_value    varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  
    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := tenancy_ocid(p_reservation_id => p_reservation_id);                                                                                                                                                                                                                                                              
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    return(v_return_value);                                                                                                                                                                                                                                                                                                              
  end;                                                                                                                                                                                                                                                                                                                                   

