--   ######     ##    ######## ##           ########  ########    ##    ##     ## #### ########  ######                                                                                                                                                                                                                                  

  function step_details (p_reservation_id number, p_res_step_id number, p_json_name varchar2) return varchar2 is                                                                                                                                                                                                                         

    v_sqlstatement    varchar2(4000);                                                                                                                                                                                                                                                                                                    
    v_return_value    varchar2(4000);                                                                                                                                                                                                                                                                                                    
    v_json_string     varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  

    v_json_string := dbms_assert.enquote_literal('$.'||p_json_name);                                                                                                                                                                                                                                                                     

    v_sqlstatement := 'select JSON_VALUE( flow_step_param , '||v_json_string||' ) '||                                                                                                                                                                                                                                                    
                      'from ll_reservation_steps '||                                                                                                                                                                                                                                                                                     
                      'where reservation_id = :reservation_id '||                                                                                                                                                                                                                                                                        
                      'and id = :res_step_id';                                                                                                                                                                                                                                                                                           

    execute immediate v_sqlstatement into v_return_value using IN p_reservation_id, IN p_res_step_id;                                                                                                                                                                                                                                    
    if v_return_value is null then                                                                                                                                                                                                                                                                                                       
      v_sqlstatement := 'select JSON_QUERY( flow_step_param , '||v_json_string||' ) '||                                                                                                                                                                                                                                                  
                        'from ll_reservation_steps '||                                                                                                                                                                                                                                                                                   
                        'where reservation_id = :reservation_id '||                                                                                                                                                                                                                                                                      
                        'and id = :res_step_id';                                                                                                                                                                                                                                                                                         

      execute immediate v_sqlstatement into v_return_value using IN p_reservation_id, IN p_res_step_id;                                                                                                                                                                                                                                  
    end if;                                                                                                                                                                                                                                                                                                                              
    ll_pkg_log.log(40,'After fetching value, step_id: '||p_res_step_id||', json_name: '||p_json_name||', json_string: '||v_json_string||', value found: '||v_return_value);                                                                                                                                                              

    return(v_return_value);                                                                                                                                                                                                                                                                                                              

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
-- =============================================================================================================                                                                                                                                                                                                                         
--                                                                                                                                                                                                                                                                                                                                       
  procedure step_status (p_reservation_id number, p_res_step_id number, p_step_date OUT date, p_step_status OUT varchar2 ) is                                                                                                                                                                                                            
    cursor c_date is select create_date, create_success                                                                                                                                                                                                                                                                                  
                     from ll_reservation_steps                                                                                                                                                                                                                                                                                           
                     where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                             
                     and id = p_res_step_id;                                                                                                                                                                                                                                                                                             
    v_date date;                                                                                                                                                                                                                                                                                                                         
  begin                                                                                                                                                                                                                                                                                                                                  
    open c_date;                                                                                                                                                                                                                                                                                                                         
    fetch c_date into p_step_date, p_step_status;                                                                                                                                                                                                                                                                                        
    close c_date;                                                                                                                                                                                                                                                                                                                        
  end;                                                                                                                                                                                                                                                                                                                                   
