    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := 'Error: Cannot find RESERVATION_STEP';                                                                                                                                                                                                                                                                           
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    return(v_return_value);                                                                                                                                                                                                                                                                                                              

