--  ##     ##  ######  ########     ##     ## ########        ##    ## ## ## ##     ## ## ### ## ######                                                                                                                                                                                                                                  
--  ##     ##       ## ##   ##      ##     ## ##     ## ##    ##    ##  #### ######### ##     ## ##                                                                                                                                                                                                                                      
--  ##     ## ##    ## ##    ##     ##     ## ##     ## ##    ##    ##   ### ##     ## ##     ## ##                                                                                                                                                                                                                                      
--   #######   ######  ##     ##     #######  ########   ######     ##    ## ##     ## ##     ## ########                                                                                                                                                                                                                                
--                                                                                                                                                                                                                                                                                                                                       
  function user_object_name (p_reservation_id number, p_param_type varchar2) return varchar2 is                                                                                                                                                                                                                                          

    cursor c_reservation is select JSON_VALUE(flow_step_param, '$.name')                                                                                                                                                                                                                                                                 
                            from ll_reservation_steps                                                                                                                                                                                                                                                                                    
                            where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                      
                            and json_value(flow_step_param, '$.type') = p_param_type;                                                                                                                                                                                                                                                    

    v_return_value    varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                                                                                                                   

    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    ll_pkg_log.log(40,'After fetching value, result is: '||v_return_value);                                                                                                                                                                                                                                                              
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := 'Error: Cannot find NAME value for TYPE '||p_param_type;                                                                                                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    ll_pkg_log.log(20,'End call');                                                                                                                                                                                                                                                                                                       

    return(v_return_value);                                                                                                                                                                                                                                                                                                              

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ######## ##        #######  ##      ##     ######  ######## ######## ########     ########  ########  ######  ##     ## ##       ########                                                                                                                                                                                            
--  ##       ##       ##     ## ##  ##  ##    ##    ##    ##    ##       ##     ##    ##     ## ##       ##    ## ##     ## ##          ##                                                                                                                                                                                               
--  ##       ##       ##     ## ##  ##  ##    ##          ##    ##       ##     ##    ##     ## ##       ##       ##     ## ##          ##                                                                                                                                                                                               
--  ######   ##       ##     ## ##  ##  ##     ######     ##    ######   ########     ########  ######    ######  ##     ## ##          ##                                                                                                                                                                                               
--  ##       ##       ##     ## ##  ##  ##          ##    ##    ##       ##           ##   ##   ##             ## ##     ## ##          ##                                                                                                                                                                                               
--  ##       ##       ##     ## ##  ##  ##    ##    ##    ##    ##       ##           ##    ##  ##       ##    ## ##     ## ##          ##                                                                                                                                                                                               
--  ##       ########  #######   ###  ###      ######     ##    ######## ##           ##     ## ########  ######   #######  ########    ##                                                                                                                                                                                               
--                                                                                                                                                                                                                                                                                                                                       
  function flow_step_result (p_reservation_id number, p_param_type varchar2, p_result_type varchar2) return varchar2 is                                                                                                                                                                                                                  

    cursor c_reservation is select flow_step_result                                                                                                                                                                                                                                                                                      
                            from ll_reservation_steps                                                                                                                                                                                                                                                                                    
                            where reservation_id = p_reservation_id                                                                                                                                                                                                                                                                      
                            and (json_value(flow_step_param, '$.type') = p_param_type or json_value(flow_step_param, '$.type') = p_param_type || 'Clean')                                                                                                                                                                                
                            and flow_step_result like '%'||p_result_type||'%';                                                                                                                                                                                                                                                           

    v_clob          clob;                                                                                                                                                                                                                                                                                                                
    v_search        varchar2(100);                                                                                                                                                                                                                                                                                                       
    v_return_value  varchar2(200);                                                                                                                                                                                                                                                                                                       

  begin                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                                                                                                                   

    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_clob;                                                                                                                                                                                                                                                                                                     
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := 'Error: Cannot find result value for TYPE '||p_param_type;                                                                                                                                                                                                                                                       
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 
    v_search := '$.'||p_result_type;                                                                                                                                                                                                                                                                                                     
    v_return_value := json_value(v_clob, v_search );                                                                                                                                                                                                                                                                                     

    ll_pkg_log.log(20,'End call');                                                                                                                                                                                                                                                                                                       

    return(v_return_value);                                                                                                                                                                                                                                                                                                              

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
