--                                                                                                                                                                                                                                                                                                                                       
  function reservation_environments (p_reservation_id number) return number is                                                                                                                                                                                                                                                           
    cursor c_reservation is select environments                                                                                                                                                                                                                                                                                          
                            from ll_reservations                                                                                                                                                                                                                                                                                         
                            where id = p_reservation_id;                                                                                                                                                                                                                                                                                 

    v_return_value    number;                                                                                                                                                                                                                                                                                                            

  begin                                                                                                                                                                                                                                                                                                                                  
    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := 0;                                                                                                                                                                                                                                                                                                               
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    return(v_return_value);                                                                                                                                                                                                                                                                                                              
  end;                                                                                                                                                                                                                                                                                                                                   
--  ########  ##     ## ########  ##       ####  ######     ##    ## ######## ##    ##                                                                                                                                                                                                                                                   
--  ##     ## ##     ## ##     ## ##        ##  ##    ##    ##   ##  ##        ##  ##                                                                                                                                                                                                                                                    
--  ##     ## ##     ## ##     ## ##        ##  ##          ##  ##   ##         ####                                                                                                                                                                                                                                                     
--  ########  ##     ## ########  ##        ##  ##          #####    ######      ##                                                                                                                                                                                                                                                      
--  ##        ##     ## ##     ## ##        ##  ##          ##  ##   ##          ##                                                                                                                                                                                                                                                      
--  ##        ##     ## ##     ## ##        ##  ##    ##    ##   ##  ##          ##                                                                                                                                                                                                                                                      
--  ##         #######  ########  ######## ####  ######     ##    ## ########    ##                                                                                                                                                                                                                                                      
  function public_key (p_reservation_id number) return varchar2 is                                                                                                                                                                                                                                                                       
    cursor c_reservation is select public_key                                                                                                                                                                                                                                                                                            
                            from ll_reservations                                                                                                                                                                                                                                                                                         
                            where id = p_reservation_id;                                                                                                                                                                                                                                                                                 

    v_return_value    varchar2(4000);                                                                                                                                                                                                                                                                                                    

  begin                                                                                                                                                                                                                                                                                                                                  
    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    if c_reservation%NOTFOUND then                                                                                                                                                                                                                                                                                                       
      v_return_value := '';                                                                                                                                                                                                                                                                                                              
    end if;                                                                                                                                                                                                                                                                                                                              
    close c_reservation;                                                                                                                                                                                                                                                                                                                 
    return(v_return_value);                                                                                                                                                                                                                                                                                                              
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ########     ###    ######## ########     ######   ##     ## ########                                                                                                                                                                                                                                                                
--  ##     ##   ## ##      ##    ##          ##    ##  ###   ###    ##                                                                                                                                                                                                                                                                   
--  ##     ##  ##   ##     ##    ##          ##        #### ####    ##                                                                                                                                                                                                                                                                   
--  ##     ## ##     ##    ##    ######      ##   #### ## ### ##    ##                                                                                                                                                                                                                                                                   
--  ##     ## #########    ##    ##          ##    ##  ##     ##    ##                                                                                                                                                                                                                                                                   
--  ##     ## ##     ##    ##    ##          ##    ##  ##     ##    ##                                                                                                                                                                                                                                                                   
--  ########  ##     ##    ##    ########     ######   ##     ##    ##                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
  function date_gmt (p_date date, p_time varchar2 default null, p_timezone varchar2 ) return date is                                                                                                                                                                                                                                     
    v_time          varchar2(10);                                                                                                                                                                                                                                                                                                        
    v_return_date   date;                                                                                                                                                                                                                                                                                                                
  begin                                                                                                                                                                                                                                                                                                                                  

    if p_time is null or trunc(p_date) <> p_date then                                                                                                                                                                                                                                                                                    
      v_time := to_char(p_date,'HH24:MI');                                                                                                                                                                                                                                                                                               
    else                                                                                                                                                                                                                                                                                                                                 
      v_time := p_time;                                                                                                                                                                                                                                                                                                                  
    end if;                                                                                                                                                                                                                                                                                                                              

    v_return_date := to_date(to_char(to_timestamp_tz(to_char(p_date,'DD-MM-YYYY')||' '||v_time||' '||p_timezone,'DD-MM-YYYY HH24:MI TZR') at TIME ZONE 'GMT','DD-MM-YYYY HH24:MI'),'DD-MM-YYYY HH24:MI');                                                                                                                                
    return(v_return_date);                                                                                                                                                                                                                                                                                                               

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ########     ###    ######## ########    ######## #### ##     ## ######## ########  #######  ##    ## ########                                                                                                                                                                                                                       
--  ##     ##   ## ##      ##    ##             ##     ##  ###   ### ##            ##  ##     ## ###   ## ##                                                                                                                                                                                                                             
--  ##     ##  ##   ##     ##    ##             ##     ##  #### #### ##           ##   ##     ## ####  ## ##                                                                                                                                                                                                                             
--  ##     ## ##     ##    ##    ######         ##     ##  ## ### ## ######      ##    ##     ## ## ## ## ######                                                                                                                                                                                                                         
--  ##     ## #########    ##    ##             ##     ##  ##     ## ##         ##     ##     ## ##  #### ##                                                                                                                                                                                                                             
--  ##     ## ##     ##    ##    ##             ##     ##  ##     ## ##        ##      ##     ## ##   ### ##                                                                                                                                                                                                                             
--  ########  ##     ##    ##    ########       ##    #### ##     ## ######## ########  #######  ##    ## ########                                                                                                                                                                                                                       
--                                                                                                                                                                                                                                                                                                                                       
  function date_timezone (p_date_gmt date, p_timezone varchar2 ) return date is                                                                                                                                                                                                                                                          
    v_time          varchar2(10);                                                                                                                                                                                                                                                                                                        
    v_return_date   date;                                                                                                                                                                                                                                                                                                                
  begin                                                                                                                                                                                                                                                                                                                                  

    v_return_date := to_date(to_char(to_timestamp_tz(to_char(p_date_gmt,'DD-MM-YYYY HH24:MI')||' GMT','DD-MM-YYYY HH24:MI TZR') at TIME ZONE p_timezone,'DD-MM-YYYY HH24:MI'),'DD-MM-YYYY HH24:MI');                                                                                                                                     
    return(v_return_date);                                                                                                                                                                                                                                                                                                               

    exception                                                                                                                                                                                                                                                                                                                            
      when others then                                                                                                                                                                                                                                                                                                                   
        begin                                                                                                                                                                                                                                                                                                                            
          ll_pkg_log.log(1,'Error in DATE GMT, p_date_gmt: '||to_char(p_date_gmt,'DD-MM-YYYY HH24:MI:SS')||', p_timezone: '||p_timezone);                                                                                                                                                                                                
          return(null);                                                                                                                                                                                                                                                                                                                  
        end;                                                                                                                                                                                                                                                                                                                             
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--   ######  ########  #######  ########     ########     ###    ######## ########     ######   ##     ## ########                                                                                                                                                                                                                       
--  ##    ##    ##    ##     ## ##     ##    ##     ##   ## ##      ##    ##          ##    ##  ###   ###    ##                                                                                                                                                                                                                          
--  ##          ##    ##     ## ##     ##    ##     ##  ##   ##     ##    ##          ##        #### ####    ##                                                                                                                                                                                                                          
--   ######     ##    ##     ## ########     ##     ## ##     ##    ##    ######      ##   #### ## ### ##    ##                                                                                                                                                                                                                          
--        ##    ##    ##     ## ##           ##     ## #########    ##    ##          ##    ##  ##     ##    ##                                                                                                                                                                                                                          
--  ##    ##    ##    ##     ## ##           ##     ## ##     ##    ##    ##          ##    ##  ##     ##    ##                                                                                                                                                                                                                          
--   ######     ##     #######  ##           ########  ##     ##    ##    ########     ######   ##     ##    ##                                                                                                                                                                                                                          
--                                                                                                                                                                                                                                                                                                                                       
  function stop_date_gmt (p_workshop_id number, p_start_date date, p_start_time varchar2, p_start_timezone varchar2, p_stop_date date, p_stop_time varchar2,  p_voucher_id number default null ) return date is                                                                                                                          
    cursor c_duration is select nvl(time_available,8) from ll_workshops where id=p_workshop_id;                                                                                                                                                                                                                                          
    cursor c_voucher is select alt_time_available from ll_vouchers where id = p_voucher_id;                                                                                                                                                                                                                                              
    v_time_available  number;                                                                                                                                                                                                                                                                                                            
    v_start_gmt       date;                                                                                                                                                                                                                                                                                                              
    v_return_date     date;                                                                                                                                                                                                                                                                                                              
  begin                                                                                                                                                                                                                                                                                                                                  
    if p_stop_date is not null then                                                                                                                                                                                                                                                                                                      
      v_return_date := date_gmt(p_date => p_stop_date, p_time => p_stop_time, p_timezone => p_start_timezone);                                                                                                                                                                                                                           
    else                                                                                                                                                                                                                                                                                                                                 
      if p_voucher_id is not null then                                                                                                                                                                                                                                                                                                   
        open c_voucher;                                                                                                                                                                                                                                                                                                                  
        fetch c_voucher into v_time_available;                                                                                                                                                                                                                                                                                           
        close c_voucher;                                                                                                                                                                                                                                                                                                                 
      end if;                                                                                                                                                                                                                                                                                                                            
      if v_time_available is null or v_time_available=0 then                                                                                                                                                                                                                                                                             
        open c_duration;                                                                                                                                                                                                                                                                                                                 
        fetch c_duration into v_time_available;                                                                                                                                                                                                                                                                                          
        close c_duration;                                                                                                                                                                                                                                                                                                                
      end if;                                                                                                                                                                                                                                                                                                                            

      v_start_gmt := date_gmt(p_date => p_start_date, p_time => p_start_time, p_timezone => p_start_timezone);                                                                                                                                                                                                                           

      v_return_date := v_start_gmt + (v_time_available/24);                                                                                                                                                                                                                                                                              
    end if;                                                                                                                                                                                                                                                                                                                              
    return(v_return_date);                                                                                                                                                                                                                                                                                                               

    exception                                                                                                                                                                                                                                                                                                                            
      when others then                                                                                                                                                                                                                                                                                                                   
        begin                                                                                                                                                                                                                                                                                                                            
          ll_pkg_log.log(1,'Error in STOP DATE GMT, p_workshop_id: '||p_workshop_id||', p_start_date: '||to_char(p_start_date,'DD-MM-YYYY HH24:MI:SS')||', p_start_time: '||p_start_time||', p_start_timezone: '||p_start_timezone||', p_stop_date: '||to_char(p_stop_date,'DD-MM-YYYY HH24:MI:SS')||', p_stop_time: '||p_stop_time);    
          return(null);                                                                                                                                                                                                                                                                                                                  
        end;                                                                                                                                                                                                                                                                                                                             
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
