--                                                                                                                                                                                                                                                                                                                                       
  procedure reset_password (p_reservation_id number) is                                                                                                                                                                                                                                                                                  

    v_param_order   number;                                                                                                                                                                                                                                                                                                              
    v_last_string   number;                                                                                                                                                                                                                                                                                                              
    v_user_ocid     varchar2(200);                                                                                                                                                                                                                                                                                                       
    v_step_id       number;                                                                                                                                                                                                                                                                                                              
    v_password      varchar2(200);                                                                                                                                                                                                                                                                                                       
    v_status        varchar2(1);                                                                                                                                                                                                                                                                                                         
    v_result        varchar2(4000);                                                                                                                                                                                                                                                                                                      

  begin                                                                                                                                                                                                                                                                                                                                  

    v_param_order := 1; -- Need to change this for multi users based on APP_USER                                                                                                                                                                                                                                                         
    v_step_id := user_object_step_id (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                              
                                      p_param_type     => 'ociUserPassword');                                                                                                                                                                                                                                                            
    ll_pkg_create.user_password (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                                   
                                 p_res_step_id    => v_step_id,                                                                                                                                                                                                                                                                          
                                 p_ocid           => v_password,                                                                                                                                                                                                                                                                         
                                 p_status         => v_status,                                                                                                                                                                                                                                                                           
                                 p_result         => v_result );                                                                                                                                                                                                                                                                         
    if v_status='Y' then                                                                                                                                                                                                                                                                                                                 
      update ll_reservation_steps set object_ocid = v_password where reservation_id = p_reservation_id and id = v_step_id;                                                                                                                                                                                                               
      commit;                                                                                                                                                                                                                                                                                                                            
    end if;                                                                                                                                                                                                                                                                                                                              
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ######## ##     ## ######## ######## ##    ## ########        ###    ##       ##        #######  ##      ## ######## ########                                                                                                                                                                                                        
--  ##        ##   ##     ##    ##       ###   ## ##     ##      ## ##   ##       ##       ##     ## ##  ##  ## ##       ##     ##                                                                                                                                                                                                       
--  ##         ## ##      ##    ##       ####  ## ##     ##     ##   ##  ##       ##       ##     ## ##  ##  ## ##       ##     ##                                                                                                                                                                                                       
--  ######      ###       ##    ######   ## ## ## ##     ##    ##     ## ##       ##       ##     ## ##  ##  ## ######   ##     ##                                                                                                                                                                                                       
--  ##         ## ##      ##    ##       ##  #### ##     ##    ######### ##       ##       ##     ## ##  ##  ## ##       ##     ##                                                                                                                                                                                                       
--  ##        ##   ##     ##    ##       ##   ### ##     ##    ##     ## ##       ##       ##     ## ##  ##  ## ##       ##     ##                                                                                                                                                                                                       
--  ######## ##     ##    ##    ######## ##    ## ########     ##     ## ######## ########  #######   ###  ###  ######## ########                                                                                                                                                                                                        
--                                                                                                                                                                                                                                                                                                                                       
  function extend_allowed (p_reservation_id number) return varchar2 is                                                                                                                                                                                                                                                                   
    cursor c_reservation is select (llr.stop_gmt - llr.start_gmt) * 24, llw.time_available, nvl(llr.extended,0) as extended                                                                                                                                                                                                              
                            from ll_reservations_vw llr, ll_workshops llw                                                                                                                                                                                                                                                                
                            where llr.workshop_id = llw.id                                                                                                                                                                                                                                                                               
                            and llr.id = p_reservation_id;                                                                                                                                                                                                                                                                               

    v_time_available number;                                                                                                                                                                                                                                                                                                             
    v_time_allocated number;                                                                                                                                                                                                                                                                                                             
    v_extended number;                                                                                                                                                                                                                                                                                                                   
    v_return_value   varchar2(1);                                                                                                                                                                                                                                                                                                        


  begin                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                                                                                                                   

    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_time_allocated, v_time_available, v_extended;                                                                                                                                                                                                                                                             
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    ll_pkg_log.log(40,'Current time allocated for reservation '||p_reservation_id||' is '||v_time_allocated);                                                                                                                                                                                                                            
    if v_time_allocated <= 2 * v_time_available and v_extended < 4 then                                                                                                                                                                                                                                                                  
      v_return_value := 'Y';                                                                                                                                                                                                                                                                                                             
    else                                                                                                                                                                                                                                                                                                                                 
      v_return_value := 'N';                                                                                                                                                                                                                                                                                                             
    end if;                                                                                                                                                                                                                                                                                                                              

    return (v_return_value);                                                                                                                                                                                                                                                                                                             
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                    
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ######## ##     ## ######## ######## ##    ## ########     ########  ########  ######  ######## ########  ##     ##    ###    ######## ####  #######  ##    ##                                                                                                                                                                       
--  ##        ##   ##     ##    ##       ###   ## ##     ##    ##     ## ##       ##    ## ##       ##     ## ##     ##   ## ##      ##     ##  ##     ## ###   ##                                                                                                                                                                       
--  ##         ## ##      ##    ##       ####  ## ##     ##    ##     ## ##       ##       ##       ##     ## ##     ##  ##   ##     ##     ##  ##     ## ####  ##                                                                                                                                                                       
--  ######      ###       ##    ######   ## ## ## ##     ##    ########  ######    ######  ######   ########  ##     ## ##     ##    ##     ##  ##     ## ## ## ##                                                                                                                                                                       
--  ##         ## ##      ##    ##       ##  #### ##     ##    ##   ##   ##             ## ##       ##   ##    ##   ##  #########    ##     ##  ##     ## ##  ####                                                                                                                                                                       
--  ##        ##   ##     ##    ##       ##   ### ##     ##    ##    ##  ##       ##    ## ##       ##    ##    ## ##   ##     ##    ##     ##  ##     ## ##   ###                                                                                                                                                                       
--  ######## ##     ##    ##    ######## ##    ## ########     ##     ## ########  ######  ######## ##     ##    ###    ##     ##    ##    ####  #######  ##    ##                                                                                                                                                                       
--                                                                                                                                                                                                                                                                                                                                       
  procedure extend_reservation (p_reservation_id number) is                                                                                                                                                                                                                                                                              

    cursor c_reservation is select llr.start_gmt, llr.stop_gmt, llr.start_timezone, llw.time_available, nvl(llr.extended,0) as extended                                                                                                                                                                                                  
                            from ll_reservations_vw llr, ll_workshops llw                                                                                                                                                                                                                                                                
                            where llr.workshop_id = llw.id                                                                                                                                                                                                                                                                               
                            and llr.id = p_reservation_id;                                                                                                                                                                                                                                                                               

    v_start_gmt      date;                                                                                                                                                                                                                                                                                                               
    v_stop_gmt       date;                                                                                                                                                                                                                                                                                                               
    v_start_timezone varchar2(200);                                                                                                                                                                                                                                                                                                      
    v_time_available number;                                                                                                                                                                                                                                                                                                             
    v_time_allocated number;                                                                                                                                                                                                                                                                                                             
    v_extended       number;                                                                                                                                                                                                                                                                                                             


  begin                                                                                                                                                                                                                                                                                                                                  

    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                                                                                                                   

    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_start_gmt, v_stop_gmt, v_start_timezone, v_time_available, v_extended;                                                                                                                                                                                                                                    
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    v_time_allocated := (v_stop_gmt - v_start_gmt) * 24;                                                                                                                                                                                                                                                                                 
    ll_pkg_log.log(40,'Current time allocated for reservation '||p_reservation_id||' is '||v_time_allocated);                                                                                                                                                                                                                            
    if v_time_allocated <= 2 * v_time_available and v_extended < 4 then                                                                                                                                                                                                                                                                  
      v_time_allocated := v_time_allocated + (0.25 * v_time_available);                                                                                                                                                                                                                                                                  
      update ll_reservations set stop_date = ll_pkg_reservation.date_timezone (p_date_gmt => v_start_gmt + (v_time_allocated/24),                                                                                                                                                                                                        
                                                                               p_timezone => v_start_timezone),                                                                                                                                                                                                                          
                                 extended = v_extended + 1                                                                                                                                                                                                                                                                               
                             where id = p_reservation_id;                                                                                                                                                                                                                                                                                
      commit;                                                                                                                                                                                                                                                                                                                            
      ll_pkg_log.log(40,'New time allocated for reservation '||p_reservation_id||' is '||v_time_allocated);                                                                                                                                                                                                                              
    end if;                                                                                                                                                                                                                                                                                                                              
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                                                                                                                    
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ######## #### ##     ## ########    ########  ######## ##     ##    ###    #### ##    ## #### ##    ##  ######                                                                                                                                                                                                                       
--     ##     ##  ###   ### ##          ##     ## ##       ###   ###   ## ##    ##  ###   ##  ##  ###   ## ##    ##                                                                                                                                                                                                                      
--     ##     ##  #### #### ##          ##     ## ##       #### ####  ##   ##   ##  ####  ##  ##  ####  ## ##                                                                                                                                                                                                                            
--     ##     ##  ## ### ## ######      ########  ######   ## ### ## ##     ##  ##  ## ## ##  ##  ## ## ## ##   ####                                                                                                                                                                                                                     
--     ##     ##  ##     ## ##          ##   ##   ##       ##     ## #########  ##  ##  ####  ##  ##  #### ##    ##                                                                                                                                                                                                                      
--     ##     ##  ##     ## ##          ##    ##  ##       ##     ## ##     ##  ##  ##   ###  ##  ##   ### ##    ##                                                                                                                                                                                                                      
--     ##    #### ##     ## ########    ##     ## ######## ##     ## ##     ## #### ##    ## #### ##    ##  ######                                                                                                                                                                                                                       
--                                                                                                                                                                                                                                                                                                                                       
  function time_remaining (p_reservation_id number) return number is                                                                                                                                                                                                                                                                     

    cursor c_reservation is select (stop_gmt - sysdate) * 24 as remaining                                                                                                                                                                                                                                                                
                            from ll_reservations_vw                                                                                                                                                                                                                                                                                      
                            where id = p_reservation_id;                                                                                                                                                                                                                                                                                 

    v_return_value number;                                                                                                                                                                                                                                                                                                               

  begin                                                                                                                                                                                                                                                                                                                                  

    open c_reservation;                                                                                                                                                                                                                                                                                                                  
    fetch c_reservation into v_return_value;                                                                                                                                                                                                                                                                                             
    close c_reservation;                                                                                                                                                                                                                                                                                                                 

    if v_return_value is null or v_return_value < 0 then                                                                                                                                                                                                                                                                                 
      v_return_value := 0;                                                                                                                                                                                                                                                                                                               
    end if;                                                                                                                                                                                                                                                                                                                              

    return(v_return_value);                                                                                                                                                                                                                                                                                                              

  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--  ########     ###    ######## ########    ######## ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ##     ##   ## ##      ##    ##          ##       ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ##     ##  ##   ##     ##    ##          ##       ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ##     ## ##     ##    ##    ######      ######   ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ##     ## #########    ##    ##          ##       ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ##     ## ##     ##    ##    ##          ##       ##     ## ##       ##                                                                                                                                                                                                                                                              
--  ########  ##     ##    ##    ########    ##        #######  ######## ########                                                                                                                                                                                                                                                        
--                                                                                                                                                                                                                                                                                                                                       
  function date_full (p_start_gmt date, p_timezone varchar2) return varchar2 is                                                                                                                                                                                                                                                          

    v_return_date  date := date_timezone (p_start_gmt, p_timezone);                                                                                                                                                                                                                                                                      
    v_return_text  varchar2(100);                                                                                                                                                                                                                                                                                                        
    v_day          number;                                                                                                                                                                                                                                                                                                               
    v_day_suffix   varchar2(10);                                                                                                                                                                                                                                                                                                         
    v_hour         number;                                                                                                                                                                                                                                                                                                               

  begin                                                                                                                                                                                                                                                                                                                                  

    v_day  := to_number(to_char(v_return_date,'DD'));                                                                                                                                                                                                                                                                                    
    v_hour := to_number(to_char(v_return_date,'HH'));                                                                                                                                                                                                                                                                                    

    if     v_day = 1 then v_day_suffix := 'st';                                                                                                                                                                                                                                                                                          
    elsif  v_day = 2 then v_day_suffix := 'nd';                                                                                                                                                                                                                                                                                          
    elsif  v_day = 3 then v_day_suffix := 'rd';                                                                                                                                                                                                                                                                                          
    elsif  v_day between 4 and 20 then v_day_suffix := 'th';                                                                                                                                                                                                                                                                             
    elsif  v_day = 21 then v_day_suffix := 'st';                                                                                                                                                                                                                                                                                         
    elsif  v_day = 22 then v_day_suffix := 'nd';                                                                                                                                                                                                                                                                                         
    elsif  v_day = 23 then v_day_suffix := 'rd';                                                                                                                                                                                                                                                                                         
    elsif  v_day between 24 and 30 then v_day_suffix := 'th';                                                                                                                                                                                                                                                                            
    elsif  v_day = 31 then v_day_suffix := 'st';                                                                                                                                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                              

    v_return_text := to_char(v_return_date,'Day Month ') ||                                                                                                                                                                                                                                                                              
                     v_day||v_day_suffix||', '||v_hour||                                                                                                                                                                                                                                                                                 
                     to_char(v_return_date,':MIam (HH24:MI)')||' '||p_timezone;                                                                                                                                                                                                                                                          
    return(v_return_text);                                                                                                                                                                                                                                                                                                               
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--   ######  ########    ###    ########  ########    ########  ########  ######  ######## ########  ##     ##    ###    ######## ####  #######  ##    ##                                                                                                                                                                                
--  ##    ##    ##      ## ##   ##     ##    ##       ##     ## ##       ##    ## ##       ##     ## ##     ##   ## ##      ##     ##  ##     ## ###   ##                                                                                                                                                                                
--  ##          ##     ##   ##  ##     ##    ##       ##     ## ##       ##       ##       ##     ## ##     ##  ##   ##     ##     ##  ##     ## ####  ##                                                                                                                                                                                
--   ######     ##    ##     ## ########     ##       ########  ######    ######  ######   ########  ##     ## ##     ##    ##     ##  ##     ## ## ## ##                                                                                                                                                                                
--        ##    ##    ######### ##   ##      ##       ##   ##   ##             ## ##       ##   ##    ##   ##  #########    ##     ##  ##     ## ##  ####                                                                                                                                                                                
--  ##    ##    ##    ##     ## ##    ##     ##       ##    ##  ##       ##    ## ##       ##    ##    ## ##   ##     ##    ##     ##  ##     ## ##   ###                                                                                                                                                                                
--   ######     ##    ##     ## ##     ##    ##       ##     ## ########  ######  ######## ##     ##    ###    ##     ##    ##    ####  #######  ##    ##                                                                                                                                                                                
--                                                                                                                                                                                                                                                                                                                                       
  procedure start_reservations is                                                                                                                                                                                                                                                                                                        
    cursor c_reservations is select id                                                                                                                                                                                                                                                                                                   
                             from ll_reservations_vw llr                                                                                                                                                                                                                                                                                 
                             where sysdate between start_gmt - ll_pkg_admin.minutes_to_days(20) and stop_gmt                                                                                                                                                                                                                             
                             and not exists (select null                                                                                                                                                                                                                                                                                 
                                                    from ll_reservation_steps llrs                                                                                                                                                                                                                                                       
                                                    where llrs.reservation_id = llr.id)                                                                                                                                                                                                                                                  
                             and instr(owner1,'@') > 0                                                                                                                                                                                                                                                                                   
                             and owner1 not like 'STRESS%'                                                                                                                                                                                                                                                                               
                             and owner1 not like '%-DONE@LIVELABS.COM';                                                                                                                                                                                                                                                                  

    cursor c_check_jobs (p_reservation_id number) is                                                                                                                                                                                                                                                                                     
                           select 'Y'                                                                                                                                                                                                                                                                                                    
                           from user_scheduler_jobs                                                                                                                                                                                                                                                                                      
		  	               where (job_name like 'IMMRES'||p_reservation_id||'_%' or                                                                                                                                                                                                                                                             
			 			          job_name like 'SETUP'||p_reservation_id||'_%' )                                                                                                                                                                                                                                                                         
                           union                                                                                                                                                                                                                                                                                                         
						   select 'Y'                                                                                                                                                                                                                                                                                                                      
						   from user_scheduler_job_log                                                                                                                                                                                                                                                                                                     
						   where (job_name like 'IMMRES'||p_reservation_id||'_%' or                                                                                                                                                                                                                                                                        
						          job_name like 'SETUP'||p_reservation_id||'_%' )                                                                                                                                                                                                                                                                          
                           and log_date > sysdate-10;                                                                                                                                                                                                                                                                                    
      v_dummy varchar2(1);								                                                                                                                                                                                                                                                                                                       

    begin                                                                                                                                                                                                                                                                                                                                

      ll_pkg_log.log(10,'Initial call');                                                                                                                                                                                                                                                                                                 

      ll_pkg_security.set_security_group;                                                                                                                                                                                                                                                                                                
      for x in c_reservations loop                                                                                                                                                                                                                                                                                                       
	    open c_check_jobs (x.id);                                                                                                                                                                                                                                                                                                           
	    fetch c_check_jobs into v_dummy;                                                                                                                                                                                                                                                                                                    
	    if c_check_jobs%NOTFOUND then                                                                                                                                                                                                                                                                                                       
          ll_pkg_log.log(30,'Scheduled reservation '||x.id);                                                                                                                                                                                                                                                                             
          ll_pkg_admin.create_job (p_type        => 'CREATE_AND_PROCESS_RES',                                                                                                                                                                                                                                                            
                                   p_parameters  => json_object( 'P1' value x.id),                                                                                                                                                                                                                                                       
			                       p_jobname     => 'SETUP'||x.id);                                                                                                                                                                                                                                                                               
        end if;                                                                                                                                                                                                                                                                                                                          
	    close c_check_jobs;                                                                                                                                                                                                                                                                                                                 
      end loop;                                                                                                                                                                                                                                                                                                                          

      ll_pkg_log.log(10,'End of call');                                                                                                                                                                                                                                                                                                  
    end;                                                                                                                                                                                                                                                                                                                                 

