--                                                                                                                                                                                                                                                                                                                                       
--  ##     ##    ###    ##       #### ########     ###    ######## ########    ########  ##     ## ########  ##       ####  ######     ##    ## ######## ##    ##                                                                                                                                                                        
--  ##     ##   ## ##   ##        ##  ##     ##   ## ##      ##    ##          ##     ## ##     ## ##     ## ##        ##  ##    ##    ##   ##  ##        ##  ##                                                                                                                                                                         
--  ##     ##  ##   ##  ##        ##  ##     ##  ##   ##     ##    ##          ##     ## ##     ## ##     ## ##        ##  ##          ##  ##   ##         ####                                                                                                                                                                          
--  ##     ## ##     ## ##        ##  ##     ## ##     ##    ##    ######      ########  ##     ## ########  ##        ##  ##          #####    ######      ##                                                                                                                                                                           
--   ##   ##  ######### ##        ##  ##     ## #########    ##    ##          ##        ##     ## ##     ## ##        ##  ##          ##  ##   ##          ##                                                                                                                                                                           
--    ## ##   ##     ## ##        ##  ##     ## ##     ##    ##    ##          ##        ##     ## ##     ## ##        ##  ##    ##    ##   ##  ##          ##                                                                                                                                                                           
--     ###    ##     ## ######## #### ########  ##     ##    ##    ########    ##         #######  ########  ######## ####  ######     ##    ## ########    ##                                                                                                                                                                           
--                                                                                                                                                                                                                                                                                                                                       
FUNCTION validate_public_key(p_key VARCHAR2)                                                                                                                                                                                                                                                                                             
RETURN VARCHAR2                                                                                                                                                                                                                                                                                                                          
IS                                                                                                                                                                                                                                                                                                                                       
    v_key_lines APEX_T_VARCHAR2;                                                                                                                                                                                                                                                                                                         
    v_key_data VARCHAR2(32767);                                                                                                                                                                                                                                                                                                          
    v_decoded RAW(32767);                                                                                                                                                                                                                                                                                                                
    v_valid VARCHAR2(1) := 'N';                                                                                                                                                                                                                                                                                                          
    v_pos NUMBER;                                                                                                                                                                                                                                                                                                                        
    v_length NUMBER;                                                                                                                                                                                                                                                                                                                     
    v_key_type VARCHAR2(100);                                                                                                                                                                                                                                                                                                            
    v_key_type_len NUMBER;                                                                                                                                                                                                                                                                                                               
    v_exponent_len NUMBER;                                                                                                                                                                                                                                                                                                               
    v_modulus_len NUMBER;                                                                                                                                                                                                                                                                                                                
BEGIN                                                                                                                                                                                                                                                                                                                                    
    -- Remove any leading/trailing whitespace                                                                                                                                                                                                                                                                                            
    v_key_data := TRIM(p_key);                                                                                                                                                                                                                                                                                                           

    -- Check if key is empty                                                                                                                                                                                                                                                                                                             
    IF v_key_data IS NULL OR LENGTH(v_key_data) = 0 THEN                                                                                                                                                                                                                                                                                 
        RETURN 'N';                                                                                                                                                                                                                                                                                                                      
    END IF;                                                                                                                                                                                                                                                                                                                              

    -- Split into lines (handle multi-line keys)                                                                                                                                                                                                                                                                                         
    v_key_lines := APEX_STRING.SPLIT(v_key_data, CHR(10));                                                                                                                                                                                                                                                                               

    -- Process each line to find the key data                                                                                                                                                                                                                                                                                            
    FOR i IN 1..v_key_lines.COUNT LOOP                                                                                                                                                                                                                                                                                                   
        v_key_data := TRIM(v_key_lines(i));                                                                                                                                                                                                                                                                                              

        -- Skip empty lines and comments                                                                                                                                                                                                                                                                                                 
        IF v_key_data IS NOT NULL AND NOT (v_key_data LIKE '#%') THEN                                                                                                                                                                                                                                                                    
            EXIT;                                                                                                                                                                                                                                                                                                                        
        END IF;                                                                                                                                                                                                                                                                                                                          
    END LOOP;                                                                                                                                                                                                                                                                                                                            

    -- Basic format validation for RSA key                                                                                                                                                                                                                                                                                               
    -- Format should be: ssh-rsa AAAAB3NzaC1yc2EA... [optional comment]                                                                                                                                                                                                                                                                  
    IF NOT REGEXP_LIKE(v_key_data, '^ssh-rsa\s+[A-Za-z0-9+/]+=*(\s+.*)?$') THEN                                                                                                                                                                                                                                                          
        RETURN 'N';                                                                                                                                                                                                                                                                                                                      
    END IF;                                                                                                                                                                                                                                                                                                                              

    -- Extract just the base64 portion (second field)                                                                                                                                                                                                                                                                                    
    v_key_data := REGEXP_SUBSTR(v_key_data, '\s+[A-Za-z0-9+/]+=*', 1, 1);                                                                                                                                                                                                                                                                
    v_key_data := TRIM(v_key_data);                                                                                                                                                                                                                                                                                                      

    -- Check minimum length (RSA keys are typically quite long)                                                                                                                                                                                                                                                                          
    -- RSA-2048 produces ~372 chars, RSA-4096 produces ~740 chars                                                                                                                                                                                                                                                                        
    IF LENGTH(v_key_data) < 350 THEN                                                                                                                                                                                                                                                                                                     
        RETURN 'N';                                                                                                                                                                                                                                                                                                                      
    END IF;                                                                                                                                                                                                                                                                                                                              

    -- Try to decode and validate the internal structure                                                                                                                                                                                                                                                                                 
    BEGIN                                                                                                                                                                                                                                                                                                                                
        v_decoded := UTL_ENCODE.BASE64_DECODE(UTL_RAW.CAST_TO_RAW(v_key_data));                                                                                                                                                                                                                                                          

        -- Validate the decoded binary structure                                                                                                                                                                                                                                                                                         
        -- SSH key format: [key type length][key type][exponent length][exponent][modulus length][modulus]                                                                                                                                                                                                                               

        v_pos := 1;                                                                                                                                                                                                                                                                                                                      

        -- Read key type length (4 bytes, big-endian)                                                                                                                                                                                                                                                                                    
        v_key_type_len := UTL_RAW.CAST_TO_BINARY_INTEGER(                                                                                                                                                                                                                                                                                
            UTL_RAW.SUBSTR(v_decoded, v_pos, 4),                                                                                                                                                                                                                                                                                         
            UTL_RAW.BIG_ENDIAN                                                                                                                                                                                                                                                                                                           
        );                                                                                                                                                                                                                                                                                                                               
        v_pos := v_pos + 4;                                                                                                                                                                                                                                                                                                              

        -- Key type length should be 7 for "ssh-rsa"                                                                                                                                                                                                                                                                                     
        IF v_key_type_len != 7 THEN                                                                                                                                                                                                                                                                                                      
            RETURN 'N';                                                                                                                                                                                                                                                                                                                  
        END IF;                                                                                                                                                                                                                                                                                                                          

        -- Read key type string                                                                                                                                                                                                                                                                                                          
        v_key_type := UTL_RAW.CAST_TO_VARCHAR2(UTL_RAW.SUBSTR(v_decoded, v_pos, v_key_type_len));                                                                                                                                                                                                                                        
        v_pos := v_pos + v_key_type_len;                                                                                                                                                                                                                                                                                                 

        -- Verify it says "ssh-rsa"                                                                                                                                                                                                                                                                                                      
        IF v_key_type != 'ssh-rsa' THEN                                                                                                                                                                                                                                                                                                  
            RETURN 'N';                                                                                                                                                                                                                                                                                                                  
        END IF;                                                                                                                                                                                                                                                                                                                          

        -- Read exponent length (4 bytes, big-endian)                                                                                                                                                                                                                                                                                    
        v_exponent_len := UTL_RAW.CAST_TO_BINARY_INTEGER(                                                                                                                                                                                                                                                                                
            UTL_RAW.SUBSTR(v_decoded, v_pos, 4),                                                                                                                                                                                                                                                                                         
            UTL_RAW.BIG_ENDIAN                                                                                                                                                                                                                                                                                                           
        );                                                                                                                                                                                                                                                                                                                               
        v_pos := v_pos + 4;                                                                                                                                                                                                                                                                                                              

        -- Exponent is typically 1 or 3 bytes (common values: 0x10001 = 65537)                                                                                                                                                                                                                                                           
        IF v_exponent_len < 1 OR v_exponent_len > 8 THEN                                                                                                                                                                                                                                                                                 
            RETURN 'N';                                                                                                                                                                                                                                                                                                                  
        END IF;                                                                                                                                                                                                                                                                                                                          

        -- Skip exponent data                                                                                                                                                                                                                                                                                                            
        v_pos := v_pos + v_exponent_len;                                                                                                                                                                                                                                                                                                 

        -- Read modulus length (4 bytes, big-endian)                                                                                                                                                                                                                                                                                     
        v_modulus_len := UTL_RAW.CAST_TO_BINARY_INTEGER(                                                                                                                                                                                                                                                                                 
            UTL_RAW.SUBSTR(v_decoded, v_pos, 4),                                                                                                                                                                                                                                                                                         
            UTL_RAW.BIG_ENDIAN                                                                                                                                                                                                                                                                                                           
        );                                                                                                                                                                                                                                                                                                                               
        v_pos := v_pos + 4;                                                                                                                                                                                                                                                                                                              

        -- Modulus length validation                                                                                                                                                                                                                                                                                                     
        -- RSA-1024: ~128 bytes, RSA-2048: ~256 bytes, RSA-4096: ~512 bytes                                                                                                                                                                                                                                                              
        -- Minimum recommended is RSA-2048 (256 bytes)                                                                                                                                                                                                                                                                                   
        IF v_modulus_len < 128 OR v_modulus_len > 1024 THEN                                                                                                                                                                                                                                                                              
            RETURN 'N';                                                                                                                                                                                                                                                                                                                  
        END IF;                                                                                                                                                                                                                                                                                                                          

        -- Verify we have enough data for the modulus                                                                                                                                                                                                                                                                                    
        v_length := UTL_RAW.LENGTH(v_decoded);                                                                                                                                                                                                                                                                                           
        IF v_pos + v_modulus_len - 1 > v_length THEN                                                                                                                                                                                                                                                                                     
            RETURN 'N';                                                                                                                                                                                                                                                                                                                  
        END IF;                                                                                                                                                                                                                                                                                                                          

        -- If we got here, the key structure is valid                                                                                                                                                                                                                                                                                    
        v_valid := 'Y';                                                                                                                                                                                                                                                                                                                  

    EXCEPTION                                                                                                                                                                                                                                                                                                                            
        WHEN OTHERS THEN                                                                                                                                                                                                                                                                                                                 
            -- Any error in parsing means invalid key                                                                                                                                                                                                                                                                                    
            v_valid := 'N';                                                                                                                                                                                                                                                                                                              
    END;                                                                                                                                                                                                                                                                                                                                 

    RETURN v_valid;                                                                                                                                                                                                                                                                                                                      

EXCEPTION                                                                                                                                                                                                                                                                                                                                
    WHEN OTHERS THEN                                                                                                                                                                                                                                                                                                                     
        -- Any unexpected error means invalid key                                                                                                                                                                                                                                                                                        
        RETURN 'N';                                                                                                                                                                                                                                                                                                                      
END;                                                                                                                                                                                                                                                                                                                                     


--                                                                                                                                                                                                                                                                                                                                       
-- ======================================================================================================================================                                                                                                                                                                                                
--                                                                                                                                                                                                                                                                                                                                       
  procedure bad_ssh_during_setup (p_reservation_id number) is                                                                                                                                                                                                                                                                            
    cursor c_jobs is select job_name                                                                                                                                                                                                                                                                                                     
                     from user_scheduler_jobs                                                                                                                                                                                                                                                                                            
		  	             where (job_name like 'IMMRES'||p_reservation_id||'_%'                                                                                                                                                                                                                                                                  
                            or                                                                                                                                                                                                                                                                                                           
			 			                job_name like 'SETUP'||p_reservation_id||'_%' )                                                                                                                                                                                                                                                                   
                     and state='RUNNING';                                                                                                                                                                                                                                                                                                
    v_job_name  varchar2(4000);                                                                                                                                                                                                                                                                                                          
    v_status    varchar2(1);                                                                                                                                                                                                                                                                                                             
    v_result    varchar2(4000);                                                                                                                                                                                                                                                                                                          
  begin                                                                                                                                                                                                                                                                                                                                  
  -- Make reservation invalid                                                                                                                                                                                                                                                                                                            
    update ll_reservations set active_flg='N' where id = p_reservation_id;                                                                                                                                                                                                                                                               
    commit;                                                                                                                                                                                                                                                                                                                              
    -- Send email to attendee                                                                                                                                                                                                                                                                                                            
    ll_pkg_apex.send_template_email (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                               
                                     p_phase          => 'BAD_SSH_KEY',                                                                                                                                                                                                                                                                  
                                     p_status         => v_status,                                                                                                                                                                                                                                                                       
                                     p_result         => v_result);                                                                                                                                                                                                                                                                      
    -- Log the error                                                                                                                                                                                                                                                                                                                     
    ll_pkg_log.log(1,'Bad SSH key detected in reservation '||p_reservation_id);                                                                                                                                                                                                                                                          
    -- Kill setup job                                                                                                                                                                                                                                                                                                                    
    open c_jobs;                                                                                                                                                                                                                                                                                                                         
    fetch c_jobs into v_job_name;                                                                                                                                                                                                                                                                                                        
    close c_jobs;                                                                                                                                                                                                                                                                                                                        
    DBMS_SCHEDULER.STOP_JOB( v_job_name ,force => FALSE);                                                                                                                                                                                                                                                                                
  end;                                                                                                                                                                                                                                                                                                                                   
--                                                                                                                                                                                                                                                                                                                                       
--                                                                                                                                                                                                                                                                                                                                       
