-- ============================================================================================================                                                                                                                                                                                                                          
  procedure display_attendee_details (p_reservation_id number, p_attendee_id number default 1) is                                                                                                                                                                                                                                        

  begin                                                                                                                                                                                                                                                                                                                                  
    ll_pkg_apex.display_attendee_details (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                          
                                          p_attendee_id    => p_attendee_id);                                                                                                                                                                                                                                                            
  end;                                                                                                                                                                                                                                                                                                                                   

-- ============================================================================================                                                                                                                                                                                                                                          
  procedure display_attendee_login_help (p_reservation_id number, p_attendee_id number default 1) is                                                                                                                                                                                                                                     
  begin                                                                                                                                                                                                                                                                                                                                  
    ll_pkg_apex.display_attendee_login_help (p_reservation_id => p_reservation_id,                                                                                                                                                                                                                                                       
                                             p_attendee_id    => p_attendee_id);                                                                                                                                                                                                                                                         
  end;                                                                                                                                                                                                                                                                                                                                   

-- ============================================================================================                                                                                                                                                                                                                                          
    function workshop_id (p_reservation_id number) return number is                                                                                                                                                                                                                                                                      
        v_workshop_id number;                                                                                                                                                                                                                                                                                                            
    begin                                                                                                                                                                                                                                                                                                                                
        select workshop_id into v_workshop_id from ll_reservations where id = p_reservation_id;                                                                                                                                                                                                                                          
        return v_workshop_id;                                                                                                                                                                                                                                                                                                            
    end;                                                                                                                                                                                                                                                                                                                                 

-- ============================================================================================                                                                                                                                                                                                                                          
    function event_id (p_reservation_id number) return number is                                                                                                                                                                                                                                                                         
        v_event_id number;                                                                                                                                                                                                                                                                                                               
    begin                                                                                                                                                                                                                                                                                                                                
        select voucher_id into v_event_id from ll_reservations where id = p_reservation_id;                                                                                                                                                                                                                                              
        return v_event_id;                                                                                                                                                                                                                                                                                                               
    end;                                                                                                                                                                                                                                                                                                                                 








-- Optimized rewrite of find_available_tenancy based on find_available_tenancy.sql                                                                                                                                                                                                                                                       
-- Eliminates temp-table DML and autonomous transaction while preserving                                                                                                                                                                                                                                                                 
-- existing business rules. Each comment uses standard single-line syntax.                                                                                                                                                                                                                                                               

PROCEDURE find_available_tenancy_opt (                                                                                                                                                                                                                                                                                                   
    p_tenancy_id     OUT NUMBER,                                                                                                                                                                                                                                                                                                         
    p_region_id      OUT NUMBER,                                                                                                                                                                                                                                                                                                         
    p_available_json OUT CLOB,                                                                                                                                                                                                                                                                                                           
    p_workshop_id    IN  NUMBER DEFAULT NULL,                                                                                                                                                                                                                                                                                            
    p_event_id       IN  NUMBER DEFAULT NULL,                                                                                                                                                                                                                                                                                            
    p_res_id         IN  NUMBER DEFAULT NULL                                                                                                                                                                                                                                                                                             
) IS                                                                                                                                                                                                                                                                                                                                     
    -- Context mirrors legacy procedure: only one of the identifiers is allowed.                                                                                                                                                                                                                                                         
    v_workshop_id          NUMBER;                                                                                                                                                                                                                                                                                                       
    v_event_id_ctx         NUMBER;                                                                                                                                                                                                                                                                                                       
    v_tenancy_id_pref      NUMBER;                                                                                                                                                                                                                                                                                                       
    v_region_id_pref       NUMBER;                                                                                                                                                                                                                                                                                                       
    v_tenancies_allowed    VARCHAR2(1000);                                                                                                                                                                                                                                                                                               
    v_workshop_regions_set NUMBER := 0;                                                                                                                                                                                                                                                                                                  
    v_restrict_public      VARCHAR2(1) := 'N';                                                                                                                                                                                                                                                                                           
    v_country_code         VARCHAR2(20);                                                                                                                                                                                                                                                                                                 
    v_username             VARCHAR2(200);                                                                                                                                                                                                                                                                                                
    v_param_filled         PLS_INTEGER := 0;                                                                                                                                                                                                                                                                                             
    v_busy_threshold_raw   VARCHAR2(100);                                                                                                                                                                                                                                                                                                
    v_busy_threshold       NUMBER := 100;                                                                                                                                                                                                                                                                                                
    v_res_busy_count       NUMBER := 0;                                                                                                                                                                                                                                                                                                  
    v_res_busy_flag        VARCHAR2(1) := 'N';                                                                                                                                                                                                                                                                                           

    -- Cursor builds candidate tenancy/region rows using a chain of CTEs.                                                                                                                                                                                                                                                                
    CURSOR c_candidates IS                                                                                                                                                                                                                                                                                                               
        WITH ctx AS (                                                                                                                                                                                                                                                                                                                    
             -- Freeze resolved input context for downstream use.                                                                                                                                                                                                                                                                        
             SELECT v_workshop_id          AS workshop_id,                                                                                                                                                                                                                                                                               
                    v_event_id_ctx         AS event_id,                                                                                                                                                                                                                                                                                  
                    v_tenancy_id_pref      AS tenancy_id,                                                                                                                                                                                                                                                                                
                    v_region_id_pref       AS region_id,                                                                                                                                                                                                                                                                                 
                    v_tenancies_allowed    AS tenancies_allowed,                                                                                                                                                                                                                                                                         
                    v_restrict_public      AS restrict_public,                                                                                                                                                                                                                                                                           
                    v_workshop_regions_set AS workshop_regions_set,                                                                                                                                                                                                                                                                      
                    v_country_code         AS country_code,                                                                                                                                                                                                                                                                              
                    v_res_busy_flag        AS res_busy                                                                                                                                                                                                                                                                                   
               FROM dual                                                                                                                                                                                                                                                                                                                 
        ),                                                                                                                                                                                                                                                                                                                               
        requirements AS (                                                                                                                                                                                                                                                                                                                
             -- Resource requirements for the workshop.                                                                                                                                                                                                                                                                                  
             SELECT req.resource_id,                                                                                                                                                                                                                                                                                                     
                    req.environments AS resource_required                                                                                                                                                                                                                                                                                
               FROM ctx,                                                                                                                                                                                                                                                                                                                 
                    ll_ws_resources_required_vw req                                                                                                                                                                                                                                                                                      
              WHERE req.workshop_id = ctx.workshop_id                                                                                                                                                                                                                                                                                    
        ),                                                                                                                                                                                                                                                                                                                               
        resource_count AS (                                                                                                                                                                                                                                                                                                              
             -- Total number of required resource types.                                                                                                                                                                                                                                                                                 
             SELECT COUNT(*) AS total_resources                                                                                                                                                                                                                                                                                          
               FROM requirements                                                                                                                                                                                                                                                                                                         
        ),                                                                                                                                                                                                                                                                                                                               
        base AS (                                                                                                                                                                                                                                                                                                                        
             -- Capacity joined with requirements and all hard filters applied.                                                                                                                                                                                                                                                          
             SELECT req.resource_id,                                                                                                                                                                                                                                                                                                     
                    avail.tenancy_id,                                                                                                                                                                                                                                                                                                    
                    avail.region_id,                                                                                                                                                                                                                                                                                                     
                    req.resource_required,                                                                                                                                                                                                                                                                                               
                    avail.num_available   AS resource_available,                                                                                                                                                                                                                                                                         
                    avail.num_provided,                                                                                                                                                                                                                                                                                                  
                    avail.num_reserved,                                                                                                                                                                                                                                                                                                  
                    lt.is_public,                                                                                                                                                                                                                                                                                                        
                    NVL(lt.preference_weight, 0) AS pref_weight                                                                                                                                                                                                                                                                          
               FROM ctx,                                                                                                                                                                                                                                                                                                                 
                    requirements req                                                                                                                                                                                                                                                                                                     
                    JOIN ll_res_available_vw avail                                                                                                                                                                                                                                                                                       
                      ON avail.resource_id = req.resource_id                                                                                                                                                                                                                                                                             
                    JOIN ll_tenancies lt                                                                                                                                                                                                                                                                                                 
                      ON lt.id = avail.tenancy_id                                                                                                                                                                                                                                                                                        
                     AND NVL(lt.active_flg, 'Y') = 'Y'                                                                                                                                                                                                                                                                                   
                    JOIN ll_oci_regions lor                                                                                                                                                                                                                                                                                              
                      ON lor.id = avail.region_id                                                                                                                                                                                                                                                                                        
                     AND NVL(lor.active_flg, 'Y') = 'Y'                                                                                                                                                                                                                                                                                  
              WHERE avail.num_available >= req.resource_required                                                                                                                                                                                                                                                                         
                AND (ctx.tenancy_id IS NULL OR avail.tenancy_id = ctx.tenancy_id)                                                                                                                                                                                                                                                        
                AND (ctx.region_id  IS NULL OR avail.region_id  = ctx.region_id)                                                                                                                                                                                                                                                         
                AND (ctx.tenancy_id IS NOT NULL                                                                                                                                                                                                                                                                                          
                     OR ctx.tenancies_allowed IS NULL                                                                                                                                                                                                                                                                                    
                     OR INSTR(':' || ctx.tenancies_allowed || ':', ':' || TO_CHAR(avail.tenancy_id) || ':') > 0)                                                                                                                                                                                                                         
                -- AND (ctx.restrict_public = 'N' OR lt.is_public = 'Y')                                                                                                                                                                                                                                                                 
                AND (   ctx.workshop_regions_set = 0                                                                                                                                                                                                                                                                                     
                     OR EXISTS (                                                                                                                                                                                                                                                                                                         
                            SELECT 1                                                                                                                                                                                                                                                                                                     
                              FROM ll_workshop_regions wr                                                                                                                                                                                                                                                                                
                             WHERE wr.workshop_id = ctx.workshop_id                                                                                                                                                                                                                                                                      
                               AND wr.tenancy_id = avail.tenancy_id                                                                                                                                                                                                                                                                      
                               AND wr.region_id  = avail.region_id) )                                                                                                                                                                                                                                                                    
        ),                                                                                                                                                                                                                                                                                                                               
        tenancy_usage AS (                                                                                                                                                                                                                                                                                                               
             -- Count active reservations per tenancy for busy adjustment.                                                                                                                                                                                                                                                               
             SELECT tenancy_id, COUNT(*) AS res_count                                                                                                                                                                                                                                                                                    
               FROM ll_reservations_vw                                                                                                                                                                                                                                                                                                   
              WHERE active_flg = 'Y'                                                                                                                                                                                                                                                                                                     
                AND start_date > sysdate - 1                                                                                                                                                                                                                                                                                             
           GROUP BY tenancy_id                                                                                                                                                                                                                                                                                                           
        ),                                                                                                                                                                                                                                                                                                                               
        region_rank AS (                                                                                                                                                                                                                                                                                                                 
             -- Distance-based region bonus (matching legacy behaviour).                                                                                                                                                                                                                                                                 
             SELECT lor.id AS region_id,                                                                                                                                                                                                                                                                                                 
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN ctx.country_code IS NULL THEN 0                                                                                                                                                                                                                                                                             
                        ELSE DENSE_RANK() OVER (                                                                                                                                                                                                                                                                                         
                                 ORDER BY ll_pkg_admin.distance_country_dc(                                                                                                                                                                                                                                                              
                                                  p_country_code => ctx.country_code,                                                                                                                                                                                                                                                    
                                                  p_region_id    => lor.id) DESC) * 100                                                                                                                                                                                                                                                  
                    END AS region_rank_bonus                                                                                                                                                                                                                                                                                             
               FROM ctx,                                                                                                                                                                                                                                                                                                                 
                    ll_oci_regions lor                                                                                                                                                                                                                                                                                                   
        ),                                                                                                                                                                                                                                                                                                                               
        row_scores AS (                                                                                                                                                                                                                                                                                                                  
             -- Compute per-resource multipliers and bonuses.                                                                                                                                                                                                                                                                            
             SELECT b.resource_id,                                                                                                                                                                                                                                                                                                       
                    b.tenancy_id,                                                                                                                                                                                                                                                                                                        
                    b.region_id,                                                                                                                                                                                                                                                                                                         
                    b.resource_required,                                                                                                                                                                                                                                                                                                 
                    b.resource_available,                                                                                                                                                                                                                                                                                                
                    b.num_provided,                                                                                                                                                                                                                                                                                                      
                    b.num_reserved,                                                                                                                                                                                                                                                                                                      
                    b.is_public,                                                                                                                                                                                                                                                                                                         
                    NVL(b.pref_weight, 0) AS pref_weight,                                                                                                                                                                                                                                                                                
                    NVL(tu.res_count, 0)  AS res_count,                                                                                                                                                                                                                                                                                  
                    NVL(rr.region_rank_bonus, 0) AS region_rank_bonus,                                                                                                                                                                                                                                                                   
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN ctx.tenancy_id IS NOT NULL AND b.tenancy_id = ctx.tenancy_id THEN 5                                                                                                                                                                                                                                         
                        ELSE 1                                                                                                                                                                                                                                                                                                           
                    END AS explicit_tenancy_mul,                                                                                                                                                                                                                                                                                         
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN ctx.tenancy_id IS NULL                                                                                                                                                                                                                                                                                      
                         AND ctx.tenancies_allowed IS NOT NULL                                                                                                                                                                                                                                                                           
                         AND INSTR(':' || ctx.tenancies_allowed || ':', ':' || TO_CHAR(b.tenancy_id) || ':') > 0 THEN 3                                                                                                                                                                                                                  
                        ELSE 1                                                                                                                                                                                                                                                                                                           
                    END AS allowed_list_mul,                                                                                                                                                                                                                                                                                             
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN ctx.tenancy_id IS NOT NULL                                                                                                                                                                                                                                                                                  
                         AND ctx.region_id  IS NOT NULL                                                                                                                                                                                                                                                                                  
                         AND b.tenancy_id = ctx.tenancy_id                                                                                                                                                                                                                                                                               
                         AND b.region_id  = ctx.region_id THEN 1.2                                                                                                                                                                                                                                                                       
                        ELSE 1                                                                                                                                                                                                                                                                                                           
                    END AS explicit_region_mul,                                                                                                                                                                                                                                                                                          
                    CASE WHEN b.is_public = 'Y' THEN 1.6 ELSE 1 END AS public_mul,                                                                                                                                                                                                                                                       
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN b.resource_required <= 0 THEN 0                                                                                                                                                                                                                                                                             
                        WHEN b.resource_available <= 0 THEN 0                                                                                                                                                                                                                                                                            
                        ELSE FLOOR(b.resource_available / b.resource_required)                                                                                                                                                                                                                                                           
                    END AS per_resource_env                                                                                                                                                                                                                                                                                              
               FROM base b                                                                                                                                                                                                                                                                                                               
               CROSS JOIN ctx                                                                                                                                                                                                                                                                                                            
               LEFT JOIN tenancy_usage tu ON tu.tenancy_id = b.tenancy_id                                                                                                                                                                                                                                                                
               LEFT JOIN region_rank  rr ON rr.region_id  = b.region_id                                                                                                                                                                                                                                                                  
        ),                                                                                                                                                                                                                                                                                                                               
        row_points AS (                                                                                                                                                                                                                                                                                                                  
             -- Apply multiplicative factors and additive bonuses.                                                                                                                                                                                                                                                                       
             SELECT rs.*,                                                                                                                                                                                                                                                                                                                
                    100                                                                                                                                                                                                                                                                                                                  
                    * rs.explicit_tenancy_mul                                                                                                                                                                                                                                                                                            
                    * rs.allowed_list_mul                                                                                                                                                                                                                                                                                                
                    * rs.explicit_region_mul                                                                                                                                                                                                                                                                                             
                    * rs.public_mul                                       AS base_points,                                                                                                                                                                                                                                                
                    CASE                                                                                                                                                                                                                                                                                                                 
                        WHEN rs.is_public = 'Y' THEN                                                                                                                                                                                                                                                                                     
                            GREATEST(                                                                                                                                                                                                                                                                                                    
                                (CASE ctx.res_busy WHEN 'Y' THEN 80 ELSE rs.pref_weight END)                                                                                                                                                                                                                                             
                                - rs.res_count,                                                                                                                                                                                                                                                                                          
                                0)                                                                                                                                                                                                                                                                                                       
                        ELSE 0                                                                                                                                                                                                                                                                                                           
                    END                                                   AS busy_bonus,                                                                                                                                                                                                                                                 
                    rs.region_rank_bonus                                   AS region_bonus                                                                                                                                                                                                                                               
               FROM row_scores rs                                                                                                                                                                                                                                                                                                        
               CROSS JOIN ctx                                                                                                                                                                                                                                                                                                            
        ),                                                                                                                                                                                                                                                                                                                               
        aggregated AS (                                                                                                                                                                                                                                                                                                                  
             -- Aggregate per-resource values to tenancy/region totals.                                                                                                                                                                                                                                                                  
             SELECT rp.tenancy_id,                                                                                                                                                                                                                                                                                                       
                    rp.region_id,                                                                                                                                                                                                                                                                                                        
                    SUM(                                                                                                                                                                                                                                                                                                                 
                        CASE                                                                                                                                                                                                                                                                                                             
                            WHEN base_points + busy_bonus + region_bonus <= 0 THEN 0                                                                                                                                                                                                                                                     
                            ELSE rp.per_resource_env                                                                                                                                                                                                                                                                                     
                        END) AS environments_raw,                                                                                                                                                                                                                                                                                        
                    SUM(base_points + busy_bonus + region_bonus) AS preference_points,                                                                                                                                                                                                                                                   
                    SUM(rp.resource_required)                    AS total_required,                                                                                                                                                                                                                                                      
                    SUM(rp.resource_available)                   AS total_available,                                                                                                                                                                                                                                                     
                    COUNT(*)                                     AS resource_count_present                                                                                                                                                                                                                                               
               FROM row_points rp                                                                                                                                                                                                                                                                                                        
           GROUP BY rp.tenancy_id, rp.region_id                                                                                                                                                                                                                                                                                          
        ),                                                                                                                                                                                                                                                                                                                               
        final AS (                                                                                                                                                                                                                                                                                                                       
             -- Keep only combinations that satisfy every required resource.                                                                                                                                                                                                                                                             
             SELECT a.tenancy_id,                                                                                                                                                                                                                                                                                                        
                    a.region_id,                                                                                                                                                                                                                                                                                                         
                    CASE WHEN a.preference_points <= 0 THEN 0 ELSE a.environments_raw END AS environments,                                                                                                                                                                                                                               
                    a.preference_points,                                                                                                                                                                                                                                                                                                 
                    a.total_required,                                                                                                                                                                                                                                                                                                    
                    a.total_available                                                                                                                                                                                                                                                                                                    
               FROM aggregated a                                                                                                                                                                                                                                                                                                         
               CROSS JOIN resource_count rc                                                                                                                                                                                                                                                                                              
              WHERE a.resource_count_present = rc.total_resources                                                                                                                                                                                                                                                                        
        )                                                                                                                                                                                                                                                                                                                                
        SELECT tenancy_id,                                                                                                                                                                                                                                                                                                               
               region_id,                                                                                                                                                                                                                                                                                                                
               environments,                                                                                                                                                                                                                                                                                                             
               preference_points                                                                                                                                                                                                                                                                                                         
          FROM final                                                                                                                                                                                                                                                                                                                     
      ORDER BY preference_points DESC, tenancy_id, region_id;                                                                                                                                                                                                                                                                            

    l_entry  CLOB;                                                                                                                                                                                                                                                                                                                       
    l_first  BOOLEAN := TRUE;                                                                                                                                                                                                                                                                                                            
BEGIN                                                                                                                                                                                                                                                                                                                                    
    -- Initialise outputs.                                                                                                                                                                                                                                                                                                               
    p_tenancy_id     := NULL;                                                                                                                                                                                                                                                                                                            
    p_region_id      := NULL;                                                                                                                                                                                                                                                                                                            
    p_available_json := '[]';                                                                                                                                                                                                                                                                                                            

    -- Resolve inputs exactly as the legacy procedure.                                                                                                                                                                                                                                                                                   
    IF p_workshop_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                    
        v_param_filled := v_param_filled + 1;                                                                                                                                                                                                                                                                                            
        v_workshop_id  := p_workshop_id;                                                                                                                                                                                                                                                                                                 
    END IF;                                                                                                                                                                                                                                                                                                                              
    IF p_event_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                       
        v_param_filled := v_param_filled + 1;                                                                                                                                                                                                                                                                                            
        v_event_id_ctx := p_event_id;                                                                                                                                                                                                                                                                                                    
    END IF;                                                                                                                                                                                                                                                                                                                              
    IF p_res_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                         
        v_param_filled := v_param_filled + 1;                                                                                                                                                                                                                                                                                            
        BEGIN                                                                                                                                                                                                                                                                                                                            
            SELECT workshop_id, voucher_id, tenancy_id, region_id                                                                                                                                                                                                                                                                        
              INTO v_workshop_id, v_event_id_ctx, v_tenancy_id_pref, v_region_id_pref                                                                                                                                                                                                                                                    
              FROM ll_reservations                                                                                                                                                                                                                                                                                                       
             WHERE id = p_res_id;                                                                                                                                                                                                                                                                                                        
        EXCEPTION                                                                                                                                                                                                                                                                                                                        
            WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                                                                                                      
                RAISE_APPLICATION_ERROR(-20001, 'Reservation not found for ID ' || p_res_id);                                                                                                                                                                                                                                            
        END;                                                                                                                                                                                                                                                                                                                             
    END IF;                                                                                                                                                                                                                                                                                                                              

    IF v_param_filled = 0 THEN                                                                                                                                                                                                                                                                                                           
        RAISE_APPLICATION_ERROR(-20002, 'Provide workshop_id, event_id, or res_id.');                                                                                                                                                                                                                                                    
    ELSIF v_param_filled > 1 THEN                                                                                                                                                                                                                                                                                                        
        RAISE_APPLICATION_ERROR(-20003, 'Only one of workshop_id, event_id, or res_id may be supplied.');                                                                                                                                                                                                                                
    END IF;                                                                                                                                                                                                                                                                                                                              

    IF v_workshop_id IS NULL THEN                                                                                                                                                                                                                                                                                                        
        BEGIN                                                                                                                                                                                                                                                                                                                            
            SELECT workshop_id                                                                                                                                                                                                                                                                                                           
              INTO v_workshop_id                                                                                                                                                                                                                                                                                                         
              FROM ll_vouchers                                                                                                                                                                                                                                                                                                           
             WHERE id = v_event_id_ctx;                                                                                                                                                                                                                                                                                                  
        EXCEPTION                                                                                                                                                                                                                                                                                                                        
            WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                                                                                                      
                RAISE_APPLICATION_ERROR(-20004, 'Unable to resolve workshop_id for the request.');                                                                                                                                                                                                                                       
        END;                                                                                                                                                                                                                                                                                                                             
    END IF;                                                                                                                                                                                                                                                                                                                              

    BEGIN                                                                                                                                                                                                                                                                                                                                
        SELECT REPLACE(NVL(tenancies_allowed, ''), ' ', '')                                                                                                                                                                                                                                                                              
          INTO v_tenancies_allowed                                                                                                                                                                                                                                                                                                       
          FROM ll_workshops                                                                                                                                                                                                                                                                                                              
         WHERE id = v_workshop_id;                                                                                                                                                                                                                                                                                                       
    EXCEPTION                                                                                                                                                                                                                                                                                                                            
        WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                                                                                                          
            v_tenancies_allowed := NULL;                                                                                                                                                                                                                                                                                                 
    END;                                                                                                                                                                                                                                                                                                                                 

    SELECT COUNT(*)                                                                                                                                                                                                                                                                                                                      
      INTO v_workshop_regions_set                                                                                                                                                                                                                                                                                                        
      FROM ll_workshop_regions                                                                                                                                                                                                                                                                                                           
     WHERE workshop_id = v_workshop_id;                                                                                                                                                                                                                                                                                                  

    IF v_tenancy_id_pref IS NULL                                                                                                                                                                                                                                                                                                         
       AND (v_tenancies_allowed IS NULL OR v_tenancies_allowed = '')                                                                                                                                                                                                                                                                     
       AND v_workshop_regions_set = 0 THEN                                                                                                                                                                                                                                                                                               
        v_restrict_public := 'Y';                                                                                                                                                                                                                                                                                                        
    END IF;                                                                                                                                                                                                                                                                                                                              

    IF p_res_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                         
        BEGIN                                                                                                                                                                                                                                                                                                                            
            SELECT owner1                                                                                                                                                                                                                                                                                                                
              INTO v_username                                                                                                                                                                                                                                                                                                            
              FROM ll_reservations                                                                                                                                                                                                                                                                                                       
             WHERE id = p_res_id;                                                                                                                                                                                                                                                                                                        

            v_country_code := ll_pkg_admin.get_country(v_username);                                                                                                                                                                                                                                                                      
        EXCEPTION                                                                                                                                                                                                                                                                                                                        
            WHEN OTHERS THEN                                                                                                                                                                                                                                                                                                             
                v_country_code := NULL;                                                                                                                                                                                                                                                                                                  
        END;                                                                                                                                                                                                                                                                                                                             
    END IF;                                                                                                                                                                                                                                                                                                                              

    BEGIN                                                                                                                                                                                                                                                                                                                                
        SELECT ll_pkg_admin.system_parameter('RESERVATION_BUSY_COUNT')                                                                                                                                                                                                                                                                   
          INTO v_busy_threshold_raw                                                                                                                                                                                                                                                                                                      
          FROM dual;                                                                                                                                                                                                                                                                                                                     
    EXCEPTION                                                                                                                                                                                                                                                                                                                            
        WHEN OTHERS THEN                                                                                                                                                                                                                                                                                                                 
            v_busy_threshold_raw := NULL;                                                                                                                                                                                                                                                                                                
    END;                                                                                                                                                                                                                                                                                                                                 
    v_busy_threshold := NVL(ll_pkg_admin.is_number(v_busy_threshold_raw), 100);                                                                                                                                                                                                                                                          

    SELECT COUNT(*)                                                                                                                                                                                                                                                                                                                      
      INTO v_res_busy_count                                                                                                                                                                                                                                                                                                              
      FROM ll_reservations_vw                                                                                                                                                                                                                                                                                                            
     WHERE start_gmt BETWEEN sysdate - 0.1 AND sysdate + 0.1;                                                                                                                                                                                                                                                                            

    IF v_res_busy_count > v_busy_threshold THEN                                                                                                                                                                                                                                                                                          
        v_res_busy_flag := 'Y';                                                                                                                                                                                                                                                                                                          
    END IF;                                                                                                                                                                                                                                                                                                                              

    -- Build JSON output and choose the top-scoring tenancy/region.                                                                                                                                                                                                                                                                      
    p_available_json := '[';                                                                                                                                                                                                                                                                                                             

    FOR rec IN c_candidates LOOP                                                                                                                                                                                                                                                                                                         
        IF l_first THEN                                                                                                                                                                                                                                                                                                                  
            p_tenancy_id := rec.tenancy_id;                                                                                                                                                                                                                                                                                              
            p_region_id  := rec.region_id;                                                                                                                                                                                                                                                                                               
            l_first      := FALSE;                                                                                                                                                                                                                                                                                                       
        ELSE                                                                                                                                                                                                                                                                                                                             
            p_available_json := p_available_json || ',';                                                                                                                                                                                                                                                                                 
        END IF;                                                                                                                                                                                                                                                                                                                          

        SELECT JSON_OBJECT(                                                                                                                                                                                                                                                                                                              
                   'tenancy_id'        VALUE rec.tenancy_id,                                                                                                                                                                                                                                                                             
                   'region_id'         VALUE rec.region_id,                                                                                                                                                                                                                                                                              
                   'environments'      VALUE rec.environments,                                                                                                                                                                                                                                                                           
                   'preference_points' VALUE rec.preference_points                                                                                                                                                                                                                                                                       
               )                                                                                                                                                                                                                                                                                                                         
          INTO l_entry                                                                                                                                                                                                                                                                                                                   
          FROM dual;                                                                                                                                                                                                                                                                                                                     

        p_available_json := p_available_json || l_entry;                                                                                                                                                                                                                                                                                 
    END LOOP;                                                                                                                                                                                                                                                                                                                            

    IF l_first THEN                                                                                                                                                                                                                                                                                                                      
        p_available_json := '[]';                                                                                                                                                                                                                                                                                                        
        p_tenancy_id     := NULL;                                                                                                                                                                                                                                                                                                        
        p_region_id      := NULL;                                                                                                                                                                                                                                                                                                        
    ELSE                                                                                                                                                                                                                                                                                                                                 
        p_available_json := p_available_json || ']';                                                                                                                                                                                                                                                                                     
    END IF;                                                                                                                                                                                                                                                                                                                              
END;                                                                                                                                                                                                                                                                                                                                     










END LL_PKG_RESERVATION;
