  CREATE OR REPLACE PACKAGE BODY "LL_PKG_SCHEDULED" as
  procedure run_every_10_min is
    v_sqlerrm   varchar2(4000);
  begin
    ll_pkg_log.log(10,'Running EVERY 10 MINUTES job');
    if nvl(ll_pkg_admin.system_parameter('CLEAN_USED_COMPS_10MIN'), 'N') = 'Y' then 
        ll_pkg_delete.clean_compartments_used;
    end if;
    ll_pkg_admin.send_warning_almost_expired;
    ll_pkg_reservation.clean_reservations_ended;
    ll_pkg_reservation.start_reservations;
    --ll_pkg_overview.compartments;
    ll_pkg_log.reset_loglevel;
    ll_pkg_log.log(10,'End EVERY 10 MINUTES job');
    exception
      when others then begin
                         v_sqlerrm := SQLERRM;
                         ll_pkg_log.log(1,'Error during execution of every 10 minutes job: '||v_sqlerrm);
                       end;
  end;
  
  procedure run_every_hour is
    v_sqlerrm   varchar2(4000);
  begin
    ll_pkg_log.log(10,'Running EVERY HOUR job');
    ll_pkg_delete.clean_compartments_used;
    if ll_pkg_admin.system_parameter('CLEAN_RECYCLEBIN') <> 'N' then
      ll_pkg_admin.clean_compartments_recyclebin;
      end if;
    ll_pkg_admin.truncate_ll_logging (p_hours => 1);
    -- find workshops that do not have enough resources to run 
    -- ll_pkg_status.checkWorkshopResources;
    DBMS_MVIEW.REFRESH(
        list => 'll_workshop_tags_search_mv',
        method => 'C',
        atomic_refresh => TRUE  -- Builds in temp space, swaps atomically
    );
    DBMS_MVIEW.REFRESH(
        list => 'll_livestack_tags_search_mv',
        method => 'C',
        atomic_refresh => TRUE  -- Builds in temp space, swaps atomically
    );
    ll_pkg_log.log(10,'End EVERY HOUR job');
    exception
      when others then begin
                         v_sqlerrm := SQLERRM;
                         ll_pkg_log.log(1,'Error during execution of every 1 hour job: '||v_sqlerrm);
                       end;
  end;
  
