    exception when others then 
        v_sqlerrm := SQLERRM;
        ll_pkg_log.log(1,'Error during execution of every 1 day job delete reservation steps: '||v_sqlerrm);
    end;
    begin
    ll_pkg_admin.send_eventcode_overviews;
