    begin
        ll_pkg_admin.generate_sitemap;
        ll_pkg_log.log(1,'Generated Google sitemap');
        exception when others then 
            v_sqlerrm := SQLERRM;
            ll_pkg_log.log(1,'Error during execution of every 1 day job generation of Google sitemap: '||v_sqlerrm);
    end;

    begin
        ll_pkg_log.log(1,'Daily Delete Compartments1');
        if ll_pkg_admin.system_parameter('DELETE_COMPARTMENTS') <> 'N' then -- make sure to put the available ocid for all the compartments
            ll_pkg_log.log(1,'Daily Delete Compartments2');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 4, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaaf7yhqpyesiqxdf5yhrj4ck5m2rwsoc3osfmymgmy2zvfsm6xelga', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaagnz7ao6z6yp25ntrw72i2jmwetavauvlws5yl3fmiuncuqvphouq');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 6, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaa6raqnjl5j3436x727hkfl2dd2lqzkplri3lzug42alqun54wgbcq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaafmu7avnm4ndmoeljwad4m5mg2ktwouvtyi6tq3dbuboucxik4f4a');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 11, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaaftqn4nu2jtlbxytuzqb6qg4ss2v7awg2cku4swwvvlxdbdpburhq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaa2pifkeu3ko46nwuicbsqg6vgjx5pvip77noivylczw35if2okeia');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 5, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaasg7dikz3txfpotjzmkzdchbze3pgbxgvqsbnx4rtw6f7pdr2swpq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaaoi4n4zxxsxgd4xyo4agic3o3cidafazdlnbex4vwton2in7vsh3a');
            --ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 17, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaabvz56ts4bj76nbjwbszgtek6pwmlvjlfyrcsv6yarfm6e6x5bggq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaabdaa555e5cbcjfrs6yrtw3pmnmnofm6tnpspvme3dqrjuvurnxjq');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 21, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaazylblrmgjf7s2jy5jbjftyhjc5j2gpkh6uviyfgfvzc6jhtj5pga', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaaq5mgqfwvdu6o24m5twxur7iwsnzsgg2he6pwm3nqddr6hf7sr2va');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 18, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaai35zz6k2emoc63mt33wxkmdac6cljuwrfiowptubcozyi5vmarha', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaatuku2ie4ny3fbj5kt42q6whyhti4xo5zcxjjjjxqfsa23c7jr7bq');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 19, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaaynq3722xurnqo4o3vjs2rvxifiitiph4h22veejz75z3ppkipkfq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaa4c6lendeuvtc2reubyypolb3b3aok5hl3ryyy6ly4jmdvpnnhoyq');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 4, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaaf7yhqpyesiqxdf5yhrj4ck5m2rwsoc3osfmymgmy2zvfsm6xelga', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaagnz7ao6z6yp25ntrw72i2jmwetavauvlws5yl3fmiuncuqvphouq');
            -- ll_pkg_delete.deleteAvailableCompartments (p_tenancy_id => 6, p_available_ocid => 'ocid1.compartment.oc1..aaaaaaaa6raqnjl5j3436x727hkfl2dd2lqzkplri3lzug42alqun54wgbcq', p_delete_ocid => 'ocid1.compartment.oc1..aaaaaaaafmu7avnm4ndmoeljwad4m5mg2ktwouvtyi6tq3dbuboucxik4f4a');
        end if;
        exception when others then 
            v_sqlerrm := SQLERRM;
            ll_pkg_log.log(1,'Error during delete compartments: '||v_sqlerrm);
    end;
    ll_pkg_log.log(1,'Daily Package Ended');
  end;
  
  
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_SECURITY" is
/*  Logging levels 
 
    1  = serious error 
    10 = start and stop of high level package 
    20 = start and stop of subroutine 
    30 = steps inside subroutine 
    40 = detailed steps inside subroutine (contains values) 
    50 = exec of commands start/stop 
    60 = detailed steps of exec commands 
    70 = signing of URLs 
    80 = details on signing of URLs
    90 = Am_I_Allowed calls */ 
     
-- Generate headers with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE 
 
  g_encryption_type   pls_integer  := DBMS_CRYPTO.ENCRYPT_AES256 + DBMS_CRYPTO.CHAIN_CBC + DBMS_CRYPTO.PAD_PKCS5;

function g_secret return varchar2 is
v_secret varchar2(50);
begin
  select value into v_secret from ll_system_parameters where name = 'ENCRYPTION_SECRET';
  return v_secret;
end;
-- 
-- ============================================================================================================
--
  function is_livelabs_admin (p_username varchar2) return varchar2 is
    cursor c_admin is select 'Y'
                      from LL_LIVELABS_ADMINS
                      where upper(p_username) = upper(username)
                      and upper(p_username) like '%@ORACLE.COM'
                      and upper(p_username) <> 'NOBODY';
    v_return_value varchar2(1);
  begin
    open c_admin;
    fetch c_admin into v_return_value;
    if c_admin%NOTFOUND then
      v_return_value := 'N';
    end if;
    close c_admin;
    return(v_return_value);
  end;                      
--
--  ##     ## #### ######## ##      ##       ###    ######## ######## ######## ##    ## ########  ######## ########       ###    ##       ##        #######  ##      ## ######## ########  
--  ##     ##  ##  ##       ##  ##  ##      ## ##      ##       ##    ##       ###   ## ##     ## ##       ##            ## ##   ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##     ##  ##  ##       ##  ##  ##     ##   ##     ##       ##    ##       ####  ## ##     ## ##       ##           ##   ##  ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##     ##  ##  ######   ##  ##  ##    ##     ##    ##       ##    ######   ## ## ## ##     ## ######   ######      ##     ## ##       ##       ##     ## ##  ##  ## ######   ##     ## 
--   ##   ##   ##  ##       ##  ##  ##    #########    ##       ##    ##       ##  #### ##     ## ##       ##          ######### ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--    ## ##    ##  ##       ##  ##  ##    ##     ##    ##       ##    ##       ##   ### ##     ## ##       ##          ##     ## ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--     ###    #### ########  ###  ###     ##     ##    ##       ##    ######## ##    ## ########  ######## ########    ##     ## ######## ########  #######   ###  ###  ######## ########  
--  
  function view_attendee_allowed (p_app_user varchar2, p_reservation_id number) return varchar2 is
  
    cursor c_reservation_owner is select start_gmt, stop_gmt, owner1, active_flg
                                 from ll_reservations_vw
                                 where id = p_reservation_id;
                                 
    v_start_gmt      date;
    v_stop_gmt       date;
    v_active_flg     varchar2(1);
    v_owner1         varchar2(100);
    v_res_exists     varchar2(1);
    v_allowed        varchar2(1);
    v_message        clob;
    v_status         varchar2(1);
    v_result         varchar2(1000);
    
  begin
    open c_reservation_owner;
    fetch c_reservation_owner into v_start_gmt, v_stop_gmt, v_owner1, v_active_flg;
    if c_reservation_owner%FOUND then
      v_res_exists := 'Y';
    else
      v_res_exists := 'N';
    end if;
    close c_reservation_owner;
    
    if v_res_exists = 'N' then
      v_message := v_message || '- Reservation does not exist<br>';
      v_allowed := 'N';
    else
      if v_owner1 <> p_app_user then
        v_message := v_message || '- User requesting is not owner of the reservation, owner: '||v_owner1||', apex user: '||p_app_user||'<br>';
        v_allowed := 'N';
      else
        if v_active_flg <> 'Y' then
          v_message := v_message || '- Reservation is not active, active flag: '||v_active_flg||'<br>';
          v_allowed := 'N';
        else
          if v_start_gmt > sysdate then
            v_message := v_message || '- Reservation has not started, sysdate: '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||', start_gmt: '||to_char(v_start_gmt,'DD Mon YYYY HH24:MI:SS')||'<br>';
            v_allowed := 'N';
          elsif v_stop_gmt < sysdate then
            v_message := v_message || '- Reservation has ended started, sysdate: '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||', stop_gmt: '||to_char(v_stop_gmt,'DD Mon YYYY HH24:MI:SS')||'<br>';
            v_allowed := 'N';
          elsif sysdate between v_start_gmt and v_stop_gmt then
            v_allowed := 'Y';
          end if;
        end if;
      end if;
    end if;
    
    if v_allowed is null then
      v_message := v_message || '- Unknown issue, v_allowed has not been set<br>';
      v_allowed := 'N';
    end if;
    
    if v_allowed='N' then
      v_message := p_app_user||' is denied access to view attendee details on Reservation number '||p_reservation_id||' at '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||' GMT<br><br>'||v_message;
      ll_pkg_log.log(1,v_message);
    else
      update ll_reservations set accessed = nvl(accessed,0)+1 where id = p_reservation_id;
      commit;
    end if;
    
    return(v_allowed);
  end;
--
--  ######## ########  #### ########       ###    ######## ######## ######## ##    ## ########  ######## ########       ###    ##       ##        #######  ##      ## ######## ########  
--  ##       ##     ##  ##     ##         ## ##      ##       ##    ##       ###   ## ##     ## ##       ##            ## ##   ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##       ##     ##  ##     ##        ##   ##     ##       ##    ##       ####  ## ##     ## ##       ##           ##   ##  ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ######   ##     ##  ##     ##       ##     ##    ##       ##    ######   ## ## ## ##     ## ######   ######      ##     ## ##       ##       ##     ## ##  ##  ## ######   ##     ## 
--  ##       ##     ##  ##     ##       #########    ##       ##    ##       ##  #### ##     ## ##       ##          ######### ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##       ##     ##  ##     ##       ##     ##    ##       ##    ##       ##   ### ##     ## ##       ##          ##     ## ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ######## ########  ####    ##       ##     ##    ##       ##    ######## ##    ## ########  ######## ########    ##     ## ######## ########  #######   ###  ###  ######## ######## 
--  
  function edit_attendee_allowed (p_app_user varchar2, p_reservation_id number) return varchar2 is
  
    cursor c_reservation_owner is select start_gmt, stop_gmt, owner1, active_flg
                                 from ll_reservations_vw
                                 where id = p_reservation_id;
                                 
    v_start_gmt      date;
    v_stop_gmt       date;
    v_active_flg     varchar2(1);
    v_owner1         varchar2(100);
    v_res_exists     varchar2(1);
    v_allowed        varchar2(1);
    v_message        clob;
    v_status         varchar2(1);
    v_result         varchar2(1000);
    
  begin
    open c_reservation_owner;
    fetch c_reservation_owner into v_start_gmt, v_stop_gmt, v_owner1, v_active_flg;
    if c_reservation_owner%FOUND then
      v_res_exists := 'Y';
    else
      v_res_exists := 'N';
    end if;
    close c_reservation_owner;
    
    if v_res_exists = 'N' then
      v_message := v_message || '- Reservation does not exist<br>';
      v_allowed := 'N';
    else
      if v_owner1 <> p_app_user then
        v_message := v_message || '- User requesting is not owner of the reservation, owner: '||v_owner1||', apex user: '||p_app_user||'<br>';
        v_allowed := 'N';
      else
        if v_active_flg <> 'Y' then
          v_message := v_message || '- Reservation is not active, active flag: '||v_active_flg||'<br>';
          v_allowed := 'N';
        else
          if sysdate between v_start_gmt and v_stop_gmt then 
            v_message := v_message || '- Reservation has started, no changed allowed, sysdate: '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||
                                      ', start_gmt: '||to_char(v_start_gmt,'DD Mon YYYY HH24:MI:SS')||', stop_gmt: '||to_char(v_stop_gmt,'DD Mon YYYY HH24:MI:SS')||'<br>';
            v_allowed := 'N';
          elsif v_stop_gmt < sysdate then
            v_message := v_message || '- Reservation has ended, sysdate: '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||', stop_gmt: '||to_char(v_stop_gmt,'DD Mon YYYY HH24:MI:SS')||'<br>';
            v_allowed := 'N';
          elsif v_stop_gmt > sysdate then
            v_allowed := 'Y';
          end if;
        end if;
      end if;
    end if;
    
    if v_allowed is null then
      v_message := v_message || '- Unknown issue, v_allowed has not been set<br>';
      v_allowed := 'N';
    end if;
    
    if v_allowed='N' then
      v_message := p_app_user||' is denied access to edit details on Reservation number '||p_reservation_id||' at '||to_char(sysdate,'DD Mon YYYY HH24:MI:SS')||' GMT<br><br>'||v_message;
      ll_pkg_log.log(1,v_message);
    end if;
    
    return(v_allowed);
  end;
--     ###    ##     ##    ####       ###    ##       ##        #######  ##      ## ######## ########  
--    ## ##   ###   ###     ##       ## ##   ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--   ##   ##  #### ####     ##      ##   ##  ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##     ## ## ### ##     ##     ##     ## ##       ##       ##     ## ##  ##  ## ######   ##     ## 
--  ######### ##     ##     ##     ######### ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##     ## ##     ##     ##     ##     ## ##       ##       ##     ## ##  ##  ## ##       ##     ## 
--  ##     ## ##     ##    ####    ##     ## ######## ########  #######   ###  ###  ######## ########  
--
  function am_i_allowed(p_apex_user varchar2, p_access_type varchar2, p_access_value varchar2, p_calling_module varchar2 default null) return varchar2 is
  
    v_return_val      varchar2(1);
    v_oracle_user     varchar2(1);
    v_email_addr      varchar2(1);
    v_status          varchar2(1);
    v_result          varchar2(200);
    v_system_status   varchar2(200)  := ll_pkg_admin.system_parameter (p_name => 'SYSTEM STATUS');
    
    cursor c_workshops_active is select 'Y' 
                                 from ll_workshops
                                 where id = to_number(p_access_value)
                                 and active_flg in ('Y', 'U');
                                 
    cursor c_user_roles is select 'Y'
                           from ll_role_permissions llrp
                           where access_type = p_access_type
                           and access_value = p_access_value
                           and exists (select null
                                       from ll_role_grants llrg
                                       where llrg.permission_id = llrp.id
                                       and exists (select null 
                                                   from ll_user_roles llur
                                                   where llur.role_id = llrg.role_id
                                                   and exists (select null
                                                               from ll_users llu
                                                               where llu.id = llur.user_id
                                                               and upper(email) = upper(p_apex_user))));
                                                               
    cursor c_vouchers is select 'Y'
                         from ll_voucher_users
                         where owner1 = p_apex_user
                         and voucher_id in ( select id from ll_vouchers_vw where workshop_id = p_access_value and sysdate between valid_from_gmt and valid_to_gmt )
                         union all
                         select 'Y'
                         from ll_vouchers
                         where workshop_id = p_access_value
                           and ( instr(upper(EMAIL_CREATOR), upper(p_apex_user)) > 0
                                 or 
                                 instr(upper(EMAIL_REQUESTOR), upper(p_apex_user)) > 0
                               );
                         
  begin
    ll_pkg_log.log(90,'Initial call');
    ll_pkg_log.log(90,'User "'||nvl(p_apex_user,'Empty user')||'" requested access allowed for type "'||p_access_type||'" and access value "'||p_access_value||'"');
   
    v_oracle_user := case instr(upper(nvl(p_apex_user,'NO_WAY')),'@ORACLE.COM') when 0 then 'N' else 'Y' end;
    v_email_addr  := case instr(upper(nvl(p_apex_user,'NO_WAY')),'@') when 0 then 'N' else 'Y' end;
    v_return_val := is_livelabs_admin (p_apex_user);
    ll_pkg_log.log(90,'User "'||nvl(p_apex_user,'Empty user')||'" after Superuser has status: '||v_return_val);
-- Generic Page Check
    if p_access_type = 'PAGE'
       and (p_access_value in ('1','10','100','180','210') -- Public Pages
            or
            p_access_value in ('110','190','200','300','320','350','400','10030', '9500') ) -- Pages when logged in
       and v_return_val <> 'Y' 
       and v_system_status='PRODUCTION' then
      v_return_val := 'Y';
    end if;
    ll_pkg_log.log(90,'User "'||nvl(p_apex_user,'Empty user')||'" after Generic pages has status: '||v_return_val);
-- Workshop views to prevent URL changing by user
    if p_access_type='WORKSHOP_VIEW' and v_system_status='PRODUCTION' and v_return_val <> 'Y' then
    
      open c_vouchers;
      fetch c_vouchers into v_return_val;
      if c_vouchers%NOTFOUND then
        open c_workshops_active;
        fetch c_workshops_active into v_return_val;
        if c_workshops_active%NOTFOUND then
          v_return_val := 'N';
        end if;
        close c_workshops_active;
      end if;
      close c_vouchers;
      
      -- In the future add option for Super User to view workshops that are in dev..
    end if;
    if p_access_type='RESERVATION_EDIT'  then
      ll_pkg_log.log(40,'Reservation edit check, p_access_value: '||p_access_value||', p_apex_user: '||p_apex_user);
      v_return_val := edit_attendee_allowed(p_app_user => p_apex_user, p_reservation_id => to_number(p_access_value));
    end if;
    if p_access_type='RESERVATION_VIEW'  then
      ll_pkg_log.log(40,'Reservation view check, p_access_value: '||p_access_value||', p_apex_user: '||p_apex_user);
      v_return_val := view_attendee_allowed(p_app_user => p_apex_user, p_reservation_id => to_number(p_access_value));
    end if;
    
    if v_return_val <> 'Y' and v_system_status='PRODUCTION' then
      open c_user_roles;
      fetch c_user_roles into v_return_val;
      close c_user_roles;
    end if;
    
    v_return_val := nvl(v_return_val,'N');
    ll_pkg_log.log(90,'User "'||nvl(p_apex_user,'Empty user')||'" after all checks has status: '||v_return_val);
    
    ll_pkg_log.log(90,'End of call');
    return(v_return_val);
    
  end;
  
-- ================================================================================================================
  
--  ######## ##    ##  ######  ########  ##    ## ########  ######## 
--  ##       ###   ## ##    ## ##     ##  ##  ##  ##     ##    ##    
--  ##       ####  ## ##       ##     ##   ####   ##     ##    ##    
--  ######   ## ## ## ##       ########     ##    ########     ##    
--  ##       ##  #### ##       ##   ##      ##    ##           ##    
--  ##       ##   ### ##    ## ##    ##     ##    ##           ##    
--  ######## ##    ##  ######  ##     ##    ##    ##           ##   
  function encrypt(p_value in varchar2) return varchar2 is
  
    v_clob           clob;
    v_raw            RAW (2000);
    v_key_raw        RAW (2000) := UTL_I18N.STRING_TO_RAW (g_secret(), 'AL32UTF8');
    
  begin
  
    if p_value is not null then
  
      v_raw := DBMS_CRYPTO.ENCRYPT ( src => UTL_I18N.STRING_TO_RAW (p_value, 'AL32UTF8'),
                                     typ => g_encryption_type,
                                     key => v_key_raw );
                                   
      v_clob :=  UTL_I18N.RAW_TO_CHAR (UTL_ENCODE.BASE64_ENCODE ( r => v_raw ), 'AL32UTF8');                                  
      
    else
    
     v_clob := '';
     
   end if;
    
    return(v_clob);
    
  end;
--  ########  ########  ######  ########  ##    ## ########  ######## 
--  ##     ## ##       ##    ## ##     ##  ##  ##  ##     ##    ##    
--  ##     ## ##       ##       ##     ##   ####   ##     ##    ##    
--  ##     ## ######   ##       ########     ##    ########     ##    
--  ##     ## ##       ##       ##   ##      ##    ##           ##    
--  ##     ## ##       ##    ## ##    ##     ##    ##           ##    
--  ########  ########  ######  ##     ##    ##    ##           ##   
  function decrypt(p_value in varchar2) return varchar2 is
  
    v_clob           clob;
    v_raw            RAW (4000);
    v_key_raw        RAW (4000) := UTL_I18N.STRING_TO_RAW (g_secret(), 'AL32UTF8');
    
  begin
  
    if p_value is not null then
  
      v_raw := DBMS_CRYPTO.DECRYPT ( src => UTL_ENCODE.BASE64_DECODE( UTL_I18N.STRING_TO_RAW ( p_value, 'AL32UTF8' ) ),
                                     typ => g_encryption_type,
                                     key => v_key_raw );
      v_clob :=  UTL_I18N.RAW_TO_CHAR ( v_raw , 'AL32UTF8');                                  
      
    else
    
      v_clob := '';
      
    end if;
    
    return(v_clob);
    
  exception
    when others then return(null);
    
  end;
--  ########  ######## ########     ###     ######  ######## 
--  ##     ## ##       ##     ##   ## ##   ##    ##    ##    
--  ##     ## ##       ##     ##  ##   ##  ##          ##    
--  ########  ######   ##     ## ##     ## ##          ##    
--  ##   ##   ##       ##     ## ######### ##          ##    
--  ##    ##  ##       ##     ## ##     ## ##    ##    ##    
--  ##     ## ######## ########  ##     ##  ######     ##  
  function redact (p_type varchar2, p_value varchar2) return varchar2 is
  
    v_return_val varchar2(4000);
  
  begin
  
    if p_type='FULL' then
      v_return_val := '(redacted)';
    elsif p_type='PEMKEY' then
      v_return_val := substr(p_value,1,instr(p_value,chr(10),1,2))||chr(10)||
                      '..... This entry is redacted for security reasons'||chr(10)||
                      substr(p_value,instr(p_value,chr(10),-1,3));
    elsif p_type='EMAIL' then
      v_return_val := substr(p_value,1,2)||'********'||substr(p_value,instr(p_value,'@'));
    elsif p_type='OCID' then
      v_return_val := substr(p_value,1,instr(p_value,'.',1,2))||'..redacted..'||substr(p_value,length(p_value)-4);
    else
      v_return_val := 'Unknown redact type';
    end if;
    
    return(v_return_val);
  end;
-- ==================================================================================================
  procedure set_security_group is
  
    v_secgrp_id  number;
    
  begin
    ll_pkg_log.log(10,'Initial call');
    
    v_secgrp_id := apex_util.find_security_group_id (p_workspace => 'DBPM');
    ll_pkg_log.log(40,'Security group: '||v_secgrp_id);
    apex_util.set_security_group_id (p_security_group_id => v_secgrp_id);
    ll_pkg_log.log(30,'Security group has been set, waiting 2 seconds for it to kick in');
    apex_util.pause(2);
    
    ll_pkg_log.log(10,'End of call');
    
  end;
  
-- ===================================================================================================
  procedure change_jobstates (p_jobs_enabled varchar) is
  
    cursor c_jobs is select job_name as job_name
                     from user_scheduler_jobs
                     where enabled <> p_jobs_enabled;
  
  begin
  
    if p_jobs_enabled = 'TRUE' then
      update LL_SYSTEM_PARAMETERS set value = 'TRUE' where name = 'ENABLE_JOBS';
    elsif p_jobs_enabled = 'FALSE' then
      update LL_SYSTEM_PARAMETERS set value = 'FALSE' where name = 'ENABLE_JOBS';
    end if;
    
    commit;
  
    for x in c_jobs loop
      
      if p_jobs_enabled = 'TRUE' then
        dbms_scheduler.ENABLE( x.job_name );
      elsif p_jobs_enabled = 'FALSE' then
        dbms_scheduler.DISABLE( x.job_name );
      end if;
      
    end loop;
    
  end;
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_STATUS" AS   
  
procedure checkLeftovers(p_tenant_id IN number, p_livelabs_compartment_id IN varchar2, p_recyclebin_compartment_id IN varchar2) as  
 
-- get cursor of all compartments in a tenancy 
cursor c_compartments is select * from (select id compartment_id, name, lifecyclestate, lastmovedate, compartmentid parent_compartmentid 
    from json_table( ll_pkg_exec.get (p_tenancy_id => p_tenant_id, 
    p_host => 'identity.us-ashburn-1.oraclecloud.com', 
    p_method => '/20160918/compartments', 
    p_query_string => 'compartmentIdInSubtree=TRUE'),
    '$[*]' COLUMNS (id, name, lifecycleState, compartmentId, NESTED freeformTags[*] COLUMNS (LastMoveDate)))); 
begin 
-- check for leftovers 
for compart in c_compartments loop 
    -- check livelabs compartment
    if compart.parent_compartmentid = p_livelabs_compartment_id then 
        -- if older than 5 days add to leftovers table
        if trunc(to_date(compart.lastmovedate, 'YYYYMMDD-HH24:MI:SS')) < trunc(sysdate-5) then
            insert into ll_leftovers (tenancy_id, resource_name, resource_ocid, lastmovedate, parent_compartment_ocid)
            values (p_tenant_id, compart.name, compart.compartment_id, to_date(compart.lastmovedate, 'YYYYMMDD-HH24:MI:SS'), compart.parent_compartmentid);
        end if;
    end if; 
    -- check recyclebin compartment
    if compart.parent_compartmentid = p_recyclebin_compartment_id then
        -- if older than 1 day add to leftovers table
        if trunc(to_date(compart.lastmovedate, 'YYYYMMDD-HH24:MI:SS')) < trunc(sysdate-1) then
            insert into ll_leftovers (tenancy_id, resource_name, resource_ocid, lastmovedate, parent_compartment_ocid)
            values (p_tenant_id, compart.name, compart.compartment_id, to_date(compart.lastmovedate, 'YYYYMMDD-HH24:MI:SS'), compart.parent_compartmentid);
        end if;
    end if;
end loop; 
end;  
 
 
procedure checkAllTenanciesForLeftovers as
cursor c_tenancies is select * from ll_tenancies;
v_region_key varchar2(50);
begin
-- clean leftovers table 
DELETE FROM ll_leftovers;
-- check all tenancies for leftovers
for tenant in c_tenancies loop
    -- make sure tenant is active and public
    if tenant.active_flg = 'Y' and tenant.is_public = 'Y' then
        -- check leftover compartments 
        LL_PKG_STATUS.checkLeftovers(tenant.id, tenant.DEFAULT_COMPARTMENT_OCID, tenant.RECYCLEBIN_OCID);
        -- set region key for each tenancy
        select region_key into v_region_key from ll_oci_regions where id = (select home_region from ll_tenancies where id = tenant.id); 
        LL_PKG_STATUS.checkUserLeftovers(tenant.id, tenant.tenancy_ocid, ll_pkg_admin.oci_endpoint(p_type => 'identity', p_region_key => v_region_key)); 
        LL_PKG_STATUS.checkQuotaLeftovers(tenant.id, tenant.tenancy_ocid, ll_pkg_admin.oci_endpoint(p_type => 'limits', p_region_key => v_region_key));
        LL_PKG_STATUS.checkNumberCompartments(tenant.id, tenant.AVAILABLE_OCID);
    end if;
end loop;
end;
procedure updateRESTCalls as 
begin
merge into ll_rest_calls calls
    using (select to_date(to_char(request_date, 'YYYYMMDD'), 'YYYYMMDD') dte, count(*) cnt from apex_webservice_log where trunc(request_date) > trunc(sysdate-5) group by to_char(request_date, 'YYYYMMDD')) apexlog
    on (calls.requests_date = apexlog.dte)
    when matched then
    update set calls.requests_count = apexlog.cnt
    when not matched then
    insert (requests_date, requests_count)
    values (apexlog.dte, apexlog.cnt);
end;
procedure checkUserLeftovers(p_tenant_id IN number, p_tenancy_ocid IN varchar2, p_host IN varchar2) as 
cursor c_users is select * from (select id, name, timeCreated
    from JSON_TABLE(ll_pkg_exec.get (p_tenancy_id => p_tenant_id,
        p_host => p_host,
        p_method => '/20160918/users/',
        p_query_string => 'compartmentId='||p_tenancy_ocid),
        '$[*]' COLUMNS (id, name, timeCreated)))
    where substr(name, 0,2) = 'LL';
begin
for leftover in c_users loop
    -- 2021-03-30T15:54:25.649Z - sample date returned 
    if trunc(CAST(to_timestamp(leftover.timeCreated, 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') as DATE)) < trunc(sysdate-7) then
        insert into ll_leftovers (tenancy_id, resource_name, resource_ocid, lastmovedate)
            values (p_tenant_id, leftover.name, leftover.id, CAST(to_timestamp(leftover.timeCreated, 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') as DATE));
    end if;
end loop;
end;
procedure checkQuotaLeftovers(p_tenant_id IN number, p_tenancy_ocid IN varchar2, p_host IN varchar2) as 
cursor c_quotas is select * from (select id, name, timeCreated
    from JSON_TABLE(ll_pkg_exec.get (p_tenancy_id => p_tenant_id,
        p_host => p_host,
        p_method => '/20181025/quotas/',
        p_query_string => 'compartmentId='||p_tenancy_ocid),
        '$[*]' COLUMNS (id, name, timeCreated)))
    where substr(name, 0,2) = 'LL';
begin
for leftover in c_quotas loop
    if trunc(CAST(to_timestamp(leftover.timeCreated, 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') as DATE)) < trunc(sysdate-7) then
        insert into ll_leftovers (tenancy_id, resource_name, resource_ocid, lastmovedate)
            values (p_tenant_id, leftover.name, leftover.id, CAST(to_timestamp(leftover.timeCreated, 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"') as DATE));
    end if;
end loop;
end;
procedure checkNumberCompartments(p_tenant_id IN number, p_available_ocid IN varchar2) as
v_count number := 0;
begin
select count(*) cnt into v_count from (select id compartment_id, name, lifecyclestate, lastmovedate, compartmentid parent_compartmentid 
    from json_table( ll_pkg_exec.get (p_tenancy_id => p_tenant_id, 
    p_host => 'identity.us-ashburn-1.oraclecloud.com', 
    p_method => '/20160918/compartments', 
    p_query_string => 'compartmentIdInSubtree=TRUE'),
    '$[*]' COLUMNS (id, name, lifecycleState, compartmentId, NESTED freeformTags[*] COLUMNS (LastMoveDate))))
    
    where parent_compartmentid = p_available_ocid
    group by parent_compartmentid; 
insert into ll_leftovers(tenancy_id, parent_compartment_ocid, number_resources)
    values (p_tenant_id, p_available_ocid, v_count);
end;
procedure checkWorkshopResources as 
v_tenancy number;
v_region number;
v_result clob;
begin
-- clear table
delete from ll_workshops_without_resources;
-- go through all workshops
for workshop in (select * from ll_workshops) loop
    -- only check active workshops
    if workshop.active_flg = 'Y' then
        ll_pkg_reservation.find_available_tenancy(v_tenancy, v_region, v_result, workshop.id);
        -- if the workshops can't be run on any tenancy, put into the table
        if v_tenancy is null then
            insert into ll_workshops_without_resources(workshop_id, number_environments) values (workshop.id, 0);
        else
            -- find how many environments can be run in the workshop
            for env in (select * from json_table(v_result, '$[*]' COLUMNS tenancy_id, region_id, environments, preference_points)) loop
            -- add to table if less than the allowed number of workshops can be run 
            if env.environments < cast(ll_pkg_admin.system_parameter('MINIMUM_ENVIRONMENTS_ALLOWED') as number) then
                insert into ll_workshops_without_resources (workshop_id, number_environments, tenancy_id, region_id) 
                    values (workshop.id, env.environments, env.tenancy_id, env.region_id);
            end if;
            end loop;
        end if;
    end if;
    -- reset variables
    v_tenancy := null;
    v_region := null;
end loop;
end;
-- procedure updateFeaturedWorkshops as
--     cursor c_featured is select workshop_id, count(*) as page_views from ll_page_visits 
--                             where workshop_id is not null
--                             group by workshop_id
--                             order by page_views desc;
--     cursor c_new is select id from ll_workshops 
--                             order by created_date desc
--                             fetch first 24 rows only;
--     v_counter number := 0;
