/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_TENANCY_SETUP" is

    type t_api_context is record (
        tenancy_id    number,
        tenancy_ocid  varchar2(200),
        region_key    varchar2(50),
        identity_host varchar2(4000)
    );

    type t_terraform_context is record (
        tenancy_id          number,
        tenancy_name        varchar2(50),
        tenancy_ocid        varchar2(200),
        swift_name          varchar2(50),
        preference_weight   number,
        home_region         number,
        region_key          varchar2(50),
        region_identifier   varchar2(50),
        active_flg          varchar2(1),
        ad_prefix           varchar2(50),
        is_public           varchar2(1),
        concurrent_move     number,
        config_source_ocid  varchar2(4000),
        resource_manager_host varchar2(4000)
    );

    type t_terraform_outputs is record (
        tenancy_name         varchar2(50),
        default_compartment  varchar2(200),
        available_ocid       varchar2(200),
        recyclebin_ocid      varchar2(200),
        delete_ocid          varchar2(200),
        default_dynamic_group varchar2(100),
        state_json           clob
    );

    procedure put_result_value(
        io_result  in out nocopy json_object_t,
        p_section  in varchar2,
        p_name     in varchar2,
        p_value    in varchar2
    ) is
        v_section json_object_t;
    begin
        if io_result.has(p_section) then
            v_section := treat(io_result.get(p_section) as json_object_t);
        else
            v_section := json_object_t();
            io_result.put(p_section, v_section);
        end if;

        v_section.put(p_name, p_value);
    end put_result_value;

    procedure complete_result(
        io_result in out nocopy json_object_t,
        p_result  out nocopy clob
    ) is
    begin
        io_result.put('status', 'SUCCEEDED');
        p_result := io_result.to_clob;
    end complete_result;

    procedure fail_run(
        p_tenancy_id in number,
        p_stage      in varchar2,
        io_result    in out nocopy json_object_t,
        p_result     out nocopy clob
    ) is
        v_err clob;
    begin
        v_err := to_clob(sqlerrm);
        io_result.put('status', 'FAILED');
        io_result.put('failed_stage', p_stage);
        io_result.put('error', v_err);
        p_result := io_result.to_clob;

        ll_pkg_log.log(
            p_loglevel => 1,
            p_value    => p_result
        );

        raise_application_error(
            -20001,
            'LiveLabs tenancy setup failed during ' || p_stage || '. ' ||
            dbms_lob.substr(v_err, 1800, 1)
        );
    end fail_run;

    procedure load_api_context(
        p_tenancy_id in number,
        p_context    out nocopy t_api_context
    ) is
        v_user_ocid       varchar2(200);
        v_user_fingerprint varchar2(200);
        v_private_key     varchar2(4000);
    begin
        select t.tenancy_ocid,
               r.region_key,
               t.user_ocid,
               t.user_fingerprint,
               t.pem_key_priv
          into p_context.tenancy_ocid,
               p_context.region_key,
               v_user_ocid,
               v_user_fingerprint,
               v_private_key
          from ll_tenancies t
          left join ll_oci_regions r on r.id = t.home_region
         where t.id = p_tenancy_id;

        p_context.tenancy_id := p_tenancy_id;

        if p_context.tenancy_ocid is null then
            raise_application_error(-20002, 'TENANCY_OCID is required.');
        end if;

        if p_context.region_key is null then
            raise_application_error(-20002, 'HOME_REGION is required for OCI API endpoint selection.');
        end if;

        if v_user_ocid is null or v_user_fingerprint is null or v_private_key is null then
            raise_application_error(
                -20002,
                'USER_OCID, USER_FINGERPRINT, and PEM_KEY_PRIV are required for signed OCI API calls.'
            );
        end if;

        p_context.identity_host := ll_pkg_admin.oci_endpoint(
            p_type       => 'identity',
            p_region_key => p_context.region_key
        );
    end load_api_context;

    procedure validate_api_signing(
        p_tenancy_id   in number,
        p_tenancy_ocid in varchar2,
        p_region_key   in varchar2
    ) is
        v_response clob;
    begin
        -- Use a read-only call to fail before any tenancy object is created.
        v_response := ll_pkg_exec.get(
            p_tenancy_id     => p_tenancy_id,
            p_host           => ll_pkg_admin.oci_endpoint(
                                    p_type       => 'identity',
                                    p_region_key => p_region_key
                                ),
            p_method         => '/20160918/compartments',
            p_compartment_id => p_tenancy_ocid,
            p_query_string   => 'limit=1'
        );

        if v_response is null
           or instr(v_response, 'NotAuthenticated') > 0
           or instr(v_response, 'Failed to verify the HTTP(S) Signature') > 0 then
            raise_application_error(
                -20002,
                'OCI API signing credentials were rejected. Verify that USER_FINGERPRINT identifies the public key uploaded to USER_OCID and that PEM_KEY_PRIV is its matching private key.'
            );
        end if;
    end validate_api_signing;

    function find_existing_identity_id(
        p_context      in t_api_context,
        p_path         in varchar2,
        p_parent_ocid  in varchar2,
        p_name         in varchar2,
        p_query_string in varchar2 default null
    ) return varchar2 is
        v_response clob;
        v_id       varchar2(200);
    begin
        v_response := ll_pkg_exec.get(
            p_tenancy_id     => p_context.tenancy_id,
            p_host           => p_context.identity_host,
            p_method         => p_path,
            p_compartment_id => p_parent_ocid,
            p_query_string   => p_query_string
        );

        begin
            select id
              into v_id
              from (
                  select item.id
                    from json_table(
                        v_response,
                        '$[*]' columns (
                            id   varchar2(200) path '$.id',
                            name varchar2(200) path '$.name'
                        )
                    ) item
                   where lower(item.name) = lower(p_name)
                  union all
                  select item.id
                    from json_table(
                        v_response,
                        '$.items[*]' columns (
                            id   varchar2(200) path '$.id',
                            name varchar2(200) path '$.name'
                        )
                    ) item
                   where lower(item.name) = lower(p_name)
              )
             where rownum = 1;
        exception
            when no_data_found then
                v_id := null;
        end;

        return v_id;
    end find_existing_identity_id;

    function ensure_identity_object(
        p_context      in t_api_context,
        p_stage        in varchar2,
        p_path         in varchar2,
        p_parent_ocid  in varchar2,
        p_name         in varchar2,
        p_query_string in varchar2,
        p_body         in clob
    ) return varchar2 is
        v_id       varchar2(200);
        v_response clob;
    begin
        v_id := find_existing_identity_id(
            p_context      => p_context,
            p_path         => p_path,
            p_parent_ocid  => p_parent_ocid,
            p_name         => p_name,
            p_query_string => p_query_string
        );

        if v_id is not null then
            return v_id;
        end if;

        v_response := ll_pkg_exec.put_post(
            p_tenancy_id => p_context.tenancy_id,
            p_type       => 'POST',
            p_host       => p_context.identity_host,
            p_method     => p_path,
            p_body       => p_body
        );
        v_id := json_value(v_response, '$.id' returning varchar2(200));

        if v_id is null then
            raise_application_error(
                -20002,
                p_stage || ' did not return an OCID. ' || dbms_lob.substr(v_response, 1800, 1)
            );
        end if;

        return v_id;
    end ensure_identity_object;

    -- 1. Add the compartment hierarchy required by LiveLabs reservations.
    procedure add_compartments(
        p_context  in t_api_context,
        io_result  in out nocopy json_object_t
    ) is
        v_livelabs_ocid     varchar2(200);
        v_nonprod_ocid      varchar2(200);
    begin
        v_livelabs_ocid := ensure_identity_object(
            p_context, 'add LiveLabs compartment', '/20160918/compartments',
            p_context.tenancy_ocid, 'LiveLabs', 'name=LiveLabs',
            json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'name' value 'LiveLabs',
                'description' value 'LiveLabs active reservations'
            )
        );
        put_result_value(io_result, 'compartments', 'livelabs', v_livelabs_ocid);

        put_result_value(io_result, 'compartments', 'available', ensure_identity_object(
            p_context, 'add LiveLabs-Available compartment', '/20160918/compartments',
            p_context.tenancy_ocid, 'LiveLabs-Available', 'name=LiveLabs-Available',
            json_object('compartmentId' value p_context.tenancy_ocid, 'name' value 'LiveLabs-Available', 'description' value 'LiveLabs available compartments')
        ));
        put_result_value(io_result, 'compartments', 'trash', ensure_identity_object(
            p_context, 'add LiveLabs-Trash compartment', '/20160918/compartments',
            p_context.tenancy_ocid, 'LiveLabs-Trash', 'name=LiveLabs-Trash',
            json_object('compartmentId' value p_context.tenancy_ocid, 'name' value 'LiveLabs-Trash', 'description' value 'LiveLabs retained resources')
        ));
        put_result_value(io_result, 'compartments', 'recyclebin', ensure_identity_object(
            p_context, 'add LiveLabs-Recyclebin compartment', '/20160918/compartments',
            p_context.tenancy_ocid, 'LiveLabs-Recyclebin', 'name=LiveLabs-Recyclebin',
            json_object('compartmentId' value p_context.tenancy_ocid, 'name' value 'LiveLabs-Recyclebin', 'description' value 'LiveLabs recycle bin')
        ));

        v_nonprod_ocid := ensure_identity_object(
            p_context, 'add Livelabs-NonProd-Compartments compartment', '/20160918/compartments',
            p_context.tenancy_ocid, 'Livelabs-NonProd-Compartments', 'name=Livelabs-NonProd-Compartments',
            json_object('compartmentId' value p_context.tenancy_ocid, 'name' value 'Livelabs-NonProd-Compartments', 'description' value 'LiveLabs non-production compartments')
        );
        put_result_value(io_result, 'compartments', 'nonprod', v_nonprod_ocid);
        put_result_value(io_result, 'compartments', 'stage_available', ensure_identity_object(
            p_context, 'add Stage-Available compartment', '/20160918/compartments',
            v_nonprod_ocid, 'Stage-Available', 'name=Stage-Available',
            json_object('compartmentId' value v_nonprod_ocid, 'name' value 'Stage-Available', 'description' value 'Stage available compartments')
        ));
        put_result_value(io_result, 'compartments', 'stage_recyclebin', ensure_identity_object(
            p_context, 'add Stage-Recyclebin compartment', '/20160918/compartments',
            v_nonprod_ocid, 'Stage-Recyclebin', 'name=Stage-Recyclebin',
            json_object('compartmentId' value v_nonprod_ocid, 'name' value 'Stage-Recyclebin', 'description' value 'Stage recycle bin')
        ));
    end add_compartments;

    -- 2. Add the LiveLabs tag namespace and required tag definitions.
    procedure add_tags(
        p_context  in t_api_context,
        io_result  in out nocopy json_object_t
    ) is
        v_namespace_ocid varchar2(200);
    begin
        v_namespace_ocid := ensure_identity_object(
            p_context, 'add Livelabs tag namespace', '/20160918/tagNamespaces',
            p_context.tenancy_ocid, 'Livelabs', null,
            json_object('compartmentId' value p_context.tenancy_ocid, 'name' value 'Livelabs', 'description' value 'LiveLabs tag namespace')
        );
        put_result_value(io_result, 'tags', 'namespace', v_namespace_ocid);

        for tag_definition in (
            select 'Owner' name, 'The LiveLabs username for this reservation.' description, 'false' is_cost_tracking from dual union all
            select 'Permissions', 'Permissions for the attendee.', 'false' from dual union all
            select 'Region', 'LiveLabs region for the permissions.', 'false' from dual union all
            select 'WorkshopID', 'Cost tracking tag for LiveLabs workshops.', 'true' from dual union all
            select 'EventID', 'Cost tracking tag for events.', 'true' from dual
        ) loop
            put_result_value(io_result, 'tags', lower(tag_definition.name), ensure_identity_object(
                p_context,
                'add ' || tag_definition.name || ' tag',
                '/20160918/tags',
                p_context.tenancy_ocid,
                tag_definition.name,
                'tagNamespaceId=' || v_namespace_ocid,
                json_object(
                    'tagNamespaceId' value v_namespace_ocid,
                    'name' value tag_definition.name,
                    'description' value tag_definition.description,
                    'isCostTracking' value tag_definition.is_cost_tracking format json
                )
            ));
        end loop;
    end add_tags;

    -- 3. Add the dynamic groups required by LiveLabs services.
    procedure add_dynamic_groups(
        p_context  in t_api_context,
        io_result  in out nocopy json_object_t
    ) is
    begin
        put_result_value(io_result, 'dynamic_groups', 'data_catalog', ensure_identity_object(
            p_context,
            'add Data-Catalog-Dynamic-Group',
            '/20160918/dynamicGroups',
            p_context.tenancy_ocid,
            'Data-Catalog-Dynamic-Group',
            'name=Data-Catalog-Dynamic-Group',
            json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'name' value 'Data-Catalog-Dynamic-Group',
                'description' value 'Data Catalog Dynamic Group',
                'matchingRule' value 'resource.compartment.id = resource.compartment.id'
            )
        ));
        put_result_value(io_result, 'dynamic_groups', 'default', ensure_identity_object(
            p_context,
            'add LiveLabs-Default-Dynamic-Group',
            '/20160918/dynamicGroups',
            p_context.tenancy_ocid,
            'LiveLabs-Default-Dynamic-Group',
            'name=LiveLabs-Default-Dynamic-Group',
            json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'name' value 'LiveLabs-Default-Dynamic-Group',
                'description' value 'Default Dynamic Group',
                'matchingRule' value 'instance.compartment.id = instance.compartment.id'
            )
        ));
    end add_dynamic_groups;

    procedure ensure_administrators_membership(
        p_context   in t_api_context,
        p_user_ocid in varchar2,
        p_user_name in varchar2,
        io_result   in out nocopy json_object_t
    ) is
        v_group_ocid      varchar2(200);
        v_membership_ocid varchar2(200);
        v_response        clob;
    begin
        v_group_ocid := find_existing_identity_id(
            p_context, '/20160918/groups', p_context.tenancy_ocid, 'Administrators', 'name=Administrators'
        );

        if v_group_ocid is null then
            raise_application_error(-20002, 'The tenancy Administrators group was not found.');
        end if;

        v_response := ll_pkg_exec.get(
            p_tenancy_id     => p_context.tenancy_id,
            p_host           => p_context.identity_host,
            p_method         => '/20160918/userGroupMemberships',
            p_compartment_id => p_context.tenancy_ocid,
            p_query_string   => 'userId=' || p_user_ocid || '&groupId=' || v_group_ocid
        );
        v_membership_ocid := nvl(
            json_value(v_response, '$[0].id' returning varchar2(200)),
            json_value(v_response, '$.items[0].id' returning varchar2(200))
        );

        if v_membership_ocid is null then
            v_response := ll_pkg_exec.put_post(
                p_tenancy_id => p_context.tenancy_id,
                p_type       => 'POST',
                p_host       => p_context.identity_host,
                p_method     => '/20160918/userGroupMemberships',
                p_body       => json_object('userId' value p_user_ocid, 'groupId' value v_group_ocid)
            );
            v_membership_ocid := json_value(v_response, '$.id' returning varchar2(200));
        end if;

        if v_membership_ocid is null then
            raise_application_error(-20002, 'Administrators membership did not return an OCID for ' || p_user_name || '.');
        end if;

        put_result_value(io_result, 'memberships', lower(p_user_name), v_membership_ocid);
    end ensure_administrators_membership;

    -- 4. Add the LiveLabs and AdminPortal users, then grant Administrators membership.
    procedure add_users(
        p_context  in t_api_context,
        io_result  in out nocopy json_object_t
    ) is
        v_livelabs_user     varchar2(200);
        v_admin_portal_user varchar2(200);
    begin
        v_livelabs_user := ensure_identity_object(
            p_context,
            'add Livelabs user',
            '/20160918/users',
            p_context.tenancy_ocid,
            'Livelabs',
            'name=Livelabs',
            json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'name' value 'Livelabs',
                'description' value 'LiveLabs Admin User - DO NOT DELETE'
            )
        );
        put_result_value(io_result, 'users', 'livelabs', v_livelabs_user);

        v_admin_portal_user := ensure_identity_object(
            p_context,
            'add AdminPortal user',
            '/20160918/users',
            p_context.tenancy_ocid,
            'AdminPortal',
            'name=AdminPortal',
            json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'name' value 'AdminPortal',
                'description' value 'Admin Portal Admin User - DO NOT DELETE'
            )
        );
        put_result_value(io_result, 'users', 'admin_portal', v_admin_portal_user);

        ensure_administrators_membership(p_context, v_livelabs_user, 'Livelabs', io_result);
        ensure_administrators_membership(p_context, v_admin_portal_user, 'AdminPortal', io_result);
    end add_users;

    -- 5. Add the baseline policies required by LiveLabs services.
    procedure add_policies(
        p_context  in t_api_context,
        io_result  in out nocopy json_object_t
    ) is
    begin
        for policy_definition in (
            select 'Livelabs-Generic-Policy' name, 'DO NOT DELETE - Livelabs needs this for every reservation - PRODUCTION' description from dual union all
            select 'Livelabs-Generic-Policy-2', 'DO NOT DELETE - Livelabs needs this for every reservation - PRODUCTION' from dual union all
            select 'Livelabs-Services-Policy', 'DO NOT DELETE - Livelabs needs this for all services - PRODUCTION' from dual union all
            select 'Livelabs-Dynamic-Group-Policy', 'DO NOT DELETE - Livelabs needs this for Dynamic groups' from dual union all
            select 'Livelabs-Domain-Dynamic-Group-Policy', 'DO NOT DELETE - Livelabs needs this for Dynamic groups in tenancies with Domains - PRODUCTION' from dual
        ) loop
            put_result_value(io_result, 'policies', lower(policy_definition.name), ensure_identity_object(
                p_context,
                'add ' || policy_definition.name,
                '/20160918/policies',
                p_context.tenancy_ocid,
                policy_definition.name,
                'name=' || policy_definition.name,
                json_object(
                    'compartmentId' value p_context.tenancy_ocid,
                    'name' value policy_definition.name,
                    'description' value policy_definition.description,
                    'statements' value json_array('Allow any-user to use cloud-shell in tenancy')
                )
            ));
        end loop;
    end add_policies;

    -- 6. Persist the values used by page 9121 after API setup succeeds.
    procedure persist_api_outputs(
        p_tenancy_id in number,
        p_result     in json_object_t
    ) is
    begin
        update ll_tenancies
           set default_compartment_name = 'LiveLabs',
               default_compartment_ocid = json_value(p_result.to_clob, '$.compartments.livelabs' returning varchar2(200)),
               available_ocid = json_value(p_result.to_clob, '$.compartments.available' returning varchar2(200)),
               recyclebin_ocid = json_value(p_result.to_clob, '$.compartments.recyclebin' returning varchar2(200)),
               delete_ocid = json_value(p_result.to_clob, '$.compartments.trash' returning varchar2(200)),
               default_dynamic_group = json_value(p_result.to_clob, '$.dynamic_groups.default' returning varchar2(100))
         where id = p_tenancy_id;

        commit;
    end persist_api_outputs;

    procedure run_api(
        p_tenancy_id in number,
        p_result     out nocopy clob
    ) is
        v_context t_api_context;
        v_result  json_object_t := json_object_t();
        v_stage   varchar2(200) := 'load tenancy';
    begin
        v_result.put('setup_method', 'API');
        v_result.put('tenancy_id', p_tenancy_id);
        load_api_context(p_tenancy_id, v_context);
        v_stage := 'validate API signing key';
        validate_api_signing(v_context.tenancy_id, v_context.tenancy_ocid, v_context.region_key);

        ll_pkg_log.log(10, 'LL_PKG_TENANCY_SETUP.RUN_API started for tenancy ID ' || p_tenancy_id);

        v_stage := '1. add compartments';
        add_compartments(v_context, v_result);
        v_stage := '2. add tags';
        add_tags(v_context, v_result);
        v_stage := '3. add dynamic groups';
        add_dynamic_groups(v_context, v_result);
        v_stage := '4. add users';
        add_users(v_context, v_result);
        v_stage := '5. add policies';
        add_policies(v_context, v_result);
        v_stage := '6. persist setup outputs';
        persist_api_outputs(p_tenancy_id, v_result);

        complete_result(v_result, p_result);
        ll_pkg_log.log(10, p_result);
    exception
        when others then
            if sqlcode = -20001 then
                raise;
            end if;

            fail_run(p_tenancy_id, v_stage, v_result, p_result);
    end run_api;

    procedure load_terraform_context(
        p_tenancy_id in number,
        p_context    out nocopy t_terraform_context
    ) is
        v_user_ocid        varchar2(200);
        v_user_fingerprint varchar2(200);
        v_private_key      varchar2(4000);
    begin
        select t.tenancy_name,
               t.tenancy_ocid,
               t.swift_name,
               t.preference_weight,
               t.home_region,
               r.region_key,
               r.region_identifier,
               t.active_flg,
               t.ad_prefix,
               t.is_public,
               t.concurrent_move,
               t.user_ocid,
               t.user_fingerprint,
               t.pem_key_priv
          into p_context.tenancy_name,
               p_context.tenancy_ocid,
               p_context.swift_name,
               p_context.preference_weight,
               p_context.home_region,
               p_context.region_key,
               p_context.region_identifier,
               p_context.active_flg,
               p_context.ad_prefix,
               p_context.is_public,
               p_context.concurrent_move,
               v_user_ocid,
               v_user_fingerprint,
               v_private_key
          from ll_tenancies t
          left join ll_oci_regions r on r.id = t.home_region
         where t.id = p_tenancy_id;

        p_context.tenancy_id := p_tenancy_id;

        if p_context.tenancy_ocid is null or p_context.region_key is null or p_context.region_identifier is null then
            raise_application_error(-20002, 'TENANCY_OCID and HOME_REGION are required.');
        end if;

        if v_user_ocid is null or v_user_fingerprint is null or v_private_key is null then
            raise_application_error(
                -20002,
                'USER_OCID, USER_FINGERPRINT, and PEM_KEY_PRIV are required for signed OCI API calls.'
            );
        end if;

        select config_source_ocid
          into p_context.config_source_ocid
          from ll_config_source_providers
         where tenancy_id = p_tenancy_id
           and region_key = p_context.region_key;

        p_context.resource_manager_host := ll_pkg_admin.oci_endpoint(
            p_type       => 'resourcemanager',
            p_region_key => p_context.region_key
        );
    end load_terraform_context;

    -- 1. Create the tenancy-specific Resource Manager stack.
    procedure create_terraform_stack(
        p_context  in t_terraform_context,
        io_result  in out nocopy json_object_t,
        p_stack_id out nocopy varchar2
    ) is
        v_response clob;
    begin
        v_response := ll_pkg_exec.put_post(
            p_tenancy_id => p_context.tenancy_id,
            p_type       => 'POST',
            p_host       => p_context.resource_manager_host,
            p_method     => '/20180917/stacks',
            p_body       => json_object(
                'compartmentId' value p_context.tenancy_ocid,
                'displayName' value 'LiveLabs Tenancy Setup - ' || p_context.tenancy_name || ' - ' || to_char(systimestamp, 'YYYYMMDDHH24MISS'),
                'description' value 'LiveLabs tenancy setup Terraform workflow',
                'terraformVersion' value '1.5.x',
                'configSource' value json_object(
                    'configSourceType' value 'GIT_CONFIG_SOURCE',
                    'configurationSourceProviderId' value p_context.config_source_ocid,
                    'workingDirectory' value 'll-tenancy-setup-test',
                    'branchName' value 'main',
                    'repositoryUrl' value 'https://github.com/oracle-livelabs/terraform.git'
                ),
                'variables' value json_object(
                    'tenancy_ocid' value p_context.tenancy_ocid,
                    'ociRegionIdentifier' value p_context.region_identifier
                ) format json
            )
        );
        p_stack_id := json_value(v_response, '$.id' returning varchar2(200));

        if p_stack_id is null then
            raise_application_error(-20002, 'Resource Manager stack creation did not return an OCID. ' || dbms_lob.substr(v_response, 1800, 1));
        end if;

        put_result_value(io_result, 'terraform', 'stack_id', p_stack_id);
    end create_terraform_stack;

    -- 2. Run and wait for the Terraform apply job.
    procedure run_terraform_apply(
        p_context  in t_terraform_context,
        p_stack_id in varchar2,
        io_result  in out nocopy json_object_t,
        p_job_id   out nocopy varchar2
    ) is
        v_response        clob;
        v_lifecycle_state varchar2(50);
        v_attempt         number := 0;
    begin
        v_response := ll_pkg_exec.put_post(
            p_tenancy_id => p_context.tenancy_id,
            p_type       => 'POST',
            p_host       => p_context.resource_manager_host,
            p_method     => '/20180917/jobs',
            p_body       => json_object(
                'stackId' value p_stack_id,
                'jobOperationDetails' value json_object(
                    'operation' value 'APPLY',
                    'executionPlanStrategy' value 'AUTO_APPROVED',
                    'terraformAdvancedOptions' value json_object('parallelism' value 10)
                )
            )
        );
        p_job_id := json_value(v_response, '$.id' returning varchar2(200));

        if p_job_id is null then
            raise_application_error(-20002, 'Terraform apply job submission did not return an OCID. ' || dbms_lob.substr(v_response, 1800, 1));
        end if;

        put_result_value(io_result, 'terraform', 'job_id', p_job_id);

        loop
            v_attempt := v_attempt + 1;
            apex_util.pause(10);
            v_response := ll_pkg_exec.get(
                p_tenancy_id => p_context.tenancy_id,
                p_host       => p_context.resource_manager_host,
                p_method     => '/20180917/jobs/' || p_job_id
            );
            v_lifecycle_state := json_value(v_response, '$.lifecycleState' returning varchar2(50));
            exit when v_lifecycle_state not in ('ACCEPTED', 'IN_PROGRESS', 'SUBMITTED') or v_attempt >= 180;
        end loop;

        if v_lifecycle_state <> 'SUCCEEDED' then
            raise_application_error(
                -20002,
                'Resource Manager job ' || p_job_id || ' finished with state ' || nvl(v_lifecycle_state, 'UNKNOWN') || '.'
            );
        end if;
    end run_terraform_apply;

    -- 3. Read the Terraform output values required by page 9121.
    procedure read_terraform_outputs(
        p_context  in t_terraform_context,
        p_job_id   in varchar2,
        io_result  in out nocopy json_object_t,
        p_outputs  out nocopy t_terraform_outputs
    ) is
        v_output_summary varchar2(4000);
    begin
        p_outputs.state_json := ll_pkg_exec.get(
            p_tenancy_id => p_context.tenancy_id,
            p_host       => p_context.resource_manager_host,
            p_method     => '/20180917/jobs/' || p_job_id || '/tfState'
        );
        v_output_summary := ll_pkg_terraform.fetch_job_output(
            p_tenancy_id => p_context.tenancy_id,
            p_host       => p_context.resource_manager_host,
            p_job_id     => p_job_id
        );
        ll_pkg_log.log(40, 'LL_PKG_TENANCY_SETUP.RUN_TERRAFORM output summary: ' || v_output_summary);

        p_outputs.tenancy_name := json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.tenancy_name' returning varchar2(50));
        p_outputs.default_compartment := nvl(json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.compartments.livelabs' returning varchar2(200)), json_value(p_outputs.state_json, '$.outputs.compartment_ids.value.livelabs' returning varchar2(200)));
        p_outputs.available_ocid := nvl(json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.compartments.livelabs_available' returning varchar2(200)), json_value(p_outputs.state_json, '$.outputs.compartment_ids.value.livelabs_available' returning varchar2(200)));
        p_outputs.recyclebin_ocid := nvl(json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.compartments.livelabs_recyclebin' returning varchar2(200)), json_value(p_outputs.state_json, '$.outputs.compartment_ids.value.livelabs_recyclebin' returning varchar2(200)));
        p_outputs.delete_ocid := nvl(json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.compartments.livelabs_trash' returning varchar2(200)), json_value(p_outputs.state_json, '$.outputs.compartment_ids.value.livelabs_trash' returning varchar2(200)));
        p_outputs.default_dynamic_group := nvl(json_value(p_outputs.state_json, '$.outputs.livelabs_tenancy_setup.value.dynamic_group_ids.default' returning varchar2(100)), json_value(p_outputs.state_json, '$.outputs.livelabs_dynamic_group_ids.value.default' returning varchar2(100)));

        if p_outputs.default_compartment is null or p_outputs.available_ocid is null or p_outputs.recyclebin_ocid is null or p_outputs.delete_ocid is null or p_outputs.default_dynamic_group is null then
            raise_application_error(-20002, 'Terraform completed without all required LiveLabs tenancy outputs.');
        end if;

        put_result_value(io_result, 'outputs', 'default_compartment_ocid', p_outputs.default_compartment);
        put_result_value(io_result, 'outputs', 'available_ocid', p_outputs.available_ocid);
        put_result_value(io_result, 'outputs', 'recyclebin_ocid', p_outputs.recyclebin_ocid);
        put_result_value(io_result, 'outputs', 'delete_ocid', p_outputs.delete_ocid);
        put_result_value(io_result, 'outputs', 'default_dynamic_group', p_outputs.default_dynamic_group);
    end read_terraform_outputs;

    -- 4. Persist the non-key page 9121 values returned by Terraform.
    procedure persist_terraform_outputs(
        p_context in t_terraform_context,
        p_outputs in t_terraform_outputs
    ) is
    begin
        update ll_tenancies
           set tenancy_name = nvl(p_outputs.tenancy_name, p_context.tenancy_name),
               tenancy_ocid = p_context.tenancy_ocid,
               swift_name = p_context.swift_name,
               preference_weight = p_context.preference_weight,
               home_region = p_context.home_region,
               active_flg = p_context.active_flg,
               ad_prefix = p_context.ad_prefix,
               is_public = p_context.is_public,
               concurrent_move = p_context.concurrent_move,
               default_compartment_name = 'LiveLabs',
               default_compartment_ocid = p_outputs.default_compartment,
               available_ocid = p_outputs.available_ocid,
               recyclebin_ocid = p_outputs.recyclebin_ocid,
               delete_ocid = p_outputs.delete_ocid,
               default_dynamic_group = p_outputs.default_dynamic_group
         where id = p_context.tenancy_id;

        commit;
    end persist_terraform_outputs;

    procedure run_terraform(
        p_tenancy_id in number,
        p_result     out nocopy clob
    ) is
        v_context t_terraform_context;
        v_outputs t_terraform_outputs;
        v_result  json_object_t := json_object_t();
        v_stack_id varchar2(200);
        v_job_id   varchar2(200);
        v_stage    varchar2(200) := 'load tenancy';
    begin
        v_result.put('setup_method', 'TERRAFORM');
        v_result.put('tenancy_id', p_tenancy_id);
        load_terraform_context(p_tenancy_id, v_context);
        v_stage := 'validate API signing key';
        validate_api_signing(v_context.tenancy_id, v_context.tenancy_ocid, v_context.region_key);

        ll_pkg_log.log(10, 'LL_PKG_TENANCY_SETUP.RUN_TERRAFORM started for tenancy ID ' || p_tenancy_id);

        v_stage := '1. create Terraform stack';
        create_terraform_stack(v_context, v_result, v_stack_id);
        v_stage := '2. run Terraform apply';
        run_terraform_apply(v_context, v_stack_id, v_result, v_job_id);
        v_stage := '3. read Terraform outputs';
        read_terraform_outputs(v_context, v_job_id, v_result, v_outputs);
        v_stage := '4. persist Terraform outputs';
        persist_terraform_outputs(v_context, v_outputs);

        complete_result(v_result, p_result);
        ll_pkg_log.log(30, v_outputs.state_json);
        ll_pkg_log.log(10, p_result);
    exception
        when others then
            if sqlcode = -20001 then
                raise;
            end if;

            fail_run(p_tenancy_id, v_stage, v_result, p_result);
    end run_terraform;

    procedure run_api(
        p_tenancy_id in number
    ) is
        v_result clob;
    begin
        run_api(p_tenancy_id, v_result);
    end run_api;

    procedure run_terraform(
        p_tenancy_id in number
    ) is
        v_result clob;
    begin
        run_terraform(p_tenancy_id, v_result);
    end run_terraform;

end ll_pkg_tenancy_setup;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_TERRAFORM" is                                                                                                                                                                          
-- Generate banners with http://patorjk.com/software/taag/#p=display&c=mysql&f=Banner3&t=TYPE%20HERE                                                                                                                                               
/*                                                                                                                                                                                                                                                 
  LOG levels                                                                                                                                                                                                                                       

  10 = Start and stop of high level packages                                                                                                                                                                                                       
  20 = Start and stop of subroutines                                                                                                                                                                                                               
  30 = Steps inside subroutines                                                                                                                                                                                                                    
  40 = Details steps inside subroutes (contains values)                                                                                                                                                                                            
  50 = Start and stop of REST statements to OCI (exec_get etc)                                                                                                                                                                                     
  60 = Detailed steps of REST commands                                                                                                                                                                                                             
  70 = Sign steps for REST commands                                                                                                                                                                                                                
  80 = Sign details (contains values)                                                                                                                                                                                                              
*/                                                                                                                                                                                                                                                 
--                                                                                                                                                                                                                                                 
--  ##      ##    ###    #### ########               ##  #######  ########           ######   #######  ##     ## ########  ##       ######## ######## ########                                                                                     
--  ##  ##  ##   ## ##    ##     ##                  ## ##     ## ##     ##         ##    ## ##     ## ###   ### ##     ## ##       ##          ##    ##                                                                                           
--  ##  ##  ##  ##   ##   ##     ##                  ## ##     ## ##     ##         ##       ##     ## #### #### ##     ## ##       ##          ##    ##                                                                                           
--  ##  ##  ## ##     ##  ##     ##                  ## ##     ## ########          ##       ##     ## ## ### ## ########  ##       ######      ##    ######                                                                                       
--  ##  ##  ## #########  ##     ##            ##    ## ##     ## ##     ##         ##       ##     ## ##     ## ##        ##       ##          ##    ##                                                                                           
--  ##  ##  ## ##     ##  ##     ##            ##    ## ##     ## ##     ##         ##    ## ##     ## ##     ## ##        ##       ##          ##    ##                                                                                           
--   ###  ###  ##     ## ####    ##    #######  ######   #######  ########  #######  ######   #######  ##     ## ##        ######## ########    ##    ########                                                                                     
--                                                                                                                                                                                                                                                 
  function wait_job_complete (p_tenancy_id number, p_host varchar2, p_job_id varchar2, p_max_minutes number) return varchar2 is                                                                                                                    
    v_current_seconds  number := 0;                                                                                                                                                                                                                
    v_step_seconds     number := 30;                                                                                                                                                                                                               
    v_json             clob;                                                                                                                                                                                                                       
    v_current_status   varchar2(200);                                                                                                                                                                                                              
    v_max_seconds      number := p_max_minutes * 60;                                                                                                                                                                                               
  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call. p_max_minutes: '||p_max_minutes||', p_job_id:'||p_job_id);                                                                                                                                                    
    ll_pkg_security.set_security_group;                                                                                                                                                                                                            
    ll_pkg_log.log(40,'Job ID: '||p_job_id);                                                                                                                                                                                                       
    while v_current_seconds < v_max_seconds and nvl(v_current_status,'ACCEPTED') in ('ACCEPTED','IN_PROGRESS') loop                                                                                                                                
      v_json := ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,                                                                                                                                                                                      
                                p_host => p_host,                                                                                                                                                                                                  
                                p_method => '/20180917/jobs/'||p_job_id );                                                                                                                                                                         

      v_current_status := JSON_VALUE( v_json, '$.lifecycleState');                                                                                                                                                                                 
      ll_pkg_log.log(40,'Current state: '||v_current_status);                                                                                                                                                                                      

      ll_pkg_log.log(30,'Waiting for job to finish, '||v_current_seconds||' from '||v_max_seconds||' passed. (Current status: '||v_current_status||' on job_ocid: '||p_job_id||')');                                                               
      if v_current_status <> 'SUCCEEDED' then                                                                                                                                                                                                      
        ll_pkg_log.log(40,'Current status <> SUCCEEDED so pause '||v_step_seconds||' seconds');                                                                                                                                                    
        apex_util.pause(v_step_seconds);                                                                                                                                                                                                           
        ll_pkg_log.log(30,'Pause has finished, checking current status of Job');                                                                                                                                                                   
      else                                                                                                                                                                                                                                         
        ll_pkg_log.log(40,'Current state is SUCCEEDED');                                                                                                                                                                                           
      end if;                                                                                                                                                                                                                                      
      v_current_seconds := v_current_seconds + v_step_seconds;                                                                                                                                                                                     
    end loop;                                                                                                                                                                                                                                      
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                              
    return(v_current_status);                                                                                                                                                                                                                      
  end;                                                                                                                                                                                                                                             
--                                                                                                                                                                                                                                                 
--  ######## ######## ########  ######  ##     ##               ##  #######  ########           #######  ##     ## ######## ########  ##     ## ########                                                                                           
--  ##       ##          ##    ##    ## ##     ##               ## ##     ## ##     ##         ##     ## ##     ##    ##    ##     ## ##     ##    ##                                                                                              
--  ##       ##          ##    ##       ##     ##               ## ##     ## ##     ##         ##     ## ##     ##    ##    ##     ## ##     ##    ##                                                                                              
--  ######   ######      ##    ##       #########               ## ##     ## ########          ##     ## ##     ##    ##    ########  ##     ##    ##                                                                                              
--  ##       ##          ##    ##       ##     ##         ##    ## ##     ## ##     ##         ##     ## ##     ##    ##    ##        ##     ##    ##                                                                                              
--  ##       ##          ##    ##    ## ##     ##         ##    ## ##     ## ##     ##         ##     ## ##     ##    ##    ##        ##     ##    ##                                                                                              
--  ##       ########    ##     ######  ##     ## #######  ######   #######  ########  #######  #######   #######     ##    ##         #######     ##                                                                                              
--                                                                                                                                                                                                                                                 
  function fetch_job_output (p_tenancy_id number, p_host varchar2, p_job_id varchar2) return varchar2 is                                                                                                                                           
    v_current_seconds  number := 0;                                                                                                                                                                                                                
    v_step_seconds     number := 10;                                                                                                                                                                                                               
    v_json             clob;                                                                                                                                                                                                                       
    v_current_status   varchar2(200);                                                                                                                                                                                                              
    v_return_value     varchar2(4000);                                                                                                                                                                                                             
  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call, p_tenancy_id: '||p_tenancy_id||', p_host: '||p_host||', p_job_id: '||p_job_id);                                                                                                                               
    v_json := ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,                                                                                                                                                                                        
                              p_host => p_host,                                                                                                                                                                                                    
                              p_method => '/20180917/jobs/'||p_job_id||'/tfState' );                                                                                                                                                               
    ll_pkg_log.log(40,'v_json: '||v_json);                                                                                                                                                                                                         
    if JSON_QUERY( v_json, '$.outputs' ) is null then                                                                                                                                                                                              
        v_return_value := JSON_QUERY( v_json, '$.modules[0].outputs' );                                                                                                                                                                            
        ll_pkg_log.log(40,'v_return_value: '||v_return_value);                                                                                                                                                                                     
        v_return_value := replace(v_return_value,'"}','"');                                                                                                                                                                                        
    elsif length(JSON_QUERY( v_json, '$.outputs' )) < 4000 then                                                                                                                                                                                    
        v_return_value := JSON_QUERY( v_json, '$.outputs' );                                                                                                                                                                                       
    else                                                                                                                                                                                                                                           
        v_return_value := 'Check output of Terraform stack';                                                                                                                                                                                       
    end if;                                                                                                                                                                                                                                        
    ll_pkg_log.log(40,'v_return_value: '||v_return_value);                                                                                                                                                                                         

    v_return_value := replace(v_return_value,'{"sensitive":false,"type":"string","value":','');                                                                                                                                                    
    ll_pkg_log.log(40,'v_return_value: '||v_return_value);                                                                                                                                                                                         
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                              

    return(v_return_value);                                                                                                                                                                                                                        
  end;                                                                                                                                                                                                                                             


  function parameter_value(p_name in varchar2) return varchar2 is                                                                                                                                                                                  
    l_value ll_system_parameters.value%type;                                                                                                                                                                                                       
  begin                                                                                                                                                                                                                                            
    select value                                                                                                                                                                                                                                   
      into l_value                                                                                                                                                                                                                                 
      from ll_system_parameters                                                                                                                                                                                                                    
     where name = p_name;                                                                                                                                                                                                                          
    return l_value;                                                                                                                                                                                                                                
  exception                                                                                                                                                                                                                                        
    when no_data_found then                                                                                                                                                                                                                        
      raise_application_error(-20001, 'Missing system parameter ' || p_name);                                                                                                                                                                      
  end parameter_value;                                                                                                                                                                                                                             

  function upload_failed_job_log(                                                                                                                                                                                                                  
    p_reservation_id in number                                                                                                                                                                                                                     
  ) return varchar2 is                                                                                                                                                                                                                             
    l_job_log           clob;                                                                                                                                                                                                                      
    l_response          clob;                                                                                                                                                                                                                      
    l_namespace         varchar2(100);                                                                                                                                                                                                             
    l_bucket            varchar2(100);                                                                                                                                                                                                             
    l_par_base          varchar2(3000);                                                                                                                                                                                                            
    l_upload_host       varchar2(1000);                                                                                                                                                                                                            
    l_object_name       varchar2(512);                                                                                                                                                                                                                 
    l_tenancy_id        number;                                                                                                                                                                                                                       
    l_host              varchar2(1000);                                                                                                                                                                                                                 
    l_job_id            varchar2(4000);                                                                                                                                                                                                                 
    l_workshop_id       number;
    l_used_persisted_log boolean := false;
  begin                                                                                                                                                                                                                                            
    l_tenancy_id := ll_pkg_reservation.tenancy_id(p_reservation_id);                                                                                                                                                                               
    l_host := ll_pkg_admin.oci_endpoint(                                                                                                                                                                                                           
      p_type       => 'resourcemanager',                                                                                                                                                                                                           
      p_region_key => ll_pkg_reservation.region_key(p_reservation_id)                                                                                                                                                                              
    );                                                                                                                                                                                                                                             
    l_job_id := ll_pkg_reservation.user_object_ocid(                                                                                                                                                                                                    
      p_reservation_id => p_reservation_id,                                                                                                                                                                                                            
      p_param_type     => 'ociTfApplyJob'                                                                                                                                                                                                              
    );                                                                                                                                                                                                                                                 
    select workshop_id
      into l_workshop_id
      from ll_reservations
     where id = p_reservation_id;
    if l_job_id is null or instr(l_job_id, 'Error:') = 1 then                                                                                                                                                                                      
      raise_application_error(-20005,                                                                                                                                                                                                              
        'Cannot resolve the Apply job OCID for reservation ' || p_reservation_id);                                                                                                                                                                 
    end if;                                                                                                                                                                                                                                        
    -- The failed-job flow has already persisted the Resource Manager console
    -- records in LL_RESERVATION_TF_LOG.  Use that durable copy first: a later
    -- retry can run after the stack/job has been cleaned up, when Resource
    -- Manager correctly no longer permits a GET of the job logs.
    select json_serialize(
             json_arrayagg(
               json_object(
                 'type'      value log_type,
                 'level'     value log_level,
                 'timestamp' value log_timestamp,
                 'message'   value log_message
                 returning clob
               )
               order by log_timestamp
               returning clob
             )
             returning clob pretty
           )
      into l_job_log
      from (
        select distinct log_type, log_level, log_timestamp, log_message
          from ll_reservation_tf_log
         where reservation_id = p_reservation_id
           and job_ocid = l_job_id
           and log_timestamp is not null
      );

    l_used_persisted_log := l_job_log is not null;

    if l_job_log is null then
      l_job_log := ll_pkg_exec.get(
        p_tenancy_id => l_tenancy_id,
        p_host       => l_host,
        p_method     => '/20180917/jobs/' || l_job_id || '/logs'
      );
    end if;

    if l_job_log is null
       or (not l_used_persisted_log and
           (apex_web_service.g_status_code not between 200 and 299
            or json_value(l_job_log, '$.code' returning varchar2 null on error) is not null)) then
      return 'No OCI Terraform log was available for reservation ' ||
             p_reservation_id || ': ' ||
             nvl(
               json_value(l_job_log, '$.message' returning varchar2 null on error),
               'Resource Manager returned HTTP ' || apex_web_service.g_status_code
             );
    end if;

    l_namespace         := parameter_value('TERRAFORM_LOG_NAMESPACE');                                                                                                                                                                             
    l_bucket            := parameter_value('TERRAFORM_LOG_BUCKET_NAME');                                                                                                                                                                           
    l_upload_host        := parameter_value('TERRAFORM_LOG_OBJECT_STORAGE_HOST');                                                                                                                                                                  

    begin                                                                                                                                                                                                                                          
      select value                                                                                                                                                                                                                                 
        into l_par_base                                                                                                                                                                                                                            
        from apex_application_settings                                                                                                                                                                                                             
       where application_id = 100                                                                                                                                                                                                                  
         and name = 'TERRAFORM_LOG_PAR_BASE_URL';                                                                                                                                                                                                  
    exception                                                                                                                                                                                                                                      
      when no_data_found then                                                                                                                                                                                                                      
        raise_application_error(-20004, 'Missing application setting TERRAFORM_LOG_PAR_BASE_URL for app 100');                                                                                                                                     
    end;                                                                                                                                                                                                                                           

    l_object_name := 'terraform-logs/res' || p_reservation_id ||
                     '-ll' || l_workshop_id ||
                     '-' || to_char(sysdate, 'DDMMYY-HH24MISS');

    apex_web_service.g_request_headers.delete;
    apex_web_service.g_request_headers(1).name  := 'Content-Type';
    apex_web_service.g_request_headers(1).value := 'application/json';

    -- The c4u02 Web Credential signs this Object Storage request directly.
    -- Do not route large CLOB logs through LL_PKG_EXEC, whose signer accepts
    -- VARCHAR2 input and therefore cannot sign a complete job log.
    l_response := apex_web_service.make_rest_request(
      p_url                  => 'https://' || l_upload_host ||
                                '/n/' || l_namespace || '/b/' || l_bucket ||
                                '/o/' || l_object_name,
      p_http_method          => 'PUT',
      p_body                 => l_job_log,
      p_credential_static_id => 'c4u02'
    );

    if apex_web_service.g_status_code not between 200 and 299 then                                                                                                                                                                                 
      raise_application_error(-20003, 'Object Storage upload returned HTTP ' || apex_web_service.g_status_code);                                                                                                                                   
    end if;                                                                                                                                                                                                                                        

    ll_pkg_log.log(30, 'Uploaded failed Terraform log to ' || l_object_name);                                                                                                                                                                      
    return rtrim(l_par_base, '/') || '/' || l_object_name;                                                                                                                                                                                         
  exception                                                                                                                                                                                                                                        
    when others then                                                                                                                                                                                                                               
      ll_pkg_log.log(1, 'Failed to upload Terraform log for reservation ' || p_reservation_id || ': ' || sqlerrm);                                                                                                                                 
      return 'JOB result is FAILED; Terraform log upload failed: ' || substr(sqlerrm, 1, 3500);                                                                                                                                                    
  end upload_failed_job_log;                                                                                                                                                                                                                       

  --  ######## ######## ########  ########     ###    ########  #######  ########  ##     ##         ########    ###    #### ##       ##     ## ########  ########          #######  ##     ## ######## ########  ##     ## ########               
--     ##    ##       ##     ## ##     ##   ## ##   ##       ##     ## ##     ## ###   ###         ##         ## ##    ##  ##       ##     ## ##     ## ##               ##     ## ##     ##    ##    ##     ## ##     ##    ##                    
--     ##    ##       ##     ## ##     ##  ##   ##  ##       ##     ## ##     ## #### ####         ##        ##   ##   ##  ##       ##     ## ##     ## ##               ##     ## ##     ##    ##    ##     ## ##     ##    ##                    
--     ##    ######   ########  ########  ##     ## ######   ##     ## ########  ## ### ##         ######   ##     ##  ##  ##       ##     ## ########  ######           ##     ## ##     ##    ##    ########  ##     ##    ##                    
--     ##    ##       ##   ##   ##   ##   ######### ##       ##     ## ##   ##   ##     ##         ##       #########  ##  ##       ##     ## ##   ##   ##               ##     ## ##     ##    ##    ##        ##     ##    ##                    
--     ##    ##       ##    ##  ##    ##  ##     ## ##       ##     ## ##    ##  ##     ##         ##       ##     ##  ##  ##       ##     ## ##    ##  ##               ##     ## ##     ##    ##    ##        ##     ##    ##                    
--     ##    ######## ##     ## ##     ## ##     ## ##        #######  ##     ## ##     ## ####### ##       ##     ## #### ########  #######  ##     ## ######## #######  #######   #######     ##    ##         #######     ##                    
