--  begin                                                                                                                                                                                                                                          
--     v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id));                                                                                                         
--     v_method := '/20180917/jobs/'||p_job_id||'/logs';                                                                                                                                                                                           
--     v_clob := ll_pkg_exec.get(p_tenancy_id => p_tenancy_id,                                                                                                                                                                                     
--                                p_host => v_host,                                                                                                                                                                                                
