 --                                                                                                                                                                                                                                                
 -- ======================================================================================================================                                                                                                                         
 --                                                                                                                                                                                                                                                
--                                                                                                                                                                                                                                                 
--   ######  ########  ########    ###    ######## ########          ######  ########    ###     ######  ##    ##                                                                                                                                  
--  ##    ## ##     ## ##         ## ##      ##    ##               ##    ##    ##      ## ##   ##    ## ##   ##                                                                                                                                   
--  ##       ##     ## ##        ##   ##     ##    ##               ##          ##     ##   ##  ##       ##  ##                                                                                                                                    
--  ##       ########  ######   ##     ##    ##    ######            ######     ##    ##     ## ##       #####                                                                                                                                     
--  ##       ##   ##   ##       #########    ##    ##                     ##    ##    ######### ##       ##  ##                                                                                                                                    
--  ##    ## ##    ##  ##       ##     ##    ##    ##               ##    ##    ##    ##     ## ##    ## ##   ##                                                                                                                                   
--   ######  ##     ## ######## ##     ##    ##    ######## #######  ######     ##    ##     ##  ######  ##    ##                                                                                                                                  
--                                                                                                                                                                                                                                                 
procedure create_stack (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS                                                                                                 
    cursor c_tf (p_tf_id number) is select terraform_text, terraform_version, nvl(directory, source_url), repository_url, branch, 'LiveLabs TF script '||id||' - ' || description as description                                                   
                                    from ll_tf_scripts                                                                                                                                                                                             
                                    where id=p_tf_id;                                                                                                                                                                                              
    cursor c_ssh is select public_key from ll_reservations where id=p_reservation_id;                                                                                                                                                              
    v_host              varchar2(200);                                                                                                                                                                                                             
    v_method            varchar2(200);                                                                                                                                                                                                             
    v_clob              clob;                                                                                                                                                                                                                      
    v_payload           clob;                                                                                                                                                                                                                      
    v_tf_id             number;                                                                                                                                                                                                                    
    v_tf_base64         clob;                                                                                                                                                                                                                      
    v_tf_zipped         blob;                                                                                                                                                                                                                      
    v_tf_version        varchar2(10);                                                                                                                                                                                                              
    v_tf_text           clob;                                                                                                                                                                                                                      
    v_tf_source_url     varchar2(4000);                                                                                                                                                                                                            
    v_tf_repository_url varchar2(4000);                                                                                                                                                                                                            
    v_tf_branch         varchar2(4000);                                                                                                                                                                                                            
    v_tf_description    varchar2(4000);                                                                                                                                                                                                            
    v_tenancy_id        number;                                                                                                                                                                                                                    
    v_tenancy_ocid      varchar2(200);                                                                                                                                                                                                             
    v_region_key        varchar2(100);                                                                                                                                                                                                             
    v_region_id         number;                                                                                                                                                                                                                    
    v_user_ocid         varchar2(500);                                                                                                                                                                                                             
    v_vcn_ocid          varchar2(500);                                                                                                                                                                                                             
    -- v_quota_ocid        varchar2(500);                                                                                                                                                                                                          
    v_pub_subnet_ocid   varchar2(500);                                                                                                                                                                                                             
    v_region_identifier varchar2(100);                                                                                                                                                                                                             
    v_compartment_ocid  varchar2(200);                                                                                                                                                                                                             
    v_object_name       varchar2(200);                                                                                                                                                                                                             
    v_tf_variables      varchar2(6000);                                                                                                                                                                                                            
    v_initial_password  varchar2(4000);                                                                                                                                                                                                            
    v_ssh_public_key    varchar2(4000);                                                                                                                                                                                                            
    v_source_blob       blob;                                                                                                                                                                                                                      
    v_csp_ocid          varchar2(4000);                                                                                                                                                                                                            
    v_priv_subnet_ocid  varchar2(500);                                                                                                                                                                                                             
    v_genai_region      varchar2(500);                                                                                                                                                                                                             
    v_live_stack_url    varchar2(1000);                                                                                                                                                                                                            
    v_repository_url    varchar2(4000);                                                                                                                                                                                                            
    v_branch_name       varchar2(4000);                                                                                                                                                                                                            
    v_ll_id             number;                                                                                                                                                                                                                    
    v_error_message     varchar2(4000);                                                                                                                                                                                                            

  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                             
    ll_pkg_log.log(30,'Waiting 15 seconds to make sure compartment info is available');                                                                                                                                                            
    apex_util.pause(15);                                                                                                                                                                                                                           
    ll_pkg_log.log(30,'End of waiting; continuing with STACK creation');                                                                                                                                                                           

    select workshop_id into v_ll_id from ll_reservations where id = p_reservation_id;                                                                                                                                                              
    v_region_key := ll_pkg_reservation.region_key(p_reservation_id);                                                                                                                                                                               
    v_region_identifier := ll_pkg_admin.region_identifier (p_region_id => ll_pkg_reservation.region_id(p_reservation_id));                                                                                                                         
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => v_region_key);                                                                                                                                               
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);                                                                                                                                                                              
    v_tenancy_ocid := ll_pkg_admin.tenancy_ocid (p_tenancy_id => v_tenancy_id);                                                                                                                                                                    
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id);                                                                                                                                                                                

    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                
                                                              p_param_type     => 'ociCompartment');                                                                                                                                               
    v_user_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                       
                                                       p_param_type     => 'ociUser');                                                                                                                                                             
    v_vcn_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                        
                                                       p_param_type     => 'ociVcn' );                                                                                                                                                             
    v_pub_subnet_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                 
                                                       p_param_type     => 'ociVcnSubPub' );                                                                                                                                                       
    v_priv_subnet_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                
                                                       p_param_type     => 'ociVcnSubPriv' );                                                                                                                                                      
    v_genai_region := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                    
                                                       p_param_type     => 'ociGenAI' );                                                                                                                                                           
    -- v_quota_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                   
    --                                                    p_param_type     => 'ociQuota' );                                                                                                                                                        
    v_object_name := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id,                                                                                                                                                         
                                                     p_res_step_id   => p_res_step_id,                                                                                                                                                             
                                                     p_json_name     => 'name');                                                                                                                                                                   
    v_tf_id := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,                                                                                                                                                              
                                                p_res_step_id    => p_res_step_id,                                                                                                                                                                 
                                                p_json_name      => 'param1');                                                                                                                                                                     

    v_initial_password := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                
                                                       p_param_type     => 'ociUserPassword');                                                                                                                                                     

    -- Get the LiveStack Demo URL for this workshop.                                                                                                                                                                                               
    BEGIN                                                                                                                                                                                                                                          
        SELECT lw.livestack_demo_url                                                                                                                                                                                                               
          INTO v_live_stack_url                                                                                                                                                                                                                    
          FROM ll_workshops lw                                                                                                                                                                                                                     
          JOIN ll_types lt                                                                                                                                                                                                                         
            ON lt.id = lw.type_id                                                                                                                                                                                                                  
         WHERE lw.id = v_ll_id                                                                                                                                                                                                                     
           AND lt.name = 'LiveStack Demo';                                                                                                                                                                                                         
    EXCEPTION                                                                                                                                                                                                                                      
        WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                    
            NULL;                                                                                                                                                                                                                                  
    END;                                                                                                                                                                                                                                           


    open c_ssh;                                                                                                                                                                                                                                    
    fetch c_ssh into v_ssh_public_key;                                                                                                                                                                                                             
    close c_ssh;                                                                                                                                                                                                                                   
    ll_pkg_log.log(30,'Retrieved all parameters required');                                                                                                                                                                                        

    -- Get the Terraform text and version.                                                                                                                                                                                                         
    open c_tf (v_tf_id);                                                                                                                                                                                                                           
    fetch c_tf into v_tf_text, v_tf_version, v_tf_source_url, v_tf_repository_url, v_tf_branch, v_tf_description;                                                                                                                                  
    close c_tf;                                                                                                                                                                                                                                    
    v_repository_url := nvl(                                                                                                                                                                                                                       
      ll_pkg_reservation.step_details(                                                                                                                                                                                                             
        p_reservation_id => p_reservation_id,                                                                                                                                                                                                      
        p_res_step_id    => p_res_step_id,                                                                                                                                                                                                         
        p_json_name      => 'repositoryUrl'                                                                                                                                                                                                        
      ),                                                                                                                                                                                                                                           
      nvl(v_tf_repository_url, 'https://github.com/oracle-livelabs/terraform-stage.git')                                                                                                                                                           
    );                                                                                                                                                                                                                                             
    v_tf_source_url := nvl(                                                                                                                                                                                                                        
      ll_pkg_reservation.step_details(                                                                                                                                                                                                             
        p_reservation_id => p_reservation_id,                                                                                                                                                                                                      
        p_res_step_id    => p_res_step_id,                                                                                                                                                                                                         
        p_json_name      => 'directory'                                                                                                                                                                                                            
      ),                                                                                                                                                                                                                                           
      v_tf_source_url                                                                                                                                                                                                                              
    );                                                                                                                                                                                                                                             
    v_branch_name := nvl(                                                                                                                                                                                                                          
      ll_pkg_reservation.step_details(                                                                                                                                                                                                             
        p_reservation_id => p_reservation_id,                                                                                                                                                                                                      
        p_res_step_id    => p_res_step_id,                                                                                                                                                                                                         
        p_json_name      => 'branchName'                                                                                                                                                                                                           
      ),                                                                                                                                                                                                                                           
      nvl(v_tf_branch, 'main')                                                                                                                                                                                                                     
    );                                                                                                                                                                                                                                             
    -- if v_tf_source_url is null then                                                                                                                                                                                                             
    --   -- Put the text in a zipfile                                                                                                                                                                                                              
    --   ll_pkg_zip.add1file  ( v_tf_zipped, 'll_terraform.tf',  ll_pkg_admin.clob_to_blob(v_tf_text) );                                                                                                                                           
    --   ll_pkg_zip.finish_zip( v_tf_zipped );                                                                                                                                                                                                     
    --   ll_pkg_log.log(30,'Created the zipfile for the Terraform');                                                                                                                                                                               

    -- else                                                                                                                                                                                                                                        
    --   v_tf_zipped := ll_pkg_exec.get_blob_from_url( p_url => v_tf_source_url);                                                                                                                                                                  

    -- end if;                                                                                                                                                                                                                                     
    -- Create Base64 from the file                                                                                                                                                                                                                 
    -- v_tf_base64 := ll_pkg_admin.Base64encode( v_tf_zipped);                                                                                                                                                                                     

    ll_pkg_log.log(30,'Adding parameter to the Terraform request');                                                                                                                                                                                
    v_tf_variables := JSON_OBJECT ( 'ociTenancyOcid'       value v_tenancy_ocid,                                                                                                                                                                   
                                    'ociRegionKey'         value v_region_key,                                                                                                                                                                     
                                    'ociRegionIdentifier'  value v_region_identifier,                                                                                                                                                              
                                    'ociUserOcid'          value v_user_ocid,                                                                                                                                                                      
                                    'ociCompartmentOcid'   value v_compartment_ocid,                                                                                                                                                               
                                    'ociVcnOcid'           value v_vcn_ocid,                                                                                                                                                                       
                                    'ociPublicSubnetOcid'  value v_pub_subnet_ocid,                                                                                                                                                                
                                    'ociPrivateSubnetOcid' value v_priv_subnet_ocid,                                                                                                                                                               
                                    -- 'ociQuotaOcid'         value v_quota_ocid,                                                                                                                                                                  
                                    'ociUserPassword'      value v_initial_password,                                                                                                                                                               
                                    'ociGenAiRegion'       value v_genai_region,                                                                                                                                                                   
                                    'resUserPublicKey'     value v_ssh_public_key,                                                                                                                                                                 
                                    'resId'                value p_reservation_id,                                                                                                                                                                 
                                    'liveStackURL'         value v_live_stack_url                                                                                                                                                                  
                                    ABSENT ON NULL);                                                                                                                                                                                               
    ll_pkg_log.log(40,'Parameters added: '||v_tf_variables);                                                                                                                                                                                       
    -- Create the OCI Resource Manager stack.                                                                                                                                                                                                      
    ll_pkg_log.log(30,'Uploading file to OCI Stack');                                                                                                                                                                                              
    v_method := '/20180917/stacks';                                                                                                                                                                                                                
    if v_tf_source_url is null then                                                                                                                                                                                                                
        v_payload := JSON_OBJECT( 'compartmentId'    value v_compartment_ocid,                                                                                                                                                                     
                                  'displayName'      value v_object_name||'-'||to_char(sysdate,'YYYYMMDD-HH24MISS'),                                                                                                                               
                                  'description'      value v_tf_description,                                                                                                                                                                       
                                  'terraformVersion' value v_tf_version,                                                                                                                                                                           
                                  'configSource'     value JSON_OBJECT( 'configSourceType'     value 'ZIP_UPLOAD',                                                                                                                                 
                                                                        'zipFileBase64Encoded' value v_tf_base64 ),                                                                                                                                
                                  'variables'        value '@TFvar@'                                                                                                                                                                               
                                  ABSENT ON NULL);                                                                                                                                                                                                 
    else                                                                                                                                                                                                                                           
        select config_source_ocid into v_csp_ocid from ll_config_source_providers where tenancy_id = v_tenancy_id and region_key = v_region_key;                                                                                                   
        v_payload := JSON_OBJECT( 'compartmentId'    value v_compartment_ocid,                                                                                                                                                                     
                                  'displayName'      value v_object_name||'-'||to_char(sysdate,'YYYYMMDD-HH24MISS'),                                                                                                                               
                                  'description'      value v_tf_description,                                                                                                                                                                       
                                  'terraformVersion' value v_tf_version,                                                                                                                                                                           
                                  'configSource'     value JSON_OBJECT( 'configSourceType'  value 'GIT_CONFIG_SOURCE',                                                                                                                             
                                                                        'configurationSourceProviderId'            value v_csp_ocid,                                                                                                               
                                                                        'workingDirectory'  value v_tf_source_url,                                                                                                                                 
                                                                        'branchName'         value v_branch_name,                                                                                                                                  
                                                                        'repositoryUrl'        value v_repository_url),                                                                                                                            
                                  'variables'        value '@TFvar@'                                                                                                                                                                               
                                  ABSENT ON NULL);                                                                                                                                                                                                 
    end if;                                                                                                                                                                                                                                        
    v_payload := replace(v_payload ,'"@TFvar@"', v_tf_variables);                                                                                                                                                                                  
    v_clob := ll_pkg_exec.put_post ( p_tenancy_id => v_tenancy_id,                                                                                                                                                                                 
                                     p_type       => 'POST',                                                                                                                                                                                       
                                     p_host       => v_host,                                                                                                                                                                                       
                                     p_method     => v_method,                                                                                                                                                                                     
                                     p_body       => v_payload);                                                                                                                                                                                   
    p_ocid := ll_pkg_admin.get_id(v_clob);                                                                                                                                                                                                         
    ll_pkg_log.log(40,'Stack request completed, OCID is '||p_ocid);                                                                                                                                                                                
    if p_ocid is null then                                                                                                                                                                                                                         
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := v_clob;                                                                                                                                                                                                                          
    else                                                                                                                                                                                                                                           
      p_status := 'Y';                                                                                                                                                                                                                             
    end if;                                                                                                                                                                                                                                        

  EXCEPTION                                                                                                                                                                                                                                        
    WHEN others THEN                                                                                                                                                                                                                               
      v_error_message := SQLERRM;                                                                                                                                                                                                                  
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := v_error_message;                                                                                                                                                                                                                 
  end;                                                                                                                                                                                                                                             
--                                                                                                                                                                                                                                                 
--     ###    ########  ########  ##       ##    ##               ##  #######  ########                                                                                                                                                            
--    ## ##   ##     ## ##     ## ##        ##  ##                ## ##     ## ##     ##                                                                                                                                                           
--   ##   ##  ##     ## ##     ## ##         ####                 ## ##     ## ##     ##                                                                                                                                                           
--  ##     ## ########  ########  ##          ##                  ## ##     ## ########                                                                                                                                                            
--  ######### ##        ##        ##          ##            ##    ## ##     ## ##     ##                                                                                                                                                           
--  ##     ## ##        ##        ##          ##            ##    ## ##     ## ##     ##                                                                                                                                                           
--  ##     ## ##        ##        ########    ##    #######  ######   #######  ########                                                                                                                                                            
--                                                                                                                                                                                                                                                 
  procedure send_terraform_failure_email (
    p_reservation_id in number,
    p_log_result     in varchar2
  ) is
    l_workshop_name  ll_workshops.name%type;
    l_workshop_owner ll_workshops.author_email%type;
    l_reservation_owner ll_reservations.owner1%type;
    l_log_url        varchar2(4000);
    l_log_link       varchar2(4000);
    l_terraform_source varchar2(30) := 'Plain Text';
    l_repository_url    varchar2(4000);
    l_branch_name       varchar2(4000);
    l_directory         varchar2(4000);
    l_source_details_html varchar2(4000);
    l_source_details_text varchar2(4000);
  begin
    ll_pkg_security.set_security_group;
    select w.name, w.author_email, r.owner1
      into l_workshop_name, l_workshop_owner, l_reservation_owner
      from ll_reservations r
      join ll_workshops w on w.id = r.workshop_id
     where r.id = p_reservation_id;

    if l_reservation_owner is null or instr(l_reservation_owner, '@') = 0 then
      ll_pkg_log.log(20, 'No reservation-owner email address for Terraform failure reservation ' || p_reservation_id);
      return;
    end if;

    if regexp_like(p_log_result, '^https://') then
      l_log_url := p_log_result;
      l_log_link := '<a href="' || apex_escape.html_attribute(p_log_result) || '">View Terraform log</a>';
    else
      l_log_link := 'No Terraform log link was available.';
    end if;

    begin
      select json_value(rs.flow_step_param, '$.repositoryUrl'),
             json_value(rs.flow_step_param, '$.branchName'),
             json_value(rs.flow_step_param, '$.directory')
        into l_repository_url, l_branch_name, l_directory
        from ll_reservation_steps rs
        join ll_flow_steps fs on fs.id = rs.flow_step_id
       where rs.reservation_id = p_reservation_id
         and fs.step_code = 'ociTerraform'
       fetch first 1 rows only;

      if l_repository_url is not null then
        l_terraform_source := 'GitHub';
        l_source_details_html :=
          '<div><strong>Repository:</strong> <a href="' ||
          apex_escape.html_attribute(l_repository_url) || '">' ||
          apex_escape.html(l_repository_url) || '</a></div>' ||
          '<div><strong>Branch:</strong> ' ||
          apex_escape.html(nvl(l_branch_name, 'main')) || '</div>' ||
          '<div><strong>Directory:</strong> ' ||
          apex_escape.html(nvl(l_directory, '(repository root)')) || '</div>';
        l_source_details_text := 'Repository: ' || l_repository_url || chr(10) ||
                                 'Branch: ' || nvl(l_branch_name, 'main') || chr(10) ||
                                 'Directory: ' || nvl(l_directory, '(repository root)');
      end if;
    exception
      when no_data_found then
        null;
    end;

    apex_mail.send(
      -- p_to              => l_workshop_owner, -- Restore workshop-owner delivery when requested.
      p_to                 => l_reservation_owner,
      p_template_static_id => 'TERRAFORM_FAILURE',
      p_placeholders       => apex_string.plist_to_json_clob(apex_t_varchar2(
                                'WORKSHOP_NAME', l_workshop_name,
                                'RESERVATION_ID', to_char(p_reservation_id),
                                'TERRAFORM_SOURCE', l_terraform_source,
                                'TERRAFORM_SOURCE_DETAILS', l_source_details_html,
                                'TERRAFORM_SOURCE_TEXT', l_source_details_text,
                                'TERRAFORM_LOG_URL', l_log_url,
                                'TERRAFORM_LOG_LINK', l_log_link)),
      p_application_id     => 100
    );
  exception
    when no_data_found then
      ll_pkg_log.log(20, 'No workshop found for Terraform failure reservation ' || p_reservation_id);
    when others then
      ll_pkg_log.log(1, 'Unable to notify Terraform failure for reservation ' || p_reservation_id || ': ' || sqlerrm);
  end;

  procedure apply_job (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS                                                                                                  
    cursor c_tf (p_tf_id number) is select nvl(max_duration_minutes,30) max_duration_minutes                                                                                                                                                       
                                    from ll_tf_scripts                                                                                                                                                                                             
                                    where id=p_tf_id;                                                                                                                                                                                              
    v_host        varchar2(200);                                                                                                                                                                                                                   
    v_method      varchar2(200);                                                                                                                                                                                                                   
    v_clob        clob;                                                                                                                                                                                                                            
    v_payload     clob;                                                                                                                                                                                                                            
    v_stack_ocid  varchar2(200);                                                                                                                                                                                                                   
    v_tenancy_id  varchar2(200);                                                                                                                                                                                                                   
    v_region_id   number;                                                                                                                                                                                                                          
    v_compartment_ocid  varchar2(200);                                                                                                                                                                                                             
    v_object_name  varchar2(200);                                                                                                                                                                                                                  
    v_job_result   varchar2(200);                                                                                                                                                                                                                  
    v_job_ocid     varchar2(200);                                                                                                                                                                                                                  
    v_tf_id        number;                                                                                                                                                                                                                         
    v_max_minutes  number;                                                                                                                                                                                                                         
    v_parallels     number;                                                                                                                                                                                                                        
    v_code varchar2(4000);                                                                                                                                                                                                                         
  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                             
    ll_pkg_security.set_security_group;                                                                                                                                                                                                            
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id));                                                                                                            
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);                                                                                                                                                                              
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id);                                                                                                                                                                                
    v_stack_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                      
                                                        p_param_type     => 'ociTerraform' );                                                                                                                                                      

    v_object_name := ll_pkg_reservation.step_details(p_reservation_id => p_reservation_id,                                                                                                                                                         
                                                     p_res_step_id   => p_res_step_id,                                                                                                                                                             
                                                     p_json_name     => 'name');                                                                                                                                                                   
    v_tf_id := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,                                                                                                                                                              
                                                p_res_step_id    => p_res_step_id,                                                                                                                                                                 
                                                p_json_name      => 'param1');                                                                                                                                                                     
    open c_tf(v_tf_id);                                                                                                                                                                                                                            
    fetch c_tf into v_max_minutes;                                                                                                                                                                                                                 
    close c_tf;                                                                                                                                                                                                                                    
    v_method := '/20180917/jobs';                                                                                                                                                                                                                  
    select parallels into v_parallels from ll_tf_scripts where id=v_tf_id;                                                                                                                                                                         
    v_payload := JSON_OBJECT ( 'stackId'             value v_stack_ocid,                                                                                                                                                                           
                               'jobOperationDetails' value JSON_OBJECT( 'operation'             value 'APPLY',                                                                                                                                     
                                                                        'executionPlanStrategy' value 'AUTO_APPROVED',                                                                                                                             
                                                                        'terraformAdvancedOptions' value JSON_OBJECT('parallelism' value nvl(v_parallels, 10)))                                                                                    
                             );                                                                                                                                                                                                                    

    v_clob := ll_pkg_exec.put_post ( p_tenancy_id => v_tenancy_id,                                                                                                                                                                                 
                                     p_type       => 'POST',                                                                                                                                                                                       
                                     p_host       => v_host,                                                                                                                                                                                       
                                     p_method     => v_method,                                                                                                                                                                                     
                                     p_body       => v_payload);                                                                                                                                                                                   
    ll_pkg_log.log(30,'Apply job sumbitted');                                                                                                                                                                                                      
    p_ocid := ll_pkg_admin.get_id(v_clob);                                                                                                                                                                                                         
    if p_ocid is null then                                                                                                                                                                                                                         
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := v_clob;                                                                                                                                                                                                                          
      ll_pkg_log.log(1,'Apply job failed, output is '||v_clob);                                                                                                                                                                                    
    else                                                                                                                                                                                                                                           
      update ll_reservation_steps set object_ocid = p_ocid where id = p_res_step_id;                                                                                                                                                               
      ll_pkg_log.log(30,'Apply job succesfully launched, waiting for result');                                                                                                                                                                     
      v_job_result := wait_job_complete (p_tenancy_id => v_tenancy_id, p_host => v_host, p_job_id => p_ocid, p_max_minutes => v_max_minutes );                                                                                                     
      ll_pkg_log.log(30,'Apply job finished or timed out, status='||p_status);                                                                                                                                                                     
      if v_job_result = 'SUCCEEDED' then                                                                                                                                                                                                           
        p_status := 'Y';                                                                                                                                                                                                                           
        p_result := '';                                                                                                                                                                                                                            
      elsif v_job_result = 'FAILED' then                                                                                                                                                                                                           
        store_failed_tf_log(p_reservation_id);                                                                                                                                                                                                     
        p_status := 'N';                                                                                                                                                                                                                           
        p_result := upload_failed_job_log(p_reservation_id);                                                                                                                                                                                       
        -- p_result := 'JOB result is '||v_job_result||', log capture initiated :'||tf_output_error (p_tenancy_id => v_tenancy_id, p_host => v_host, p_job_id => p_ocid);                                                                          

      else                                                                                                                                                                                                                                         
        p_status := 'N';                                                                                                                                                                                                                           
        p_result := 'JOB result is '||v_job_result;                                                                                                                                                                                                
      end if;                                                                                                                                                                                                                                      
    end if;                                                                                                                                                                                                                                        
  EXCEPTION                                                                                                                                                                                                                                        
    WHEN others THEN                                                                                                                                                                                                                               
      p_status := 'N';                                                                                                                                                                                                                             
      store_failed_tf_log(p_reservation_id);
      p_result := upload_failed_job_log(p_reservation_id);
  end;                                                                                                                                                                                                                                             
--                                                                                                                                                                                                                                                 
-- ===================================================================================================================                                                                                                                             
--                                                                                                                                                                                                                                                 
  procedure check_job_result (p_reservation_id IN number, p_res_step_id IN number, p_ocid OUT varchar2, p_status OUT varchar2, p_result OUT varchar2) AS                                                                                           
    cursor c_tf (p_tf_id number) is select nvl(max_duration_minutes,30) max_duration_minutes, nvl(min_duration_minutes,nvl(max_duration_minutes,30)) min_duration_minutes                                                                          
                                    from ll_tf_scripts                                                                                                                                                                                             
                                    where id=p_tf_id;                                                                                                                                                                                              
    v_host              varchar2(200);                                                                                                                                                                                                             
    v_tenancy_id        varchar2(200);                                                                                                                                                                                                             
    v_region_id         number;                                                                                                                                                                                                                    
    v_job_ocid          varchar2(200);                                                                                                                                                                                                             
    v_tf_id             number;                                                                                                                                                                                                                    
    v_apply_step_id     number;                                                                                                                                                                                                                    
    v_max_minutes       number;                                                                                                                                                                                                                    
    v_min_minutes       number;                                                                                                                                                                                                                    
    v_minutes_wait      number;                                                                                                                                                                                                                    
    v_minutes_waited    number;                                                                                                                                                                                                                    
    v_json              clob;                                                                                                                                                                                                                      
    v_step_status       varchar2(1);                                                                                                                                                                                                               
    v_step_date         date;                                                                                                                                                                                                                      
    v_current_status    varchar2(500);                                                                                                                                                                                                             

      begin                                                                                                                                                                                                                                        
    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                             
    ll_pkg_security.set_security_group;                                                                                                                                                                                                            
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id));                                                                                                            
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);                                                                                                                                                                              
    v_tf_id := ll_pkg_reservation.step_details (p_reservation_id => p_reservation_id,                                                                                                                                                              
                                                p_res_step_id    => p_res_step_id,                                                                                                                                                                 
                                                p_json_name      => 'param1');                                                                                                                                                                     
    v_job_ocid := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,                                                                                                                                                       
                                                       p_param_type     => 'ociTfApplyJob');                                                                                                                                                       
    v_apply_step_id := ll_pkg_reservation.user_object_step_id (p_reservation_id => p_reservation_id,                                                                                                                                               
                                                               p_param_type     => 'ociTfApplyJob');                                                                                                                                               
-- Get status for the submit/apply job step so we can calculate how much time has passed                                                                                                                                                           
    ll_pkg_reservation.step_status (p_reservation_id   => p_reservation_id,                                                                                                                                                                        
                                    p_res_step_id      => v_apply_step_id,                                                                                                                                                                         
                                    p_step_date        => v_step_date,                                                                                                                                                                             
                                    p_step_status      => v_step_status );                                                                                                                                                                         
    ll_pkg_log.log(40,'Job OCID is '||v_job_ocid);                                                                                                                                                                                                 
    open c_tf(v_tf_id);                                                                                                                                                                                                                            
    fetch c_tf into v_max_minutes, v_min_minutes;                                                                                                                                                                                                  
    close c_tf;                                                                                                                                                                                                                                    
    -- Get current status of the job                                                                                                                                                                                                               
    v_json := ll_pkg_exec.get(p_tenancy_id => v_tenancy_id,                                                                                                                                                                                        
                                p_host     => v_host,                                                                                                                                                                                              
                                p_method   => '/20180917/jobs/'||v_job_ocid );                                                                                                                                                                     

    v_current_status := JSON_VALUE( v_json, '$.lifecycleState');                                                                                                                                                                                   
    ll_pkg_log.log(40,'Current state: '||v_current_status);                                                                                                                                                                                        
    v_minutes_wait := 0;                                                                                                                                                                                                                           
    v_minutes_waited := floor((sysdate - v_step_date) * 24 * 60);                                                                                                                                                                                  
    ll_pkg_log.log(30,'We have already waited '||v_minutes_waited||' for the apply');                                                                                                                                                              
    if v_current_status in ('SUBMITTED', 'IN_PROGRESS', 'ACCEPTED') then                                                                                                                                                                           
      if v_minutes_waited < v_min_minutes then                                                                                                                                                                                                     
        v_minutes_wait := v_min_minutes - v_minutes_waited;                                                                                                                                                                                        
        p_status := 'W';                                                                                                                                                                                                                           
        p_result := v_minutes_wait;                                                                                                                                                                                                                
        ll_pkg_log.log(40,'We will initially wait '||v_minutes_wait||' on status '||v_current_status);                                                                                                                                             
      elsif v_minutes_waited < v_max_minutes then                                                                                                                                                                                                  
        v_minutes_wait := 5;                                                                                                                                                                                                                       
        p_status := 'W';                                                                                                                                                                                                                           
        p_result := v_minutes_wait;                                                                                                                                                                                                                
        ll_pkg_log.log(40,'We will wait another '||v_minutes_wait||' on status '||v_current_status);                                                                                                                                               
      elsif v_minutes_waited > v_max_minutes then                                                                                                                                                                                                  
        p_status := 'N';                                                                                                                                                                                                                           
        p_result := 'Wait timed out, JOB result is '||v_current_status;                                                                                                                                                                            
        ll_pkg_log.log(40,'Wait timed out, job result is '||v_current_status);                                                                                                                                                                     
      end if;                                                                                                                                                                                                                                      
    elsif v_current_status = 'SUCCEEDED' then                                                                                                                                                                                                      
      p_status := 'Y';                                                                                                                                                                                                                             
      p_result := fetch_job_output (p_tenancy_id => v_tenancy_id, p_host => v_host, p_job_id => v_job_ocid);                                                                                                                                       
      ll_pkg_log.log(40,'Wait result is '||v_current_status||' execting with status Y');                                                                                                                                                           
    elsif v_current_status = 'FAILED' then                                                                                                                                                                                                         
      store_failed_tf_log(p_reservation_id);                                                                                                                                                                                                       
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := upload_failed_job_log(p_reservation_id);                                                                                                                                                                                         
      ll_pkg_log.log(40,'Wait result is FAILED; Terraform log link written to flow step result');                                                                                                                                                  
    else                                                                                                                                                                                                                                            
      p_status := 'N';                                                                                                                                                                                                                              
      store_failed_tf_log(p_reservation_id);
      p_result := upload_failed_job_log(p_reservation_id);
      ll_pkg_log.log(40,'Wait result is '||v_current_status||' execting with status N');                                                                                                                                                            
    end if;                                                                                                                                                                                                                                        
    ll_pkg_log.log(20,'End call');                                                                                                                                                                                                                 

  EXCEPTION                                                                                                                                                                                                                                        
    WHEN others THEN                                                                                                                                                                                                                                
      p_status := 'N';                                                                                                                                                                                                                             
      store_failed_tf_log(p_reservation_id);
      p_result := upload_failed_job_log(p_reservation_id);
  end;                                                                                                                                                                                                                                             
--                                                                                                                                                                                                                                                 
--  ########  ######## ##       ######## ######## ########          ######  ########    ###     ######  ##    ##                                                                                                                                   
--  ##     ## ##       ##       ##          ##    ##               ##    ##    ##      ## ##   ##    ## ##   ##                                                                                                                                    
--  ##     ## ##       ##       ##          ##    ##               ##          ##     ##   ##  ##       ##  ##                                                                                                                                     
--  ##     ## ######   ##       ######      ##    ######            ######     ##    ##     ## ##       #####                                                                                                                                      
--  ##     ## ##       ##       ##          ##    ##                     ##    ##    ######### ##       ##  ##                                                                                                                                     
--  ##     ## ##       ##       ##          ##    ##               ##    ##    ##    ##     ## ##    ## ##   ##                                                                                                                                    
--  ########  ######## ######## ########    ##    ######## #######  ######     ##    ##     ##  ######  ##    ##                                                                                                                                   
--                                                                                                                                                                                                                                                 
  procedure delete_stack (p_reservation_id IN number, p_res_step_id IN number, p_status OUT varchar2, p_result OUT varchar2) AS                                                                                                                    

    v_host        varchar2(200);                                                                                                                                                                                                                   
    v_method      varchar2(200);                                                                                                                                                                                                                   
    v_clob        clob;                                                                                                                                                                                                                            
    v_payload     clob;                                                                                                                                                                                                                            
    v_stack_ocid     varchar2(200);                                                                                                                                                                                                                
    v_tenancy_id  varchar2(200);                                                                                                                                                                                                                   
    v_region_id   number;                                                                                                                                                                                                                          
    v_compartment_ocid  varchar2(200);                                                                                                                                                                                                             
    v_object_name  varchar2(200);                                                                                                                                                                                                                  
  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                             
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id));                                                                                                            
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);                                                                                                                                                                              
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id);                                                                                                                                                                                
    v_stack_ocid := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,                                                                                                                                                     
                                                         p_param_type     => 'ociTerraform');                                                                                                                                                      
    v_method := '/20180917/stacks/'||v_stack_ocid;                                                                                                                                                                                                 
    v_clob := ll_pkg_exec.delete ( p_tenancy_id => v_tenancy_id,                                                                                                                                                                                   
                                   p_host       => v_host,                                                                                                                                                                                         
                                   p_method     => v_method);                                                                                                                                                                                      
    if v_clob is not null then                                                                                                                                                                                                                     
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := v_clob;                                                                                                                                                                                                                          
    else                                                                                                                                                                                                                                           
      p_status := 'Y';                                                                                                                                                                                                                             
    end if;                                                                                                                                                                                                                                        
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                              
  EXCEPTION                                                                                                                                                                                                                                        
    WHEN others THEN                                                                                                                                                                                                                               
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := SQLERRM;                                                                                                                                                                                                                         
  end;                                                                                                                                                                                                                                             
--                                                                                                                                                                                                                                                 
--  ########  ########  ######  ######## ########   #######  ##    ##               ##  #######  ########                                                                                                                                          
--  ##     ## ##       ##    ##    ##    ##     ## ##     ##  ##  ##                ## ##     ## ##     ##                                                                                                                                         
--  ##     ## ##       ##          ##    ##     ## ##     ##   ####                 ## ##     ## ##     ##                                                                                                                                         
--  ##     ## ######    ######     ##    ########  ##     ##    ##                  ## ##     ## ########                                                                                                                                          
--  ##     ## ##             ##    ##    ##   ##   ##     ##    ##            ##    ## ##     ## ##     ##                                                                                                                                         
--  ##     ## ##       ##    ##    ##    ##    ##  ##     ##    ##            ##    ## ##     ## ##     ##                                                                                                                                         
--  ########  ########  ######     ##    ##     ##  #######     ##    #######  ######   #######  ########                                                                                                                                          
--                                                                                                                                                                                                                                                 
  procedure destroy_job (p_reservation_id IN number, p_res_step_id IN number, p_status OUT varchar2, p_result OUT varchar2) AS                                                                                                                     
    v_host        varchar2(200);                                                                                                                                                                                                                   
    v_method      varchar2(200);                                                                                                                                                                                                                   
    v_clob        clob;                                                                                                                                                                                                                            
    v_payload     clob;                                                                                                                                                                                                                            
    v_stack_ocid  varchar2(200);                                                                                                                                                                                                                   
    v_tenancy_id  number;                                                                                                                                                                                                                          
    v_region_id   number;                                                                                                                                                                                                                          
    v_compartment_ocid  varchar2(200);                                                                                                                                                                                                             
    v_object_name  varchar2(200);                                                                                                                                                                                                                  
    v_job_ocid     varchar2(200);                                                                                                                                                                                                                  
    v_job_result   varchar2(200);                                                                                                                                                                                                                  
    v_max_minutes  number          := 45;                                                                                                                                                                                                          
  begin                                                                                                                                                                                                                                            
    ll_pkg_log.log(20,'Initial call');                                                                                                                                                                                                             
    ll_pkg_security.set_security_group;                                                                                                                                                                                                            
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id));                                                                                                            
    v_tenancy_id := ll_pkg_reservation.tenancy_id (p_reservation_id);                                                                                                                                                                              
    v_region_id := ll_pkg_reservation.region_id (p_reservation_id);                                                                                                                                                                                

    v_compartment_ocid := ll_pkg_reservation.user_object_ocid(p_reservation_id => p_reservation_id,                                                                                                                                                
                                                              p_param_type     => 'ociCompartment');                                                                                                                                               
    v_stack_ocid := ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id,                                                                                                                                                     
                                                         p_param_type     => 'ociTerraform' );                                                                                                                                                     
    v_method := '/20180917/jobs';                                                                                                                                                                                                                  
    v_payload := JSON_OBJECT ( 'stackId'             value v_stack_ocid,                                                                                                                                                                           
                               'jobOperationDetails' value JSON_OBJECT( 'operation'             value 'DESTROY',                                                                                                                                   
                                                                        'executionPlanStrategy' value 'AUTO_APPROVED')                                                                                                                             
                             );                                                                                                                                                                                                                    
    v_clob := ll_pkg_exec.put_post ( p_tenancy_id => v_tenancy_id,                                                                                                                                                                                 
                                     p_type       => 'POST',                                                                                                                                                                                       
                                     p_host       => v_host,                                                                                                                                                                                       
                                     p_method     => v_method,                                                                                                                                                                                     
                                     p_body       => v_payload);                                                                                                                                                                                   
    ll_pkg_log.log(30,'Destroy job sumbitted');                                                                                                                                                                                                    
    v_job_ocid := ll_pkg_admin.get_id(v_clob);                                                                                                                                                                                                     
    if v_job_ocid is null then                                                                                                                                                                                                                     
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := v_clob;                                                                                                                                                                                                                          
      ll_pkg_log.log(1,'Destroy job failed, output is '||v_clob);                                                                                                                                                                                  
    else                                                                                                                                                                                                                                           
      ll_pkg_log.log(30,'Destroy job succesfully launched, waiting for result');                                                                                                                                                                   
      v_job_result := wait_job_complete (p_tenancy_id => v_tenancy_id, p_host => v_host, p_job_id => v_job_ocid, p_max_minutes => v_max_minutes );                                                                                                 
      ll_pkg_log.log(30,'Destroy job finished or timed out, status='||p_status);                                                                                                                                                                   
      if v_job_result = 'SUCCEEDED' then                                                                                                                                                                                                           
        p_status := 'Y';                                                                                                                                                                                                                           
        p_result := '';                                                                                                                                                                                                                            
      elsif v_job_result = 'FAILED' then                                                                                                                                                                                                           
        store_failed_tf_log(p_reservation_id);                                                                                                                                                                                                     
        p_status := 'N';                                                                                                                                                                                                                           
        p_result := upload_failed_job_log(p_reservation_id);                                                                                                                                                                                       
        --p_result := 'JOB result is '|| v_job_result||'log capture intiated' ||function terraform_failure_output (p_tenancy_id number, p_host varchar2, p_region_key varchar2, p_job_id varchar2);                                                
      else                                                                                                                                                                                                                                         
        p_status := 'N';                                                                                                                                                                                                                           
        p_result := 'JOB result is '||v_job_result;                                                                                                                                                                                                
      end if;                                                                                                                                                                                                                                      
    end if;                                                                                                                                                                                                                                        
    ll_pkg_log.log(20,'End of call');                                                                                                                                                                                                              

  EXCEPTION                                                                                                                                                                                                                                        
    WHEN others THEN                                                                                                                                                                                                                               
      p_status := 'N';                                                                                                                                                                                                                             
      p_result := SQLERRM;                                                                                                                                                                                                                         
  end;                                                                                                                                                                                                                                             

  procedure store_failed_tf_log (p_reservation_id number) is                                                                                                                                                                                       
    l_tenancy_id number;                                                                                                                                                                                                                           
    l_host       varchar2(1000);                                                                                                                                                                                                                   
    l_job_id     varchar2(4000);                                                                                                                                                                                                                   
  begin                                                                                                                                                                                                                                            
    l_tenancy_id := ll_pkg_reservation.tenancy_id(p_reservation_id);                                                                                                                                                                               
    l_host := ll_pkg_admin.oci_endpoint(                                                                                                                                                                                                           
      p_type       => 'resourcemanager',                                                                                                                                                                                                           
      p_region_key => ll_pkg_reservation.region_key(p_reservation_id)                                                                                                                                                                              
    );                                                                                                                                                                                                                                             
    l_job_id := ll_pkg_reservation.user_object_ocid(                                                                                                                                                                                               
      p_reservation_id => p_reservation_id,                                                                                                                                                                                                        
      p_param_type     => 'ociTfApplyJob'                                                                                                                                                                                                          
    );                                                                                                                                                                                                                                             
    if l_job_id is null or instr(l_job_id, 'Error:') = 1 then                                                                                                                                                                                      
      raise_application_error(-20005,                                                                                                                                                                                                              
        'Cannot resolve the Apply job OCID for reservation ' || p_reservation_id);                                                                                                                                                                 
    end if;                                                                                                                                                                                                                                        
    for x in (select p_reservation_id, l_tenancy_id p_tenancy_id, l_job_id p_job_id, log_type, log_level, log_timestamp, log_message                                                                                                               
              from JSON_TABLE( ll_pkg_exec.get ( p_tenancy_id => l_tenancy_id,                                                                                                                                                                     
                                                 p_host => l_host,                                                                                                                                                                                 
                                                 p_method => '/20180917/jobs/'||l_job_id||'/logs'),                                                                                                                                                
                               '$[*]' COLUMNS ( log_type      varchar2 PATH '$.type',                                                                                                                                                              
                                                log_level     varchar2 PATH '$.level',                                                                                                                                                             
                                                log_timestamp varchar2 PATH '$.timestamp',                                                                                                                                                         
                                                log_message   varchar2 PATH '$.message') )) loop                                                                                                                                                   
    insert into LL_RESERVATION_TF_LOG (reservation_id, tenancy_id, job_ocid, log_type, log_level, log_timestamp, log_message) values (x.p_reservation_id, x.p_tenancy_id, x.p_job_id, x.log_type, x.log_level, x.log_timestamp, x.log_message);    
    end loop;                                                                                                                                                                                                                                      
      --select p_reservation_id, l_tenancy_id p_tenancy_id, l_job_id p_job_id, log_type, log_level, log_timestamp, log_message                                                                                                                     
      --from JSON_TABLE( ll_pkg_exec.get(p_tenancy_id => p_tenancy_id, p_host => p_host, p_method => '/20180917/jobs/'||l_job_id||'/logs'),                                                                                                        
        --         '$[*]' COLUMNS ( log_type      varchar2 PATH '$.type',                                                                                                                                                                          
          --                        log_level     varchar2 PATH '$.level',                                                                                                                                                                         
            --                      log_timestamp varchar2 PATH '$.timestamp',                                                                                                                                                                     
              --                    log_message   varchar2 PATH '$.message') );                                                                                                                                                                    
    commit;                                                                                                                                                                                                                                        
  end;                                                                                                                                                                                                                                             

  FUNCTION fetch_terraform_logs(p_reservation_id IN VARCHAR2) RETURN CLOB IS                                                                                                                                                                       
        v_max_lines integer := 12;                                                                                                                                                                                                                 
        v_tf_log CLOB;                                                                                                                                                                                                                             
        v_return CLOB := '';                                                                                                                                                                                                                       
        type t_log_entries is table of varchar2(4000) index by pls_integer;                                                                                                                                                                        
        v_log_entries t_log_entries;                                                                                                                                                                                                               
        v_error_count integer := 0;                                                                                                                                                                                                                
        v_last_error_start integer := null;                                                                                                                                                                                                        
        v_error_block clob;                                                                                                                                                                                                                        
    BEGIN                                                                                                                                                                                                                                          
        -- Fetch tf logs, getting the logs in reverse order with sortOrder=DESC                                                                                                                                                                    
        v_tf_log := ll_pkg_exec.get(                                                                                                                                                                                                               
            p_tenancy_id  => ll_pkg_reservation.tenancy_id(p_reservation_id),                                                                                                                                                                      
            p_host       => ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => ll_pkg_reservation.region_key(p_reservation_id)),                                                                                              
            p_method     => '/20180917/jobs/' || ll_pkg_reservation.user_object_ocid (p_reservation_id => p_reservation_id, p_param_type => 'ociTfApplyJob') || '/logs',                                                                           
            p_query_string => 'sortOrder=DESC',                                                                                                                                                                                                    
            p_multiple_page =>'N'                                                                                                                                                                                                                  
        );                                                                                                                                                                                                                                         

        -- make sure it's not null or just empty brackets                                                                                                                                                                                          
        if v_tf_log is not null and LENGTH(v_tf_log) > 2 then                                                                                                                                                                                      
            -- store logs in array                                                                                                                                                                                                                 
            for item in (select message, rownum as rn from json_table(v_tf_log, '$[*]'  columns (message varchar2(4000) path '$.message'))) loop                                                                                                   
                v_log_entries(item.rn) := item.message;                                                                                                                                                                                            
            end loop;                                                                                                                                                                                                                              

            -- now look for "Error: " and capture following lines                                                                                                                                                                                  
            -- Only capture the last 3 errors (which appear first in DESC order)                                                                                                                                                                   
            for i in 1..v_log_entries.count loop                                                                                                                                                                                                   
                if regexp_like(v_log_entries(i), '^\s*Error:\s+\S', 'n') then                                                                                                                                                                      
                    v_error_count := v_error_count + 1;                                                                                                                                                                                            

                    -- Only process first 3 errors encountered (last 3 chronologically)                                                                                                                                                            
                    if v_error_count <= 3 then                                                                                                                                                                                                     
                        v_error_block := '';                                                                                                                                                                                                       

                        -- Determine how many lines to capture                                                                                                                                                                                     
                        -- If there's a previous error, stop before reaching it                                                                                                                                                                    
                        declare                                                                                                                                                                                                                    
                            v_lines_to_capture integer := v_max_lines;                                                                                                                                                                             
                        begin                                                                                                                                                                                                                      
                            if v_last_error_start is not null then                                                                                                                                                                                 
                                -- Calculate distance to previous error                                                                                                                                                                            
                                v_lines_to_capture := least(v_max_lines, i - v_last_error_start - 1);                                                                                                                                              
                            end if;                                                                                                                                                                                                                

                            -- Capture the lines BEFORE this error (because of DESC order)                                                                                                                                                         
                            for j in 0..v_lines_to_capture loop                                                                                                                                                                                    
                                if v_log_entries.exists(i - j) then                                                                                                                                                                                
                                    v_error_block := v_error_block || v_log_entries(i - j) || chr(10);                                                                                                                                             
                                end if;                                                                                                                                                                                                            
                            end loop;                                                                                                                                                                                                              
                        end;                                                                                                                                                                                                                       

                        -- Add separator between errors if this isn't the first                                                                                                                                                                    
                        if v_error_count > 1 then                                                                                                                                                                                                  
                            v_return := v_return || chr(10) || chr(10) || '--------------- Error ' || v_error_count || ' ---------------' || chr(10);                                                                                              
                        end if;                                                                                                                                                                                                                    

                        v_return := v_return || v_error_block;                                                                                                                                                                                     
                        v_last_error_start := i;                                                                                                                                                                                                   
                    else                                                                                                                                                                                                                           
                        exit;                                                                                                                                                                                                                      
                    end if;                                                                                                                                                                                                                        
                end if;                                                                                                                                                                                                                            
            end loop;                                                                                                                                                                                                                              

            if v_error_count > 0 then                                                                                                                                                                                                              
                RETURN '--------------- ERROR 1 ---------------' || chr(10) || v_return;                                                                                                                                                           
            else                                                                                                                                                                                                                                   
                RETURN NULL;                                                                                                                                                                                                                       
            end if;                                                                                                                                                                                                                                
        ELSE                                                                                                                                                                                                                                       
            ll_pkg_log.log(40, 'No Terraform logs found or logs empty.');                                                                                                                                                                          
            RETURN NULL;                                                                                                                                                                                                                           
        END IF;                                                                                                                                                                                                                                    
    EXCEPTION                                                                                                                                                                                                                                      
        WHEN OTHERS THEN                                                                                                                                                                                                                           
            ll_pkg_log.log(1, 'Error fetching Terraform logs: ' || SQLERRM);                                                                                                                                                                       
            RETURN 'Could not fetch Terraform Logs';                                                                                                                                                                                               
    END fetch_terraform_logs;                                                                                                                                                                                                                      

      -- create configuration source provider so we can upload terraform to oci through github                                                                                                                                                     
  procedure create_config_source_provider (p_tenancy_id in number, p_region_key in varchar2) is                                                                                                                                                    
    v_root_ocid varchar2(4000);                                                                                                                                                                                                                    
    v_body clob;                                                                                                                                                                                                                                   
    v_response clob;                                                                                                                                                                                                                               
    v_id varchar2(4000);                                                                                                                                                                                                                           
    v_tenancy_name varchar2(200);                                                                                                                                                                                                                  
  begin                                                                                                                                                                                                                                            
    v_root_ocid := ll_pkg_admin.tenancy_ocid(p_tenancy_id);                                                                                                                                                                                        
    select tenancy_name into v_tenancy_name from ll_tenancies where id = p_tenancy_id;                                                                                                                                                             
    v_body := json_object(                                                                                                                                                                                                                         
        'compartmentId'             value   v_root_ocid,                                                                                                                                                                                           
        'configSourceProviderType'  value   'GITHUB_ACCESS_TOKEN',                                                                                                                                                                                 
        'displayName'               value   'Github Access for Terraform Files',                                                                                                                                                                   
        'accessToken'               value   'XXXXX',                                                                                                                                                            
        'apiEndpoint'               value   'https://github.com/oracle-livelabs/'                                                                                                                                                                  
    );                                                                                                                                                                                                                                             
    v_response := ll_pkg_exec.put_post ( p_tenancy_id => p_tenancy_id,                                                                                                                                                                             
                                     p_type       => 'POST',                                                                                                                                                                                       
                                     p_host       => ll_pkg_admin.oci_endpoint( p_type => 'resourcemanager', p_region_key => p_region_key),                                                                                                        
                                     p_method     => '/20180917/configurationSourceProviders',                                                                                                                                                     
                                     p_body       => v_body);                                                                                                                                                                                      
    if apex_web_service.g_status_code < 300 then                                                                                                                                                                                                   
        v_id := json_value(v_response, '$.id');                                                                                                                                                                                                    
        insert into ll_config_source_providers(tenancy_id, region_key, tenancy_name, config_source_ocid)                                                                                                                                           
        values (p_tenancy_id, p_region_key, v_tenancy_name, v_id);                                                                                                                                                                                 
        ll_pkg_log.log(1, 'CSP Created in ' || p_tenancy_id || ' region ' || p_region_key);                                                                                                                                                        
    else                                                                                                                                                                                                                                           
        ll_pkg_log.log(1, 'Error creating config source provider in tenancy ' || p_tenancy_id || ' region ' || p_region_key || ': ' || v_response);                                                                                                
    end if;                                                                                                                                                                                                                                        
  end;                                                                                                                                                                                                                                             
  -- create CSP for all regions in a tenancy                                                                                                                                                                                                       
  procedure create_csp_all_regions(p_tenancy_id number) is                                                                                                                                                                                         
    v_regions clob;                                                                                                                                                                                                                                
  begin                                                                                                                                                                                                                                            
    v_regions := ll_pkg_admin.subscribed_regions(p_tenancy_id);                                                                                                                                                                                    
    for region in (select regionKey from json_table(v_regions, '$[*]' columns (regionKey))) loop                                                                                                                                                   
        create_config_source_provider(p_tenancy_id, region.regionKey);                                                                                                                                                                             
    end loop;                                                                                                                                                                                                                                      
  end;                                                                                                                                                                                                                                             
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_PKG_ZIP" is
/*  EXAMPLE
  declare
    g_zipped_blob blob;
  begin
    as_zip.add1file( g_zipped_blob, 'test4.txt', null ); -- a empty file
    as_zip.add1file( g_zipped_blob, 'dir1/test1.txt', utl_raw.cast_to_raw( q'<A file with some more text, stored in a subfolder which isn't added>' ) );
    as_zip.add1file( g_zipped_blob, 'test1234.txt', utl_raw.cast_to_raw( 'A small file' ) );
    as_zip.add1file( g_zipped_blob, 'dir2/', null ); -- a folder
    as_zip.add1file( g_zipped_blob, 'dir3/', null ); -- a folder
    as_zip.add1file( g_zipped_blob, 'dir3/test2.txt', utl_raw.cast_to_raw( 'A small filein a previous created folder' ) );
    as_zip.finish_zip( g_zipped_blob );
    as_zip.save_zip( g_zipped_blob, 'MY_DIR', 'my.zip' );
    dbms_lob.freetemporary( g_zipped_blob );
  end;
  --
  declare
    zip_files as_zip.file_list;
  begin
    zip_files  := as_zip.get_file_list( 'MY_DIR', 'my.zip' );
    for i in zip_files.first() .. zip_files.last
    loop
      dbms_output.put_line( zip_files( i ) );
      dbms_output.put_line( utl_raw.cast_to_varchar2( as_zip.get_file( 'MY_DIR', 'my.zip', zip_files( i ) ) ) );
    end loop;
  end;
*/
  c_LOCAL_FILE_HEADER        constant raw(4) := hextoraw( '504B0304' ); -- Local file header signature
  c_END_OF_CENTRAL_DIRECTORY constant raw(4) := hextoraw( '504B0506' ); -- End of central directory signature
--
-- ==============================================================================================================
--
  function blob2num( p_blob blob, p_len integer, p_pos integer )
  return number
  is
    rv number;
  begin
    rv := utl_raw.cast_to_binary_integer( dbms_lob.substr( p_blob, p_len, p_pos ), utl_raw.little_endian );
    if rv < 0
    then
      rv := rv + 4294967296;
    end if;
    return rv;
  end;
--
-- ==============================================================================================================
--
  function raw2varchar2( p_raw raw, p_encoding varchar2 )
  return varchar2
  is
  begin
    return coalesce( utl_i18n.raw_to_char( p_raw, p_encoding )
                   , utl_i18n.raw_to_char( p_raw, utl_i18n.map_charset( p_encoding, utl_i18n.GENERIC_CONTEXT, utl_i18n.IANA_TO_ORACLE ) )
                   );
  end;
--
-- ==============================================================================================================
--
  function little_endian( p_big number, p_bytes pls_integer := 4 )
  return raw
  is
    t_big number := p_big;
  begin
    if t_big > 2147483647
    then
      t_big := t_big - 4294967296;
    end if;
    return utl_raw.substr( utl_raw.cast_from_binary_integer( t_big, utl_raw.little_endian ), 1, p_bytes );
  end;
--
-- ==============================================================================================================
--
  function file2blob
    ( p_dir varchar2
    , p_file_name varchar2
    )
  return blob
  is
    file_lob bfile;
    file_blob blob;
  begin
    file_lob := bfilename( p_dir, p_file_name );
    dbms_lob.open( file_lob, dbms_lob.file_readonly );
    dbms_lob.createtemporary( file_blob, true );
    dbms_lob.loadfromfile( file_blob, file_lob, dbms_lob.lobmaxsize );
    dbms_lob.close( file_lob );
    return file_blob;
  exception
    when others then
      if dbms_lob.isopen( file_lob ) = 1
      then
        dbms_lob.close( file_lob );
      end if;
      if dbms_lob.istemporary( file_blob ) = 1
      then
        dbms_lob.freetemporary( file_blob );
      end if;
      raise;
  end;
--
-- ==============================================================================================================
--
  function get_file_list
    ( p_zipped_blob blob
    , p_encoding varchar2 := null
    )
  return file_list
  is
    t_ind integer;
    t_hd_ind integer;
    t_rv file_list;
    t_encoding varchar2(32767);
  begin
    t_ind := nvl( dbms_lob.getlength( p_zipped_blob ), 0 ) - 21;
    loop
      exit when t_ind < 1 or dbms_lob.substr( p_zipped_blob, 4, t_ind ) = c_END_OF_CENTRAL_DIRECTORY;
      t_ind := t_ind - 1;
    end loop;
--
    if t_ind <= 0
    then
      return null;
    end if;
--
    t_hd_ind := blob2num( p_zipped_blob, 4, t_ind + 16 ) + 1;
    t_rv := file_list();
    t_rv.extend( blob2num( p_zipped_blob, 2, t_ind + 10 ) );
    for i in 1 .. blob2num( p_zipped_blob, 2, t_ind + 8 )
    loop
      if p_encoding is null
      then
        if utl_raw.bit_and( dbms_lob.substr( p_zipped_blob, 1, t_hd_ind + 9 ), hextoraw( '08' ) ) = hextoraw( '08' )
        then
          t_encoding := 'AL32UTF8'; -- utf8
        else
          t_encoding := 'US8PC437'; -- IBM codepage 437
        end if;
      else
        t_encoding := p_encoding;
      end if;
      t_rv( i ) := raw2varchar2
                     ( dbms_lob.substr( p_zipped_blob
                                      , blob2num( p_zipped_blob, 2, t_hd_ind + 28 )
                                      , t_hd_ind + 46
                                      )
                     , t_encoding
                     );
      t_hd_ind := t_hd_ind + 46
                + blob2num( p_zipped_blob, 2, t_hd_ind + 28 )  -- File name length
                + blob2num( p_zipped_blob, 2, t_hd_ind + 30 )  -- Extra field length
                + blob2num( p_zipped_blob, 2, t_hd_ind + 32 ); -- File comment length
    end loop;
--
    return t_rv;
  end;
--
-- ==============================================================================================================
--
  function get_file_list
    ( p_dir varchar2
    , p_zip_file varchar2
    , p_encoding varchar2 := null
    )
  return file_list
  is
  begin
    return get_file_list( file2blob( p_dir, p_zip_file ), p_encoding );
  end;
--
-- ==============================================================================================================
--
  function get_file
    ( p_zipped_blob blob
    , p_file_name varchar2
    , p_encoding varchar2 := null
    )
  return blob
  is
    t_tmp blob;
    t_ind integer;
    t_hd_ind integer;
    t_fl_ind integer;
    t_encoding varchar2(32767);
    t_len integer;
  begin
    t_ind := nvl( dbms_lob.getlength( p_zipped_blob ), 0 ) - 21;
    loop
      exit when t_ind < 1 or dbms_lob.substr( p_zipped_blob, 4, t_ind ) = c_END_OF_CENTRAL_DIRECTORY;
      t_ind := t_ind - 1;
    end loop;
--
    if t_ind <= 0
    then
      return null;
    end if;
--
    t_hd_ind := blob2num( p_zipped_blob, 4, t_ind + 16 ) + 1;
    for i in 1 .. blob2num( p_zipped_blob, 2, t_ind + 8 )
    loop
      if p_encoding is null
      then
        if utl_raw.bit_and( dbms_lob.substr( p_zipped_blob, 1, t_hd_ind + 9 ), hextoraw( '08' ) ) = hextoraw( '08' )
        then
          t_encoding := 'AL32UTF8'; -- utf8
        else
          t_encoding := 'US8PC437'; -- IBM codepage 437
        end if;
      else
        t_encoding := p_encoding;
      end if;
      if p_file_name = raw2varchar2
                         ( dbms_lob.substr( p_zipped_blob
                                          , blob2num( p_zipped_blob, 2, t_hd_ind + 28 )
                                          , t_hd_ind + 46
                                          )
                         , t_encoding
                         )
      then
        t_len := blob2num( p_zipped_blob, 4, t_hd_ind + 24 ); -- uncompressed length
        if t_len = 0
        then
          if substr( p_file_name, -1 ) in ( '/', '\' )
          then  -- directory/folder
            return null;
          else -- empty file
            return empty_blob();
          end if;
        end if;
--
        if dbms_lob.substr( p_zipped_blob, 2, t_hd_ind + 10 ) in ( hextoraw( '0800' ) -- deflate
                                                                 , hextoraw( '0900' ) -- deflate64
                                                                 )
        then
          t_fl_ind := blob2num( p_zipped_blob, 4, t_hd_ind + 42 );
          t_tmp := hextoraw( '1F8B0800000000000003' ); -- gzip header
          dbms_lob.copy( t_tmp
                       , p_zipped_blob
                       ,  blob2num( p_zipped_blob, 4, t_hd_ind + 20 )
                       , 11
                       , t_fl_ind + 31
                       + blob2num( p_zipped_blob, 2, t_fl_ind + 27 ) -- File name length
                       + blob2num( p_zipped_blob, 2, t_fl_ind + 29 ) -- Extra field length
                       );
          dbms_lob.append( t_tmp, utl_raw.concat( dbms_lob.substr( p_zipped_blob, 4, t_hd_ind + 16 ) -- CRC32
                                                , little_endian( t_len ) -- uncompressed length
                                                )
                         );
          return utl_compress.lz_uncompress( t_tmp );
        end if;
--
        if dbms_lob.substr( p_zipped_blob, 2, t_hd_ind + 10 ) = hextoraw( '0000' ) -- The file is stored (no compression)
        then
          t_fl_ind := blob2num( p_zipped_blob, 4, t_hd_ind + 42 );
          dbms_lob.createtemporary( t_tmp, true );
          dbms_lob.copy( t_tmp
                       , p_zipped_blob
                       , t_len
                       , 1
                       , t_fl_ind + 31
                       + blob2num( p_zipped_blob, 2, t_fl_ind + 27 ) -- File name length
                       + blob2num( p_zipped_blob, 2, t_fl_ind + 29 ) -- Extra field length
                       );
          return t_tmp;
        end if;
      end if;
      t_hd_ind := t_hd_ind + 46
                + blob2num( p_zipped_blob, 2, t_hd_ind + 28 )  -- File name length
                + blob2num( p_zipped_blob, 2, t_hd_ind + 30 )  -- Extra field length
                + blob2num( p_zipped_blob, 2, t_hd_ind + 32 ); -- File comment length
    end loop;
--
    return null;
  end;
--
-- ==============================================================================================================
--
  function get_file
    ( p_dir varchar2
    , p_zip_file varchar2
    , p_file_name varchar2
    , p_encoding varchar2 := null
    )
  return blob
  is
  begin
    return get_file( file2blob( p_dir, p_zip_file ), p_file_name, p_encoding );
  end;
--
-- ==============================================================================================================
--
  procedure add1file
    ( p_zipped_blob in out blob
    , p_name varchar2
    , p_content blob
    )
  is
    t_now date;
    t_blob blob;
    t_len integer;
    t_clen integer;
    t_crc32 raw(4) := hextoraw( '00000000' );
    t_compressed boolean := false;
    t_name raw(32767);
  begin
    t_now := sysdate;
    t_len := nvl( dbms_lob.getlength( p_content ), 0 );
    if t_len > 0
    then
      t_blob := utl_compress.lz_compress( p_content );
      t_clen := dbms_lob.getlength( t_blob ) - 18;
      t_compressed := t_clen < t_len;
      t_crc32 := dbms_lob.substr( t_blob, 4, t_clen + 11 );
    end if;
    if not t_compressed
    then
      t_clen := t_len;
      t_blob := p_content;
    end if;
    if p_zipped_blob is null
    then
      dbms_lob.createtemporary( p_zipped_blob, true );
    end if;
    t_name := utl_i18n.string_to_raw( p_name, 'AL32UTF8' );
    dbms_lob.append( p_zipped_blob
                   , utl_raw.concat( c_LOCAL_FILE_HEADER -- Local file header signature
                                   , hextoraw( '1400' )  -- version 2.0
                                   , case when t_name = utl_i18n.string_to_raw( p_name, 'US8PC437' )
                                       then hextoraw( '0000' ) -- no General purpose bits
                                       else hextoraw( '0008' ) -- set Language encoding flag (EFS)
                                     end
                                   , case when t_compressed
                                        then hextoraw( '0800' ) -- deflate
                                        else hextoraw( '0000' ) -- stored
                                     end
                                   , little_endian( to_number( to_char( t_now, 'ss' ) ) / 2
                                                  + to_number( to_char( t_now, 'mi' ) ) * 32
                                                  + to_number( to_char( t_now, 'hh24' ) ) * 2048
                                                  , 2
                                                  ) -- File last modification time
                                   , little_endian( to_number( to_char( t_now, 'dd' ) )
                                                  + to_number( to_char( t_now, 'mm' ) ) * 32
                                                  + ( to_number( to_char( t_now, 'yyyy' ) ) - 1980 ) * 512
                                                  , 2
                                                  ) -- File last modification date
                                   , t_crc32 -- CRC-32
                                   , little_endian( t_clen )                      -- compressed size
                                   , little_endian( t_len )                       -- uncompressed size
                                   , little_endian( utl_raw.length( t_name ), 2 ) -- File name length
                                   , hextoraw( '0000' )                           -- Extra field length
                                   , t_name                                       -- File name
                                   )
                   );
    if t_compressed
    then
      dbms_lob.copy( p_zipped_blob, t_blob, t_clen, dbms_lob.getlength( p_zipped_blob ) + 1, 11 ); -- compressed content
    elsif t_clen > 0
    then
      dbms_lob.copy( p_zipped_blob, t_blob, t_clen, dbms_lob.getlength( p_zipped_blob ) + 1, 1 ); --  content
    end if;
    if dbms_lob.istemporary( t_blob ) = 1
    then
      dbms_lob.freetemporary( t_blob );
    end if;
  end;
--
-- ==============================================================================================================
--
  procedure finish_zip( p_zipped_blob in out blob )
  is
    t_cnt pls_integer := 0;
    t_offs integer;
    t_offs_dir_header integer;
    t_offs_end_header integer;
    t_comment raw(32767) := utl_raw.cast_to_raw( 'Implementation by Anton Scheffer' );
  begin
    t_offs_dir_header := dbms_lob.getlength( p_zipped_blob );
    t_offs := 1;
    while dbms_lob.substr( p_zipped_blob, utl_raw.length( c_LOCAL_FILE_HEADER ), t_offs ) = c_LOCAL_FILE_HEADER
    loop
      t_cnt := t_cnt + 1;
      dbms_lob.append( p_zipped_blob
                     , utl_raw.concat( hextoraw( '504B0102' )      -- Central directory file header signature
                                     , hextoraw( '1400' )          -- version 2.0
                                     , dbms_lob.substr( p_zipped_blob, 26, t_offs + 4 )
                                     , hextoraw( '0000' )          -- File comment length
                                     , hextoraw( '0000' )          -- Disk number where file starts
                                     , hextoraw( '0000' )          -- Internal file attributes =>
                                                                   --     0000 binary file
                                                                   --     0100 (ascii)text file
                                     , case
                                         when dbms_lob.substr( p_zipped_blob
                                                             , 1
                                                             , t_offs + 30 + blob2num( p_zipped_blob, 2, t_offs + 26 ) - 1
                                                             ) in ( hextoraw( '2F' ) -- /
                                                                  , hextoraw( '5C' ) -- \
                                                                  )
                                         then hextoraw( '10000000' ) -- a directory/folder
                                         else hextoraw( '2000B681' ) -- a file
                                       end                         -- External file attributes
                                     , little_endian( t_offs - 1 ) -- Relative offset of local file header
                                     , dbms_lob.substr( p_zipped_blob
                                                      , blob2num( p_zipped_blob, 2, t_offs + 26 )
                                                      , t_offs + 30
                                                      )            -- File name
                                     )
                     );
      t_offs := t_offs + 30 + blob2num( p_zipped_blob, 4, t_offs + 18 )  -- compressed size
                            + blob2num( p_zipped_blob, 2, t_offs + 26 )  -- File name length
                            + blob2num( p_zipped_blob, 2, t_offs + 28 ); -- Extra field length
    end loop;
    t_offs_end_header := dbms_lob.getlength( p_zipped_blob );
    dbms_lob.append( p_zipped_blob
                   , utl_raw.concat( c_END_OF_CENTRAL_DIRECTORY                                -- End of central directory signature
                                   , hextoraw( '0000' )                                        -- Number of this disk
                                   , hextoraw( '0000' )                                        -- Disk where central directory starts
                                   , little_endian( t_cnt, 2 )                                 -- Number of central directory records on this disk
                                   , little_endian( t_cnt, 2 )                                 -- Total number of central directory records
                                   , little_endian( t_offs_end_header - t_offs_dir_header )    -- Size of central directory
                                   , little_endian( t_offs_dir_header )                        -- Offset of start of central directory, relative to start of archive
                                   , little_endian( nvl( utl_raw.length( t_comment ), 0 ), 2 ) -- ZIP file comment length
                                   , t_comment
                                   )
                   );
  end;
end;
/
  CREATE OR REPLACE PACKAGE BODY "LL_TESTING" as
-- 
--     ######   #######  ##     ## ########     ###    ########  ######## ##     ## ######## ##    ## ########  
--    ##    ## ##     ## ###   ### ##     ##   ## ##   ##     ##    ##    ###   ### ##       ###   ##    ##     
--    ##       ##     ## #### #### ##     ##  ##   ##  ##     ##    ##    #### #### ##       ####  ##    ##     
--    ##       ##     ## ## ### ## ########  ##     ## ########     ##    ## ### ## ######   ## ## ##    ##     
--    ##       ##     ## ##     ## ##        ######### ##   ##      ##    ##     ## ##       ##  ####    ##     
--    ##    ## ##     ## ##     ## ##        ##     ## ##    ##     ##    ##     ## ##       ##   ###    ##     
--     ######   #######  ##     ## ##        ##     ## ##     ##    ##    ##     ## ######## ##    ##    ##       
--
  procedure compartment AS 
    cursor c_tenancies is 
                          select id
                          from ll_tenancies
                          where upper(tenancy_name)='C4U03';
                          
    cursor c_compartments (p_tenancy_id number, p_compartment_ocid varchar2, p_host varchar2, p_name varchar2 default null) is 
                             select id
                             from json_table( ll_pkg_exec.get (p_tenancy_id       => p_tenancy_id,
                                                               p_host             => p_host,
                                                               p_method           => '/20160918/compartments',
                                                               p_query_string     => 'compartmentIdInSubtree=TRUE&sortBy=NAME' ),
                                             '$[*]' COLUMNS (id, name, lifecycleState, compartmentId, NESTED PATH '$.freeformTags[*]' COLUMNS (LastMoveDate)))
                             where lifecyclestate <> 'DELETED'
                             and compartmentId = p_compartment_ocid
--                             and ((p_name is null and (name not like 'RESERVED%' or to_date(nvl(lastmovedate,to_char(sysdate,'YYYYMMDD-HH24:MI:SS')),'YYYYMMDD-HH24:MI:SS')<sysdate-3)) or name = nvl(p_name,'X')) 
                             order by case nvl(lastmovedate,'X') when 'X' then 0 else 1 end, lastmovedate;
                                           
    v_host                  varchar2(4000);     
    v_ocid                  varchar2(1000); 
    v_default_ocid          varchar2(200);
    v_available_ocid        varchar2(200);
    v_tenancy_id            number;    
                                             
  begin
  
    ll_pkg_security.set_security_group;
    
    open c_tenancies;
    fetch c_tenancies into v_tenancy_id;
    close c_tenancies;
  
    v_host := ll_pkg_admin.oci_endpoint( p_type => 'identity', 
                                         p_region_key => 'IAD');
    v_available_ocid := 'ocid1.compartment.oc1..aaaaaaaaf7yhqpyesiqxdf5yhrj4ck5m2rwsoc3osfmymgmy2zvfsm6xelga';
    
    open c_compartments (v_tenancy_id, v_available_ocid, v_host);
    fetch c_compartments into v_ocid;
    if c_compartments%NOTFOUND then
      dbms_output.put_line('No compartments found in AVAILABLE state');
    else
      dbms_output.put_line('Compartment Found');
    end if;
    close c_compartments;
    
  end;
end;
/
